css:
/* ERPNext Web Page > Style (CSS) */

html,
body{
  margin:0 !important;
  padding:0 !important;
}

body{
  overflow-x:hidden !important;
}

body > .navbar,
body > nav.navbar,
body > header.navbar,
body > .web-header,
body > header.web-header,
.web-header,
.navbar.navbar-light,
.navbar.navbar-expand-lg,
footer,
.web-footer,
.website-footer{
  display:none !important;
}

#life-glp-app{
  --green:#075a38;
  --green2:#0b6e45;
  --deep:#033923;
  --deep2:#022c1c;
  --teal:#0b806c;
  --gold:#b4870d;
  --gold2:#d1aa3b;
  --cream:#f8f5ed;
  --cream2:#f1ecdf;
  --paper:#fff;
  --ink:#10261c;
  --ink2:#355246;
  --muted:#70867b;
  --muted2:#95a49d;
  --line:#e3ddcf;
  --line2:#d7d0bf;
  --ok:#087b4d;
  --warn:#9c7208;
  --crit:#a72b21;
  --blue:#20568f;
  --purple:#67419a;
  --shadow:0 1px 2px rgba(13,43,29,.05),0 3px 9px rgba(13,43,29,.05);
  --serif:Georgia,"Times New Roman",serif;
  --sans:"Segoe UI",Arial,sans-serif;

  width:100vw !important;
  max-width:100vw !important;
  min-height:100vh;
  margin-left:calc(50% - 50vw) !important;
  margin-right:calc(50% - 50vw) !important;
  background:var(--cream);
  color:var(--ink);
  font-family:var(--sans);
  font-size:13px;
}

#life-glp-app *{
  box-sizing:border-box;
}

#life-glp-app button,
#life-glp-app input,
#life-glp-app select{
  font:inherit;
  color:inherit;
}

#life-glp-app button{
  cursor:pointer;
}

/* Header */
.glp-mast{
  position:sticky;
  top:0;
  z-index:100;
  height:64px;
  padding:0 18px;
  display:flex;
  align-items:center;
  gap:14px;
  color:#fff;
  background:linear-gradient(110deg,#04472e,#087044);
  box-shadow:0 2px 14px rgba(2,45,29,.22);
}

.glp-home{
  height:38px;
  min-width:86px;
  padding:0 14px;
  border:1px solid rgba(255,255,255,.16);
  border-radius:9px;
  color:#fff !important;
  background:rgba(255,255,255,.08);
  font-weight:700;
}

.glp-title{
  flex:1;
  min-width:0;
  text-align:center;
}

.glp-title strong{
  display:block;
  font-family:var(--serif);
  font-size:24px;
  line-height:1;
  letter-spacing:.13em;
}

.glp-title span{
  display:block;
  margin-top:6px;
  color:#a4d0ba;
  font-size:9px;
  letter-spacing:.28em;
}

.glp-user{
  min-width:220px;
  height:46px;
  padding:5px 16px 5px 6px;
  border:1px solid rgba(255,255,255,.14);
  border-radius:25px;
  display:flex;
  align-items:center;
  gap:10px;
  color:#fff !important;
  text-align:left;
  background:rgba(255,255,255,.08);
}

.glp-avatar{
  width:34px;
  height:34px;
  flex:0 0 34px;
  border-radius:50%;
  display:grid;
  place-items:center;
  background:linear-gradient(145deg,#2aa06a,#087044);
  font-size:11px;
  font-weight:900;
}

.glp-user-copy b,
.glp-user-copy small{
  display:block;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

.glp-user-copy small{
  margin-top:2px;
  color:#a4d0ba;
  font-size:9px;
  letter-spacing:.09em;
  text-transform:uppercase;
}

/* Shell/sidebar */
.glp-shell{
  min-height:calc(100vh - 64px);
  display:flex;
}

.glp-side{
  position:sticky;
  top:64px;
  width:232px;
  height:calc(100vh - 64px);
  flex:0 0 232px;
  display:flex;
  flex-direction:column;
  color:#d4e5dc;
  background:linear-gradient(180deg,#043c28,#022d1e);
  z-index:80;
}

.glp-side-title{
  min-height:49px;
  padding:11px 14px;
  display:flex;
  align-items:center;
  gap:9px;
  border-bottom:1px solid rgba(255,255,255,.08);
}

.glp-side-title b{
  color:#8ebaa3;
  font-size:10px;
  letter-spacing:.18em;
}

.glp-side-icon{
  width:24px;
  height:24px;
  border-radius:7px;
  display:grid;
  place-items:center;
  background:linear-gradient(155deg,#2faf79,#087044);
  font-size:11px;
}

.glp-side-icon.gold{
  background:linear-gradient(155deg,#e7c867,#a77b10);
}

.glp-side-search{
  padding:10px 10px 7px;
}

.glp-side-search input{
  width:100%;
  height:35px;
  padding:0 10px;
  border:1px solid rgba(255,255,255,.13);
  border-radius:8px;
  color:#eef7f2 !important;
  background:rgba(255,255,255,.06);
  outline:none;
  font-size:11px;
}

.glp-side-search input::placeholder{
  color:#79a28e;
}

.glp-nav{
  flex:1;
  overflow-y:auto;
  padding:3px 7px 12px;
}

.glp-nav::-webkit-scrollbar{
  width:5px;
}

.glp-nav::-webkit-scrollbar-thumb{
  border-radius:6px;
  background:rgba(255,255,255,.14);
}

.glp-nav-group{
  margin-bottom:4px;
}

.glp-nav-head{
  width:100%;
  min-height:42px;
  padding:7px 8px;
  border:0;
  border-radius:8px;
  display:flex;
  align-items:center;
  gap:8px;
  color:#e0ece6 !important;
  background:transparent;
  text-align:left;
}

.glp-nav-head:hover,
.glp-nav-group.open .glp-nav-head{
  background:rgba(255,255,255,.06);
}

.glp-nav-icon{
  width:24px;
  height:24px;
  flex:0 0 24px;
  border-radius:7px;
  display:grid;
  place-items:center;
  color:#fff;
  background:linear-gradient(155deg,#2faf79,#087044);
  font-size:11px;
}

.glp-nav-icon.gold{background:linear-gradient(155deg,#e7c867,#a77b10)}
.glp-nav-icon.teal{background:linear-gradient(155deg,#28bfa9,#0b6155)}
.glp-nav-icon.blue{background:linear-gradient(155deg,#5b93d5,#1c4279)}
.glp-nav-icon.rose{background:linear-gradient(155deg,#df796b,#8a251b)}
.glp-nav-icon.purple{background:linear-gradient(155deg,#9978d0,#4b2c7c)}
.glp-nav-icon.slate{background:linear-gradient(155deg,#91a79b,#3d5448)}

.glp-nav-head b{
  flex:1;
  font-size:10.5px;
  letter-spacing:.1em;
}

.glp-nav-count{
  min-width:20px;
  padding:1px 5px;
  border-radius:5px;
  text-align:center;
  background:rgba(255,255,255,.12);
  font-size:9px;
  font-weight:800;
}

.glp-nav-arrow{
  color:#78a08d;
  font-size:8px;
}

.glp-nav-items{
  display:none;
  padding:0 0 3px;
}

.glp-nav-group.open .glp-nav-items{
  display:block;
}

.glp-nav-item{
  position:relative;
  width:100%;
  padding:8px 8px 8px 38px;
  border:0;
  border-radius:8px;
  display:block;
  color:#bfd7ca !important;
  background:transparent;
  text-align:left;
}

.glp-nav-item:hover{
  color:#fff !important;
  background:rgba(255,255,255,.055);
}

.glp-nav-item.active{
  color:#fff !important;
  background:rgba(47,164,111,.18);
  box-shadow:inset 3px 0 0 var(--gold2);
}

.glp-nav-item b{
  display:block;
  font-size:11px;
}

.glp-nav-item small{
  display:block;
  margin-top:1px;
  color:#7ea691;
  font-size:9px;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

.glp-side-foot{
  padding:10px 12px;
  border-top:1px solid rgba(255,255,255,.08);
  color:#729985;
  font-size:8px;
  line-height:1.55;
}

/* Main filter */
.glp-main{
  min-width:0;
  flex:1;
  background:var(--cream);
}

.glp-filterbar{
  position:sticky;
  top:64px;
  z-index:70;
  min-height:50px;
  padding:7px 14px;
  display:flex;
  align-items:center;
  gap:8px;
  border-bottom:1px solid var(--line);
  background:rgba(248,245,237,.97);
  backdrop-filter:blur(8px);
}

.glp-filter-label{
  color:var(--muted);
  font-size:9px;
  font-weight:900;
  letter-spacing:.14em;
}

.glp-chip{
  min-height:34px;
  padding:6px 11px;
  border:1px solid var(--line2);
  border-radius:8px;
  display:inline-flex;
  align-items:center;
  gap:6px;
  background:#fff;
  white-space:nowrap;
  font-size:11px;
  font-weight:650;
  box-shadow:0 1px 2px rgba(20,40,30,.03);
}

.glp-chip.gold{
  border-color:#dfc66f;
  color:#74570b !important;
  background:#fff7dc;
}

.glp-branch-count{
  border-color:#b8dac8;
  color:#087044 !important;
  background:#edf7f2;
}

.glp-branch-select{
  min-width:160px;
  max-width:220px;
  padding-right:30px;
  font-weight:750;
}

.glp-spacer{
  flex:1;
}

.glp-menu{
  display:none;
}

.glp-date-panel{
  position:absolute;
  top:48px;
  left:365px;
  width:300px;
  padding:12px;
  border:1px solid var(--line2);
  border-radius:10px;
  display:none;
  grid-template-columns:1fr 1fr;
  gap:10px;
  background:#fff;
  box-shadow:0 12px 30px rgba(0,0,0,.14);
}

.glp-date-panel.open{
  display:grid;
}

.glp-date-panel label{
  display:flex;
  flex-direction:column;
  gap:5px;
}

.glp-date-panel label span{
  color:var(--muted);
  font-size:9px;
  font-weight:800;
  text-transform:uppercase;
}

.glp-date-panel input{
  height:34px;
  border:1px solid var(--line2);
  border-radius:7px;
  padding:0 7px;
}

.glp-date-actions{
  grid-column:1/-1;
  display:flex;
  justify-content:flex-end;
  gap:7px;
}

/* Content */
.glp-content{
  max-width:1680px;
  margin:0 auto;
  padding:14px;
}

.glp-page-head{
  margin-bottom:14px;
  padding:15px 18px;
  border:1px solid var(--line);
  border-left:4px solid var(--green2);
  border-radius:10px;
  display:flex;
  align-items:center;
  gap:16px;
  background:#fff;
  box-shadow:var(--shadow);
}

.glp-page-head-main{
  min-width:0;
  flex:1;
}

.glp-kicker{
  color:var(--gold);
  font-size:9px;
  font-weight:900;
  letter-spacing:.18em;
}

.glp-page-head h2{
  margin:4px 0 0;
  font-family:var(--serif);
  font-size:28px;
  font-weight:600;
  line-height:1.05;
}

.glp-page-head p{
  max-width:900px;
  margin:6px 0 0;
  color:var(--muted);
  font-size:11px;
  line-height:1.55;
}

.glp-actions{
  display:flex;
  gap:7px;
  flex-wrap:wrap;
  justify-content:flex-end;
}

.glp-btn{
  min-height:34px;
  padding:7px 12px;
  border:1px solid var(--line2);
  border-radius:7px;
  background:#fff;
  font-size:10.5px;
  font-weight:800;
}

.glp-btn.primary{
  border-color:var(--green);
  color:#fff !important;
  background:linear-gradient(180deg,#0a7448,#075a38);
}

.glp-btn.gold{
  border-color:#b78a12;
  color:#fff !important;
  background:linear-gradient(180deg,#cda63c,#aa7f0d);
}

.glp-btn.sm{
  min-height:28px;
  padding:5px 8px;
  font-size:9.5px;
}

/* Legend */
.glp-legend{
  margin-bottom:12px;
  padding:10px 13px;
  border:1px solid var(--line);
  border-radius:10px;
  display:flex;
  align-items:center;
  gap:18px;
  flex-wrap:wrap;
  background:#fff;
  box-shadow:var(--shadow);
}

.glp-legend-title{
  color:var(--muted);
  font-size:9px;
  font-weight:900;
  letter-spacing:.14em;
}

.glp-legend-item{
  display:inline-flex;
  align-items:center;
  gap:6px;
  font-size:10.5px;
  font-weight:650;
}

.glp-dot{
  width:8px;
  height:8px;
  border-radius:3px;
}

/* KPI */
.glp-grid{
  display:grid;
  gap:10px;
}

.glp-grid-7{
  grid-template-columns:repeat(7,minmax(120px,1fr));
  margin-bottom:12px;
}

.glp-grid-6{
  grid-template-columns:repeat(6,minmax(130px,1fr));
  margin-bottom:12px;
}

.glp-grid-4{
  grid-template-columns:repeat(4,minmax(0,1fr));
  margin-bottom:12px;
}

.glp-tile{
  position:relative;
  min-height:105px;
  padding:14px 14px 11px 17px;
  overflow:hidden;
  border:1px solid var(--line);
  border-radius:9px;
  background:#fff;
  box-shadow:var(--shadow);
}

.glp-tile.clickable{
  cursor:pointer;
}

.glp-tile:before{
  content:"";
  position:absolute;
  left:0;
  top:0;
  bottom:0;
  width:3px;
  background:var(--green2);
}

.glp-tile.gold:before{background:var(--gold)}
.glp-tile.ok:before{background:var(--ok)}
.glp-tile.warn:before{background:var(--warn)}
.glp-tile.crit:before{background:var(--crit)}
.glp-tile.blue:before{background:var(--blue)}
.glp-tile.teal:before{background:var(--teal)}
.glp-tile.purple:before{background:var(--purple)}

.glp-tile-value{
  color:var(--ink);
  font-family:var(--serif);
  font-size:27px;
  font-weight:700;
  line-height:1;
}

.glp-tile.gold .glp-tile-value{color:#9b7308}
.glp-tile.ok .glp-tile-value{color:var(--ok)}
.glp-tile.crit .glp-tile-value{color:var(--crit)}
.glp-tile.blue .glp-tile-value{color:var(--blue)}
.glp-tile.teal .glp-tile-value{color:var(--teal)}
.glp-tile.purple .glp-tile-value{color:var(--purple)}

.glp-tile-label{
  margin-top:9px;
  color:var(--ink2);
  font-size:9px;
  font-weight:900;
  letter-spacing:.11em;
  text-transform:uppercase;
}

.glp-tile-detail{
  margin-top:5px;
  color:var(--muted);
  font-size:9.5px;
}

/* Sections/cards */
.glp-section-head{
  min-height:34px;
  margin:12px 0 7px;
  display:flex;
  align-items:center;
  gap:8px;
}

.glp-section-head b{
  font-family:var(--serif);
  font-size:16px;
}

.glp-section-head span{
  color:var(--muted);
  font-size:9.5px;
}

.glp-section-head .glp-spacer{
  flex:1;
}

.glp-card{
  overflow:hidden;
  border:1px solid var(--line);
  border-radius:10px;
  background:#fff;
  box-shadow:var(--shadow);
}

.glp-card + .glp-card{
  margin-top:12px;
}

.glp-card-head{
  min-height:44px;
  padding:9px 12px;
  display:flex;
  align-items:center;
  gap:10px;
  border-bottom:1px solid var(--line);
}

.glp-card-head h3{
  margin:0;
  font-size:12px;
}

.glp-card-head .sub{
  color:var(--muted);
  font-size:9.5px;
}

/* Filter box */
.glp-view-filter{
  margin-bottom:12px;
  padding:11px 13px;
  border:1px solid var(--line);
  border-radius:10px;
  display:flex;
  align-items:flex-end;
  gap:12px;
  flex-wrap:wrap;
  background:#f5f0e5;
}

.glp-filter-field{
  display:flex;
  flex-direction:column;
  gap:5px;
}

.glp-filter-field label{
  color:#173e2d;
  font-size:9px;
  font-weight:900;
  letter-spacing:.12em;
}

.glp-input,
.glp-select{
  height:36px;
  border:1px solid var(--line2);
  border-radius:7px;
  padding:0 10px;
  background:#fff;
  font-size:11px;
}

.glp-input{
  width:280px;
}

.glp-select{
  min-width:175px;
}

/* Table */
.glp-table-wrap{
  width:100%;
  overflow:auto;
}

.glp-table{
  width:100%;
  border-collapse:collapse;
  font-size:10.5px;
}

.glp-table th{
  padding:9px 10px;
  border-bottom:1px solid var(--line2);
  color:#173e2d;
  background:#f2eee3;
  text-align:left;
  font-size:8.5px;
  font-weight:900;
  letter-spacing:.11em;
  text-transform:uppercase;
  white-space:nowrap;
}

.glp-table td{
  padding:9px 10px;
  border-bottom:1px solid #efebe2;
  color:var(--ink2);
  vertical-align:middle;
}

.glp-table tbody tr:last-child td{
  border-bottom:0;
}

.glp-table tbody tr.click{
  cursor:pointer;
}

.glp-table tbody tr.click:hover td{
  background:#fbfcfa;
}

.glp-name{
  display:block;
  color:var(--ink);
  font-size:11px;
  font-weight:800;
}

.glp-muted{
  display:block;
  margin-top:2px;
  color:var(--muted2);
  font-size:8.8px;
}

.glp-num{
  text-align:right;
  white-space:nowrap;
  font-variant-numeric:tabular-nums;
}

.glp-tag{
  display:inline-flex;
  align-items:center;
  min-height:21px;
  padding:3px 8px;
  border:1px solid var(--line2);
  border-radius:12px;
  background:#f5f3ed;
  font-size:8.5px;
  font-weight:900;
  white-space:nowrap;
}

.glp-tag.ok{
  border-color:#bee1cd;
  color:var(--ok);
  background:#e7f5ed;
}

.glp-tag.warn{
  border-color:#ead5a2;
  color:var(--warn);
  background:#fcf2db;
}

.glp-tag.crit{
  border-color:#ebc2bc;
  color:var(--crit);
  background:#fae9e6;
}

.glp-tag.blue{
  border-color:#c7d9ee;
  color:var(--blue);
  background:#eaf1f9;
}

.glp-tag.purple{
  border-color:#dacdf0;
  color:var(--purple);
  background:#f1ebfa;
}

.glp-progress{
  width:115px;
  max-width:100%;
  height:5px;
  margin-top:5px;
  overflow:hidden;
  border-radius:5px;
  background:#ece8de;
}

.glp-progress span{
  display:block;
  height:100%;
  border-radius:5px;
  background:linear-gradient(90deg,#0b6e45,#2aa16b);
}

/* Empty/loading */
.glp-empty{
  padding:24px;
  text-align:center;
  color:var(--muted);
}

.glp-loading{
  min-height:150px;
  padding:25px;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:12px;
  border:1px solid var(--line);
  border-radius:10px;
  background:#fff;
}

.glp-loading b,
.glp-loading span{
  display:block;
}

.glp-loading span{
  margin-top:3px;
  color:var(--muted);
}

.glp-spinner{
  width:28px;
  height:28px;
  border:3px solid #dce7e1;
  border-top-color:var(--green);
  border-radius:50%;
  animation:glpspin .8s linear infinite;
}

@keyframes glpspin{
  to{transform:rotate(360deg)}
}

/* Toast */
.glp-toast-wrap{
  position:fixed;
  right:18px;
  bottom:18px;
  z-index:250;
}

.glp-toast{
  margin-top:7px;
  padding:10px 12px;
  border-radius:8px;
  color:#fff;
  background:#075a38;
  box-shadow:0 7px 24px rgba(0,0,0,.2);
  font-size:11px;
  font-weight:700;
}

.glp-toast.error{
  background:#9f2d23;
}

/* Responsive */
@media(max-width:1300px){
  .glp-grid-7{
    grid-template-columns:repeat(4,minmax(130px,1fr));
  }
}

@media(max-width:1000px){
  .glp-side{
    position:fixed;
    left:-240px;
    z-index:120;
    transition:left .2s ease;
  }

  .glp-side.open{
    left:0;
  }

  .glp-menu{
    display:inline-flex;
  }

  .glp-user{
    min-width:0;
  }

  .glp-user-copy{
    display:none;
  }

  .glp-grid-7,
  .glp-grid-6,
