/* ============================================================
   V4.55 — FINAL NORMAL / LINING DIGITS FIX
   ------------------------------------------------------------
   Purpose:
   - Keep every digit on one baseline: 0123456789
   - Fix Therapy Session / Appointment body-level native modal
   - Fix date, time, number, search and select controls
   - Fix KPI/table/pagination/sidebar numeric values
   - Preserve the existing serif design for ordinary headings/text
   ============================================================ */

/* Ask supporting fonts for lining/tabular figures wherever available. */
html body #life-glp-app,
html body #life-glp-app *,
html body #glp-native-modal,
html body #glp-native-modal * {
  font-variant-numeric: lining-nums tabular-nums !important;
  font-variant-position: normal !important;
  font-feature-settings: "lnum" 1, "onum" 0, "tnum" 1 !important;
}

/* Dashboard controls: use a font with dependable lining digits. */
html body #life-glp-app input,
html body #life-glp-app select,
html body #life-glp-app option,
html body #life-glp-app textarea,
html body #life-glp-app .glp-date-display,
html body #life-glp-app .glp-chip,
html body #life-glp-app .glp-num,
html body #life-glp-app .glp-nav-count,
html body #life-glp-app .glp-pagination-info,
html body #life-glp-app .glp-pagination .glp-btn,
html body #life-glp-app .glp-assessment-result-meta {
  font-family: "Segoe UI", Arial, Tahoma, sans-serif !important;
  font-variant-numeric: lining-nums tabular-nums !important;
  font-variant-position: normal !important;
  font-feature-settings: "lnum" 1, "onum" 0, "tnum" 1 !important;
}

/* KPI numbers must never use Georgia old-style figures. */
html body #life-glp-app .glp-tile-value {
  font-family: "Segoe UI", Arial, Tahoma, sans-serif !important;
  font-variant-numeric: lining-nums tabular-nums !important;
  font-variant-position: normal !important;
  font-feature-settings: "lnum" 1, "onum" 0, "tnum" 1 !important;
}

/* Numeric table cells / headers. */
html body #life-glp-app .glp-table .glp-num,
html body #life-glp-app .glp-table th.glp-num,
html body #life-glp-app .glp-table td.glp-num {
  font-family: "Segoe UI", Arial, Tahoma, sans-serif !important;
  font-variant-numeric: lining-nums tabular-nums !important;
  font-variant-position: normal !important;
  font-feature-settings: "lnum" 1, "onum" 0, "tnum" 1 !important;
}

/* ------------------------------------------------------------
   IMPORTANT: #glp-native-modal is appended directly to <body>,
   not inside #life-glp-app.  These selectors intentionally have
   higher specificity than the CSS injected by JavaScript.
   ------------------------------------------------------------ */
html body #glp-native-modal input,
html body #glp-native-modal select,
html body #glp-native-modal option,
html body #glp-native-modal textarea,
html body #glp-native-modal button {
  font-family: "Segoe UI", Arial, Tahoma, sans-serif !important;
  font-variant-numeric: lining-nums tabular-nums !important;
  font-variant-position: normal !important;
  font-feature-settings: "lnum" 1, "onum" 0, "tnum" 1 !important;
}

/* Beat the dynamically injected combo-input serif rule. */
