  function esc(v) {
    return String(v == null ? "" : v)
      .replace(/&/g,"&amp;")
      .replace(/</g,"&lt;")
      .replace(/>/g,"&gt;")
      .replace(/"/g,"&quot;")
      .replace(/'/g,"&#039;");
  }

  function n(v) {
    var x = Number(v);
    return Number.isFinite(x) ? x : 0;
  }

  function norm(v) {
    return String(v == null ? "" : v).trim().toLowerCase();
  }

  var EXCLUDED_BRANCHES = [
    "testing branch",
    "head office"
  ];


  /* BUSINESS RULE: 1 GLP dose = 4 individual injection executions. */
  var GLP_INJECTIONS_PER_DOSE = 4;

  function isExcludedBranch(branchName) {
    var b = norm(branchName);
    return EXCLUDED_BRANCHES.indexOf(b) >= 0;
  }

  function todayISO() {
    var d = new Date();
    return d.getFullYear() + "-" +
      String(d.getMonth() + 1).padStart(2,"0") + "-" +
      String(d.getDate()).padStart(2,"0");
  }

  function displayDateDMY(value) {
    if (!value) return "";

    var p = String(value).slice(0,10).split("-");

    if (p.length !== 3) {
      return String(value);
    }

    return (
      String(p[2]).padStart(2,"0") +
      "-" +
      String(p[1]).padStart(2,"0") +
      "-" +
      String(p[0])
    );
  }

  function businessMonthRange(referenceISO) {
    var d = new Date(
      (referenceISO || todayISO()) + "T00:00:00"
    );

    var y = d.getFullYear();
    var m = d.getMonth();
    var day = d.getDate();

    var fromDate;
    var toDate;

    if (day >= 6) {
      fromDate = new Date(y, m, 6);
      toDate = new Date(y, m + 1, 5);
    } else {
      fromDate = new Date(y, m - 1, 6);
      toDate = new Date(y, m, 5);
    }

    function iso(x) {
      return (
        x.getFullYear() +
        "-" +
        String(x.getMonth() + 1).padStart(2,"0") +
        "-" +
        String(x.getDate()).padStart(2,"0")
      );
    }

    return {
      from: iso(fromDate),
      to: iso(toDate)
    };
  }

  function openNativeDatePicker(inputId) {
    var input = $(inputId);

    if (!input) {
      return;
    }

    try {
      if (typeof input.showPicker === "function") {
        input.showPicker();
      } else {
        input.focus();
        input.click();
      }
    } catch (e) {
      input.focus();
      input.click();
    }
  }

  function addMonthsISO(value, months) {
    var d = new Date((value || todayISO()) + "T00:00:00");
    d.setMonth(d.getMonth() + months);
    return d.getFullYear() + "-" +
      String(d.getMonth() + 1).padStart(2,"0") + "-" +
      String(d.getDate()).padStart(2,"0");
  }

  function fmtDate(v) {
    if (!v) return "—";
    var p = String(v).slice(0,10).split("-");
    if (p.length !== 3) return esc(v);
    var m = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
    return p[2] + "-" + m[Number(p[1])-1] + "-" + String(p[0]).slice(2);
  }

  function fmtTime(v) {
    if (!v) return "—";
    var p = String(v).split(":");
    var h = Number(p[0]);
    var mm = String(p[1] || "00").padStart(2,"0");
    if (!Number.isFinite(h)) return esc(v);
    var ap = h >= 12 ? "pm" : "am";
    return (h % 12 || 12) + ":" + mm + " " + ap;
  }

  function money(v) {
    return "₹" + Math.round(n(v)).toLocaleString("en-IN");
  }

  function moneyShort(v) {
    var x = n(v);
    var ax = Math.abs(x);
    if (ax >= 10000000) return "₹" + (x/10000000).toFixed(2) + " Cr";
    if (ax >= 100000) return "₹" + (x/100000).toFixed(2) + " L";
    if (ax >= 1000) return "₹" + (x/1000).toFixed(1) + " K";
    return money(x);
  }

  function pct(a,b) {
    if (!b) return 0;
