  function glpSearchableSelectText(
    option
  ) {
    if (!option) {
      return "";
    }

    return String(
      option.textContent ||
      option.innerText ||
      option.value ||
      ""
    ).trim();
  }


  function glpSearchableSelectEscape(
    value
  ) {
    return String(
      value == null
        ? ""
        : value
    )
      .replace(
        /&/g,
        "&amp;"
      )
      .replace(
        /</g,
        "&lt;"
      )
      .replace(
        />/g,
        "&gt;"
      )
      .replace(
        /"/g,
        "&quot;"
      )
      .replace(
        /'/g,
        "&#039;"
      );
  }


  function glpSearchableSelectCloseAll(
    exceptWrapper
  ) {
    var root =
      document.getElementById(
        "life-glp-app"
      );

    if (!root) {
      return;
    }

    root.querySelectorAll(
      ".glp-search-select.open"
    ).forEach(
      function (
        wrapper
      ) {
        if (
          wrapper !==
          exceptWrapper
        ) {
          wrapper.classList.remove(
            "open"
          );
        }
      }
    );
  }


  function glpSearchableSelectRender(
    select,
    wrapper,
    input,
    menu,
    query
  ) {
    if (
      !select ||
      !wrapper ||
      !input ||
      !menu
    ) {
      return;
    }

    var q =
      String(
        query || ""
      )
        .trim()
        .toLowerCase();

    var options =
      Array.from(
        select.options ||
        []
      );

    var rows = [];

    options.forEach(
      function (
        option
      ) {
        if (
          option.disabled
        ) {
          return;
        }

        var label =
          glpSearchableSelectText(
            option
          );

        var value =
          String(
            option.value == null
              ? ""
              : option.value
          );

        var searchable =
          (
            label +
            " " +
            value
          ).toLowerCase();

        if (
          q &&
          searchable.indexOf(
            q
          ) ===
            -1
        ) {
          return;
        }

        rows.push(
          {
            label:
              label,
            value:
              value,
            selected:
              String(
                select.value
              ) ===
              value
          }
        );
      }
    );

    if (
      !rows.length
    ) {
      menu.innerHTML =
        '<div class="glp-search-select-empty">No matching option</div>';

      return;
    }

    menu.innerHTML =
      rows
        .map(
          function (
            row
          ) {
            return (
              '<div class="glp-search-select-option' +
              (
                row.selected
                  ? " selected"
                  : ""
              ) +
              '" data-value="' +
              glpSearchableSelectEscape(
                row.value
              ) +
              '">' +
              glpSearchableSelectEscape(
                row.label
              ) +
              '</div>'
            );
          }
        )
        .join("");

    menu
      .querySelectorAll(
        ".glp-search-select-option"
      )
      .forEach(
        function (
          row
        ) {
          row.addEventListener(
            "mousedown",
            function (
              event
            ) {
              event.preventDefault();

              var value =
                row.getAttribute(
                  "data-value"
                );

              select.value =
                value == null
                  ? ""
                  : value;

              var selectedOption =
                select.options[
                  select.selectedIndex
                ];

              input.value =
                selectedOption
                  ? glpSearchableSelectText(
                      selectedOption
                    )
                  : "";

              input.dataset.lastValue =
                select.value;

              wrapper.classList.remove(
                "open"
              );

              select.dispatchEvent(
                new Event(
                  "change",
                  {
                    bubbles:
                      true
                  }
                )
              );
            }
          );
        }
      );
  }


  function glpSearchableSelectSync(
    select
  ) {
    if (
      !select ||
      !select._glpSearchable
    ) {
      return;
    }

    var state =
      select._glpSearchable;

    var selectedOption =
      select.options[
        select.selectedIndex
      ];

    state.input.value =
      selectedOption
        ? glpSearchableSelectText(
            selectedOption
          )
        : "";

    state.input.dataset.lastValue =
      select.value || "";

    state.input.disabled =
      !!select.disabled;

    state.input.required =
      !!select.required;

    state.input.placeholder =
      select.getAttribute(
        "data-search-placeholder"
      ) ||
      select.getAttribute(
        "placeholder"
      ) ||
      (
        selectedOption &&
        !selectedOption.value
          ? glpSearchableSelectText(
              selectedOption
            )
          : "Search or select..."
      );
  }


  function glpEnhanceOneSelect(
    select
  ) {
    if (
      !select ||
      select.dataset.glpSearchEnhanced ===
        "1"
    ) {
      return;
    }

    /*
      Skip selects explicitly opted out by code.
    */
    if (
      select.hasAttribute(
        "data-no-search-select"
      )
    ) {
      return;
    }

    select.dataset.glpSearchEnhanced =
      "1";

    var wrapper =
      document.createElement(
        "div"
      );

    wrapper.className =
      "glp-search-select";

    var control =
      document.createElement(
        "div"
      );

    control.className =
      "glp-search-select-control";

    var input =
      document.createElement(
        "input"
      );

    input.type =
      "text";

    input.className =
      "glp-search-select-input";

    input.autocomplete =
      "off";

    input.spellcheck =
      false;

    var arrow =
      document.createElement(
        "span"
      );

    arrow.className =
      "glp-search-select-arrow";

    arrow.textContent =
      "⌄";

    var menu =
      document.createElement(
        "div"
      );

    menu.className =
      "glp-search-select-menu";

    select.parentNode.insertBefore(
      wrapper,
      select
    );

    wrapper.appendChild(
      select
    );

    wrapper.appendChild(
      control
    );

    control.appendChild(
      input
    );

    control.appendChild(
      arrow
    );

    wrapper.appendChild(
      menu
    );

    select.classList.add(
      "glp-search-select-native"
    );

    select._glpSearchable = {
      wrapper:
        wrapper,
      input:
        input,
      menu:
        menu
    };

    glpSearchableSelectSync(
      select
    );

    input.addEventListener(
      "focus",
      function () {
        if (
          select.disabled
        ) {
          return;
        }

        glpSearchableSelectCloseAll(
          wrapper
        );

        wrapper.classList.add(
          "open"
        );

        /*
          Select existing display text on focus, so user can immediately type.
        */
        try {
          input.select();
        } catch (_) {}

        glpSearchableSelectRender(
          select,
          wrapper,
          input,
          menu,
          ""
        );
      }
    );

    input.addEventListener(
      "input",
      function () {
        if (
          select.disabled
        ) {
          return;
        }

        wrapper.classList.add(
          "open"
        );

        glpSearchableSelectRender(
          select,
          wrapper,
          input,
          menu,
          input.value
        );
      }
    );

    input.addEventListener(
      "keydown",
      function (
        event
      ) {
        var visible =
          Array.from(
            menu.querySelectorAll(
              ".glp-search-select-option"
            )
          );

        var activeIndex =
          visible.findIndex(
            function (
              row
            ) {
              return row.classList.contains(
                "active"
              );
            }
          );

        if (
          event.key ===
          "ArrowDown"
        ) {
          event.preventDefault();

          if (
            !wrapper.classList.contains(
              "open"
            )
          ) {
            wrapper.classList.add(
              "open"
            );

            glpSearchableSelectRender(
              select,
              wrapper,
              input,
              menu,
              input.value
            );

            visible =
              Array.from(
                menu.querySelectorAll(
                  ".glp-search-select-option"
                )
              );

            activeIndex =
              -1;
          }

          visible.forEach(
            function (
              row
            ) {
              row.classList.remove(
                "active"
              );
            }
          );

          if (
            visible.length
          ) {
            activeIndex =
              Math.min(
                activeIndex + 1,
                visible.length - 1
              );

            visible[
              activeIndex
            ].classList.add(
              "active"
            );

            visible[
              activeIndex
            ].scrollIntoView(
              {
                block:
                  "nearest"
              }
            );
          }

        } else if (
          event.key ===
          "ArrowUp"
        ) {
          event.preventDefault();

          visible.forEach(
            function (
              row
            ) {
              row.classList.remove(
                "active"
              );
            }
          );

          if (
            visible.length
          ) {
            activeIndex =
              activeIndex < 0
                ? visible.length - 1
                : Math.max(
                    activeIndex - 1,
                    0
                  );

            visible[
              activeIndex
            ].classList.add(
              "active"
            );

            visible[
              activeIndex
            ].scrollIntoView(
              {
                block:
                  "nearest"
              }
            );
          }

        } else if (
          event.key ===
          "Enter"
        ) {
          if (
            wrapper.classList.contains(
              "open"
            )
          ) {
            var active =
              menu.querySelector(
                ".glp-search-select-option.active"
              ) ||
              menu.querySelector(
                ".glp-search-select-option"
              );

            if (
              active
            ) {
              event.preventDefault();

              active.dispatchEvent(
                new MouseEvent(
                  "mousedown",
                  {
                    bubbles:
                      true
                  }
                )
              );
            }
          }

        } else if (
          event.key ===
          "Escape"
        ) {
          wrapper.classList.remove(
            "open"
          );

          glpSearchableSelectSync(
            select
          );
        }
      }
    );

    input.addEventListener(
      "blur",
      function () {
        setTimeout(
          function () {
            wrapper.classList.remove(
              "open"
            );

            /*
              If user typed text but did not choose an option, restore
              the actual selected value.
            */
            glpSearchableSelectSync(
              select
            );
          },
          150
        );
      }
    );

    arrow.addEventListener(
      "mousedown",
      function (
        event
      ) {
        event.preventDefault();

        if (
          select.disabled
        ) {
          return;
        }

        if (
          wrapper.classList.contains(
            "open"
          )
        ) {
          wrapper.classList.remove(
            "open"
          );

        } else {
          glpSearchableSelectCloseAll(
            wrapper
          );

          wrapper.classList.add(
            "open"
          );

          glpSearchableSelectRender(
            select,
            wrapper,
            input,
            menu,
            ""
          );

          input.focus();
        }
      }
    );

    select.addEventListener(
      "change",
      function () {
        glpSearchableSelectSync(
          select
        );
      }
    );

    /*
      React to code that changes disabled/required on the original select.
    */
    try {
      var observer =
        new MutationObserver(
          function () {
            glpSearchableSelectSync(
              select
            );

            glpSearchableSelectRender(
              select,
              wrapper,
              input,
              menu,
              input.value
            );
          }
        );

      observer.observe(
        select,
        {
          attributes:
            true,
          childList:
            true,
          subtree:
            true,
          attributeFilter:
            [
              "disabled",
              "required",
              "class",
              "style"
            ]
        }
      );
    } catch (_) {}
  }


  function enhanceGLPSearchableSelects(
    root
  ) {
    installGLPSearchableSelectStyles();

    var scope =
      root ||
      document.getElementById(
        "life-glp-app"
      );

    if (!scope) {
      return;
    }

    if (
      scope.matches &&
      scope.matches(
        "select"
      )
    ) {
      glpEnhanceOneSelect(
        scope
      );
    }

    scope
      .querySelectorAll(
        "select"
      )
      .forEach(
        glpEnhanceOneSelect
      );
  }


  function installGLPSearchableSelectObserver() {
    var root =
      document.getElementById(
        "life-glp-app"
      );

    if (!root) {
      return;
    }

    enhanceGLPSearchableSelects(
      root
    );

    if (
      root._glpSearchSelectObserver
    ) {
      return;
    }

    var observer =
      new MutationObserver(
        function (
          mutations
        ) {
          mutations.forEach(
            function (
              mutation
            ) {
              mutation.addedNodes.forEach(
                function (
                  node
                ) {
                  if (
                    !node ||
                    node.nodeType !==
                      1
                  ) {
                    return;
                  }

                  if (
                    node.matches &&
                    node.matches(
                      "select"
                    )
                  ) {
                    glpEnhanceOneSelect(
                      node
                    );
                  }

                  if (
                    node.querySelectorAll
                  ) {
                    node
                      .querySelectorAll(
                        "select"
                      )
                      .forEach(
                        glpEnhanceOneSelect
                      );
                  }
                }
              );
            }
          );
        }
      );

    observer.observe(
      root,
      {
        childList:
          true,
        subtree:
          true
      }
    );

    root._glpSearchSelectObserver =
      observer;

    document.addEventListener(
      "mousedown",
      function (
        event
      ) {
        if (
          !event.target.closest(
            ".glp-search-select"
          )
        ) {
          glpSearchableSelectCloseAll();
        }
      }
    );
  }


  /*
    Install once now and once after current render stack.
