      sel.innerHTML =
        '<option value="' +
          esc(rows[0]) +
        '">' +
          esc(rows[0]) +
        '</option>';

      STATE.branch =
        rows[0];

      sel.value =
        rows[0];

      sel.disabled = true;

    } else {
      sel.disabled = false;

      sel.innerHTML =
        '<option value="ALL">All branches</option>' +
        rows.map(function (b) {
          return (
            '<option value="' +
              esc(b) +
