  var SCHEMA = {};

  function frappeCall(method, args, timeoutMs) {
    return new Promise(function (resolve, reject) {
      if (!window.frappe || typeof frappe.call !== "function") {
        reject(new Error("frappe.call is not available"));
        return;
      }

      var finished = false;

      var timer = setTimeout(
        function () {
          if (finished) return;
          finished = true;

          reject(
            new Error(
              "ERPNext request timed out: " +
              method
            )
          );
        },
        timeoutMs || 20000
      );

      frappe.call({
        method: method,
        args: args || {},

        callback: function (r) {
          if (finished) return;

          finished = true;
          clearTimeout(timer);

          resolve(
            r ? r.message : null
          );
        },

        error: function (e) {
          if (finished) return;

          finished = true;
          clearTimeout(timer);

          reject(
            e ||
            new Error(
              "ERPNext request failed"
            )
          );
        }
      });
    });
  }

  function getListPage(doctype, fields, filters, orderBy, start, length) {
    return frappeCall("frappe.client.get_list", {
      doctype: doctype,
      fields: fields,
      filters: filters || [],
      order_by: orderBy || "modified desc",
      limit_start: start || 0,
      limit_page_length: length || 500
    });
  }

  function getFullDoc(doctype, name) {
    return frappeCall("frappe.client.get", {
      doctype: doctype,
      name: name
    });
  }

  /*
    Frappe requires the parent DocType when get_list is called
    directly on a child-table DocType. Without `parent`,
    check_parent_permission() returns HTTP 403.
  */
  function getChildListPage(
    parentDoctype,
    childDoctype,
    fields,
    filters,
    orderBy,
    start,
    length
  ) {
    return frappeCall(
      "frappe.client.get_list",
      {
        doctype: childDoctype,
        parent: parentDoctype,
        fields: fields,
        filters: filters || [],
        order_by:
          orderBy ||
          "modified desc",
        limit_start:
          start || 0,
        limit_page_length:
          length || 500
      }
    );
  }

  var SCHEMA_CACHE_PREFIX = "life_glp_schema_v522_";
  var SCHEMA_CACHE_TTL = 12 * 60 * 60 * 1000;

  function readCachedSchema(doctype) {
    try {
      var raw = localStorage.getItem(
        SCHEMA_CACHE_PREFIX + doctype
      );

      if (!raw) return null;

      var parsed = JSON.parse(raw);

      if (
        !parsed ||
        !parsed.savedAt ||
        (Date.now() - parsed.savedAt) > SCHEMA_CACHE_TTL
      ) {
        localStorage.removeItem(
          SCHEMA_CACHE_PREFIX + doctype
        );
        return null;
      }

      return parsed.schema || null;

    } catch (e) {
      return null;
    }
  }

  function saveCachedSchema(doctype, schema) {
    try {
      localStorage.setItem(
        SCHEMA_CACHE_PREFIX + doctype,
        JSON.stringify({
          savedAt: Date.now(),
          schema: schema
        })
      );
    } catch (e) {}
  }

  async function discoverDoctype(doctype) {
    var cached = readCachedSchema(doctype);

    if (cached) {
      return cached;
    }

    var spec = DATA_SPECS[doctype];

    var result = {
      exists: true,
      fields: ["name"],
      fieldSet: {name:true},
      branchField: "",
      dateField: ""
    };

    try {
      var names = await getListPage(
        doctype,
        ["name"],
        [],
        "modified desc",
        0,
        1
      );

      if (!names || !names.length) {
        saveCachedSchema(doctype, result);
        return result;
      }

      var sample = await getFullDoc(
        doctype,
        names[0].name
      );

      if (!sample) {
        saveCachedSchema(doctype, result);
        return result;
      }

      var set = {};

      Object.keys(sample).forEach(function (k) {
        set[k] = true;
      });

      result.fieldSet = set;

      result.fields = spec.fields.filter(function (f) {
        return !!set[f];
      });

      /*
        Patient mobile fields differ between ERPNext/Healthcare setups.
        Include any real mobile/phone/contact-number field found on the
        live Patient DocType instead of assuming one fixed field name.
      */
      if (doctype === "Patient") {
        Object.keys(sample).forEach(function (f) {
          if (
