  function resolveBranchesOnRows() {
    var patientByName = {};
    var patientByCustomer = {};
    var plansByPatient = {};
    var appointmentsByPatient = {};

    STATE.data.patients.forEach(function (p) {
      patientByName[p.name] = p;

      if (p.customer) {
        patientByCustomer[p.customer] = p;
      }
    });

    STATE.data.plans.forEach(function (p) {
      if (!p.patient) return;

      if (!plansByPatient[p.patient]) {
        plansByPatient[p.patient] = [];
      }

      plansByPatient[p.patient].push(p);
    });

    STATE.data.appointments.forEach(function (a) {
      if (!a.patient) return;

      if (!appointmentsByPatient[a.patient]) {
        appointmentsByPatient[a.patient] = [];
      }

      appointmentsByPatient[a.patient].push(a);
    });

    function patientBranch(patient) {
      if (!patient) return "";

      var own = directDetectedBranch(
        patient,
        "Patient"
      );

      if (own) return own;

      var plans = plansByPatient[patient.name] || [];

      for (var i = 0; i < plans.length; i++) {
        var pb = directDetectedBranch(
          plans[i],
          "Therapy Plan"
        );

        if (pb) return pb;
      }

      var appts =
        appointmentsByPatient[patient.name] || [];

      for (var j = 0; j < appts.length; j++) {
        var ab = directDetectedBranch(
          appts[j],
          "Patient Appointment"
        );

        if (ab) return ab;
      }

      return "";
    }

    STATE.data.patients.forEach(function (p) {
      p._branch = patientBranch(p);
    });

    STATE.data.plans.forEach(function (p) {
      p._branch =
        directDetectedBranch(p,"Therapy Plan") ||
        patientBranch(patientByName[p.patient]);
    });

    STATE.data.appointments.forEach(function (a) {
      a._branch =
        directDetectedBranch(
          a,
          "Patient Appointment"
        ) ||
        patientBranch(patientByName[a.patient]);
    });

    STATE.data.sessions.forEach(function (s) {
      s._branch =
        directDetectedBranch(
          s,
          "Therapy Session"
        ) ||
        patientBranch(patientByName[s.patient]);
    });

    STATE.data.invoices.forEach(function (i) {
      var patient =
        (i.patient && patientByName[i.patient]) ||
        (i.customer && patientByCustomer[i.customer]) ||
        null;

      i._branch =
        directDetectedBranch(
          i,
          "Sales Invoice"
        ) ||
        patientBranch(patient);
    });

    STATE.data.payments.forEach(function (p) {
      var patient =
        p.party
          ? patientByCustomer[p.party]
          : null;

      p._branch =
        directDetectedBranch(
          p,
          "Payment Entry"
        ) ||
        patientBranch(patient);
    });

    STATE.data.leads.forEach(function (l) {
      l._branch =
        directDetectedBranch(
          l,
          "Lead"
        );
    });
  }

