  function applyCurrentUserBranchScope() {
    var allowed =
      (STATE.userBranchScope || [])
        .filter(Boolean);

    if (!allowed.length) {
      return;
    }

    var allowedNorm =
      allowed.map(norm);

    var master =
      (
        STATE.allBranches &&
        STATE.allBranches.length
          ? STATE.allBranches
          : allowed
      );

    var scopedMaster =
      master.filter(function (b) {
        return (
          allowedNorm.indexOf(
            norm(b)
          ) >= 0
        );
      });

    if (!scopedMaster.length) {
      scopedMaster =
        allowed.slice();
    }

    STATE.allBranches =
      scopedMaster.slice();

    STATE.branches =
      scopedMaster.slice();

    if (
      STATE.userBranchLocked &&
      scopedMaster.length === 1
    ) {
      STATE.branch =
        scopedMaster[0];

      STATE.branchDetail = "";
    } else if (
      STATE.branch !== "ALL" &&
      allowedNorm.indexOf(
        norm(STATE.branch)
      ) < 0
    ) {
      STATE.branch = "ALL";
      STATE.branchDetail = "";
    }
  }

