  async function mapChunksLimited(
    chunks,
    concurrency,
    worker
  ) {
    var result = [];
    var cursor = 0;

    async function runner() {
      while (true) {
        var index = cursor++;

        if (index >= chunks.length) {
          return;
        }

        var rows =
          await worker(
            chunks[index],
            index
          );

        if (rows && rows.length) {
          result = result.concat(rows);
        }
      }
    }

    var jobs = [];
    var count =
      Math.min(
        concurrency || 2,
        chunks.length
      );

    for (var i = 0; i < count; i++) {
      jobs.push(runner());
    }

    await Promise.all(jobs);

    return result;
  }


