        Older already-submitted Therapy Plans can still contain:
          GLP-1 ... 1 Dose -> no_of_sessions = 1

        For ONLY that exact legacy condition, interpret 1 as 4 execution
        sessions. This is a floor/normalisation rule, NOT multiplication:
          1 -> 4
          4 -> 4
          8 -> 8
        so a corrected backend value can never become 16.
      */
      if (
        rowPlanned === 1 &&
        isGLPDoseTherapyName(
          therapyLabel
        )
      ) {
        rowPlanned =
          GLP_INJECTIONS_PER_DOSE;
      }

      planned += rowPlanned;

      /*
        Completed is NOT multiplied. One saved Therapy Session equals
        one actual injection execution.
      */
      completed +=
        firstNumericField(
          row,
          completedFields
        );
    });

    var allRowsAreGLP =
      therapyRows.length > 0 &&
      glpRows.length ===
        therapyRows.length;

    /*
      Safe fallback only when every therapy row in the plan is GLP.
      In that case Therapy Plan.total_sessions cannot contain a
      non-GLP therapy session.
    */
    if (
      planned <= 0 &&
      allRowsAreGLP &&
      n(doc && doc.total_sessions) > 0
    ) {
      planned =
        n(doc.total_sessions);
    }

    if (
      completed <= 0 &&
      allRowsAreGLP &&
      n(doc && doc.total_sessions_completed) > 0
    ) {
      completed =
        n(doc.total_sessions_completed);
    }

    return {
      planned: planned,
      completed: completed,
      allRowsAreGLP: allRowsAreGLP,
      therapyTypes:
        glpRows.map(function (row) {
          return (
            row.therapy_type ||
            row.therapy_type_name ||
            row.therapy ||
            row.item_name ||
            row.item_code ||
            row.item ||
            "GLP Therapy"
          );
        }).filter(Boolean)
    };
  }

