              plan._glp_planned_sessions =
                info.planned;

              plan._glp_child_completed_sessions =
                info.completed;

              plan._all_therapy_rows_are_glp =
                info.allRowsAreGLP;

              if (
                info.therapyTypes &&
                info.therapyTypes.length
              ) {
                plan._glp_therapy_types =
                  Array.from(
                    new Set(
                      info.therapyTypes
                    )
                  );
