  }

  async function loadGLPTherapySessionsStrict() {
    var schema =
      SCHEMA[
        "Therapy Session"
      ];

    if (
      !schema ||
      !schema.exists
    ) {
      STATE.glpTherapySessions = [];
      STATE.glpDoseSessions = [];
      STATE.data.sessions = [];
      return [];
    }

    var rows = [];
    var planLinkedRows = [];
    var planField = "";

    [
      "therapy_plan",
      "custom_therapy_plan",
      "therapy_plan_1"
    ].some(function (f) {
      if (
        schema.fieldSet &&
        schema.fieldSet[f]
      ) {
        planField = f;
        return true;
      }

      return false;
    });

    /*
      IMPORTANT FOR SESSION PROGRESS:
      Do NOT apply the dashboard From/To date here.
      Progress is lifetime progress of the selected GLP Therapy Plan.
      The selected date range is applied later only to Doses Given KPI.
    */
    if (
      planField &&
      STATE.glpPlanIds.length
    ) {
      var planChunks =
        chunkArray(
          STATE.glpPlanIds,
          150
        );

      var byPlan =
        await mapChunksLimited(
          planChunks,
          2,
          async function (ids) {
            try {
              return await getAllRows(
                "Therapy Session",
                schema.fields,
                [
                  [
                    planField,
                    "in",
                    ids
                  ]
                ],
                "modified desc",
                1000
              );
            } catch (e) {
              void 0;
              return [];
            }
          }
        );

      planLinkedRows =
        byPlan || [];

      rows = rows.concat(
        planLinkedRows
      );
    }

    /*
      Compatibility fallback for older Therapy Sessions where therapy_plan
      was not populated.

      PERFORMANCE:
      The old code fetched every session twice: once by Therapy Plan and
      again by Patient + Therapy Type. Now Patient fallback runs only for
      Therapy Plans that returned no plan-linked rows.
    */
    if (
      schema.fieldSet &&
      schema.fieldSet.patient &&
      schema.fieldSet.therapy_type &&
      STATE.glpPatientIds.length
    ) {
      var typeNames =
        glpTherapyTypeNames();

      if (typeNames.length) {
        var fallbackPatientIds =
          STATE.glpPatientIds.slice();

        if (
          planField &&
          planLinkedRows.length
        ) {
          var linkedPlanIds =
            new Set(
              planLinkedRows
                .map(function (s) {
                  return s &&
                    s[planField];
                })
                .filter(Boolean)
            );

          fallbackPatientIds =
            (STATE.glpPlans || [])
              .filter(function (p) {
                return (
                  p &&
                  p.patient &&
                  !linkedPlanIds.has(
                    p.name
                  )
                );
              })
              .map(function (p) {
                return p.patient;
              })
              .filter(Boolean);

          fallbackPatientIds =
            Array.from(
              new Set(
                fallbackPatientIds
              )
            );
        }

        var patientChunks =
          chunkArray(
            fallbackPatientIds,
            150
          );

        var byPatient =
          await mapChunksLimited(
            patientChunks,
            2,
            async function (ids) {
              try {
                return await getAllRows(
                  "Therapy Session",
                  schema.fields,
                  [
                    [
                      "patient",
                      "in",
                      ids
                    ],
                    [
                      "therapy_type",
                      "in",
                      typeNames
                    ]
                  ],
                  "modified desc",
                  1000
                );
              } catch (e) {
                void 0;
                return [];
              }
            }
          );

        rows = rows.concat(
          byPatient || []
        );
      }
    }

    rows =
      uniqueRowsByName(
        rows || []
      );

    rows.forEach(function (s) {
      s._branch =
        therapySessionBranchStrict(s);
    });

    STATE.glpTherapySessions =
      rows.filter(function (s) {
        return (
          therapySessionIsCompleted(s) &&
          isGLPTherapySession(s)
        );
      });

    /*
      Executive Command Doses Given must remain dose/injection-only
      AND inside the selected dashboard date range.
    */
    STATE.glpDoseSessions =
      STATE.glpTherapySessions
        .filter(
          isGLPDoseSession
        )
        .filter(function (s) {
          var d =
            therapySessionDateISO(s);

          return !!(
            d &&
            d >= STATE.from &&
            d <= STATE.to
          );
        });

    STATE.data.sessions =
      STATE.glpTherapySessions.slice();

    void 0;

    return STATE.glpDoseSessions;
  }

  async function loadGLPProgrammeData() {
    await loadProgrammeRecordsFast();

    var linkedPlans =
      await loadPlansFromProgrammeRecords();

    if (!linkedPlans.length) {
      await loadGLPTherapyPlans();
    }

    var plans =
      STATE.glpPlans || [];

    /*
      VERY FAST VISIBLE PAINT:
      As soon as strict GLP plans/programme records are identified, replace
      the full-page spinner. Financial/session/appointment figures continue
      loading and then refresh the same page.

      This is intentionally a provisional summary; no fake/demo values are
      inserted.
    */
    STATE.summary = {
      leads:
        programmeRecordLeadIdSet().size,
      converted:
        strictGLPConvertedLeadCount(),
      patients:
        glpClientIdSet().size,
      plans:
        plans.length,
      activePlans:
        strictActiveClientIdSet().size,
      sessions: 0,
      appts: 0,
      completedAppts: 0,
      missedAppts: 0,
      upcoming30: 0,
      invoices: 0,
      payments: 0,
      gross: 0,
      dues: 0,
      collected: 0,
      collectionRate: 0,
      totalSessions: 0,
      completedSessions: 0,
      adherence: 0,
      programme:
        programmeRecordMetrics(),
      dueClients: 0,
      stockCover: null,
      avgWeightLoss: null
    };

    STATE.data.plans =
      plans;

    applyStrictGLPBranches();

    if (
      STATE.view === "dashboard"
    ) {
      setBranches();
      render();

      void 0;
    }

    /*
      Load the remaining schemas only after the page is already visible.
    */
    await prepareDashboardEnrichmentSchemaFast();

    /*
      Primary enrichment first. Do NOT run full Therapy Plan document loads
      concurrently with these requests.
    */
    var loaded =
      await Promise.all([
        loadDashboardBranchInvoices(),
        loadGLPAppointmentsBundle(),
        loadGLPTherapySessionsStrict()
      ]);

    var invoiceRows =
      loaded[0] || [];

    /*
      Keep GLP revenue correct. Invoice item rows are fetched in one batched
      child-table request rather than loading full invoices one by one.
    */
    await loadGLPInvoiceItemAmounts(
      invoiceRows
    );

    var appointmentBundle =
      loaded[1] || {
        selected:[],
        upcoming:[]
      };

    var selectedAppointments =
      appointmentBundle.selected ||
      [];

    var upcomingAppointments =
      appointmentBundle.upcoming ||
      [];

    var doseSessions =
      loaded[2] || [];

    var apptMap = {};

    selectedAppointments
      .concat(
        upcomingAppointments
      )
      .forEach(function (a) {
        if (a && a.name) {
          a._branch =
            appointmentBranchStrict(a);

          apptMap[a.name] = a;
        }
      });

    STATE.glpAppointments =
      Object.keys(apptMap)
        .map(function (name) {
          return apptMap[name];
        });

    var gross =
      invoiceRows.reduce(
        function (s, i) {
          return s +
            glpInvoiceAmount(i);
        },
        0
      );

    var dues =
      invoiceRows.reduce(
        function (s, i) {
          return s +
            glpInvoicePending(i);
        },
        0
      );

    var collected =
      invoiceRows.reduce(
        function (s, i) {
          return s +
            glpInvoiceCollected(i);
        },
        0
      );

    var completedDoseCount =
      doseSessions.reduce(
        function (sum,s) {
          return sum +
            Math.max(
              1,
              n(
                s.sessions_quantity ||
                s.session_qty ||
                s.qty ||
                1
              )
            );
        },
        0
      );

    var missedDoseCount =
      strictMissedDoseAppointments()
        .length;

    var bookedDoseCount =
      strictBookedDoseAppointments30()
        .length;

    var adherence =
      pct(
        completedDoseCount,
        completedDoseCount +
        missedDoseCount
      );

    var strictLeadIds =
      programmeRecordLeadIdSet();

    STATE.summary = {
      leads:
        strictLeadIds.size,

      converted:
        strictGLPConvertedLeadCount(),

      patients:
        glpClientIdSet().size,

      plans:
        plans.length,

      activePlans:
        strictActiveClientIdSet().size,

      sessions:
        completedDoseCount,

      appts:
        selectedAppointments.length,

      completedAppts:
        completedDoseCount,

      missedAppts:
        missedDoseCount,

      upcoming30:
        bookedDoseCount,

      invoices:
        invoiceRows.length,

      payments:
        0,

      gross:
        gross,

      dues:
        dues,

      collected:
        collected,

      collectionRate:
        pct(
          collected,
          gross
        ),

      totalSessions:
        completedDoseCount +
        missedDoseCount,

      completedSessions:
        completedDoseCount,

      adherence:
        adherence,

      programme:
        programmeRecordMetrics(),

      dueClients:
        strictGLPClientDueCount(),

      stockCover:
        strictStockCoverDays(
          STATE.branch
        ),

      avgWeightLoss:
        strictAverageWeightLoss(
          STATE.branch
        )
    };

    STATE.glpInvoices =
      invoiceRows;

    STATE.dashboardBranchInvoices =
      invoiceRows;

    STATE.data.plans =
      plans;

    STATE.data.invoices =
      invoiceRows.slice();

    STATE.data.appointments =
      STATE.glpAppointments.slice();

    applyStrictGLPBranches();

    /*
      Detailed per-plan progress is the last enrichment. Starting it here,
      after the main dashboard data has loaded, prevents it from slowing the
      initial/API-critical requests.
    */
    STATE._planTotalsPromise =
      loadGLPPlanSessionTotals()
        .catch(function (e) {
          void 0;
        });

    if (
      STATE.view === "dashboard"
    ) {
      render();
    }

    void 0;

    return STATE.summary;
  }

