  function addObservedBranches() {
    var set = {};

    STATE.branches.forEach(function (b) {
      if (b && !isExcludedBranch(b)) {
        set[b] = true;
      }
    });

    Object.keys(STATE.data).forEach(function (key) {
      (STATE.data[key] || []).forEach(function (row) {
        if (
          row &&
          row._branch &&
          !isExcludedBranch(row._branch)
        ) {
          set[row._branch] = true;
        }
      });
    });

    STATE.branches =
      Object.keys(set).sort(function (a,b) {
        return a.localeCompare(b);
      });

    if (
      STATE.branch !== "ALL" &&
      (
        STATE.branches.indexOf(STATE.branch) < 0 ||
        isExcludedBranch(STATE.branch)
      )
    ) {
      STATE.branch = "ALL";
    }
  }

