  async function loadFullViewFast(view) {
    if (
      view === "usedstock"
    ) {
      await glpLoadUsedStockV580();
      STATE.loadedViews.usedstock = true;
      return;
    }

    if (
      view === "followups" ||
      view === "stock" ||
      view === "pens" ||
      view === "adverse"
    ) {
      await loadProgrammeRecordsFast();
    }

    if (view === "invoices") {
      await loadInvoicePageFast(
        STATE.invoicePage
      );
      return;
    }

    if (view === "plans") {
      STATE.data.plans =
        (STATE.glpPlans || [])
          .slice();

      STATE.loadedViews.plans = true;
      return;
    }

    if (view === "appointments") {
      STATE.data.appointments =
        await loadGLPAppointmentRowsRobust(
          true,
          "appointment_date desc",
          1000
        );

      await loadAppointmentStockFast(
        STATE.data.appointments
      );

      STATE.loadedViews.appointments = true;
      return;
    }

    if (view === "patients") {
      await ensureSchemaFast(
        "Patient"
      );

      var glpIds =
        Array.from(
          glpClientIdSet()
        );

      if (!glpIds.length) {
        STATE.data.patients = [];

      } else {
        var patientChunks =
          chunkArray(
            glpIds,
            150
          );

        STATE.data.patients =
          await mapChunksLimited(
            patientChunks,
            2,

            async function (ids) {
              try {
                return await getAllRows(
                  "Patient",
                  SCHEMA["Patient"].fields,
                  [
                    [
                      "name",
                      "in",
                      ids
                    ]
                  ],
                  "modified desc",
                  500
                );

              } catch (e) {
                void 0;

                return [];
              }
            }
          );

        STATE.data.patients =
          uniqueRowsByName(
            STATE.data.patients
          )
          .filter(
            isGLPClientRecord
          );

        STATE.data.patients.forEach(
          function (p) {
            var direct =
              directDetectedBranch(
                p,
                "Patient"
              );

            var rec =
              (STATE.programmeRecords || [])
                .find(function (r) {
                  return (
                    r.client ===
                      p.name &&
                    r.branch
                  );
                });

            var plan =
              (STATE.glpPlans || [])
                .find(function (x) {
                  return (
                    x.patient ===
                    p.name
                  );
                });

            p._branch =
              direct ||
              (
                rec &&
                rec.branch
              ) ||
              planBranchStrict(
                plan
              ) ||
              "";
          }
        );
      }

      STATE.loadedViews.patients = true;
      return;
    }

    if (view === "assessment") {
      /*
        V5.75 FAST ASSESSMENT OPEN
        -------------------------
        New Assessment does NOT need the full GLP programme dataset,
        programme records, Sales Invoices, Appointments, Therapy Sessions,
        or the old 2,000-row Employee master before it can render.

        consultation_employee is Link -> Healthcare Practitioner, so the old
        Employee load was redundant. Load only the small masters actually
        required by the assessment form, and load them in parallel.
      */

      STATE.data.leads =
        STATE.assessmentLead
          ? STATE.data.leads
          : [];

      var assessmentJobs = [];

      if (
        !STATE.glpTherapyTypes ||
        !STATE.glpTherapyTypes.length
      ) {
        assessmentJobs.push(
          loadTherapyTypesFast()
        );
      }

      if (
        !STATE.assessmentLeadSources ||
        !STATE.assessmentLeadSources.length
      ) {
        assessmentJobs.push(
          loadAssessmentLeadSourcesFast()
        );
      }

      if (
        !STATE.assessmentPractitioners ||
        !STATE.assessmentPractitioners.length
      ) {
        assessmentJobs.push(
          loadAssessmentPractitionersV564()
        );
      }

      if (assessmentJobs.length) {
        await Promise.all(
          assessmentJobs.map(function (job) {
            return Promise.resolve(job).catch(function (e) {
              void 0;
              return null;
            });
          })
        );
      }

      /*
        The current Consultation Employee field uses Healthcare Practitioner.
        Keep the legacy Employee cache empty so it cannot slow assessment open
        or accidentally feed an HR-EMP-* value into the practitioner link.
      */
      STATE.assessmentEmployees = [];

      STATE.loadedViews.assessment = true;
      return;
    }

    if (view === "leads") {
      /*
        Enquiries page = Slimming pipeline.
        Do NOT require a GLP Programme Record here because an enquiry
        exists before enrolment/assessment. Source is Lead > Treatment Interests.
      */
      var leadFilters =
        baseServerFilters(
          "Lead",
          true
        );

      if (
        fieldExists(
          "Lead",
          "custom_treatment_interests"
        )
      ) {
        leadFilters.push([
          "custom_treatment_interests",
          "like",
          "%Slimming%"
        ]);
      }

      try {
        STATE.data.leads =
          await getAllRows(
            "Lead",
            SCHEMA["Lead"].fields,
            leadFilters,
            DATA_SPECS["Lead"].order,
            1000
          );
      } catch (e) {
        void 0;
        STATE.data.leads = [];
      }

      STATE.data.leads =
        uniqueRowsByName(
          STATE.data.leads
        );

      STATE.data.leads.forEach(
        function (l) {
          l._branch =
            directDetectedBranch(
              l,
              "Lead"
            ) || "";
        }
      );

      await resolveLeadOwnerNames(
        STATE.data.leads
      );

      STATE.loadedViews.leads = true;
      return;
    }
  }

  async function ensureSchemaFast(doctype) {
    if (
      SCHEMA[doctype] &&
      SCHEMA[doctype].exists !== false
    ) {
      return SCHEMA[doctype];
    }

    SCHEMA[doctype] =
      await discoverDoctype(
        doctype
      );

    return SCHEMA[doctype];
  }

  async function prepareSchemaFast() {
    /*
      FIRST PAINT ONLY:
      GLP Programme Record + Therapy Plan are the only schemas required
      before we can identify the programme/client base.
    */
    var doctypes = [
      "Therapy Plan",
      "GLP Programme Record"
    ];

    var discoveries =
      await Promise.all(
        doctypes.map(
          discoverDoctype
        )
      );

    doctypes.forEach(
      function (dt, i) {
        SCHEMA[dt] =
          discoveries[i];
      }
    );
