  async function loadData() {
    var loadSignature =
      [
        STATE.branch,
        STATE.from,
        STATE.to
      ].join("|");

    if (
      STATE._loadingData &&
      STATE._loadingSignature ===
        loadSignature
    ) {
      void 0;

      return;
    }

    STATE._loadingData = true;
    STATE._loadingSignature =
      loadSignature;

    CONTENT.innerHTML =
      '<div class="glp-loading">' +
        '<span class="glp-spinner"></span>' +
        '<div>' +
          '<b>Opening GLP-1 dashboard...</b>' +
          '<span>Loading only GLP programme data.</span>' +
        '</div>' +
      '</div>';

    var loadStartedAt =
      (
        window.performance &&
        performance.now
      )
        ? performance.now()
        : Date.now();

    try {
      /*
        These values do not change when the user clicks Apply, Reset,
        changes branch or changes date. Load them only once per page session.
      */
      if (!STATE._bootstrapReady) {
        await Promise.all([
          prepareSchemaFast(),
          loadBranchMaster(),
          loadCurrentUserFast(),
          loadCurrentUserBranchScopeFast()
        ]);

        STATE._bootstrapReady =
          true;
        STATE._branchScopeReady =
          true;
      } else if (
        !STATE._branchScopeReady
      ) {
        await loadCurrentUserBranchScopeFast();

        STATE._branchScopeReady =
          true;
      }

      applyCurrentUserBranchScope();

      setUser();

      await loadGLPProgrammeData();

      if (
        STATE.view !== "dashboard"
      ) {
        await loadFullViewFast(
          STATE.view
        );
      }

      setBranches();
      render();

      var firstPaintAt =
        (
          window.performance &&
          performance.now
        )
          ? performance.now()
          : Date.now();

      STATE._lastFastLoadMs =
        Math.round(
          firstPaintAt -
          loadStartedAt
        );

      void 0;

      /*
        When the detailed Therapy Plan totals finish, update progress values
        without making the user wait on the loading screen.
      */
      var enrichment =
        STATE._planTotalsPromise;

      if (enrichment) {
        Promise.resolve(
          enrichment
        ).then(function () {
          if (
            STATE._loadingSignature ===
              loadSignature
          ) {
            render();

            void 0;
          }
        });
      }

      void 0;

    } catch (e) {
      void 0;

      CONTENT.innerHTML =
        '<div class="glp-empty">' +
          '<b>Dashboard could not open.</b><br>' +
          'Send the first red GLP Dashboard console error.' +
        '</div>';

    } finally {
      STATE._loadingData = false;
    }
  }


