  function glpDoseText(value) {
    return norm(
      String(value || "")
        .replace(/[-_/]+/g," ")
    );
  }

  function isGLPDoseTherapyName(value) {
    var s =
      glpDoseText(value);

    if (!s) return false;

    return (
      /\bdose\b/.test(s) ||
      /\binj\b/.test(s) ||
      /\binjection\b/.test(s) ||
      /\binjectable\b/.test(s)
    );
  }

  function appointmentTherapyLabel(a) {
    if (!a) return "";

    return (
      a.therapy_type ||
      a.therapy_type1 ||
      a.concern ||
      a.appointment_type ||
      ""
    );
  }

  function isGLPDoseAppointment(a) {
    return isGLPDoseTherapyName(
      appointmentTherapyLabel(a)
    );
  }

  function therapySessionDateISO(s) {
    if (!s) return "";

    return String(
      s.custom_actual_session_date ||
      s.session_date ||
      s.start_date ||
      s.end_date ||
      s.creation ||
      ""
    ).slice(0,10);
  }

  function therapySessionIsCompleted(s) {
    if (!s) return false;

    /*
      Therapy Session is commonly NON-SUBMITTABLE in Healthcare, so a
      successfully saved execution can legitimately remain docstatus = 0.
      One saved GLP execution therefore counts unless it was cancelled.
    */
    if (Number(s.docstatus) === 2) {
      return false;
    }

    var status = norm(s.status);

    if ([
      "cancelled",
      "canceled",
      "no show",
      "rejected"
    ].indexOf(status) >= 0) {
      return false;
    }

    return true;
  }

  function therapySessionTherapyLabel(s) {
    if (!s) return "";

    return (
      s.therapy_type ||
      s.concern ||
      s.appointment_type ||
      ""
    );
  }

  function isGLPTherapySession(s) {
    if (!s) return false;

    var therapyLabel =
      therapySessionTherapyLabel(s);

    if (
      therapyLabel &&
      valueMatchesGLPTherapy(
        therapyLabel
      )
    ) {
      return true;
    }

    var planId =
      therapySessionPlanId(s);

    var plan =
      planId &&
      STATE.glpPlanMap
        ? STATE.glpPlanMap[planId]
        : null;

    /*
      If the Therapy Session is linked to a strict GLP plan and its
      therapy type is blank, treat it as GLP. If a non-GLP therapy type
      is explicitly present, do not count it.
    */
    return !!(
      plan &&
      !therapyLabel &&
      (plan._glp_therapy_types || []).length
    );
  }

  function isGLPDoseSession(s) {
    return !!(
      isGLPTherapySession(s) &&
      isGLPDoseTherapyName(
        therapySessionTherapyLabel(s) ||
        (
          therapySessionPlanId(s) &&
          STATE.glpPlanMap[
            therapySessionPlanId(s)
          ] &&
          (
            STATE.glpPlanMap[
              therapySessionPlanId(s)
            ]._glp_therapy_types || []
          ).join(" ")
        ) ||
        ""
      )
    );
  }


  function therapySessionPlanId(s) {
    if (!s) return "";

    return (
      s.therapy_plan ||
      s.custom_therapy_plan ||
      s.therapy_plan_1 ||
      ""
    );
  }

  function appointmentPlanId(a) {
    if (!a) return "";

    return (
      a.therapy_plan ||
      a.custom_therapy_plan ||
      a.therapy_plan_1 ||
      ""
    );
  }

  function sessionBelongsToPlan(s, plan) {
    if (!s || !plan) return false;

    var sPlanId =
      therapySessionPlanId(s);

    if (sPlanId) {
      return sPlanId === plan.name;
    }

    if (
      !plan.patient ||
      s.patient !== plan.patient
    ) {
      return false;
    }

    var therapyLabel =
      therapySessionTherapyLabel(s);

    if (!therapyLabel) {
      var patientPlans =
        (STATE.glpPlans || [])
          .filter(function (p) {
            return p.patient ===
              plan.patient;
          });

      return patientPlans.length === 1;
    }

    return (
      plan._glp_therapy_types || []
    ).some(function (type) {
      return (
        norm(type) ===
          norm(therapyLabel) ||
        valueMatchesGLPTherapy(
          therapyLabel
        )
      );
    });
  }

  function glpSessionProgressForPlan(plan) {
    if (!plan) {
      return {done:0,total:0};
    }

    var done =
      (STATE.glpTherapySessions || [])
        .filter(function (s) {
          return sessionBelongsToPlan(
            s,
            plan
          );
        })
        .reduce(function (sum,s) {
          if (
            isGLPDoseSession(s)
          ) {
            return sum + 1;
          }

          return sum +
            Math.max(
              1,
              n(
                s.sessions_quantity ||
                s.session_qty ||
                s.qty ||
                1
              )
            );
        },0);

    /*
      If legacy Therapy Session links are missing, the Therapy Plan
      child table's GLP completed count is the safe fallback.
    */
    if (
      done <= 0 &&
      n(
        plan._glp_child_completed_sessions
      ) > 0
    ) {
      done =
        n(
          plan._glp_child_completed_sessions
        );
    }

    var total =
      n(
        plan._glp_planned_sessions
      );

    /*
      Same legacy guard at render time. The detailed Therapy Plan loader
      above normally normalises this already, but this prevents a temporary
      0 / 1 first paint while older plan data is still enriching.
    */
    if (
      total === 1 &&
      (plan._glp_therapy_types || [])
        .some(
          isGLPDoseTherapyName
        )
    ) {
      total =
        GLP_INJECTIONS_PER_DOSE;
    }

    var programmeRecord =
      (STATE.programmeRecords || [])
        .find(function (r) {
          return (
            r.therapy_plan ===
              plan.name ||
            (
              plan.patient &&
              r.client ===
                plan.patient
            )
          );
        });

    /*
      Dose total from GLP Programme Record is a valid fallback only
      when this plan's displayed GLP therapies are dose/injection types.
    */
    if (
      total <= 0 &&
      programmeRecord &&
      n(programmeRecord.total_doses) > 0 &&
      (plan._glp_therapy_types || [])
        .some(
          isGLPDoseTherapyName
        )
    ) {
      /*
        Programme Record.total_doses is still a commercial dose count.
        Use ×4 only as a temporary fallback when the full Therapy Plan
        execution count has not loaded yet.
      */
      total =
        n(
          programmeRecord.total_doses
        ) *
        GLP_INJECTIONS_PER_DOSE;
    }

    if (
      total <= 0 &&
      plan._all_therapy_rows_are_glp &&
      n(plan.total_sessions) > 0
    ) {
      total =
        n(plan.total_sessions);
    }

    if (
      total <= 0 &&
      done > 0
    ) {
      total = done;
    }

    return {
      done: done,
      total: total
    };
  }

  function nextGLPInjectionExecutionNumber(
    plan,
    therapyType
  ) {
    if (!plan) return 1;

    var done =
      (STATE.glpTherapySessions || [])
        .filter(function (s) {
          return (
            sessionBelongsToPlan(
              s,
              plan
            ) &&
            isGLPDoseSession(s) &&
            (
              !therapyType ||
              norm(
                therapySessionTherapyLabel(s)
              ) ===
                norm(therapyType)
            )
          );
        })
        .length;

    return done + 1;
  }

  function strictActiveClientIdSet() {
    var ids = new Set();

    (STATE.glpPlans || [])
      .forEach(function (p) {
        if (
          p.patient &&
          [
            "not started",
            "in progress"
          ].indexOf(
            norm(p.status)
          ) >= 0
        ) {
          ids.add(p.patient);
        }
      });

    (STATE.programmeRecords || [])
      .forEach(function (r) {
        if (
          r.client &&
          norm(r.overall_status) ===
            "active"
        ) {
          ids.add(r.client);
        }
      });

    return ids;
  }

  function strictGLPBranchSet() {
    var set = new Set();

    (STATE.programmeRecords || [])
      .forEach(function (r) {
        if (
          r.branch &&
          !isExcludedBranch(r.branch)
        ) {
          set.add(r.branch);
        }
      });

    (STATE.glpPlans || [])
      .forEach(function (p) {
        var b =
          planBranchStrict(p);

        if (
          b &&
          !isExcludedBranch(b)
        ) {
          set.add(b);
        }
      });

    (STATE.dashboardBranchInvoices || [])
      .forEach(function (i) {
        var b =
          invoiceBranchStrict(i);

        if (
          b &&
          !isExcludedBranch(b)
        ) {
          set.add(b);
        }
      });

    (STATE.glpAppointments || [])
      .forEach(function (a) {
        var b =
          appointmentBranchStrict(a);

        if (
          b &&
          !isExcludedBranch(b)
        ) {
          set.add(b);
        }
      });

    (STATE.glpDoseSessions || [])
      .forEach(function (s) {
        var b =
          therapySessionBranchStrict(s);

        if (
          b &&
          !isExcludedBranch(b)
        ) {
          set.add(b);
        }
      });

    return set;
  }

  function applyStrictGLPBranches() {
    var found =
      Array.from(
        strictGLPBranchSet()
      )
      .sort(function (a,b) {
        return a.localeCompare(b);
      });

    if (
      STATE.branch === "ALL" ||
      !STATE.glpBranches.length
    ) {
      STATE.glpBranches =
        found.slice();
    }

    STATE.branches =
      (
        STATE.glpBranches.length
          ? STATE.glpBranches
          : found
      ).slice();

    if (
      STATE.branch !== "ALL" &&
      STATE.branches.indexOf(
        STATE.branch
      ) < 0
    ) {
      STATE.branch = "ALL";
    }
  }

  function strictGLPClientDueCount() {
    var ids = new Set();

    (STATE.dashboardBranchInvoices || [])
      .filter(function (i) {
        return (
          glpInvoicePending(i) > 0
        );
      })
      .forEach(function (i) {
        var plan =
          STATE.glpPlanMap[
            i.therapy_plan_reference_id
          ];

        if (
          plan &&
          plan.patient
        ) {
          ids.add(plan.patient);
        }
      });

    return ids.size;
  }

