      );
  }

  function strictBookedDoseAppointments30() {
    var from =
      todayISO();

    var to =
      addDays(
        from,
        30
      );

    return (
      STATE.glpAppointments || []
    ).filter(function (a) {
      return (
        isGLPDoseAppointment(a) &&
        !appointmentDone(a) &&
        !appointmentMissed(a) &&
        a.appointment_date &&
        a.appointment_date >= from &&
        a.appointment_date <= to
      );
    });
  }

  function strictStockCoverDays(
    branch
  ) {
    var records =
      (STATE.programmeRecords || [])
        .filter(function (r) {
          return (
            !branch ||
            branch === "ALL" ||
            norm(r.branch) ===
              norm(branch)
          );
        });

    var available =
      records.reduce(
        function (sum,r) {
          return sum +
            n(r.doses_available);
        },
        0
      );

    var bookings =
      strictBookedDoseAppointments30()
        .filter(function (a) {
          return (
            !branch ||
            branch === "ALL" ||
            norm(
              appointmentBranchStrict(a)
            ) ===
              norm(branch)
          );
        })
        .length;

    if (!bookings) {
      return null;
    }

    return Math.round(
      available * 30 /
      bookings
    );
  }

  function strictWeightLossMap() {
    var baseline = {};
    var current = {};
    var result = {};

    (STATE.programmeRecords || [])
      .forEach(function (r) {
        if (
          r.client &&
          n(r.weight) > 0 &&
          baseline[r.client] ===
            undefined
        ) {
          baseline[r.client] =
            n(r.weight);
        }
      });

    (STATE.glpDoseSessions || [])
      .slice()
      .sort(function (a,b) {
        var ad =
          String(
            a.custom_actual_session_date ||
            a.session_date ||
            a.start_date ||
            a.creation ||
            ""
          );

        var bd =
          String(
            b.custom_actual_session_date ||
            b.session_date ||
            b.start_date ||
            b.creation ||
            ""
          );

        return bd.localeCompare(ad);
      })
      .forEach(function (s) {
        if (
          !s.patient ||
          current[s.patient] !==
            undefined
        ) {
          return;
        }

        var w =
          n(
            s.after_weight ||
            s.weight_after ||
            s.weight
          );

        if (w > 0) {
          current[s.patient] = w;
        }
      });

    Object.keys(baseline)
      .forEach(function (patient) {
        if (
          current[patient] > 0
        ) {
          result[patient] =
            Math.max(
              0,
              baseline[patient] -
              current[patient]
            );
        }
      });

    return result;
  }

  function strictAverageWeightLoss(
    branch
  ) {
    var map =
      strictWeightLossMap();

    var patients =
      new Set();

    (STATE.glpPlans || [])
      .forEach(function (p) {
        if (
          p.patient &&
          (
            !branch ||
            branch === "ALL" ||
            norm(
              planBranchStrict(p)
            ) ===
              norm(branch)
          )
        ) {
          patients.add(
            p.patient
          );
        }
      });

    (STATE.programmeRecords || [])
      .forEach(function (r) {
        if (
          r.client &&
          (
            !branch ||
            branch === "ALL" ||
            norm(r.branch) ===
              norm(branch)
          )
        ) {
          patients.add(
            r.client
          );
        }
      });

    var vals =
      Array.from(patients)
        .map(function (p) {
          return map[p];
        })
        .filter(function (v) {
          return (
            v !== undefined &&
            Number.isFinite(v)
          );
        });

    if (!vals.length) {
      return null;
    }

    return Math.round(
      (
        vals.reduce(
          function (a,b) {
            return a+b;
          },
          0
        ) /
        vals.length
      ) * 10
    ) / 10;
  }

