  function invoiceHeaderTotal(inv) {
    return n(
      inv &&
      (
        inv.grand_total ||
        inv.rounded_total
      )
    );
  }

  function glpInvoiceItemMatches(row) {
    if (!row) return false;

    return [
      row.item_code,
      row.item_name,
      row.description
    ].some(function (value) {
      return !!value &&
        valueMatchesGLPTherapy(value);
    });
  }

  async function loadGLPInvoiceItemAmounts(invoices) {
    invoices = invoices || [];

    var names = Array.from(
      new Set(
        invoices
          .map(function (i) {
            return i && i.name;
          })
          .filter(Boolean)
      )
    );

    if (!names.length) {
      return;
    }

    var amounts = STATE.glpInvoiceItemAmounts || {};
    var matched = STATE.glpInvoiceItemMatched || {};

    names.forEach(function (name) {
      amounts[name] = 0;
      matched[name] = false;
    });

    var chunks = chunkArray(names, 100);

    var rows = await mapChunksLimited(
      chunks,
      2,
      async function (ids) {
        try {
          return await getChildListPage(
            "Sales Invoice",
            "Sales Invoice Item",
            [
              "parent",
              "item_code",
              "item_name",
              "description",
              "qty",
              "rate",
              "amount",
              "net_amount",
              "base_net_amount"
            ],
            [["parent","in",ids]],
            "parent asc, idx asc",
            0,
            5000
          );
        } catch (e) {
          void 0;
          return [];
        }
      }
    );

    (rows || []).forEach(function (row) {
      if (!row || !row.parent) return;
      if (!glpInvoiceItemMatches(row)) return;

      matched[row.parent] = true;
      amounts[row.parent] =
        n(amounts[row.parent]) +
        n(
          row.net_amount ||
          row.amount ||
          row.base_net_amount
        );
    });

    STATE.glpInvoiceItemAmounts = amounts;
    STATE.glpInvoiceItemMatched = matched;

    void 0;
  }

  function glpInvoiceAmount(inv) {
    if (!inv || !inv.name) return 0;

    return n(
      STATE.glpInvoiceItemAmounts &&
      STATE.glpInvoiceItemAmounts[inv.name]
    );
  }

  function glpInvoiceHasMatchedAmount(inv) {
    return !!(
      inv &&
      inv.name &&
      STATE.glpInvoiceItemMatched &&
      STATE.glpInvoiceItemMatched[inv.name]
    );
  }

  function glpInvoicePending(inv) {
    var glpAmount = glpInvoiceAmount(inv);
    var invoiceTotal = invoiceHeaderTotal(inv);
    var invoicePending = Math.max(
      0,
      n(inv && inv.outstanding_amount)
    );

    if (!glpAmount || !invoiceTotal || !invoicePending) {
      return 0;
    }

    /*
      ERPNext stores outstanding at invoice level, not per item row.
      For mixed invoices, allocate the outstanding balance to the GLP
      package in the same proportion as the GLP line amount.
    */
    return Math.min(
      glpAmount,
      invoicePending * glpAmount / invoiceTotal
    );
  }

  function glpInvoiceCollected(inv) {
    return Math.max(
      0,
      glpInvoiceAmount(inv) -
      glpInvoicePending(inv)
    );
  }

  function branchSummaryRows() {
    var records =
      STATE.programmeRecords || [];

    var plans =
      STATE.glpPlans || [];

    var invoices =
      STATE.dashboardBranchInvoices || [];

    var branchNames =
      Array.from(
        strictGLPBranchSet()
      );

    if (
      STATE.branch !== "ALL"
    ) {
      branchNames =
        branchNames.filter(
          function (b) {
            return (
              norm(b) ===
              norm(STATE.branch)
            );
          }
        );
    }

    return branchNames
      .map(function (branch) {
        var key =
          norm(branch);

        var brRecords =
          records.filter(
            function (r) {
              return (
                norm(r.branch) ===
                key
              );
            }
          );

        var brPlans =
          plans.filter(
            function (p) {
              return (
                norm(
                  planBranchStrict(p)
                ) === key
              );
            }
          );

        var brInvoices =
          invoices.filter(
            function (i) {
              return (
                norm(
                  invoiceBranchStrict(i)
                ) === key
              );
            }
          );

        var clientIds =
          new Set();

        brPlans.forEach(function (p) {
          if (p.patient) {
            clientIds.add(p.patient);
          }
        });

        brRecords.forEach(function (r) {
          if (r.client) {
            clientIds.add(r.client);
          }
        });

        var activeIds =
          new Set();

        brPlans.forEach(function (p) {
          if (
            p.patient &&
            [
              "not started",
              "in progress"
            ].indexOf(
              norm(p.status)
            ) >= 0
          ) {
            activeIds.add(
              p.patient
            );
          }
        });

        brRecords.forEach(function (r) {
          if (
            r.client &&
            norm(r.overall_status) ===
              "active"
          ) {
            activeIds.add(
              r.client
            );
          }
        });

        var doseSessions =
          strictCompletedDoseSessions()
            .filter(function (s) {
              return (
                norm(
                  therapySessionBranchStrict(s)
                ) === key
              );
            });

        var dosesGiven =
          doseSessions.reduce(
            function (sum,s) {
              return sum +
                Math.max(
                  1,
                  n(
                    s.sessions_quantity ||
                    s.session_qty ||
                    s.qty ||
                    1
                  )
                );
            },
            0
          );

        var revenue =
          brInvoices.reduce(
            function (s,i) {
              return s +
                glpInvoiceAmount(i);
            },
            0
          );

        var dues =
          brInvoices.reduce(
            function (s,i) {
              return s +
                glpInvoicePending(i);
            },
            0
          );

        var collected =
          brInvoices.reduce(
            function (s,i) {
              return s +
                glpInvoiceCollected(i);
            },
            0
          );

        var collection =
          pct(
            collected,
            revenue
          );

        var dosesInStore =
          brRecords.reduce(
            function (s,r) {
              return s +
                n(
                  r.doses_available
                );
            },
            0
          );

        var cover =
          strictStockCoverDays(
            branch
          );

        var avgKg =
          strictAverageWeightLoss(
            branch
          );

        var serious =
          brRecords.filter(
            function (r) {
              return (
                Number(
                  r.adverse_event ||
                  0
                ) === 1 &&
                [
                  "severe",
                  "serious"
                ].indexOf(
                  norm(r.severity)
                ) >= 0
              );
            }
          ).length;

        var coldAlert =
          brRecords.some(
            function (r) {
              return [
                "warning",
                "failed"
              ].indexOf(
                norm(
                  r.cold_chain_status
                )
              ) >= 0;
            }
          );

        var position =
          (
            serious > 0 ||
            coldAlert ||
            (
              cover !== null &&
              cover < 21
            )
          )
            ? "Intervene"
            : (
                (
                  revenue > 0 &&
                  collection < 75
                )
                  ? "Watch"
                  : "On plan"
              );

        return {
          branch:
            branch,
          clients:
            clientIds.size,
          activePlans:
            activeIds.size,
          dosesGiven:
            dosesGiven,
          revenue:
            revenue,
          dues:
            dues,
          collected:
            collected,
          collection:
            collection,
          dosesInStore:
            dosesInStore,
          cover:
            cover,
          avgKg:
            avgKg,
          position:
            position
        };
      })
      .sort(function (a,b) {
        if (
          b.revenue !==
          a.revenue
        ) {
          return (
            b.revenue -
            a.revenue
          );
        }

        return a.branch
          .localeCompare(
            b.branch
          );
      });
  }

