  async function loadBranchDetailData(branch) {
    var leadPromise =
      Promise.resolve([]);

    var apptPromise =
      Promise.resolve([]);

    var patientPromise =
      Promise.resolve([]);

    try {
      var leadFilters =
        dateOnlyServerFilters(
          "Lead"
        );

      if (
        SCHEMA["Lead"] &&
        SCHEMA["Lead"].branchField
      ) {
        leadFilters.push([
          SCHEMA["Lead"].branchField,
          "=",
          branch
        ]);
      }

      leadPromise =
        fetchFastRows(
          "Lead",
          leadFilters,
          DATA_SPECS["Lead"].order,
          0,
          100
        ).then(function (rows) {
          rows = rows || [];

          if (
            !(
              SCHEMA["Lead"] &&
              SCHEMA["Lead"].branchField
            )
          ) {
            rows =
              rows.filter(function (r) {
                return (
                  norm(
                    directDetectedBranch(
                      r,
                      "Lead"
                    )
                  ) ===
                  norm(branch)
                );
              });
          }

          return resolveLeadOwnerNames(rows)
            .then(function () {
              return rows;
            });
        });

    } catch (e) {
      leadPromise =
        Promise.resolve([]);
    }

    try {
      var apptFilters =
        appointmentGLPBaseFilters(
          true
        );

      if (apptFilters) {
        apptFilters =
          apptFilters.slice();

        if (
          SCHEMA["Patient Appointment"] &&
          SCHEMA["Patient Appointment"].branchField
        ) {
          apptFilters.push([
            SCHEMA["Patient Appointment"].branchField,
            "=",
            branch
          ]);
        }

        apptPromise =
          getAllRows(
            "Patient Appointment",
            SCHEMA["Patient Appointment"].fields,
            apptFilters,
            "appointment_date desc",
            500
          ).then(function (rows) {
            rows = rows || [];

            if (
              !(
                SCHEMA["Patient Appointment"] &&
                SCHEMA["Patient Appointment"].branchField
              )
            ) {
              rows =
                rows.filter(function (r) {
                  return (
                    norm(
                      directDetectedBranch(
                        r,
                        "Patient Appointment"
                      )
                    ) ===
                    norm(branch)
                  );
                });
            }

            return rows;
          });
      }

    } catch (e2) {
      apptPromise =
        Promise.resolve([]);
    }

    try {
      await ensureSchemaFast(
        "Patient"
      );

      var patientIds =
        Array.from(
          new Set(
            branchPlanRows(branch)
              .map(function (p) {
                return p.patient;
              })
              .filter(Boolean)
              .concat(
                branchRecordRows(branch)
                  .map(function (r) {
                    return r.client;
                  })
                  .filter(Boolean)
              )
          )
        );

      if (patientIds.length) {
        var patientChunks =
          chunkArray(
            patientIds,
            150
          );

        patientPromise =
          mapChunksLimited(
            patientChunks,
            2,
            async function (ids) {
              try {
                return await getAllRows(
                  "Patient",
                  SCHEMA["Patient"].fields,
                  [
                    [
                      "name",
                      "in",
                      ids
                    ]
                  ],
                  "modified desc",
                  500
                );
              } catch (e) {
                void 0;
                return [];
              }
            }
          ).then(function (rows) {
            return uniqueRowsByName(
              rows || []
            );
          });
      }

    } catch (e3) {
      void 0;

      patientPromise =
        Promise.resolve([]);
    }

    var result =
      await Promise.all([
        leadPromise,
        apptPromise,
        patientPromise
      ]);

    STATE.branchDetailData = {
      leads:
        result[0] || [],
      appointments:
        result[1] || [],
      patients:
        result[2] || []
    };
  }

