  function addMonthsISO(iso, months) {
    var d = new Date(
      String(iso || todayISO()) + "T00:00:00"
    );

    d.setDate(1);
    d.setMonth(d.getMonth() + months);

    return (
      d.getFullYear() +
      "-" +
      String(d.getMonth() + 1).padStart(2,"0") +
      "-01"
    );
  }

  function monthEndISO(monthStartISO) {
    var d = new Date(
      String(monthStartISO) + "T00:00:00"
    );

    d.setMonth(d.getMonth() + 1);
    d.setDate(0);

    return (
      d.getFullYear() +
      "-" +
      String(d.getMonth() + 1).padStart(2,"0") +
      "-" +
      String(d.getDate()).padStart(2,"0")
    );
  }

  function monthLabelFromISO(iso) {
    if (!iso) return "—";
    var d = new Date(String(iso) + "T00:00:00");
    return d.toLocaleString("en-US", {
      month: "short",
      year: "2-digit"
    });
  }

  function demandPlannerData() {
    var pm =
      programmeRecordMetrics();

    var plans =
      STATE.glpPlans || [];

    var appointments =
      (STATE.glpAppointments || [])
        .filter(function (a) {
          return (
            STATE.branch === "ALL" ||
            norm(
              appointmentBranchStrict(a)
            ) ===
              norm(STATE.branch)
          );
        });

    var startBase =
      (STATE.from || todayISO()).slice(0,7) + "-01";

    var monthStarts = [
      addMonthsISO(startBase, 0),
      addMonthsISO(startBase, 1),
      addMonthsISO(startBase, 2),
      addMonthsISO(startBase, 3)
    ];

    var bookedByMonth = {};
    monthStarts.forEach(function (m) {
      bookedByMonth[m] = 0;
    });

    appointments
      .filter(
        isGLPDoseAppointment
      )
      .forEach(function (a) {
        var dt =
          String(
            a.appointment_date || ""
          ).slice(0,7) + "-01";

        if (
          bookedByMonth[dt] !==
          undefined
        ) {
          bookedByMonth[dt] += 1;
        }
      });

    var continuationByMonth = {};
    monthStarts.forEach(function (m) {
      continuationByMonth[m] = 0;
    });

    var activePlans =
      plans.filter(function (p) {
        return [
          "not started",
          "in progress"
        ].indexOf(
          norm(p.status)
        ) >= 0;
      });

    activePlans.forEach(function (p) {
      var remaining =
        Math.max(
          0,
          n(p.total_sessions) -
          n(p.total_sessions_completed)
        );

      if (!remaining) return;

      var dt =
        String(
          p.custom_next_session_date ||
          p.due_date ||
          p.start_date ||
          startBase
        ).slice(0,7) + "-01";

      if (
        continuationByMonth[dt] !==
        undefined
      ) {
        continuationByMonth[dt] += 1;
      } else {
        continuationByMonth[
          monthStarts[0]
        ] += 1;
      }
    });

    var months =
      monthStarts.map(function (m) {
        return {
          iso: m,
          label: monthLabelFromISO(m),
          booked:
            bookedByMonth[m] || 0,
          continuation:
            continuationByMonth[m] || 0,
          value:
            (bookedByMonth[m] || 0) +
            (continuationByMonth[m] || 0)
        };
      });

    var maxValue =
      months.reduce(function (mx, row) {
        return Math.max(mx, row.value);
      }, 0);

    maxValue = Math.max(maxValue, 1);

    var stockOnHand =
      pm.dosesAvailable || 0;

    var dueTotal =
      months.reduce(function (s,m) {
        return s + m.value;
      }, 0);

    var alerts = [];

    if (
      dueTotal > stockOnHand &&
      dueTotal > 0
    ) {
      alerts.push({
        kind: "warn",
        title: "Stock cover short",
        body:
          "Available " +
          stockOnHand +
          " doses against " +
          dueTotal +
          " due across this planning horizon. Raise indent before the month begins."
      });
    }

    (STATE.programmeRecords || [])
      .filter(function (r) {
        var opened =
          r.pen_open_date ||
          r.pen_start_date ||
          r.opened_on ||
          r.last_session_date;

        if (!opened) return false;

        var openDate =
          new Date(
            String(opened) + "T00:00:00"
          );

        var limit =
          new Date(openDate);
        limit.setDate(limit.getDate() + 28);

        return (
          limit < new Date() &&
          n(r.doses_available) > 0
        );
      })
      .slice(0,3)
      .forEach(function (r) {
        alerts.push({
          kind: "crit",
          title:
            "Open pen past 28-day limit — " +
            (r.pen_id || r.name),
          body:
            (r.client_name || r.client || "Client") +
            " · " +
            n(r.doses_available) +
            " doses still available."
        });
      });

    (STATE.programmeRecords || [])
      .filter(function (r) {
        return (
          Number(r.adverse_event || 0) === 1 &&
          ["severe","serious"].indexOf(
            norm(r.severity)
          ) >= 0
        );
      })
      .slice(0,4)
      .forEach(function (r) {
        alerts.push({
          kind: "crit",
          title:
            "Serious adverse event open — " +
            (r.client_name || r.client || r.name),
          body:
            String(
              r.adverse_event_note ||
              r.remarks ||
              "Requires doctor sign-off and review."
            )
        });
      });

    var approvalCount =
      (STATE.data.invoices || [])
        .filter(function (i) {
          return (
            submittedInvoice(i) &&
            glpInvoicePending(i) > 0
          );
        }).length;

    if (approvalCount > 0) {
      alerts.push({
        kind: "warn",
        title:
          approvalCount +
          " billing follow-ups waiting",
        body:
          "Outstanding invoices need collection action to keep branch positions on plan."
      });
    }

    if (!alerts.length) {
      alerts.push({
        kind: "ok",
        title: "No immediate alerts",
        body:
          "Current programme records do not show stock, safety or dues actions needing urgent attention."
      });
    }

    return {
      months: months,
      maxValue: maxValue,
      stockOnHand: stockOnHand,
      dueTotal: dueTotal,
      alerts: alerts.slice(0,7)
    };
  }

