  function isSlimmingEnquiry(l) {
    var treatment =
      String(
        (l && l.custom_treatment_interests) || ""
      ).toLowerCase();

    return (
      treatment.indexOf(
        "slimming"
      ) >= 0
    );
  }

  function enquiryStage(l) {
    var s = norm(leadStage(l));
    if (s === "converted") return "Converted";
    if (["lost","do not contact","junk"].includes(s)) return "Lost";
    if (["consultation done","consulted"].includes(s)) return "Consulted";
    if (["appointment booked","consultation booked"].includes(s)) return "Consultation Booked";
    if (["open","interested","contacted"].includes(s)) return "Contacted";
    return "New";
  }

  function enquiryClientDisplay(l) {
    var mobile =
      maskClientMobile(
        (l && (
          l.mobile_no ||
          l.phone
        )) ||
        ""
      );

    return [
      leadName(l),
      (
        mobile &&
        mobile.masked
      ) || "",
      (l && l.name) || ""
    ]
      .filter(Boolean)
      .join(" · ");
  }

  function enquiryClientSearchText(l) {
    return norm(
      [
        leadName(l),
        l && l.name,
        l && l.mobile_no,
        l && l.phone,
        enquiryClientDisplay(l)
      ].join(" ")
    );
  }

  function leadFiltered() {
    return scoped(STATE.data.leads).filter(function (l) {
      if (!isSlimmingEnquiry(l)) return false;

      var text = [
        l.name,
        leadName(l),
        l.mobile_no,
        l.phone,
        leadSource(l),
        l._branch,
        l._owner_name,
        l.custom_treatment_interests,
        l.custom_specific_interests,
        l.custom_remarks,
        enquiryStage(l)
      ].join(" ");

      var clientQuery =
        norm(
          STATE.leadClientFilter ||
          ""
        );

      var selectedClientId =
        String(
          STATE.leadClientSelectedId ||
          ""
        ).trim();

      var useClientQuery =
        clientQuery.length >= 3;

      var clientText =
        enquiryClientSearchText(l);

      return qmatch(text) &&
        (
          selectedClientId
            ? l.name === selectedClientId
            : (
                !useClientQuery ||
                clientText.indexOf(
                  clientQuery
                ) >= 0
              )
        ) &&
        (STATE.stage === "ALL" || enquiryStage(l) === STATE.stage) &&
        (STATE.source === "ALL" || norm(leadSource(l)) === norm(STATE.source));
    });
  }

  window.glpMoveLeadForward = async function (name) {
    var l = (STATE.data.leads || []).find(function (x) { return x.name === name; });
    if (!l) return;
    var next = {"New":"Open","Contacted":"Appointment Booked","Consultation Booked":"Consultation Done","Consulted":"Converted"}[enquiryStage(l)];
    if (!next) return toast("This enquiry cannot move further.");
    try {
      await frappeCall("frappe.client.set_value",{
        doctype:"Lead",name:name,
        fieldname:{status:next,custom_status_updated_date:todayISO()}
      });
      await loadFullViewFast("leads");
      render();
      toast("Enquiry moved forward");
    } catch (e) {
      glpSafeMessage("Could not move enquiry",glpRequestErrorMessage(e),true);
    }
