  function renderLeadPagination(
    page,
    totalPages,
    totalRows
  ) {
    var pageSize =
      STATE.leadPageSize ||
      15;

    if (
      totalRows <=
      pageSize
    ) {
      return "";
    }

    var buttons = "";

    buttons +=
      '<button type="button" class="glp-btn sm" data-enquiry-page="' +
      Math.max(
        1,
        page - 1
      ) +
      '"' +
      (
        page <= 1
          ? ' disabled'
          : ''
      ) +
      '>‹ Previous</button>';

    var fromPage =
      Math.max(
        1,
        page - 2
      );

    var toPage =
      Math.min(
        totalPages,
        page + 2
      );

    if (
      fromPage > 1
    ) {
      buttons +=
        '<button type="button" class="glp-btn sm" data-enquiry-page="1">1</button>';

      if (
        fromPage > 2
      ) {
        buttons +=
          '<span class="glp-page-dots">…</span>';
      }
    }

    for (
      var p = fromPage;
      p <= toPage;
      p++
    ) {
      buttons +=
        '<button type="button" class="glp-btn sm ' +
        (
          p === page
            ? 'primary'
            : ''
        ) +
        '" data-enquiry-page="' +
        p +
        '">' +
        p +
        '</button>';
    }

    if (
      toPage <
      totalPages
    ) {
      if (
        toPage <
        totalPages - 1
      ) {
        buttons +=
          '<span class="glp-page-dots">…</span>';
      }

      buttons +=
        '<button type="button" class="glp-btn sm" data-enquiry-page="' +
        totalPages +
        '">' +
        totalPages +
        '</button>';
    }

    buttons +=
      '<button type="button" class="glp-btn sm" data-enquiry-page="' +
      Math.min(
        totalPages,
        page + 1
      ) +
      '"' +
      (
        page >=
        totalPages
          ? ' disabled'
          : ''
      ) +
      '>Next ›</button>';

    return (
      '<div class="glp-pagination">' +
        '<div class="glp-pagination-info">' +
          pageSize +
          ' clients per page · Page ' +
          page +
          ' of ' +
          totalPages +
        '</div>' +
        '<div class="glp-pagination-buttons">' +
          buttons +
        '</div>' +
      '</div>'
    );
  }


