  function assessmentClientBranchScope() {
    var allowed =
      (STATE.userBranchScope || [])
        .filter(Boolean);

    if (
      STATE.userBranchLocked &&
      allowed.length === 1
    ) {
      return allowed.slice();
    }

    if (
      STATE.branch &&
      STATE.branch !== "ALL"
    ) {
      if (
        !allowed.length ||
        allowed.map(norm).indexOf(
          norm(STATE.branch)
        ) >= 0
      ) {
        return [STATE.branch];
      }
    }

    return allowed.slice();
  }

  function assessmentClientScopeLabel() {
    var branches =
      assessmentClientBranchScope();

    if (branches.length === 1) {
      return branches[0];
    }

    if (branches.length > 1) {
      return "your permitted branches";
    }

    return "the selected branch";
  }

  function assessmentGLPPlanForRecord(record) {
    if (!record) return null;

    if (
      record.therapy_plan &&
      STATE.glpPlanMap &&
      STATE.glpPlanMap[
        record.therapy_plan
      ]
    ) {
      return STATE.glpPlanMap[
        record.therapy_plan
      ];
    }

    if (record.client) {
      return (
        (STATE.glpPlans || [])
          .find(function (p) {
            return (
              p &&
              p.patient ===
                record.client
            );
          }) ||
        null
      );
    }

    return null;
  }

  function assessmentGLPLeadInfoMap() {
    var map = {};
    var branchScope =
      assessmentClientBranchScope();

    var branchNorm =
      branchScope.map(norm);

    (STATE.programmeRecords || [])
      .forEach(function (record) {
        if (
          !record ||
          !record.lead
        ) {
          return;
        }

        /*
          New Assessment client picker:
          a Programme Record alone is NOT enough.
          The client must already be connected to a real GLP Therapy Plan.
        */
        var plan =
          assessmentGLPPlanForRecord(
            record
          );

        if (!plan) {
          return;
        }

        var planBranch =
          planBranchStrict(plan) ||
          plan._branch ||
          record.branch ||
          "";

        if (
          branchNorm.length &&
          (
            !planBranch ||
            branchNorm.indexOf(
              norm(planBranch)
            ) < 0
          )
        ) {
          return;
        }

        map[record.lead] = {
          lead: record.lead,
          client:
            record.client ||
            plan.patient ||
            "",
          therapy_plan:
            plan.name ||
            record.therapy_plan ||
            "",
          branch: planBranch
        };
      });

    return map;
  }

  function assessmentGLPLeadIdSet() {
    return new Set(
      Object.keys(
        assessmentGLPLeadInfoMap()
      )
    );
  }

  function assessmentGLPLeadBranch(
    leadNameValue
  ) {
    var info =
      assessmentGLPLeadInfoMap()[
        leadNameValue
      ];

    return (
      info &&
      info.branch
    ) || "";
  }

  function assessmentSelectedLead() {
    if (!STATE.assessmentLead) {
      return null;
    }

    for (
      var i = 0;
      i < STATE.data.leads.length;
      i++
    ) {
      if (
        STATE.data.leads[i].name ===
        STATE.assessmentLead
      ) {
        return STATE.data.leads[i];
      }
    }

    return null;
  }

  async function searchAssessmentEnquiriesFast(
    query
  ) {
    query =
      String(
        query || ""
      ).trim();

    if (query.length < 3) {
      return [];
    }

    await ensureSchemaFast(
      "Lead"
    );

    var schema =
      SCHEMA["Lead"];

    if (
      !schema ||
      !schema.exists
    ) {
      return [];
    }

    var wantedFields = [
      "name",
      "first_name",
      "last_name",
      "lead_name",
      "mobile_no",
      "phone",
      "branch",
      "source",
      "lead_owner",
      "status",
      "custom_posting_date",
      "creation",
      "gender",
      "age",
      "date_of_birth",
      "height",
      "weight",
      "medical_history",
      "custom_bmi",
      "custom_target_weight",
      "custom_current_medication",
      "custom_previous_attempts"
    ];

    var fields =
      wantedFields.filter(
        function (f) {
          return (
            f === "name" ||
            (
              schema.fieldSet &&
              schema.fieldSet[f]
            )
          );
        }
      );

    if (
      fields.indexOf("name") < 0
    ) {
      fields.unshift("name");
    }

    var filters =
      baseServerFilters(
        "Lead",
        true
      );

    var glpLeadInfo =
      assessmentGLPLeadInfoMap();

    var allowedLeadIds =
      Object.keys(
        glpLeadInfo
      );

    /*
      This is intentionally NOT a general Lead search.
      Only Leads connected to an actual GLP Therapy Plan in the
      logged-in / selected branch are searchable here.
    */
    if (!allowedLeadIds.length) {
      return [];
    }

    filters.push([
      "name",
      "in",
      allowedLeadIds
    ]);

    var assessmentBranches =
      assessmentClientBranchScope();

    if (
      schema.fieldSet &&
      schema.fieldSet.branch &&
      assessmentBranches.length
    ) {
      filters.push([
        "branch",
        assessmentBranches.length === 1
          ? "="
          : "in",
        assessmentBranches.length === 1
          ? assessmentBranches[0]
          : assessmentBranches
      ]);
    }

    var like =
      "%" + query + "%";

    var searchable = [
      "first_name",
      "last_name",
      "lead_name",
      "mobile_no",
      "phone",
      "name",
      "branch"
    ].filter(
      function (f) {
        return (
          f === "name" ||
          (
            schema.fieldSet &&
            schema.fieldSet[f]
          )
        );
      }
    );

    var orFilters =
      searchable.map(
        function (fieldname) {
          return [
            "Lead",
            fieldname,
            "like",
            like
          ];
        }
      );

    var rows =
      await frappeCall(
        "frappe.client.get_list",
        {
          doctype:
            "Lead",
          fields:
            fields,
          filters:
            filters,
          or_filters:
            orFilters,
          order_by:
            DATA_SPECS["Lead"].order,
          limit_start:
            0,
          limit_page_length:
            25
        },
        12000
      );

    rows =
      rows || [];

    rows =
      rows.filter(
        function (l) {
          return (
            l &&
            glpLeadInfo[
              l.name
            ]
          );
        }
      );

    rows.forEach(
      function (l) {
        l._branch =
          assessmentGLPLeadBranch(
            l.name
          ) ||
          directDetectedBranch(
            l,
            "Lead"
          ) ||
          "";
      }
    );

    return rows;
  }

  async function loadSelectedAssessmentLeadFull(
    leadNameValue
  ) {
    if (!leadNameValue) {
      return null;
    }

    if (
      !assessmentGLPLeadIdSet().has(
        leadNameValue
      )
    ) {
      void 0;

      return null;
    }

    try {
      var full =
        await getFullDoc(
          "Lead",
          leadNameValue
        );

      if (!full) {
        return null;
      }

      full._branch =
        assessmentGLPLeadBranch(
          full.name
        ) ||
        directDetectedBranch(
          full,
          "Lead"
        ) ||
        full.branch ||
        "";

      var replaced = false;

      STATE.data.leads =
        (STATE.data.leads || [])
          .map(function (row) {
            if (
              row.name ===
              full.name
            ) {
              replaced = true;
              return full;
            }

            return row;
          });

      if (!replaced) {
        STATE.data.leads.unshift(
          full
        );
      }

      return full;

    } catch (e) {
      void 0;

      return null;
    }
  }

