  function refreshAssessmentEmployeeSelect(
    branch,
    preserveValue
  ) {
    /*
      V5.66 IMPORTANT:
      GLP Assessment.consultation_employee is Link -> Healthcare Practitioner.

      Therefore this select MUST store Healthcare Practitioner names
      (HLC-PRAC-...), not Employee IDs (HR-EMP-...).

      We keep the existing function name because older dashboard binding code
      already calls it when Branch changes.
    */
    var select =
      $(
        "ass-consultation-employee"
      );

    if (!select) {
      return;
    }

    branch =
      String(
        branch || ""
      ).trim();

    var options =
      glpAssessmentConsultationOptionsV564(
        branch,
        preserveValue ||
          select.value ||
          ""
      );

    var currentValue =
      String(
        preserveValue ||
        select.value ||
        ""
      ).trim();

    var currentStillValid =
      options.some(function (option) {
        return (
          String(option.value) ===
          currentValue
        );
      });

    if (!branch) {
      select.innerHTML =
        '<option value="">— select branch first —</option>';

      select.value = "";
      select.disabled = true;
      return;
    }

    select.disabled = false;

    select.innerHTML =
      '<option value="">— select practitioner —</option>' +
      options
        .map(function (option) {
          return (
            '<option value="' +
              esc(option.value) +
            '">' +
              esc(option.label) +
            '</option>'
          );
        })
        .join("");

    if (
      currentStillValid
    ) {
      select.value =
        currentValue;
    } else {
      select.value =
        "";
    }

    if (!options.length) {
      select.innerHTML =
        '<option value="">— no active practitioners available —</option>';

      select.value =
        "";

      /*
        Do not hard-disable here because permissions / branch metadata can
        vary across LIFE Healthcare Practitioner records.
      */
      select.disabled =
        false;
    }

    void 0;
  }

