  function assessmentEligibilityVisual() {
    var eligibility =
      assessmentValue("ass-eligibility") ||
      "Pending";

    var clearance =
      assessmentValue("ass-doctor-clearance") ||
      "Pending";

    var e = norm(eligibility);
    var c = norm(clearance);

    if (
      e === "not eligible" ||
      c === "rejected"
    ) {
      return {
        tone:"crit",
        title:"Red — do not proceed",
        text:"Eligibility or doctor clearance has been rejected. Review the clinical findings before programme enrolment."
      };
    }

    if (
      e === "eligible" &&
      c === "cleared"
    ) {
      return {
        tone:"ok",
        title:"Green — eligible",
        text:"Eligibility and doctor clearance are complete. Continue to consent and programme confirmation."
      };
    }

    if (e === "conditional") {
      return {
        tone:"warn",
        title:"Amber — doctor clearance",
        text:"Conditional eligibility. Doctor clearance and a clinical note should be completed before enrolment."
      };
    }

    return {
      tone:"warn",
      title:"Amber — assessment pending",
      text:"Complete screening, eligibility and doctor clearance before final programme enrolment."
    };
  }

  function recalculateAssessmentBMI() {
    var heightEl = $("ass-height");
    var weightEl = $("ass-weight");
    var bmiEl = $("ass-bmi");

    if (
      !heightEl ||
      !weightEl ||
      !bmiEl
    ) {
      return;
    }

    var height = n(heightEl.value);
    var weight = n(weightEl.value);

    if (
      height > 0 &&
      weight > 0
    ) {
      var metres = height / 100;
      bmiEl.value =
        (weight / (metres * metres))
          .toFixed(1);
    } else if (
      !heightEl.value ||
      !weightEl.value
    ) {
      bmiEl.value = "";
    }
  }

