  function validateAssessmentStep(step) {
    step = Number(step || 1);

    function fail(message,id) {
      toast(message,true);
      var el = id ? $(id) : null;
      if (el) {
        try { el.focus(); } catch (e) {}
      }
      return false;
    }

    if (step === 1) {
      if (!assessmentValue("ass-first-name")) {
        return fail("Enter the client name.","ass-first-name");
      }

      if (!normalizedPhone(assessmentValue("ass-mobile"))) {
        return fail("Enter a valid mobile number.","ass-mobile");
      }

      if (!assessmentValue("ass-gender")) {
        return fail("Select Sex / Gender.","ass-gender");
      }

      var branch = assessmentValue("ass-branch");
      if (!branch || isExcludedBranch(branch)) {
        return fail("Select a valid Branch.","ass-branch");
      }

      var source = assessmentValue("ass-source");
      if (!source) {
        return fail("Select Media / Source.","ass-source");
      }

      if (
        STATE.assessmentLeadSources &&
        STATE.assessmentLeadSources.length &&
        STATE.assessmentLeadSources.indexOf(source) < 0
      ) {
        return fail("Select a valid Media from Therapy Plan.","ass-source");
      }

      var consultationEmployee =
        assessmentValue(
          "ass-consultation-employee"
        );

      if (!consultationEmployee) {
        return fail(
          "Select Consultation Employee.",
          "ass-consultation-employee"
        );
      }

      /*
        V5.66:
        GLP Assessment.consultation_employee is Link -> Healthcare Practitioner.
        Validate the selected HLC-PRAC-* value directly.
      */
      var selectedConsultationPractitioner =
        (
          STATE.assessmentPractitioners ||
          []
        ).find(
          function (
            practitioner
          ) {
            return (
              practitioner &&
              String(
                practitioner.name
              ) ===
                String(
                  consultationEmployee
                )
            );
          }
        );

      if (
        !selectedConsultationPractitioner
      ) {
        return fail(
          "Select a valid Healthcare Practitioner for Consultation Employee.",
          "ass-consultation-employee"
        );
      }

      if (
        selectedConsultationPractitioner.status &&
        norm(
          selectedConsultationPractitioner.status
        ) !==
          "active"
      ) {
        return fail(
          "Select an active Healthcare Practitioner.",
          "ass-consultation-employee"
        );
      }

      var selectedPractitionerBranch =
        glpAssessmentPractitionerBranchV566(
          selectedConsultationPractitioner
        );

      if (
        selectedPractitionerBranch &&
        branch &&
        norm(
          selectedPractitionerBranch
        ) !==
          norm(
            branch
          )
      ) {
        return fail(
          "Select a Consultation Employee for " +
            branch +
            ".",
          "ass-consultation-employee"
        );
      }

      if (!assessmentValue("ass-visited-for")) {
        return fail("Visited For is required.","ass-visited-for");
      }

      if (!assessmentValue("ass-booking-decision")) {
        return fail("Select Booked / Not-Booked.","ass-booking-decision");
      }

      if (!assessmentValue("ass-treatment-category")) {
        return fail("Treatment Category is required.","ass-treatment-category");
      }

      var dob = assessmentValue("ass-dob");
      if (dob) {
        var dobDate = new Date(dob + "T00:00:00");
        var nowDate = new Date();
        nowDate.setHours(0,0,0,0);

        if (
          !Number.isFinite(dobDate.getTime()) ||
          dobDate.getFullYear() < 1900 ||
          dobDate > nowDate
        ) {
          return fail("Check Date of birth — use the calendar picker.","ass-dob");
        }
      }
    }

    if (step === 2) {
      var height =
        n(
          assessmentValue(
            "ass-height"
          )
        );

      var weight =
        n(
          assessmentValue(
            "ass-weight"
          )
        );

      var waist =
        assessmentValue(
          "ass-waist"
        );

      var bodyFat =
        assessmentValue(
          "ass-body-fat"
        );

      var visceralFat =
        assessmentValue(
          "ass-visceral-fat"
        );

      var muscleMass =
        assessmentValue(
          "ass-muscle-mass"
        );

      var targetWeight =
        assessmentValue(
          "ass-target-weight"
        );

      if (
        !height ||
        !weight
      ) {
        return fail(
          "Enter Height and Weight before continuing.",
          !height
            ? "ass-height"
            : "ass-weight"
        );
      }

      if (
        height < 50 ||
        height > 250
      ) {
        return fail(
          "Height must be between 50 and 250 cm.",
          "ass-height"
        );
      }

      if (
        weight <= 0 ||
        weight > 250
      ) {
        return fail(
          "Weight must be between 0.1 and 250 kg.",
          "ass-weight"
        );
      }

      if (
        waist !== "" &&
        n(waist) < 0
      ) {
        return fail(
          "Waist cannot be negative.",
          "ass-waist"
        );
      }

      if (
        bodyFat !== "" &&
        (
          n(bodyFat) < 0 ||
          n(bodyFat) > 100
        )
      ) {
        return fail(
          "Body fat must be between 0 and 100%.",
          "ass-body-fat"
        );
      }

      if (
        visceralFat !== "" &&
        n(visceralFat) < 0
      ) {
        return fail(
          "Visceral fat cannot be negative.",
          "ass-visceral-fat"
        );
      }

      if (
        muscleMass !== "" &&
        (
          n(muscleMass) < 0 ||
          n(muscleMass) > 250
        )
      ) {
        return fail(
          "Muscle mass must be between 0 and 250 kg.",
          "ass-muscle-mass"
        );
      }

      if (
        targetWeight !== "" &&
        (
          n(targetWeight) <= 0 ||
          n(targetWeight) > 250
        )
      ) {
        return fail(
          "Target weight must be between 0.1 and 250 kg.",
          "ass-target-weight"
        );
      }

      recalculateAssessmentBMI();
    }

    if (step === 3) {
      var eligibility = norm(assessmentValue("ass-eligibility") || "Conditional");
      var note = assessmentValue("ass-doctor-note");
      var doctor = assessmentValue("ass-doctor");

      if (eligibility === "not eligible") {
        return fail("This assessment is marked Not Eligible. Do not continue to prescription.","ass-eligibility");
      }

      if (!doctor) {
        return fail("Select the practitioner who assessed the client.","ass-doctor");
      }

      if ((eligibility === "conditional" || eligibility === "pending") && !note) {
        return fail("Record the doctor note before continuing.","ass-doctor-note");
      }
    }

    if (step === 4) {
      if (!assessmentValue("ass-therapy-type")) {
        return fail("Select the GLP Therapy Type.","ass-therapy-type");
      }

      var planSessions = Number(
        assessmentValue("ass-plan-sessions") || 0
      );

      if (
        !Number.isFinite(planSessions) ||
        planSessions <= 0 ||
        Math.floor(planSessions) !== planSessions
      ) {
        return fail("Therapy Plan sessions must be a whole number greater than zero.","ass-plan-sessions");
      }

      var clearance = norm(assessmentValue("ass-doctor-clearance"));
      if (clearance !== "cleared") {
        return fail("Doctor Clearance must be Cleared before consent.","ass-doctor-clearance");
      }
    }

    if (step === 5) {
      if (norm(assessmentValue("ass-consent-status")) !== "signed") {
        return fail("Mark consent as signed before Package & billing.","ass-consent-status");
      }
    }

    return true;
  }

