  async function uploadAssessmentBaselineLab(file) {
    if (!file) return null;

    var lowerName = String(file.name || "").toLowerCase();
    var allowedByName =
      lowerName.endsWith(".pdf") ||
      lowerName.endsWith(".jpg") ||
      lowerName.endsWith(".jpeg") ||
      lowerName.endsWith(".png") ||
      lowerName.endsWith(".webp");

    if (!allowedByName) {
      throw new Error(
        "Attach a PDF, JPG, JPEG, PNG or WEBP lab report."
      );
    }

    if (Number(file.size || 0) > 15 * 1024 * 1024) {
      throw new Error(
        "Lab report file must be 15 MB or smaller."
      );
    }

    var form = new FormData();

    form.append("file", file, file.name);
    form.append("is_private", "1");

    var recordNameEl = $("ass-programme-record-name");
    var recordName = recordNameEl
      ? String(recordNameEl.value || "").trim()
      : "";

    if (recordName) {
      form.append("doctype", "GLP Programme Record");
      form.append("docname", recordName);
      form.append("fieldname", "baseline_labs");
    }

    var csrf =
      (
        window.frappe &&
        (
          frappe.csrf_token ||
          (frappe.boot && frappe.boot.csrf_token)
        )
      ) || "";

    var response = await fetch(
      "/api/method/upload_file",
      {
        method: "POST",
        credentials: "same-origin",
        headers: csrf
          ? {"X-Frappe-CSRF-Token": csrf}
          : {},
        body: form
      }
    );

    var payload = {};

    try {
      payload = await response.json();
    } catch (e) {}

    if (!response.ok) {
      throw new Error(
        (
          payload &&
          (
            payload.exception ||
            payload.message ||
            payload._server_messages
          )
        ) ||
        ("Lab report upload failed (" + response.status + ").")
      );
    }

    var uploaded =
      payload && payload.message
        ? payload.message
        : payload;

    if (!uploaded || !uploaded.file_url) {
      throw new Error(
        "ERPNext uploaded the file but did not return a file URL."
      );
    }

    return uploaded;
  }


