  function glpServerMessageFromResponse(
    body,
    fallback
  ) {
    if (!body) {
      return fallback || "ERPNext request failed.";
    }

    if (
      body.message &&
      typeof body.message ===
        "string"
    ) {
      return body.message;
    }

    if (
      body.exception &&
      typeof body.exception ===
        "string"
    ) {
      var lines =
        body.exception.split(
          "\n"
        );

      if (lines.length) {
        return (
          lines[
            lines.length - 1
          ] ||
          body.exception
        );
      }
    }

    if (
      body._server_messages
    ) {
      try {
        var serverMessages =
          JSON.parse(
            body._server_messages
          );

        if (
          Array.isArray(
            serverMessages
          )
        ) {
          for (
            var i = 0;
            i < serverMessages.length;
            i++
          ) {
            try {
              var parsed =
                JSON.parse(
                  serverMessages[i]
                );

              if (
                parsed &&
                parsed.message
              ) {
                return String(
                  parsed.message
                ).replace(
                  /<[^>]*>/g,
                  ""
                );
              }
            } catch (_) {}
          }
        }
      } catch (_) {}
    }

    return (
      fallback ||
      "ERPNext request failed."
    );
  }


  async function assessmentCreateClientAPI(
    payload
  ) {
    var csrf =
      (
        window.frappe &&
        (
          frappe.csrf_token ||
          (
            frappe.boot &&
            frappe.boot.csrf_token
          )
        )
      ) ||
      "";

    var form =
      new URLSearchParams();

    Object.keys(
      payload ||
      {}
    ).forEach(
      function (
        key
      ) {
        var value =
          payload[
            key
          ];

        if (
          value !==
            undefined &&
          value !==
            null
        ) {
          form.append(
            key,
            String(
              value
            )
          );
        }
      }
    );

    var controller =
      typeof AbortController !==
      "undefined"
        ? new AbortController()
        : null;

    var timer =
      controller
        ? setTimeout(
            function () {
              try {
                controller.abort();
              } catch (_) {}
            },
            45000
          )
        : null;

    try {
      var response =
        await fetch(
          "/api/method/lifescc.billing.create_client",
          {
            method:
              "POST",
            credentials:
              "same-origin",
            headers:
              Object.assign(
                {
                  "Accept":
                    "application/json",
                  "Content-Type":
                    "application/x-www-form-urlencoded; charset=UTF-8"
                },
                csrf
                  ? {
                      "X-Frappe-CSRF-Token":
                        csrf
                    }
                  : {}
              ),
            body:
              form.toString(),
            signal:
              controller
                ? controller.signal
                : undefined
          }
        );

      var body = {};

      try {
        body =
          await response.json();
      } catch (_) {}

      if (
        !response.ok
      ) {
        throw new Error(
          glpServerMessageFromResponse(
            body,
            "Client creation failed (HTTP " +
              response.status +
              ")."
          )
        );
      }

      return (
        body &&
        body.message
          ? body.message
          : null
      );

    } catch (error) {
      if (
        error &&
        error.name ===
          "AbortError"
      ) {
        throw new Error(
          "Client creation took more than 45 seconds."
        );
      }

      throw error;

    } finally {
      if (timer) {
        clearTimeout(
          timer
        );
      }
    }
  }


