      [
        "practitioner_name",
        "department",
        "designation",
        "status",
        "employee",
        "employee_id",
        "custom_employee",
        "custom_employee_id",
        "branch",
        "branch_name",
        "custom_branch",
        "custom_branch_name"
      ].forEach(
        function (
          fieldname
        ) {
          if (
            schema.fieldSet &&
            schema.fieldSet[
              fieldname
            ]
          ) {
            fields.push(
              fieldname
            );
          }
        }
      );

      STATE.assessmentPractitioners =
        await getListPage(
          "Healthcare Practitioner",
          fields,
          [],
          (
            schema.fieldSet &&
            schema.fieldSet.practitioner_name
          )
            ? "practitioner_name asc"
            : "name asc",
          0,
          2000
        );

      STATE.assessmentPractitioners =
        (
          STATE.assessmentPractitioners ||
          []
        ).filter(
          function (
            practitioner
          ) {
            return (
              practitioner &&
              practitioner.name &&
              (
                !practitioner.status ||
                norm(
                  practitioner.status
                ) ===
                  "active"
              )
            );
          }
        );

    } catch (
      error
    ) {
      void 0;

      STATE.assessmentPractitioners =
        STATE.assessmentPractitioners ||
        [];
    }
  }


  function glpAssessmentPractitionerBranchV566(
    practitioner
  ) {
    practitioner =
      practitioner || {};

    return String(
      practitioner.branch ||
      practitioner.branch_name ||
      practitioner.custom_branch ||
      practitioner.custom_branch_name ||
      ""
    ).trim();
  }


  function glpAssessmentPractitionerLabelV566(
    practitioner
  ) {
    practitioner =
      practitioner || {};

    var label =
      String(
        practitioner.practitioner_name ||
        practitioner.name ||
        ""
      ).trim();

    var designation =
      String(
        practitioner.designation ||
        practitioner.department ||
        ""
      ).trim();

    if (
      designation &&
      label.toLowerCase().indexOf(
        designation.toLowerCase()
      ) ===
        -1
    ) {
      label +=
        " — " +
        designation;
    }

    return label;
  }


  function glpAssessmentPractitionerOptionsV564(
    current
  ) {
    var rows =
      (
        STATE.assessmentPractitioners ||
        []
      ).map(
        function (
          practitioner
        ) {
          return {
            value:
              practitioner.name,
            label:
              glpAssessmentPractitionerLabelV566(
                practitioner
              )
          };
        }
      );

    current =
      String(
        current || ""
      ).trim();

    if (
      current &&
      !rows.some(
        function (
          option
        ) {
          return (
            String(
              option.value
            ) ===
            current
          );
        }
      )
    ) {
      rows.unshift(
        {
          value:
            current,
          label:
            current
        }
      );
    }

    return rows;
  }


  function glpAssessmentConsultationOptionsV564(
    branch,
    current
  ) {
    branch =
      String(
        branch || ""
      ).trim();

    current =
      String(
        current || ""
      ).trim();

    var practitioners =
      (
        STATE.assessmentPractitioners ||
        []
      ).filter(
        function (
          practitioner
        ) {
          if (
            !practitioner ||
            !practitioner.name
          ) {
            return false;
          }

          if (
            practitioner.status &&
            norm(
              practitioner.status
            ) !==
              "active"
          ) {
            return false;
          }

          var practitionerBranch =
            glpAssessmentPractitionerBranchV566(
              practitioner
            );

          /*
            If the Healthcare Practitioner DocType has a usable Branch value,
            respect the selected branch.

            If this site's Practitioner records do not store Branch on the
            practitioner itself, rely on Frappe permissions and keep the
            permitted practitioner in the list rather than incorrectly hiding
            everyone.
          */
          if (
            branch &&
            practitionerBranch &&
            norm(
              practitionerBranch
            ) !==
              norm(
                branch
              )
          ) {
            return false;
          }

          return true;
        }
      );

    var rows =
      practitioners.map(
        function (
          practitioner
        ) {
          return {
            value:
              practitioner.name,
            label:
              glpAssessmentPractitionerLabelV566(
                practitioner
              )
          };
        }
      );

    if (
      current &&
      !rows.some(
        function (
          option
        ) {
          return (
            String(
              option.value
            ) ===
            current
          );
        }
      )
    ) {
      var currentPractitioner =
        (
          STATE.assessmentPractitioners ||
          []
        ).find(
          function (
            practitioner
          ) {
            return (
              String(
                practitioner.name
              ) ===
              current
            );
          }
        );

      /*
        Preserve only an actual Healthcare Practitioner value.
        Do NOT reinsert old HR-EMP-* values.
      */
      if (
        currentPractitioner
      ) {
        rows.unshift(
          {
            value:
              current,
            label:
              glpAssessmentPractitionerLabelV566(
                currentPractitioner
              )
          }
        );
      }
    }

    return rows;
  }

  function glpAssessmentApiV564(action,payload) {
    payload = payload || {};
    var csrf = (window.frappe && (frappe.csrf_token || (frappe.boot && frappe.boot.csrf_token))) || "";
    var form = new URLSearchParams();
    form.append("action", action);
    form.append("payload", JSON.stringify(payload));
    return fetch("/api/method/life_glp_prepare_client_v61", {
      method:"POST",
      credentials:"same-origin",
      headers:Object.assign({
        "Accept":"application/json",
        "Content-Type":"application/x-www-form-urlencoded; charset=UTF-8"
      }, csrf ? {"X-Frappe-CSRF-Token":csrf} : {}),
      body:form.toString()
    }).then(async function(response){
      var body={};
      try { body=await response.json(); } catch (_) {}
      if (!response.ok) {
        throw new Error(glpServerMessageFromResponse(body,"GLP Assessment request failed (HTTP "+response.status+")."));
      }
      var result = body && body.message ? body.message : null;
      if (!result || result.server_version !== "V5.64") {
        throw new Error("The GLP Assessment V5.64 Server Script is not active. Expected server_version V5.64.");
      }
      return result;
    });
  }

  function glpAssessmentCurrentV564() {
    return STATE.glpAssessmentRecord || null;
  }

  function glpAssessmentRecordValueV564(field,fallback) {
    var r=glpAssessmentCurrentV564();
    if (r && r[field] !== undefined && r[field] !== null && String(r[field]).trim() !== "") return r[field];
    return fallback === undefined ? "" : fallback;
  }

  function glpAssessmentCheckboxV564(label,id,checked) {
    return '<label style="display:flex;align-items:flex-start;gap:9px;padding:10px 11px;border:1px solid #e2ddd2;border-radius:9px;background:#fff;cursor:pointer;">'+
      '<input id="'+esc(id)+'" type="checkbox" '+(checked?'checked':'')+' style="margin-top:2px;">'+
      '<span style="font-size:12.5px;line-height:1.35;color:#26463a;font-weight:650;">'+esc(label)+'</span></label>';
  }

  function glpAssessmentContraFromRecordV564(record) {
    var out=[];
    (record && Array.isArray(record.contraindications) ? record.contraindications : []).forEach(function(row){
      var label = row.contraindication || row.condition || row.contraindication_name || "";
      var hasSelected = row.selected !== undefined || row.is_selected !== undefined || row.checked !== undefined;
      var selected = hasSelected ? !!Number(row.selected !== undefined ? row.selected : (row.is_selected !== undefined ? row.is_selected : row.checked)) : true;
      if (label && selected) out.push(label);
    });
    return out;
  }

  function glpAssessmentLabValueV564(row,candidates,fallback) {
    row=row||{};
    for (var i=0;i<candidates.length;i++) {
      var v=row[candidates[i]];
      if (v !== undefined && v !== null && String(v).trim() !== "") return v;
    }
    return fallback === undefined ? "" : fallback;
  }

