        }
      );

    var hiddenRows =
      tests.map(
        function (test) {
          var row =
            rowFor(test);

          var status =
            glpAssessmentLabValueV564(
              row,
              [
                "status",
                "lab_status"
              ],
              completed
                ? "Uploaded"
                : "Pending"
            );

          var date =
            glpAssessmentLabValueV564(
              row,
              [
                "test_date",
                "date"
              ],
              ""
            );

          var file =
            glpAssessmentLabValueV564(
              row,
              [
                "report_file",
                "report",
                "attachment"
              ],
              ""
