          return (
            '<div class="glp-v564-lab-row glp-pdf-hidden" data-lab="' +
              esc(test) +
            '">' +
              '<select class="glp-v564-lab-status">' +
                '<option' +
                  (
                    status === "Pending"
                      ? " selected"
                      : ""
                  ) +
                '>Pending</option>' +
                '<option' +
                  (
                    status === "Uploaded"
                      ? " selected"
                      : ""
                  ) +
                '>Uploaded</option>' +
                '<option' +
                  (
                    status === "Reviewed"
                      ? " selected"
                      : ""
                  ) +
                '>Reviewed</option>' +
              '</select>' +
              '<input class="glp-v564-lab-date" type="date" value="' +
                esc(date) +
              '">' +
              '<input class="glp-v564-lab-url" value="' +
                esc(file) +
              '">' +
              '<input class="glp-v564-lab-remarks" value="' +
                esc(remarks) +
              '">' +
            '</div>'
          );
        }
      ).join("");

    return (
      '<div class="glp-assessment-check-section">' +
        '<div class="glp-assessment-inline-title">' +
          '<b>Baseline labs</b>' +
          '<span>HbA1c, FBS/PP, thyroid, LFT, RFT, lipid, CBC</span>' +
        '</div>' +
        '<input type="hidden" id="ass-labs-status" value="' +
          (
            completed
              ? "Completed"
              : "Pending"
          ) +
        '">' +
        '<input type="checkbox" id="ass-bca-done" class="glp-pdf-hidden" ' +
          (
            record &&
            Number(
              record.bca_completed ||
              0
            )
              ? "checked"
              : ""
          ) +
        '>' +
        '<div class="glp-assessment-chip-wrap">' +
          '<button type="button" class="glp-assessment-choice' +
            (
              completed
                ? " active"
                : ""
            ) +
          '" data-assessment-labs-uploaded>' +
            (
              completed
                ? "✓ Lab reports uploaded"
                : "Mark lab reports uploaded"
            ) +
          '</button>' +
          '<button type="button" class="glp-assessment-choice' +
            (
              record &&
              Number(
                record.bca_completed ||
                0
