  async function glpAssessmentUploadFileV564(file,fieldname) {
    if (!file) return "";
    if (Number(file.size||0) > 15*1024*1024) throw new Error("Attachment must be 15 MB or smaller.");
    var form=new FormData();
    form.append("file",file,file.name);
    form.append("is_private","1");
    form.append("folder","Home/Attachments");
    var record=glpAssessmentCurrentV564();
    if (record && record.name) {
      form.append("doctype","GLP Assessment");
      form.append("docname",record.name);
      if (fieldname) form.append("fieldname",fieldname);
    }
    var csrf=(window.frappe&&(frappe.csrf_token||(frappe.boot&&frappe.boot.csrf_token)))||"";
    var response=await fetch("/api/method/upload_file",{method:"POST",credentials:"same-origin",headers:csrf?{"X-Frappe-CSRF-Token":csrf,"Accept":"application/json"}:{"Accept":"application/json"},body:form});
    var body={}; try{body=await response.json();}catch(_){}
    if (!response.ok || !body || !body.message || !body.message.file_url) throw new Error(glpServerMessageFromResponse(body,"Attachment upload failed (HTTP "+response.status+")."));
    return body.message.file_url;
  }

  function glpAssessmentSavedMaxStepV564() {
    var r=glpAssessmentCurrentV564();
    if (!r) return 1;
    var current=Number(r.current_step||1);
    var saved=Number(r.last_saved_step||0);
    return Math.max(1,Math.min(6,Math.max(current,saved+1)));
  }

  function showAssessmentStep(step) {
    step=Math.max(1,Math.min(6,Number(step||1)));
    var maxAllowed=glpAssessmentSavedMaxStepV564();
    if (step>maxAllowed) step=maxAllowed;
    STATE.assessmentStep=step;
    Array.from(ROOT.querySelectorAll(".glp-assessment-step-panel")).forEach(function(panel){
      panel.classList.toggle("active",Number(panel.getAttribute("data-assessment-panel"))===step);
    });
    var record=glpAssessmentCurrentV564();
    var saved=record?Number(record.last_saved_step||0):0;
    Array.from(ROOT.querySelectorAll("[data-assessment-step]")).forEach(function(btn){
      var no=Number(btn.getAttribute("data-assessment-step")||1);
      btn.classList.toggle("active",no===step);
      btn.classList.toggle("done",no<=saved && no!==step);
      btn.disabled=no>maxAllowed;
    });
    updateAssessmentLivePanel();
  }

