  function validateAssessmentStep(step) {
    step=Number(step||1);
    function fail(message,id){toast(message,true);var el=id?$(id):null;if(el){try{el.focus();}catch(_){}}return false;}
    if(step===1){
      if(!assessmentValue("ass-first-name"))return fail("Enter Full Name.","ass-first-name");
      var ph=normalizedPhone(assessmentValue("ass-mobile")); if(!ph||!ph.digits||ph.digits.length!==10)return fail("Enter a valid 10-digit mobile number.","ass-mobile");
      if(!assessmentValue("ass-gender"))return fail("Select Gender.","ass-gender");
      if(!assessmentValue("ass-branch")||isExcludedBranch(assessmentValue("ass-branch")))return fail("Select a valid Branch.","ass-branch");
      if(!assessmentValue("ass-source"))return fail("Select Media / Source.","ass-source");
      if(!assessmentValue("ass-consultation-employee"))return fail("Select Consultation Employee.","ass-consultation-employee");
      if(!assessmentValue("ass-visited-for"))return fail("Visited For is required.","ass-visited-for");
      if(!assessmentValue("ass-booking-decision"))return fail("Select Booked / Not-Booked.","ass-booking-decision");
      if(!assessmentValue("ass-treatment-category"))return fail("Treatment Category is required.","ass-treatment-category");
    }
    if(step===2){
      var h=n(assessmentValue("ass-height")),w=n(assessmentValue("ass-weight"));
      if(!h||h<50||h>250)return fail("Enter Height between 50 and 250 cm.","ass-height");
      if(!w||w<=0||w>300)return fail("Enter a valid Weight.","ass-weight");
    }
    if(step===3){
      var verdict=assessmentValue("ass-eligibility");
      if(["Green","Amber","Red"].indexOf(verdict)<0)return fail("Select Green, Amber or Red Eligibility Verdict.","ass-eligibility");
      if(!assessmentValue("ass-doctor"))return fail("Select Assessed By.","ass-doctor");
      if((verdict==="Amber"||verdict==="Red")&&!assessmentValue("ass-doctor-note"))return fail("Doctor Note is required for Amber or Red.","ass-doctor-note");
    }
    if(step===4){
      if(!assessmentValue("ass-molecule"))return fail("Select Molecule.","ass-molecule");
      if(!assessmentValue("ass-starting-dose"))return fail("Select Starting Dose.","ass-starting-dose");
      if(!assessmentValue("ass-prescription-ref"))return fail("Enter Prescription Reference.","ass-prescription-ref");
      if(!assessmentValue("ass-prescribed-by"))return fail("Select Prescribed By.","ass-prescribed-by");
      if(!assessmentValue("ass-prescription-date"))return fail("Select Prescription Date.","ass-prescription-date");
      if(!assessmentValue("ass-prescription-file-url"))return fail("Attach Prescription File.","ass-prescription-file");
    }
    if(step===5){
      var checks=["ass-medical-supervision","ass-common-effects","ass-serious-risks","ass-attendance","ass-outcome","ass-package-terms","ass-health-change"];
      if(!checks.every(function(id){return $(id)&&$(id).checked;}))return fail("Confirm all consent explanation items before continuing.",checks.find(function(id){return !$(id)||!$(id).checked;}));
      if(!$("ass-consent-signed")||!$("ass-consent-signed").checked)return fail("Consent Signed is required.","ass-consent-signed");
      if(!assessmentValue("ass-consent-file-url"))return fail("Attach Signed Consent File.","ass-consent-file");
      if(!assessmentValue("ass-consent-taken-by"))return fail("Select Consent Taken By.","ass-consent-taken-by");
      if(!assessmentValue("ass-consent-datetime"))return fail("Enter Consent Date and Time.","ass-consent-datetime");
      /* V5.68 PDF design: Photo ID is a collected/on-file marker; the file field is optional here. */
    }
    return true;
  }

