  async function glpAssessmentTryResumeByMobileV564() {
    /*
      V5.73 EXISTING PATIENT FLOW
      ---------------------------
      Patient is created only once.

      If the mobile belongs to an existing Patient:
        - NEVER create another Patient
        - create a new GLP Assessment when the previous programme is completed
        - reuse an unfinished/open GLP Assessment when one already exists
        - move directly to Step 2 (Screening)

      If no Patient exists:
        - remain on Step 1
        - normal Registration creates the Patient once
    */
    if (
      STATE.glpAssessmentResumeBusy ||
      glpAssessmentCurrentV564()
    ) {
      return;
    }

    var ph = normalizedPhone(
      assessmentValue("ass-mobile")
    );

    if (
      !ph ||
      !ph.digits ||
      ph.digits.length !== 10
    ) {
      return;
    }

    STATE.glpAssessmentResumeBusy = true;

    try {
      var patient = await assessmentFindExistingPatient(
        ph.digits
      );

      if (!patient || !patient.name) {
        return;
      }

      var selectedLead = assessmentSelectedLead();

      var result = await glpAssessmentApiV564(
        "start_existing_patient",
        {
          patient: patient.name,
          mobile: ph.digits,
          source_lead:
            selectedLead && selectedLead.name
              ? selectedLead.name
              : ""
        }
      );

      if (
        !result ||
        !result.assessment ||
        !result.assessment.name
      ) {
        throw new Error(
          "Existing client was found, but the GLP Assessment could not be prepared."
        );
      }

      STATE.glpAssessmentRecord = result.assessment;

      var nextStep = Number(
        result.assessment.current_step || 2
      );

      if (
        !result.resumed_open_assessment &&
        nextStep < 2
      ) {
        nextStep = 2;
      }

      STATE.assessmentStep = Math.max(
        2,
        Math.min(6, nextStep)
      );

      if (result.resumed_open_assessment) {
        toast(
          "Existing client found. Continuing open GLP Assessment: " +
          result.assessment.name
        );
      } else {
        toast(
          "Existing client found. Patient reused and new GLP Assessment created. Opening Screening."
        );
      }

      render();

    } catch (e) {
      void 0;

      glpSafeMessage(
        "Could not start assessment",
        e && e.message
          ? e.message
          : "The existing client could not be opened for Screening.",
        true
      );

    } finally {
      STATE.glpAssessmentResumeBusy = false;
    }
  }

