  async function findAssessmentLeadByMobile(
    mobile
  ) {
    var phone =
      normalizedPhone(
        mobile
      );

    if (!phone) {
      return null;
    }

    await ensureSchemaFast(
      "Lead"
    );

    var schema =
      SCHEMA["Lead"];

    if (
      !schema ||
      !schema.exists
    ) {
      return null;
    }

    var fields = [
      "name",
      "first_name",
      "lead_name",
      "mobile_no",
      "phone",
      "branch",
      "lead_assign_to_branch",
      "source",
      "status",
      "custom_treatment_interests"
    ].filter(
      function (fieldname) {
        return (
          fieldname === "name" ||
          (
            schema.fieldSet &&
            schema.fieldSet[
              fieldname
            ]
          )
        );
      }
    );

    var searchable = [
      "mobile_no",
      "phone"
    ].filter(
      function (fieldname) {
        return (
          schema.fieldSet &&
          schema.fieldSet[
            fieldname
          ]
        );
      }
    );

    if (!searchable.length) {
      return null;
    }

    var last10 =
      phone.digits;

    var rows =
      await frappeCall(
        "frappe.client.get_list",
        {
          doctype:
            "Lead",
          fields:
            fields,
          filters:
            [],
          or_filters:
            searchable.map(
              function (fieldname) {
                return [
                  "Lead",
                  fieldname,
                  "like",
                  "%" +
                  last10 +
                  "%"
                ];
              }
            ),
          order_by:
            "modified desc",
          limit_start:
            0,
          limit_page_length:
            25
        },
        12000
      );

    rows =
      rows || [];

    return (
      rows.find(
        function (row) {
          var value =
            normalizedPhone(
              row.mobile_no ||
              row.phone ||
              ""
            );

          return (
            value &&
            value.digits ===
              last10
          );
        }
      ) ||
      null
    );
  }


  function assessmentLeadPutIfField(
    doc,
    fieldname,
    value
  ) {
    var schema =
      SCHEMA["Lead"];

    if (
      fieldname === "name" ||
      (
        schema &&
        schema.fieldSet &&
        schema.fieldSet[
          fieldname
        ]
      )
    ) {
      doc[fieldname] =
        value;
    }
  }


  async function assessmentResolveExistingLeadByMobile(
    mobile
  ) {
    var phone =
      normalizedPhone(
        mobile
      );

    if (
      !phone ||
      !phone.digits
    ) {
      return null;
    }

    /*
      V5.60:
      Billing already uses lifescc.billing.lead_lookup for its registration
      flow. Prefer that same server-side lookup because LIFE's duplicate-lead
      hook may normalize mobiles differently from frappe.client.get_list.
    */
    try {
      var lookup =
        await frappeCall(
          "lifescc.billing.lead_lookup",
          {
            mobile:
              phone.digits
          },
          15000
        );

      if (
        lookup &&
        lookup.found &&
        lookup.lead
      ) {
        return {
          name:
            lookup.lead,

          patient_name:
            lookup.patient_name ||
            "",

          mobile_no:
            lookup.mobile ||
            phone.digits,

          source:
            lookup.media ||
            "",

          branch:
            lookup.branch ||
            ""
        };
      }
    } catch (
      lookupError
    ) {
      void 0;
    }

    try {
      return await findAssessmentLeadByMobile(
        mobile
      );
    } catch (
      directError
    ) {
      void 0;

      return null;
    }
  }


  async function createOrUpdateAssessmentLead() {
    await ensureSchemaFast(
      "Lead"
    );

    var fullName =
      assessmentValue(
        "ass-first-name"
      );

    var mobile =
      assessmentValue(
        "ass-mobile"
      );

    var branch =
      assessmentValue(
        "ass-branch"
      );

    var source =
      assessmentValue(
        "ass-source"
      );

    var existing =
      await assessmentResolveExistingLeadByMobile(
        mobile
      );

    var leadDoc;

    if (
      existing &&
      existing.name
    ) {
      leadDoc =
        await getFullDoc(
          "Lead",
          existing.name
        );
    }

    if (!leadDoc) {
      leadDoc = {
        doctype:
          "Lead"
      };
    }

    assessmentLeadPutIfField(
      leadDoc,
      "first_name",
      fullName
    );

    assessmentLeadPutIfField(
      leadDoc,
      "lead_name",
      fullName
    );

    assessmentLeadPutIfField(
      leadDoc,
      "mobile_no",
      mobile
    );

    assessmentLeadPutIfField(
      leadDoc,
      "branch",
      branch
    );

    assessmentLeadPutIfField(
      leadDoc,
      "lead_assign_to_branch",
      branch
    );

    if (source) {
      assessmentLeadPutIfField(
        leadDoc,
        "source",
        source
      );
    }

    assessmentLeadPutIfField(
      leadDoc,
      "gender",
      assessmentValue(
        "ass-gender"
      )
    );

    assessmentLeadPutIfField(
      leadDoc,
      "age",
      n(
        assessmentValue(
          "ass-age"
        )
      )
    );

    assessmentLeadPutIfField(
      leadDoc,
      "height",
      n(
        assessmentValue(
          "ass-height"
        )
      )
    );

    assessmentLeadPutIfField(
      leadDoc,
      "weight",
      n(
        assessmentValue(
          "ass-weight"
        )
      )
    );

    assessmentLeadPutIfField(
      leadDoc,
      "medical_history",
      assessmentValue(
        "ass-history"
      )
    );

    assessmentLeadPutIfField(
      leadDoc,
      "custom_target_weight",
      n(
        assessmentValue(
          "ass-target-weight"
        )
      )
    );

    assessmentLeadPutIfField(
      leadDoc,
      "custom_current_medication",
      assessmentValue(
        "ass-medication"
      )
    );

    assessmentLeadPutIfField(
      leadDoc,
      "custom_bmi",
      assessmentValue(
        "ass-bmi"
      )
    );

    assessmentLeadPutIfField(
      leadDoc,
      "sex",
      assessmentValue(
        "ass-gender"
      )
    );

    assessmentLeadPutIfField(
      leadDoc,
      "dob",
      assessmentValue(
        "ass-dob"
      )
    );

    assessmentLeadPutIfField(
      leadDoc,
      "custom_visited_for",
      assessmentValue(
        "ass-visited-for"
      )
    );

    assessmentLeadPutIfField(
      leadDoc,
      "custom_final_decision",
      assessmentValue(
        "ass-booking-decision"
      )
    );

    /*
      This dashboard is specifically the GLP/Slimming programme.
      Preserve any existing interests but guarantee Slimming is present.
    */
    if (
      SCHEMA["Lead"] &&
      SCHEMA["Lead"].fieldSet &&
      SCHEMA["Lead"].fieldSet[
        "custom_treatment_interests"
      ]
    ) {
      var interests =
        String(
          leadDoc.custom_treatment_interests ||
          ""
        ).trim();

      if (
        interests
          .toLowerCase()
          .indexOf(
            "slimming"
          ) < 0
      ) {
        leadDoc.custom_treatment_interests =
          interests
            ? (
                interests +
                ", Slimming"
              )
            : "Slimming";
      }
    }

    if (
      !leadDoc.name &&
      SCHEMA["Lead"] &&
      SCHEMA["Lead"].fieldSet &&
      SCHEMA["Lead"].fieldSet.status
    ) {
      leadDoc.status =
        "Open";
    }

    var saved;

    if (leadDoc.name) {
      saved =
        await frappeCall(
          "frappe.client.save",
          {
            doc:
              leadDoc
          },
          20000
        );

    } else {
      try {
        saved =
          await frappeCall(
            "frappe.client.insert",
            {
              doc:
                leadDoc
            },
            20000
          );

      } catch (
        insertError
      ) {
        /*
          LIFE has a server-side restrict_duplicate_lead hook. A Lead can be
          inserted by another flow or stored in a mobile format that our first
          lookup did not match.

          If insert is rejected as a duplicate, re-resolve the existing Lead
          and REUSE it instead of failing the entire Create Therapy Plan flow.
        */
        var message =
          String(
            (
              insertError &&
              (
                insertError.message ||
                insertError._server_messages
              )
            ) ||
            ""
          );

        var looksDuplicate =
          /lead already exists|duplicate/i.test(
            message
          );

        if (
          looksDuplicate
        ) {
          var duplicateLead =
            await assessmentResolveExistingLeadByMobile(
              mobile
            );

          if (
            duplicateLead &&
            duplicateLead.name
          ) {
            saved =
              await getFullDoc(
                "Lead",
                duplicateLead.name
              );

            void 0;

          } else {
            throw insertError;
          }

        } else {
          throw insertError;
        }
      }
    }

    if (
      saved &&
      saved.name
    ) {
      STATE.assessmentLead =
        saved.name;

      saved._branch =
        directDetectedBranch(
          saved,
          "Lead"
        ) ||
        branch;

      var replaced = false;

      STATE.data.leads =
        (STATE.data.leads || [])
          .map(
            function (row) {
              if (
                row.name ===
                saved.name
              ) {
                replaced = true;
                return saved;
              }

              return row;
            }
          );

