  async function assessmentFindExistingPatient(
    mobile
  ) {
    var phone =
      normalizedPhone(
        mobile
      );

    if (!phone) {
      return null;
    }

    /*
      First use Patient rows that are already loaded in the GLP dashboard.
    */
    var loaded =
      (STATE.data.patients || [])
        .find(
          function (patient) {
            var candidate =
              normalizedPhone(
                patientMobileValue(
                  patient
                )
              );

            return (
              candidate &&
              candidate.digits ===
                phone.digits
            );
          }
        );

    if (loaded) {
      return loaded;
    }

    /*
      A brand-new assessment may not yet be part of STATE.data.patients.
      Search the real Patient DocType using only actual mobile-like fields
      discovered from Patient metadata.
    */
    try {
      await ensureSchemaFast(
        "Patient"
      );

      var schema =
        SCHEMA["Patient"];

      if (
        !schema ||
        !schema.exists
      ) {
        return null;
      }

      var mobileFields =
        (schema.fields || [])
          .filter(
            function (fieldname) {
              return (
                fieldname !== "name" &&
                /(mobile|phone|telephone|contact.*(no|number))/i.test(
                  fieldname
                )
              );
            }
          );

      if (!mobileFields.length) {
        return null;
      }

      var requestedFields =
        [
          "name",
          "patient_name",
          "first_name",
          "sex"
        ]
          .concat(
            mobileFields
          )
          .filter(
            function (fieldname,index,all) {
              return (
                fieldname === "name" ||
                (
                  schema.fieldSet &&
                  schema.fieldSet[fieldname]
                )
              ) &&
              all.indexOf(
                fieldname
              ) === index;
            }
          );

      var rows =
        await frappeCall(
          "frappe.client.get_list",
          {
            doctype:
              "Patient",
            fields:
              requestedFields,
            filters:
              [],
            or_filters:
              mobileFields.map(
                function (fieldname) {
                  return [
                    "Patient",
                    fieldname,
                    "like",
                    "%" +
                    phone.digits +
                    "%"
                  ];
                }
              ),
            order_by:
              "modified desc",
            limit_start:
              0,
            limit_page_length:
              30
          },
          12000
        );

      rows =
        rows || [];

      return (
        rows.find(
          function (patient) {
            var candidate =
              normalizedPhone(
                patientMobileValue(
                  patient
                )
              );

            return (
              candidate &&
              candidate.digits ===
                phone.digits
            );
          }
        ) ||
        null
      );

    } catch (e) {
      void 0;

      return null;
    }
  }


