      var branchEl = doc.getElementById("bl-branch");
      if (branchEl && branch) branchEl.value = branch;

      var mediaEl = doc.getElementById("bl-media");
      if (mediaEl && media) {
        var hasMedia = Array.prototype.some.call(
          mediaEl.options || [],
          function (o) {
