          }
        } catch (e) {}
      }

      var practitionerEl = doc.getElementById("bl-practitioner");
      if (practitionerEl && practitioner) {
        practitionerEl.value = practitioner;
      }

      var c =
        (billingWindow.CATALOG || []).find(
          function (item) {
            return norm(item && (item.n || item.name)) === norm(therapy);
