      var range = row.querySelector(".tp-range");

      billingWindow.BILL.lines[0].therapy = c.n || c.name;

      /*
        V5.25 GLP COMMERCIAL QTY FIX

        IMPORTANT:
        - Therapy Plan execution sessions = 4
        - Sales Invoice commercial quantity = 1

        Previously this line copied the 4 execution sessions into Billing qty,
        which produced Qty 4 and Rs.80,000 for the 1-dose GLP item.

        For the exact 1-dose GLP commercial item, Billing must always start at
        Qty 1. The Therapy Plan is converted to 4 executable sessions separately
        by the Sales Invoice After Submit Server Script.
