      var glpCommercialOneDose =
        norm(c.n || c.name) ===
        norm("GLP-1 (WM Inj) 1 Dose");

      billingWindow.BILL.lines[0].qty =
        glpCommercialOneDose
          ? 1
          : (sessions > 0 ? sessions : 1);

      billingWindow.BILL.lines[0].rate = Number(c.rec || c.rate || 0);
      billingWindow.BILL.lines[0].category = c.category || "";

      if (search) search.value = c.n || c.name;
      if (qty) qty.value = String(billingWindow.BILL.lines[0].qty);
      if (rate) rate.value = String(billingWindow.BILL.lines[0].rate);
      if (amount) {
        amount.value = String(
          Math.round(
            billingWindow.BILL.lines[0].qty *
            billingWindow.BILL.lines[0].rate
          )
        );
      }

      if (range && typeof billingWindow.fmtM === "function") {
        range.innerHTML =
          '<b>' + billingWindow.fmtM(c.min) + '</b> – ' + billingWindow.fmtM(c.max);
      }

      try {
        if (typeof billingWindow.setRowCat === "function") {
          billingWindow.setRowCat(row,c.category);
        }
      } catch (e) {}

      try {
        if (typeof billingWindow.recalc === "function") {
          billingWindow.recalc();
        }
