  ) {
    if (
      !billingWindow ||
      billingWindow.closed ||
      !patient ||
      !patient.name
    ) {
      return;
    }

    /*
      V5.58 - EXACT BILLING FLOW
      =========================

      Your Billing dashboard already works like this:

        openSummary(patient)
              ↓
        button #cs-newbill
        "New Bill (Therapy Plan)"
              ↓
        button click calls startBilling(patient)
              ↓
        renderBillWorkspace()

      V5.58 follows THAT EXACT EXISTING Billing flow.

      We do NOT modify the Billing dashboard.
      We do NOT try to skip its normal internal event flow.

      Instead:
        1. Open /billing.
        2. Open the created/reused Patient summary.
        3. Wait for the real Billing button:
             #cs-newbill
        4. CLICK THAT BUTTON automatically.
        5. Wait for the real Therapy Plan workspace:
             #bl-lines
        6. Filter the current Billing tab to GLP Therapy Types only.
        7. Hide Package / Template mode only for this GLP-launched tab.
    */

    function billingEval(
      source
    ) {
      return billingWindow.eval(
        source
      );
    }

    function billingPath() {
      try {
        return String(
          (
            billingWindow.location &&
            billingWindow.location.pathname
          ) ||
          ""
        ).replace(
          /\/+$/,
          ""
        );
      } catch (_) {
        return "";
      }
    }

    function ensureBillingPage() {
      try {
        if (
          billingPath() !==
          "/billing"
        ) {
          billingWindow.location.replace(
            "/billing"
          );
        }
      } catch (_) {
        try {
          billingWindow.location.href =
            "/billing";
        } catch (_) {}
      }
    }

    var patientName =
      String(
        patient.name ||
        ""
      ).trim();

    var patientDisplayName =
      String(
        patient.patient_name ||
        assessmentValue(
          "ass-first-name"
        ) ||
        patientName
      ).trim();

    var requestedBranch =
      String(
        assessmentValue("ass-branch") ||
        (savedRecord && savedRecord.branch) ||
        patient.branch_name ||
        patient.branch ||
        patient.custom_branch ||
        ""
      ).trim();

    var requestedSource =
      String(
        assessmentValue("ass-source") ||
        (savedRecord && savedRecord.media) ||
        ""
      ).trim();

    var requestedPractitioner =
      String(
        assessmentValue("ass-prescribed-by") ||
        (savedRecord && savedRecord.prescribed_by) ||
        assessmentValue("ass-doctor") ||
        ""
      ).trim();

    var selectedTherapy = "";

    var requestedSessions = 1;

    if (
      !Number.isFinite(
        requestedSessions
      ) ||
      requestedSessions <= 0
    ) {
      requestedSessions =
        4;
    }

    var glpNames =
      assessmentGLPCatalogNames();

    ensureBillingPage();

    var startedAt =
      Date.now();

    var summaryRequested =
      false;

    var newBillClicked =
      false;

    var timer =
      setInterval(
        function () {
          if (
            !billingWindow ||
            billingWindow.closed
          ) {
            clearInterval(
              timer
            );
            return;
          }

          if (
            Date.now() -
              startedAt >
            60000
          ) {
            clearInterval(
              timer
            );

            void 0;

            try {
              var timeoutStage =
                billingWindow.document.getElementById(
                  "stage"
                );

              if (timeoutStage) {
                timeoutStage.innerHTML =
                  '<div class="card"><div class="empty">⚠️ The client was created, but Billing could not automatically open <b>New Bill (Therapy Plan)</b>.<br>Please return to the GLP page and try again.</div></div>';
              }
            } catch (_) {}

            return;
          }

          try {
            if (
              billingPath() !==
                "/billing" ||
              !billingWindow.document ||
              billingWindow.document.readyState !==
                "complete"
            ) {
              return;
            }

            var doc =
              billingWindow.document;

            var stage =
              doc.getElementById(
                "stage"
              );

            if (!stage) {
              return;
            }

            /*
              If the Therapy Plan workspace is ALREADY visible,
              no need to go through summary again.
            */
            var therapyWorkspace =
              doc.getElementById(
                "bl-lines"
              );

            if (
              therapyWorkspace
            ) {
              clearInterval(
                timer
              );

              finishGLPBillingWorkspace();

              return;
            }

            /*
              IMPORTANT:
              If Billing is currently showing the Client Summary (like the
              screenshot you sent), use its REAL button.
            */
            var newBillButton =
              doc.getElementById(
                "cs-newbill"
              );

            if (
              newBillButton &&
              !newBillClicked
            ) {
              newBillClicked =
                true;

              void 0;

              newBillButton.click();

              return;
            }

            /*
              If Billing is still on its landing/search screen, ask Billing
              to open this Patient summary first.

              We use openSummary() because that is the Billing dashboard's
              native client-selection path. Once summary renders, the loop
              above finds #cs-newbill and clicks it.
            */
            if (
              !summaryRequested
            ) {
              var readyForSummary =
                false;

              try {
                readyForSummary =
                  !!billingEval(
                    "(function(){" +
                      "try{" +
                        "return (" +
                          "typeof openSummary==='function' && " +
                          "typeof getDoc==='function' && " +
                          "typeof CATALOG!=='undefined' && " +
                          "Array.isArray(CATALOG) && " +
                          "typeof BRANCHES!=='undefined' && " +
                          "Array.isArray(BRANCHES)" +
                        ");" +
                      "}catch(e){return false;}" +
                    "})()"
                  );
              } catch (_) {
                readyForSummary =
                  false;
              }

              if (
                readyForSummary
              ) {
                summaryRequested =
                  true;

                /*
                  Filter Billing's in-memory catalogue BEFORE opening
                  New Bill, so the Add Therapy dropdown is GLP-only.
                */
                try {
                  billingEval(
                    "(function(){" +
                      "function n(v){" +
                        "return String(v||'').toLowerCase().replace(/[^a-z0-9.]+/g,'');" +
                      "}" +

                      "function isGLP(v){" +
                        "var s=String(v||'').toLowerCase();" +
                        "return (" +
                          "s.indexOf('glp')>-1 || " +
                          "s.indexOf('wm inj')>-1 || " +
                          "s.indexOf('semaglutide')>-1 || " +
                          "s.indexOf('tirzepatide')>-1 || " +
                          "s.indexOf('mounjaro')>-1 || " +
                          "s.indexOf('ozempic')>-1 || " +
                          "s.indexOf('wegovy')>-1" +
                        ");" +
                      "}" +

                      "var names=" +
                        JSON.stringify(
                          glpNames
                        ) +
                        ";" +

                      "var allowed={};" +

                      "names.forEach(function(x){" +
                        "if(x)allowed[n(x)]=true;" +
                      "});" +

                      "CATALOG=(CATALOG||[]).filter(function(item){" +
                        "var nm=String((item&&(item.n||item.name))||'');" +
                        "var code=String((item&&item.item)||'');" +
                        "return (" +
                          "allowed[n(nm)] || " +
                          "allowed[n(code)] || " +
                          "isGLP(nm) || " +
                          "isGLP(code)" +
                        ");" +
                      "});" +

                      /*
                        GLP launch = therapy type only.
                        Do not allow a historical package-only flag to remove
                        an otherwise genuine GLP therapy.
                      */
                      "CATALOG.forEach(function(item){" +
                        "item.pkg_only=0;" +
                      "});" +

                      "if(typeof TEMPLATES!=='undefined'){" +
                        "TEMPLATES=[];" +
                      "}" +

                      "BILL_MODE='individual';" +

                      "return CATALOG.length;" +
                    "})()"
                  );

                } catch (
                  catalogError
                ) {
                  void 0;
                }

                void 0;

                billingEval(
                  "openSummary(" +
                    JSON.stringify(
                      patientName
                    ) +
                  ");"
                );
              }
            }

          } catch (
            error
          ) {
            /*
              During page navigation there can be short moments where the
              same-origin child window is not ready. Continue polling.
            */
          }
        },
        120
      );


