  async function assessmentPrepareClientV61(
    payload
  ) {
    var csrf =
      (
        window.frappe &&
        (
          frappe.csrf_token ||
          (
            frappe.boot &&
            frappe.boot.csrf_token
          )
        )
      ) ||
      "";

    var form =
      new URLSearchParams();

    Object.keys(
      payload ||
      {}
    ).forEach(
      function (
        key
      ) {
        var value =
          payload[
            key
          ];

        if (
          value !==
            undefined &&
          value !==
            null
        ) {
          form.append(
            key,
            String(
              value
            )
          );
        }
      }
    );

    var response =
      await fetch(
        "/api/method/life_glp_prepare_client_v61",
        {
          method:
            "POST",
          credentials:
            "same-origin",
          headers:
            Object.assign(
              {
                "Accept":
                  "application/json",
                "Content-Type":
                  "application/x-www-form-urlencoded; charset=UTF-8"
              },
              csrf
                ? {
                    "X-Frappe-CSRF-Token":
                      csrf
                  }
                : {}
            ),
          body:
            form.toString()
        }
      );

    var body = {};

    try {
      body =
        await response.json();
    } catch (_) {}

    if (
      !response.ok
    ) {
      throw new Error(
        glpServerMessageFromResponse(
          body,
          "GLP client preparation failed (HTTP " +
            response.status +
            ")."
        )
      );
    }

    var result =
      body &&
      body.message
        ? body.message
        : null;

    if (
      !result ||
      result.server_version !==
        "V5.62"
    ) {
      throw new Error(
        "The GLP V5.62 Server Script is not active. Expected server_version V5.62."
      );
    }

    return result;
  }


