  function normalizedPhone(value) {
    var full = String(value || "").trim();

    if (!full) return null;

    /* Never treat ERPNext document IDs/names as phone numbers. */
    if (/[A-Za-z]/.test(full)) return null;

    var digits = full.replace(/\D/g, "");

    /* Indian/local mobiles are normally 10 digits; allow country code. */
    if (digits.length < 10 || digits.length > 15) {
      return null;
    }

    var displayDigits = digits;

    if (displayDigits.length > 10) {
      displayDigits = displayDigits.slice(-10);
    }

    return {
      full: full,
      digits: displayDigits
    };
  }

  function patientMobileValue(patient) {
    if (!patient) return "";

    var preferred = [
      "mobile",
      "mobile_no",
      "mobile_number",
      "custom_mobile",
      "custom_mobile_no",
      "custom_mobile_number",
      "contact_mobile",
      "contact_number",
      "phone",
      "phone_no",
      "phone_number",
      "telephone"
    ];

    var seen = {};

    for (var i = 0; i < preferred.length; i++) {
      var key = preferred[i];
      seen[key] = true;

      if (
        patient[key] &&
        normalizedPhone(patient[key])
      ) {
        return patient[key];
      }
    }

    /* Fallback for custom Healthcare fields such as custom_client_mobile. */
    var keys = Object.keys(patient);

    for (var j = 0; j < keys.length; j++) {
      var field = keys[j];

      if (
        !seen[field] &&
        /(mobile|phone|telephone|contact.*(no|number))/i.test(field) &&
        patient[field] &&
        normalizedPhone(patient[field])
      ) {
        return patient[field];
      }
    }

    return "";
  }

  function maskClientMobile(value) {
    var phone = normalizedPhone(value);

    if (!phone) {
      return {
        full: "",
        masked: "—"
      };
    }

    return {
      full: phone.full,
      masked:
        phone.digits.slice(0,3) +
        "••••" +
        phone.digits.slice(-3)
    };
  }


