      '</span>'
    );
  }

  function therapyPlanDisplayTitle(plan) {
    if (!plan) {
      return "—";
    }

    var title =
      String(
        plan.title ||
        ""
      ).trim();

    /*
      ERPNext Therapy Plan titles may be stored as a naming/template
      expression such as "{patient_name}". Resolve the common tokens
      before showing the value in the dashboard.
    */
    if (title) {
      title = title
        .replace(
          /\{patient_name\}/gi,
          String(
            plan.patient_name ||
            plan.patient ||
            ""
          )
        )
        .replace(
          /\{patient\}/gi,
          String(
            plan.patient ||
            plan.patient_name ||
            ""
          )
        )
        .replace(
          /\{therapy_plan_template\}/gi,
          String(
            plan.therapy_plan_template ||
            ""
          )
        )
        .trim();
    }

    /*
      Never expose unresolved template syntax to the user.
    */
    if (
      !title ||
      /\{[^}]+\}/.test(title)
    ) {
      title =
        String(
          plan.therapy_plan_template ||
          plan.patient_name ||
          plan.patient ||
          "Therapy Plan"
        ).trim();
    }

    return title || "Therapy Plan";
  }

  function glpClientIdSet() {
    var ids = new Set();

    (STATE.glpPatientIds || [])
      .forEach(function (id) {
        if (id) {
          ids.add(id);
        }
      });

    (STATE.glpPlans || [])
      .forEach(function (p) {
        if (
          p &&
          p.patient
        ) {
          ids.add(
            p.patient
          );
        }
      });

    (STATE.programmeRecords || [])
      .forEach(function (r) {
        if (
          r &&
          r.client
        ) {
          ids.add(
            r.client
          );
        }
      });

    return ids;
  }

  function isGLPClientRecord(patient) {
    if (
      !patient ||
      !patient.name
    ) {
      return false;
    }

    return glpClientIdSet().has(
      patient.name
    );
  }

