  function patientAgeFromDob(
    dob
  ) {
    if (!dob) {
      return "";
    }

    var birth =
      new Date(
        String(dob) +
        "T00:00:00"
      );

    if (
      !Number.isFinite(
        birth.getTime()
      )
    ) {
      return "";
    }

    var now =
      new Date();

    var age =
      now.getFullYear() -
      birth.getFullYear();

    var month =
      now.getMonth() -
      birth.getMonth();

    if (
      month < 0 ||
      (
        month === 0 &&
        now.getDate() <
          birth.getDate()
      )
    ) {
      age -= 1;
    }

    return age >= 0
      ? age
      : "";
  }


  function patientSexShort(
    sex
  ) {
    var s =
      norm(
        sex
      );

    if (s === "female") {
      return "F";
    }

    if (s === "male") {
      return "M";
    }

    if (s) {
      return String(sex)
        .charAt(0)
        .toUpperCase();
    }

    return "";
  }


  function patientProgrammeRecord(
    patientName
  ) {
    return (
      STATE.programmeRecords ||
