            patientName
        );
      })
      .sort(function (a,b) {
        return String(
          b.posting_date ||
          b.modified ||
          b.creation ||
          ""
        ).localeCompare(
          String(
            a.posting_date ||
            a.modified ||
            a.creation ||
            ""
          )
        );
      })[0] || null;
  }


  function patientLatestPlan(
    patientName
  ) {
    return (
      STATE.glpPlans ||
      STATE.data.plans ||
      []
    )
      .filter(function (plan) {
        return (
          plan &&
          plan.patient ===
            patientName &&
          inBranch(plan)
        );
      })
      .sort(function (a,b) {
        return String(
          b.start_date ||
          b.modified ||
          b.creation ||
          ""
        ).localeCompare(
          String(
            a.start_date ||
            a.modified ||
            a.creation ||
            ""
          )
        );
      })[0] || null;
  }


  function patientLatestCurrentWeight(
    patientName
  ) {
    var sessions =
      (
        STATE.glpDoseSessions ||
        []
      )
        .filter(function (session) {
          return (
            session &&
            session.patient ===
              patientName
          );
        })
        .slice()
        .sort(function (a,b) {
          var ad =
            String(
              a.custom_actual_session_date ||
              a.session_date ||
              a.start_date ||
              a.creation ||
              ""
            );

          var bd =
            String(
              b.custom_actual_session_date ||
              b.session_date ||
              b.start_date ||
              b.creation ||
              ""
            );

          return bd.localeCompare(
            ad
          );
        });

    for (
      var i = 0;
      i < sessions.length;
      i++
    ) {
      var weight =
        n(
          sessions[i].after_weight ||
          sessions[i].weight_after ||
          sessions[i].weight
        );

      if (weight > 0) {
        return weight;
      }
    }

    return 0;
  }


  function patientWeightTextNumber(
    value
  ) {
    var number =
      n(value);

    if (
      number <= 0
    ) {
      return "—";
    }

    var rounded =
      Math.round(
        number * 10
      ) / 10;

    return (
      Math.floor(rounded) ===
      rounded
        ? String(
            Math.floor(
              rounded
            )
          )
        : rounded.toFixed(1)
    );
  }


  function patientPackageLabel(
    plan,
    record
  ) {
    if (
      plan &&
      plan.therapy_plan_template
    ) {
      return plan
        .therapy_plan_template;
    }

    var planTherapies =
      (
        plan &&
        plan._glp_therapy_types
      ) ||
      [];

    if (
      planTherapies.length
    ) {
      return planTherapies[0];
    }

    if (
      record &&
      record.therapy_type
    ) {
      return record.therapy_type;
    }

    return "—";
  }


  function patientMoleculeLabel(
    plan,
    record
  ) {
    var candidates = [];

    if (
      record &&
      record.therapy_type
    ) {
      candidates.push(
        record.therapy_type
      );
    }

    (
      (
        plan &&
        plan._glp_therapy_types
      ) ||
      []
    ).forEach(function (therapy) {
      candidates.push(
        therapy
      );
    });

    var known =
      [
        "Semaglutide",
        "Tirzepatide",
        "Liraglutide",
        "Dulaglutide"
      ];

    for (
      var i = 0;
      i < candidates.length;
      i++
    ) {
      var text =
        String(
          candidates[i] ||
          ""
        );

      for (
        var j = 0;
        j < known.length;
        j++
      ) {
        if (
          norm(text).indexOf(
            norm(
              known[j]
            )
          ) >= 0
        ) {
          return known[j];
        }
      }
    }

    return (
      candidates[0] ||
      "—"
    );
  }


  function patientNextDoseAppointment(
    patientName
  ) {
    return (
      STATE.glpAppointments ||
      []
    )
      .filter(function (appointment) {
        return (
          appointment &&
          appointment.patient ===
            patientName &&
          (
            STATE.branch === "ALL" ||
            norm(
              appointmentBranchStrict(
                appointment
              )
            ) ===
              norm(
                STATE.branch
              )
          ) &&
          appointment.appointment_date >=
            todayISO() &&
          isGLPDoseAppointment(
            appointment
          ) &&
          !appointmentDone(
            appointment
          ) &&
          !appointmentMissed(
            appointment
          )
        );
      })
      .sort(function (a,b) {
        var ad =
          String(
            a.appointment_date ||
            ""
          ) +
          " " +
          String(
            a.appointment_time ||
            ""
          );

        var bd =
          String(
            b.appointment_date ||
            ""
          ) +
          " " +
          String(
            b.appointment_time ||
            ""
          );

        return ad.localeCompare(
          bd
        );
      })[0] || null;
  }


  function patientGLPDues(
    patient,
    plans
  ) {
    var planIds =
      new Set(
        (plans || [])
          .map(function (plan) {
            return (
              plan &&
              plan.name
            );
          })
          .filter(Boolean)
      );

    return (
      STATE.glpInvoices ||
      []
    )
      .filter(function (invoice) {
        return (
          invoice &&
          submittedInvoice(
            invoice
          ) &&
          (
            (
              invoice
                .therapy_plan_reference_id &&
              planIds.has(
                invoice
                  .therapy_plan_reference_id
              )
            ) ||
            (
              patient &&
              patient.customer &&
              invoice.customer ===
                patient.customer
            )
          )
        );
      })
      .reduce(function (sum, invoice) {
        return (
          sum +
          glpInvoicePending(
            invoice
          )
        );
      },0);
  }


  function patientDisplayStatus(
    patient,
    plan,
    record
  ) {
    var raw =
      (
        record &&
        record.overall_status
      ) ||
      (
        plan &&
        plan.status
      ) ||
      (
        patient &&
        patient.status
      ) ||
      "—";

    var normalized =
      norm(
        raw
      );

    if (
      normalized ===
      "in progress"
    ) {
      return "Active";
    }

    return String(
      raw
    );
  }


  function patientHasClinicalGate(
    record
  ) {
    if (!record) {
      return false;
    }

    var eligibility =
      norm(
        record.eligibility_status
      );

    var clearance =
      norm(
        record.doctor_clearance
      );

    var consent =
      norm(
        record.consent_status
      );

    return (
      Number(
        record.dose_held ||
        0
      ) === 1 ||
      (
        eligibility &&
        eligibility !==
          "eligible"
      ) ||
      (
        clearance &&
        clearance !==
          "cleared"
      ) ||
      (
        consent &&
        consent !==
          "signed"
      )
    );
  }


  function patientReferenceContext(
    patient
  ) {
    var plans =
      (
        STATE.glpPlans ||
        STATE.data.plans ||
        []
      )
        .filter(function (plan) {
          return (
            plan &&
            plan.patient ===
              patient.name &&
            inBranch(
              plan
            )
          );
        })
        .sort(function (a,b) {
          return String(
            b.start_date ||
            b.modified ||
            b.creation ||
            ""
          ).localeCompare(
            String(
              a.start_date ||
              a.modified ||
              a.creation ||
              ""
            )
          );
        });

    var plan =
      plans[0] ||
      null;

    var record =
      patientProgrammeRecord(
        patient.name
      );

    var progressData =
      plan
        ? glpSessionProgressForPlan(
            plan
          )
        : {
            done:0,
            total:0
          };

    var therapyLabel =
      patientMoleculeLabel(
        plan,
        record
      );

    if (
      progressData.total <= 0 &&
      record &&
      n(
        record.total_doses
      ) > 0 &&
      isGLPDoseTherapyName(
        (
          record.therapy_type ||
          therapyLabel
        )
      )
    ) {
      progressData.total =
        n(
          record.total_doses
        ) *
        GLP_INJECTIONS_PER_DOSE;
    }

    var baselineWeight =
      record &&
      n(
        record.weight
      ) > 0
        ? n(
            record.weight
          )
        : 0;

    var currentWeight =
      patientLatestCurrentWeight(
        patient.name
      );

    var weightLoss =
      (
        baselineWeight > 0 &&
        currentWeight > 0
      )
        ? Math.max(
            0,
            baselineWeight -
              currentWeight
          )
        : 0;

    var due =
      patientGLPDues(
        patient,
        plans
      );

    return {
      patient:
        patient,
      plans:
        plans,
      plan:
        plan,
      record:
        record,
      packageLabel:
        patientPackageLabel(
          plan,
          record
        ),
      moleculeLabel:
        therapyLabel,
      strength:
        (
          record &&
          record.strength
        ) ||
        "",
      progress:
        progressData,
      baselineWeight:
        baselineWeight,
      currentWeight:
        currentWeight,
      weightLoss:
        weightLoss,
      next:
        patientNextDoseAppointment(
          patient.name
        ),
      due:
        due,
      status:
        patientDisplayStatus(
          patient,
          plan,
          record
        ),
      gated:
        patientHasClinicalGate(
          record
        )
    };
  }


  function patientStatusOptionsHtml(
    contexts
  ) {
    var order =
      [
        "Active",
        "Not Started",
        "Completed",
        "Paused",
        "Disabled"
      ];

    var found = {};

    (contexts || [])
      .forEach(function (context) {
        if (
          context &&
          context.status &&
          context.status !== "—"
        ) {
          found[
            context.status
          ] = true;
        }
      });

    var values =
      order.filter(function (value) {
        return !!found[value];
      });

    Object.keys(
      found
    )
      .sort()
      .forEach(function (value) {
        if (
          values.indexOf(
            value
          ) < 0
        ) {
          values.push(
            value
          );
        }
      });

    return (
      '<option value="ALL"' +
        (
          STATE.status ===
          "ALL"
            ? " selected"
            : ""
        ) +
      '>ALL</option>' +
      values
        .map(function (value) {
          return (
            '<option value="' +
              esc(value) +
            '"' +
              (
                STATE.status ===
                value
                  ? " selected"
                  : ""
              ) +
            '>' +
              esc(value) +
            '</option>'
          );
        })
        .join("")
    );
  }


