  function renderPatients() {
    installPatientReferenceStyles();

    var basePatients =
      scoped(
        STATE.data.patients
      )
        .filter(
          isGLPClientRecord
        );

    var allContexts =
      basePatients.map(
        patientReferenceContext
      );

    var active =
      allContexts.filter(function (context) {
        return (
          norm(
            context.status
          ) ===
            "active" ||
          (
            context.plan &&
            [
              "not started",
              "in progress"
            ].indexOf(
              norm(
                context.plan.status
              )
            ) >= 0
          )
        );
      }).length;

    var totalLost =
      allContexts.reduce(
        function (sum, context) {
          return (
            sum +
            n(
              context.weightLoss
            )
          );
        },
        0
      );

    var totalDone =
      allContexts.reduce(
        function (sum, context) {
          return (
            sum +
            n(
              context.progress &&
              context.progress.done
            )
          );
        },
        0
      );

    var totalPlanned =
      allContexts.reduce(
        function (sum, context) {
          return (
            sum +
            n(
              context.progress &&
              context.progress.total
            )
          );
        },
        0
      );

    var outstanding =
      allContexts.reduce(
        function (sum, context) {
          return (
            sum +
            n(
              context.due
            )
          );
        },
        0
      );

    var dueClients =
      allContexts.filter(function (context) {
        return (
          n(
            context.due
          ) > 0
        );
      }).length;

    var filtered =
      allContexts
        .filter(function (context) {
          var p =
            context.patient ||
            {};

          return qmatch([
            p.name,
            p.patient_name,
            patientMobileValue(
              p
            ),
            p.email,
            p._branch,
            context.packageLabel,
            context.moleculeLabel,
            context.strength,
            context.status
          ].join(" "));
        })
        .filter(function (context) {
          return (
            STATE.status === "ALL" ||
            norm(
              context.status
            ) ===
              norm(
                STATE.status
              )
          );
        });

    var h =
      pageHead(
        "CLIENTS · GLP-1 PROGRAMME",
        "Patients",
        "GLP-1 register and progress — package, dose execution, weight movement, next dose and pending collection.",
        '<button class="glp-btn" type="button" data-export="patients">Export</button>'
      );

    h +=
      '<div class="glp-grid glp-grid-4">' +
        tile(
          "Active on programme",
          active,
          allContexts.length +
            " total enrolled",
          "ok",
          ""
        ) +
        tile(
          "Total weight lost",
          totalLost > 0
            ? (
                Math.round(
                  totalLost * 10
                ) / 10
              ) + " kg"
            : "—",
          "across clients with recorded GLP weights",
          "teal",
          ""
        ) +
        tile(
          "Dose adherence",
          pct(
            totalDone,
            totalPlanned
          ) + "%",
          totalDone +
            " of " +
            totalPlanned +
            " GLP executions",
          "ok",
          ""
        ) +
        tile(
          "Outstanding dues",
          outstanding > 0
            ? moneyShort(
                outstanding
              )
            : money(0),
          dueClients +
            (
              dueClients === 1
                ? " client"
                : " clients"
            ),
          outstanding
            ? "crit"
            : "ok",
          ""
        ) +
      '</div>';

    h +=
      patientReferenceFilterHtml(
        allContexts
      );

    h +=
      patientTable(
        filtered
      );

    return h;
  }


  function patientTable(
    contexts
  ) {
    var rows =
      (contexts || [])
        .map(function (context) {
          var p =
            context.patient ||
            {};

          var plan =
            context.plan;

          var record =
            context.record;

          var age =
            patientAgeFromDob(
              p.dob
            );

          var sex =
            patientSexShort(
              p.sex
            );

          var identityBits = [];

          if (p.name) {
            identityBits.push(
              p.name
            );
          }

          if (
            sex ||
            age !== ""
          ) {
            identityBits.push(
              (
                sex ||
                "—"
              ) +
              (
                age !== ""
                  ? "/" + age
                  : ""
              )
            );
          }

          if (
            p._branch
          ) {
            identityBits.push(
              p._branch
            );
          }

          var packageDates = [];

          if (
            plan &&
            plan.start_date
          ) {
            packageDates.push(
              fmtDate(
                plan.start_date
              )
            );
          }

          if (
            plan &&
            plan.due_date
          ) {
            packageDates.push(
              fmtDate(
                plan.due_date
              )
            );
          }

          var doseDone =
            n(
              context.progress &&
              context.progress.done
            );

          var doseTotal =
            n(
              context.progress &&
              context.progress.total
            );

          var weightHtml =
            '<span class="glp-patient-ref-weight-main">—</span>';

          if (
            context.baselineWeight > 0 &&
            context.currentWeight > 0
          ) {
            weightHtml =
              '<span class="glp-patient-ref-weight-main">' +
                patientWeightTextNumber(
                  context.baselineWeight
                ) +
                ' → <b>' +
                patientWeightTextNumber(
