  function glpDateAddDays(
    iso,
    days
  ) {
    var date =
      new Date(
        String(
          iso ||
          todayISO()
        ).slice(
          0,
          10
        ) +
        "T00:00:00"
      );

    date.setDate(
      date.getDate() +
      Number(
        days ||
        0
      )
    );

    return (
      date.getFullYear() +
      "-" +
      String(
        date.getMonth() + 1
      ).padStart(
        2,
        "0"
      ) +
      "-" +
      String(
        date.getDate()
      ).padStart(
        2,
        "0"
      )
    );
  }


