  function glpAppointmentDeskResolvedTherapy(
    appointment
  ) {
    var direct =
      appointmentTherapyLabel(
        appointment
      );

    if (
      direct &&
      norm(
        direct
      ) !==
        "session" &&
      norm(
        direct
      ) !==
        "appointment"
    ) {
      return direct;
    }

    var plan =
      STATE.glpPlanMap[
        appointmentPlanId(
          appointment
        )
      ];

    var types =
      plan &&
      Array.isArray(
        plan._glp_therapy_types
      )
        ? plan._glp_therapy_types
        : [];

    return (
      types[0] ||
      direct ||
      "Session"
    );
  }


  function glpAppointmentDeskTypeCode(
    appointment
  ) {
    var label =
      glpAppointmentDeskResolvedTherapy(
        appointment
      );

    var text =
      norm(
        label
      );

    if (
      isGLPDoseTherapyName(
        label
      ) ||
      valueMatchesGLPTherapy(
        label
      )
    ) {
      return "GLP";
    }

    if (
      text.indexOf(
        "wellness"
      ) >= 0
    ) {
      return "WEL";
    }

    if (
      text.indexOf(
        "muscle"
      ) >= 0
    ) {
      return "MSC";
    }

    var words =
      String(
        label ||
        "Session"
      )
        .replace(
          /[^A-Za-z0-9 ]+/g,
          " "
        )
        .trim()
        .split(
          /\s+/
        )
        .filter(Boolean);

    if (
      words.length > 1
    ) {
      return words
        .slice(
          0,
          3
        )
        .map(
          function (word) {
            return word.charAt(0);
          }
        )
        .join(
          ""
        )
        .toUpperCase();
    }

    return String(
      words[0] ||
      "SES"
    )
      .slice(
        0,
        4
      )
      .toUpperCase();
  }


