  async function glpLoadAppointmentWarehouseMap(
    branches
  ) {
    branches =
      Array.from(
        new Set(
          (branches || [])
            .filter(Boolean)
            .filter(
              function (branch) {
                return !isExcludedBranch(
                  branch
                );
              }
            )
        )
      );

    var meta =
      await glpPopupMeta(
        "Warehouse"
      );

    var fieldMap =
      glpPopupFieldMap(
        meta
      );

    var branchField =
      glpPopupMetaBranchField(
        meta
      );

    var fields = [
      "name"
    ];

    [
      "warehouse_name",
      "parent_warehouse",
      "is_group",
      "disabled",
      "company",
      branchField,
      "branch",
      "branch_name",
      "custom_branch",
      "custom_branch_name",
      "location",
      "custom_location",
      "custom_available_all_branches",
      "available_all_branches",
      "custom_branch_list_text",
      "branch_list_text"
    ].forEach(
      function (fieldname) {
        if (
          fieldname &&
          fieldname !==
            "name" &&
          fieldMap[
            fieldname
          ] &&
          fields.indexOf(
            fieldname
          ) < 0
        ) {
          fields.push(
            fieldname
          );
        }
      }
    );

    var warehouses = [];

    try {
      warehouses =
        await getListPage(
          "Warehouse",
          fields,
          [],
          "name asc",
          0,
          1000
        );

    } catch (e) {
      void 0;

      try {
        warehouses =
          await getListPage(
            "Warehouse",
            [
              "name",
              "warehouse_name",
              "parent_warehouse",
              "is_group",
              "disabled"
            ],
            [],
            "name asc",
            0,
            1000
          );

      } catch (e2) {
        warehouses =
          await getListPage(
            "Warehouse",
            [
              "name"
            ],
            [],
            "name asc",
            0,
            1000
          ).catch(
            function () {
              return [];
            }
          );
      }
    }

    warehouses =
      (warehouses || [])
        .filter(
          function (warehouse) {
            return !(
              Number(
                warehouse.is_group ||
                0
              ) === 1 ||
              Number(
                warehouse.disabled ||
                0
              ) === 1
            );
          }
        );

    var map = {};

    branches.forEach(
      function (branch) {
        var matches =
          warehouses.filter(
            function (warehouse) {
              if (
                branchField &&
                warehouse[
                  branchField
                ] &&
                glpLooseBranchValueMatch(
                  warehouse[
                    branchField
                  ],
                  branch
                )
              ) {
                return true;
              }

              if (
                glpMasterRowMatchesBranch(
                  warehouse,
                  branch,
                  branchField
                )
              ) {
                return true;
              }

              return glpMasterNameContainsBranch(
                glpWarehouseBranchText(
                  warehouse
                ),
                branch
              );
            }
          );

        /*
          Never use HO / unrelated warehouses as a fallback.
          Stock on the Appointment Desk must represent the appointment
          branch's own warehouse position.
        */
        map[
          branch
        ] =
          matches;
      }
    );

    STATE.appointmentStockWarehouseMap =
      map;

    void 0;

    return map;
  }


