              ],
              "posting_date desc",
              1000
            );
          } catch (e) {
            void 0;

            return [];
          }
        }
      );

    invoiceRows =
      uniqueRowsByName(
        invoiceRows ||
        []
      );

    if (!invoiceRows.length) {
      return planItems;
    }

    var invoiceToPlan = {};

    invoiceRows.forEach(
      function (invoice) {
        if (
          invoice &&
          invoice.name &&
          invoice.therapy_plan_reference_id
        ) {
          invoiceToPlan[
            invoice.name
          ] =
            invoice.therapy_plan_reference_id;
        }
      }
    );

    var itemRows =
      await mapChunksLimited(
        chunkArray(
          Object.keys(
            invoiceToPlan
          ),
          100
        ),
        2,
        async function (invoiceNames) {
          try {
            return (
              await getChildListPage(
                "Sales Invoice",
                "Sales Invoice Item",
                [
                  "parent",
                  "item_code",
                  "item_name",
                  "description"
                ],
                [
                  [
                    "parent",
                    "in",
                    invoiceNames
                  ]
                ],
                "parent asc, idx asc",
                0,
                5000
              )
            ) ||
            [];
          } catch (e) {
            void 0;

            return [];
          }
        }
      );

    (itemRows || [])
      .forEach(
        function (row) {
          if (
            !row ||
            !row.parent ||
            !row.item_code
          ) {
            return;
          }

          if (
            !glpInvoiceItemMatches(
              row
            )
          ) {
            return;
          }

          var plan =
            invoiceToPlan[
              row.parent
            ];

          if (!plan) {
            return;
          }

          if (
            !planItems[
              plan
            ]
          ) {
            planItems[
              plan
            ] =
              [];
          }

          if (
            !planItems[
              plan
            ].some(
              function (item) {
                return (
                  item.item_code ===
                  row.item_code
                );
              }
            )
          ) {
            planItems[
              plan
            ].push(
              {
                item_code:
                  row.item_code,
                item_name:
                  row.item_name ||
                  row.item_code,
                description:
                  row.description ||
                  ""
              }
            );
          }
        }
      );

    return planItems;
  }


  async function glpLoadAppointmentItemMasters(
    itemCodes
  ) {
    itemCodes =
      Array.from(
        new Set(
          (itemCodes || [])
            .filter(Boolean)
        )
      );

    var map = {};

    if (!itemCodes.length) {
      return map;
    }

    var rows =
      await mapChunksLimited(
        chunkArray(
          itemCodes,
          120
        ),
        2,
        async function (codes) {
          try {
            return await getListPage(
              "Item",
              [
                "name",
                "item_code",
                "item_name",
                "is_stock_item",
                "stock_uom",
                "disabled"
              ],
              [
                [
                  "name",
                  "in",
                  codes
                ]
              ],
              "item_name asc",
              0,
              500
            );
          } catch (e) {
            void 0;

            return [];
          }
        }
      );

    (rows || [])
      .forEach(
        function (item) {
          if (!item) {
            return;
          }

          var code =
            item.item_code ||
            item.name;

          if (code) {
            map[
              code
            ] =
              item;
          }

          if (
            item.name &&
            !map[
              item.name
            ]
          ) {
            map[
              item.name
            ] =
              item;
          }
        }
      );

    return map;
  }


  function glpAppointmentRelevantStockItems(
    appointment,
    planInvoiceItems,
    itemMasters
  ) {
    var directCode =
      glpAppointmentDirectItemCode(
        appointment
      );

    var candidates = [];

    if (
      directCode &&
      itemMasters[
        directCode
      ] &&
      Number(
        itemMasters[
          directCode
        ].is_stock_item ||
        0
      ) === 1
    ) {
      candidates.push(
        {
          item_code:
            directCode,
          item_name:
            itemMasters[
              directCode
            ].item_name ||
            directCode,
          stock_uom:
            itemMasters[
              directCode
            ].stock_uom ||
            ""
        }
      );
    }

    var planId =
      appointmentPlanId(
        appointment
      );

    var invoiceItems =
      (
        planInvoiceItems[
          planId
        ] ||
        []
      )
        .filter(
          function (row) {
            return (
              row.item_code &&
              itemMasters[
                row.item_code
              ] &&
              Number(
                itemMasters[
                  row.item_code
                ].is_stock_item ||
                0
              ) === 1
            );
          }
        )
        .map(
          function (row) {
            return {
              item_code:
                row.item_code,
              item_name:
                (
                  itemMasters[
                    row.item_code
                  ] &&
                  itemMasters[
                    row.item_code
                  ].item_name
                ) ||
                row.item_name ||
                row.item_code,
              stock_uom:
                (
                  itemMasters[
                    row.item_code
                  ] &&
                  itemMasters[
                    row.item_code
                  ].stock_uom
                ) ||
                ""
            };
          }
        );

    var strengthTokens =
      glpAppointmentStrengthTokens(
        glpAppointmentDeskResolvedTherapy(
          appointment
        )
      );

    if (
      strengthTokens.length &&
      invoiceItems.length
    ) {
      var strengthMatches =
        invoiceItems.filter(
          function (item) {
            var text =
              norm(
                item.item_code +
                " " +
                item.item_name
              )
                .replace(
                  /\s+/g,
                  ""
                );

            return strengthTokens.some(
              function (token) {
                return (
                  text.indexOf(
                    token
                  ) >= 0
                );
              }
            );
          }
        );

      if (strengthMatches.length) {
        invoiceItems =
          strengthMatches;
      }
    }

    invoiceItems.forEach(
      function (item) {
        if (
          !candidates.some(
            function (existing) {
              return (
                existing.item_code ===
                item.item_code
              );
            }
          )
        ) {
          candidates.push(
            item
          );
        }
      }
    );

    return candidates;
  }


  function glpAppointmentStockQtyText(
    qty
  ) {
    qty =
      Number(
        qty ||
        0
      );

    if (
      Math.abs(
        qty -
        Math.round(
          qty
        )
      ) <
      0.000001
    ) {
      return String(
        Math.round(
          qty
        )
      );
    }

    return qty.toLocaleString(
      "en-IN",
      {
        maximumFractionDigits:2
      }
    );
  }


  async function loadAppointmentStockFast(
    appointments
  ) {
    appointments =
      appointments ||
      [];

    STATE.appointmentStockLoading =
      true;

    try {
      if (!appointments.length) {
        STATE.appointmentStockByAppointment =
          {};

        return;
      }

      var branches =
        Array.from(
          new Set(
            appointments
              .map(
                function (appointment) {
                  return (
                    appointmentBranchStrict(
                      appointment
                    ) ||
                    appointment._branch ||
                    appointment.branch ||
                    ""
                  );
                }
              )
              .filter(Boolean)
              .filter(
                function (branch) {
                  return !isExcludedBranch(
                    branch
                  );
                }
              )
          )
        );

      var warehouseMap =
        await glpLoadAppointmentWarehouseMap(
          branches
        );

      var planInvoiceItems =
        await glpLoadAppointmentPlanInvoiceItems(
          appointments
        );

      var itemCodes = [];

      appointments.forEach(
        function (appointment) {
          var direct =
            glpAppointmentDirectItemCode(
              appointment
            );

          if (direct) {
            itemCodes.push(
              direct
            );
          }

          var plan =
            appointmentPlanId(
              appointment
            );

          (
            planInvoiceItems[
              plan
            ] ||
            []
          )
            .forEach(
              function (row) {
                if (
                  row.item_code
                ) {
                  itemCodes.push(
                    row.item_code
                  );
                }
              }
            );
        }
      );

      itemCodes =
        Array.from(
          new Set(
            itemCodes
              .filter(Boolean)
          )
        );

      var itemMasters =
        await glpLoadAppointmentItemMasters(
          itemCodes
        );

      var appointmentItems = {};
      var stockItemCodes = [];

      appointments.forEach(
        function (appointment) {
          var items =
            glpAppointmentRelevantStockItems(
              appointment,
              planInvoiceItems,
              itemMasters
            );

          appointmentItems[
            appointment.name
          ] =
            items;

          items.forEach(
            function (item) {
              stockItemCodes.push(
                item.item_code
              );
            }
          );
        }
      );

      stockItemCodes =
        Array.from(
          new Set(
            stockItemCodes
              .filter(Boolean)
          )
        );

      var warehouseNames =
        Array.from(
          new Set(
            Object.keys(
              warehouseMap
            )
              .reduce(
                function (
                  all,
                  branch
                ) {
                  return all.concat(
                    (
                      warehouseMap[
                        branch
                      ] ||
                      []
                    )
                      .map(
                        function (warehouse) {
                          return warehouse.name;
                        }
                      )
                  );
                },
                []
              )
              .filter(Boolean)
          )
        );

      var binRows = [];

      if (
        warehouseNames.length &&
        stockItemCodes.length
      ) {
        var warehouseChunks =
          chunkArray(
            warehouseNames,
            80
          );

        var itemChunks =
          chunkArray(
            stockItemCodes,
            80
          );

        var tasks = [];

        warehouseChunks.forEach(
          function (warehouseChunk) {
            itemChunks.forEach(
              function (itemChunk) {
                tasks.push(
                  function () {
                    return getListPage(
                      "Bin",
                      [
                        "name",
                        "warehouse",
                        "item_code",
                        "actual_qty",
                        "reserved_qty",
                        "projected_qty"
                      ],
                      [
                        [
                          "warehouse",
                          "in",
                          warehouseChunk
                        ],
                        [
                          "item_code",
                          "in",
                          itemChunk
                        ]
                      ],
                      "warehouse asc",
                      0,
                      1000
                    ).catch(
                      function (e) {
                        void 0;

                        return [];
                      }
                    );
                  }
                );
              }
            );
          }
        );

        for (
          var taskIndex = 0;
          taskIndex < tasks.length;
          taskIndex++
        ) {
          var rows =
            await tasks[
              taskIndex
            ]();

          binRows =
            binRows.concat(
              rows ||
              []
            );
        }
      }

      var binMap = {};

      (binRows || [])
        .forEach(
          function (bin) {
            if (
              !bin ||
              !bin.warehouse ||
              !bin.item_code
            ) {
              return;
            }

            var key =
              bin.warehouse +
              "||" +
              bin.item_code;

            binMap[
              key
            ] = {
              actual_qty:
                n(
                  bin.actual_qty
                ),
              reserved_qty:
                n(
                  bin.reserved_qty
                ),
              projected_qty:
                n(
                  bin.projected_qty
                )
            };
          }
        );

      var result = {};

      appointments.forEach(
        function (appointment) {
          var branch =
            appointmentBranchStrict(
              appointment
            ) ||
            appointment._branch ||
            appointment.branch ||
            "";

          var warehouses =
            warehouseMap[
              branch
            ] ||
            [];

          var items =
            appointmentItems[
              appointment.name
            ] ||
            [];

          if (!branch) {
            result[
              appointment.name
            ] = {
              state:"no-branch",
              qty:0,
              branch:"",
              warehouses:[],
              items:items
            };

            return;
          }

          if (!warehouses.length) {
            result[
              appointment.name
            ] = {
              state:"no-warehouse",
              qty:0,
              branch:branch,
              warehouses:[],
              items:items
            };

            return;
          }

          if (!items.length) {
            result[
              appointment.name
            ] = {
              state:"no-item",
              qty:0,
              branch:branch,
              warehouses:
                warehouses,
              items:[]
            };

            return;
          }

          var totalQty = 0;
          var totalReserved = 0;
          var totalProjected = 0;
          var breakdown = [];

          warehouses.forEach(
            function (warehouse) {
              items.forEach(
                function (item) {
                  var bin =
                    binMap[
                      warehouse.name +
                      "||" +
                      item.item_code
                    ];

                  var qty =
                    bin
                      ? n(
                          bin.actual_qty
                        )
                      : 0;

                  var reserved =
                    bin
                      ? n(
                          bin.reserved_qty
                        )
                      : 0;

                  var projected =
                    bin
                      ? n(
                          bin.projected_qty
                        )
                      : 0;

                  totalQty +=
                    qty;

                  totalReserved +=
                    reserved;

                  totalProjected +=
                    projected;

                  breakdown.push(
                    {
                      warehouse:
                        warehouse.name,
                      item_code:
                        item.item_code,
                      item_name:
                        item.item_name,
                      stock_uom:
                        item.stock_uom,
                      actual_qty:
                        qty,
                      reserved_qty:
                        reserved,
                      projected_qty:
                        projected
                    }
                  );
                }
              );
            }
          );

          result[
            appointment.name
          ] = {
            state:
              totalQty > 0
                ? "available"
                : "zero",
            qty:
              totalQty,
            reserved_qty:
              totalReserved,
            projected_qty:
              totalProjected,
            branch:
              branch,
            warehouses:
              warehouses,
            items:
              items,
            breakdown:
              breakdown
          };
        }
      );

      STATE.appointmentStockByAppointment =
        result;

      STATE.appointmentStockLoadedAt =
        Date.now();

      void 0;

    } catch (e) {
      void 0;

      STATE.appointmentStockByAppointment =
        {};

    } finally {
      STATE.appointmentStockLoading =
        false;
    }
  }


  function glpAppointmentStockCell(
    appointment
  ) {
    var stock =
      STATE.appointmentStockByAppointment[
        appointment.name
      ];

    if (
      STATE.appointmentStockLoading &&
      !stock
    ) {
      return (
        '<span class="glp-appt-stock-pill loading">Loading…</span>' +
        '<span class="glp-muted">branch warehouse</span>'
      );
    }

    if (!stock) {
      return (
        '<span class="glp-appt-stock-pill neutral">—</span>' +
        '<span class="glp-muted">stock not loaded</span>'
      );
    }

    if (
      stock.state ===
      "no-warehouse"
    ) {
      return (
        '<span class="glp-appt-stock-pill warn">No warehouse</span>' +
        '<span class="glp-muted">' +
          esc(
            stock.branch ||
            "branch"
          ) +
        '</span>'
      );
    }

    if (
      stock.state ===
      "no-item"
    ) {
      var warehouseText =
        (stock.warehouses || [])
          .map(
            function (warehouse) {
              return warehouse.name;
            }
          )
          .slice(
            0,
            1
          )
          .join(
            ""
          );

      return (
        '<span class="glp-appt-stock-pill neutral">No stock item</span>' +
        '<span class="glp-muted">' +
          esc(
            warehouseText ||
            "Therapy Type / Invoice item is not a stock item"
          ) +
        '</span>'
      );
    }

    var qty =
      n(
        stock.qty
      );

    var tone =
      qty <= 0
        ? "crit"
        : (
            qty <= 2
              ? "warn"
              : "ok"
          );

    var itemText =
      (stock.items || [])
        .map(
          function (item) {
            return (
              item.item_name ||
              item.item_code
            );
          }
        )
        .join(
          ", "
        );

    var warehouseText =
      (stock.warehouses || [])
        .map(
          function (warehouse) {
            return warehouse.name;
          }
        )
        .join(
          ", "
        );

    var title =
      [
        itemText,
        warehouseText,
        "Actual Qty: " +
          glpAppointmentStockQtyText(
            qty
          ),
        "Reserved Qty: " +
          glpAppointmentStockQtyText(
            stock.reserved_qty
          ),
        "Projected Qty: " +
          glpAppointmentStockQtyText(
            stock.projected_qty
          )
      ]
        .filter(Boolean)
        .join(
          " · "
        );

    return (
      '<span class="glp-appt-stock-pill ' +
        tone +
        '" title="' +
        esc(
          title
        ) +
      '">' +
        (
          qty > 0
            ? (
                glpAppointmentStockQtyText(
                  qty
                ) +
                " in stock"
              )
            : "Out of stock"
        ) +
      '</span>' +
      '<span class="glp-muted" title="' +
        esc(
          warehouseText
        ) +
      '">' +
        esc(
          (
            stock.items &&
            stock.items.length === 1
              ? (
                  stock.items[0].item_name ||
                  stock.items[0].item_code
                )
              : (
                  stock.items.length +
                  " GLP stock items"
                )
          ) ||
          "—"
        ) +
      '</span>'
    );
  }


  function glpAppointmentDeskFilterList(
    sourceList
  ) {
    var list =
      (sourceList || [])
        .slice();

    var period =
      STATE.appointmentDeskPeriod ||
      "today";

    var meta =
      glpAppointmentDeskPeriodMeta()[
        period
      ] ||
      glpAppointmentDeskPeriodMeta().today;

    if (
      period ===
      "missed"
    ) {
      list =
        list.filter(
          appointmentMissed
        );

    } else if (
      period !==
      "all" &&
      meta.from &&
      meta.to
    ) {
      list =
        list.filter(
          function (appointment) {
            var date =
              String(
                appointment.appointment_date ||
                ""
              ).slice(
                0,
                10
              );

            return (
              date &&
              date >=
                meta.from &&
              date <=
                meta.to
            );
          }
        );
    }

    var branch =
      STATE.appointmentDeskBranch ||
      "ALL";

    if (
      STATE.branch !==
      "ALL"
    ) {
      branch =
        STATE.branch;
    }

    if (
      branch !==
      "ALL"
    ) {
      list =
        list.filter(
          function (appointment) {
            return (
              norm(
                appointmentBranchStrict(
                  appointment
                ) ||
                appointment._branch ||
                ""
              ) ===
              norm(
                branch
              )
            );
          }
        );
    }

    var type =
      STATE.appointmentDeskType ||
      "ALL";

    if (
      type !==
      "ALL"
    ) {
      list =
        list.filter(
          function (appointment) {
            return (
              norm(
                glpAppointmentDeskTypeFilterValue(
                  appointment
                )
              ) ===
              norm(
                type
              )
            );
          }
        );
    }

    if (
      STATE.q
    ) {
      list =
        list.filter(
          function (appointment) {
            return qmatch(
              [
                appointment.name,
                appointment.patient,
                appointment.patient_name,
                glpAppointmentDeskResolvedTherapy(
                  appointment
                ),
                appointment.practitioner,
                appointment.practitioner_name,
                glpAppointmentStatus(
                  appointment
                ),
                appointmentBranchStrict(
                  appointment
                ),
                glpAppointmentServiceRoom(
                  appointment
                )
              ].join(
                " "
              )
            );
          }
        );
    }

    return list;
  }


