  function glpAppointmentDeskTabsHtml() {
    var meta =
      glpAppointmentDeskPeriodMeta();

    var order = [
      "today",
      "tomorrow",
      "week",
      "nextweek",
      "next30",
      "missed",
      "all"
    ];

    return (
      '<div class="glp-appt-tabs">' +
        order.map(
          function (key) {
            var item =
              meta[
                key
              ];

            return (
              '<button type="button" class="glp-appt-tab' +
                (
                  STATE.appointmentDeskPeriod ===
                    key
                    ? " active"
                    : ""
                ) +
              '" data-appointment-period="' +
                esc(
                  key
                ) +
              '">' +
                esc(
