  function glpAppointmentDeskToolbarHtml(
    allList,
    shownList
  ) {
    var branchValues =
      Array.from(
        new Set(
          (allList || [])
            .map(
              function (appointment) {
                return (
                  appointmentBranchStrict(
                    appointment
                  ) ||
                  appointment._branch ||
                  ""
                );
              }
            )
            .filter(Boolean)
            .filter(
              function (branch) {
                return !isExcludedBranch(
                  branch
                );
              }
            )
        )
      )
        .sort(
          function (a,b) {
            return a.localeCompare(
              b
            );
          }
        );

    if (
      STATE.branch !==
      "ALL"
    ) {
      branchValues = [
        STATE.branch
      ];

      STATE.appointmentDeskBranch =
        STATE.branch;

    } else if (
      STATE.appointmentDeskBranch !==
        "ALL" &&
      branchValues.indexOf(
        STATE.appointmentDeskBranch
      ) < 0
    ) {
      STATE.appointmentDeskBranch =
        "ALL";
    }

    var typeValues =
      Array.from(
        new Set(
          (allList || [])
            .map(
              glpAppointmentDeskTypeFilterValue
            )
            .filter(Boolean)
        )
      )
        .sort(
          function (a,b) {
            return a.localeCompare(
              b
            );
          }
        );

    if (
      STATE.appointmentDeskType !==
        "ALL" &&
      typeValues.indexOf(
        STATE.appointmentDeskType
      ) < 0
    ) {
      STATE.appointmentDeskType =
        "ALL";
    }

    var doseCount =
      (shownList || [])
        .filter(
          isGLPDoseAppointment
        )
        .length;

    return (
      '<div class="glp-appt-toolbar">' +

        '<div class="glp-appt-toolbar-field">' +
          '<label>Session Type</label>' +
          '<select id="glp-appt-type-filter">' +
            '<option value="ALL">All types</option>' +
            typeValues.map(
              function (type) {
                return (
                  '<option value="' +
                    esc(
                      type
                    ) +
                  '"' +
                  (
                    STATE.appointmentDeskType ===
                      type
                      ? " selected"
                      : ""
                  ) +
                  '>' +
                    esc(
                      type
                    ) +
                  '</option>'
                );
              }
            ).join(
              ""
            ) +
          '</select>' +
        '</div>' +

        '<div class="glp-appt-toolbar-field">' +
          '<label>Branch</label>' +
          '<select id="glp-appt-branch-filter"' +
            (
              STATE.branch !==
                "ALL"
                ? " disabled"
                : ""
            ) +
          '>' +
            (
              STATE.branch ===
                "ALL"
                ? '<option value="ALL">All branches</option>'
                : ""
            ) +
            branchValues.map(
              function (branch) {
                return (
                  '<option value="' +
                    esc(
                      branch
                    ) +
                  '"' +
                  (
                    (
                      STATE.branch !==
                        "ALL"
                        ? STATE.branch
                        : STATE.appointmentDeskBranch
                    ) ===
                      branch
                      ? " selected"
                      : ""
                  ) +
                  '>' +
                    esc(
                      branch
                    ) +
                  '</option>'
                );
              }
            ).join(
              ""
            ) +
          '</select>' +
        '</div>' +

        '<div>' +
          '<button class="glp-btn" type="button" data-appointment-desk-reset>Reset</button>' +
        '</div>' +

        '<div class="glp-appt-showing">' +
          '<span>Showing</span>' +
          '<b>' +
            (shownList || []).length +
            ' appointments · ' +
            doseCount +
            ' GLP doses' +
          '</b>' +
        '</div>' +

      '</div>'
    );
  }


  function exportAppointmentDeskCSV(
    list
  ) {
    list =
      list ||
      [];

    var rows = [
      [
        "Date",
        "Time",
        "Client",
        "Client ID",
        "Branch",
        "Type",
        "Dose / Therapy",
        "Performed By",
        "Status",
        "Service Room",
        "Stock Qty",
        "Stock Item",
        "Branch Warehouse"
      ]
    ];

    list.forEach(
      function (appointment) {
        var stock =
          STATE.appointmentStockByAppointment[
            appointment.name
          ] ||
          {};

        rows.push(
          [
            appointment.appointment_date ||
              "",
            appointment.appointment_time ||
              "",
            appointment.patient_name ||
              appointment.patient ||
              "",
            appointment.patient ||
              "",
            appointmentBranchStrict(
              appointment
            ) ||
              appointment._branch ||
              "",
            glpAppointmentDeskTypeCode(
              appointment
            ),
            glpAppointmentDeskResolvedTherapy(
              appointment
            ),
            appointment.practitioner_name ||
              appointment.practitioner ||
              "",
            glpAppointmentStatus(
              appointment
            ),
            glpAppointmentServiceRoom(
              appointment
            ),
            stock.qty !== undefined
              ? stock.qty
              : "",
            (stock.items || [])
              .map(
                function (item) {
                  return (
                    item.item_name ||
                    item.item_code
                  );
                }
              )
              .join(
                " | "
              ),
            (stock.warehouses || [])
              .map(
                function (warehouse) {
                  return warehouse.name;
                }
              )
              .join(
                " | "
              )
          ]
        );
      }
    );

    var csv =
      rows.map(
        function (row) {
          return row.map(
            function (cell) {
              return (
                '"' +
                String(
                  cell === null ||
                  cell === undefined
                    ? ""
                    : cell
                ).replace(
                  /"/g,
                  '""'
                ) +
                '"'
              );
            }
          ).join(
            ","
          );
        }
      ).join(
        "\r\n"
      );

    var blob =
      new Blob(
        [
          "\ufeff" +
          csv
        ],
        {
          type:
            "text/csv;charset=utf-8"
        }
      );

    var url =
      URL.createObjectURL(
        blob
      );

    var link =
      document.createElement(
        "a"
      );

    link.href =
      url;

    link.download =
      "LIFE_GLP_Appointment_Desk_" +
      todayISO() +
      ".csv";

    document.body.appendChild(
      link
    );

    link.click();
    link.remove();

    setTimeout(
      function () {
        URL.revokeObjectURL(
          url
        );
      },
      1000
    );
  }


