  function appointmentTable(
    list
  ) {
    var rows =
      (list || [])
        .map(
          function (appointment) {
            var done =
              appointmentDone(
                appointment
              );

            var branch =
              appointmentBranchStrict(
                appointment
              ) ||
              appointment._branch ||
              "—";

            var isDose =
              isGLPDoseAppointment(
                appointment
              );

            var actionHtml =
              "";

            if (
              !done &&
              !appointmentMissed(
                appointment
              )
            ) {
              if (
                isDose
              ) {
                actionHtml =
                  '<button type="button" class="glp-appt-action execute" data-view="plans">Execute session</button>';
              } else {
                actionHtml =
                  '<button type="button" class="glp-appt-action" data-appointment-mark-done="' +
                    esc(
                      appointment.name
                    ) +
                  '">Mark done</button>';
              }
            }

            return (
              '<tr class="click' +
                (
                  done
                    ? ' glp-appt-done-row'
                    : ''
                ) +
              '" data-appointment-details="' +
                esc(
                  appointment.name
                ) +
              '">' +

                '<td>' +
                  '<span class="glp-appt-date">' +
                    esc(
                      glpAppointmentDeskShortDate(
                        appointment.appointment_date
                      )
                    ) +
                  '</span>' +
                  '<span class="glp-appt-time">' +
                    esc(
                      fmtTime(
                        appointment.appointment_time
                      )
                    ) +
                  '</span>' +
                '</td>' +

                '<td>' +
                  '<span class="glp-appt-client">' +
                    esc(
                      appointment.patient_name ||
                      appointment.patient ||
                      "—"
                    ) +
                  '</span>' +
                  '<span class="glp-appt-meta">' +
                    esc(
                      (
                        appointment.patient ||
                        ""
                      ) +
                      (
                        branch
                          ? " · " +
                            branch
                          : ""
                      )
                    ) +
                  '</span>' +
                '</td>' +

                '<td>' +
                  '<span class="glp-appt-type-pill">' +
                    esc(
                      glpAppointmentDeskTypeCode(
                        appointment
                      )
                    ) +
                  '</span>' +
                '</td>' +

                '<td>' +
                  '<span class="glp-appt-dose">' +
                    esc(
                      glpAppointmentDeskResolvedTherapy(
                        appointment
                      )
                    ) +
                  '</span>' +
                '</td>' +

                '<td>' +
                  esc(
                    appointment.practitioner_name ||
                    appointment.practitioner ||
                    "—"
                  ) +
                '</td>' +

                '<td>' +
                  glpAppointmentDeskStatusHtml(
                    appointment
                  ) +
                '</td>' +

                '<td>' +
                  glpAppointmentStockCell(
                    appointment
                  ) +
                '</td>' +

                '<td class="glp-appt-action-cell">' +
                  actionHtml +
                '</td>' +

              '</tr>'
            );
          }
        )
        .join("");

    if (
      !rows
    ) {
      rows =
        '<tr><td colspan="8" class="glp-appt-empty">No appointments found for this Appointment Desk filter.</td></tr>';
    }

    return (
      '<div class="glp-appt-card">' +
        '<div class="glp-appt-table-wrap">' +
          '<table class="glp-appt-table">' +
            '<thead>' +
              '<tr>' +
                '<th>Date / Time</th>' +
                '<th>Client</th>' +
                '<th>Type</th>' +
                '<th>Dose</th>' +
                '<th>Performed By</th>' +
                '<th>Status</th>' +
                '<th>Stock</th>' +
                '<th></th>' +
              '</tr>' +
            '</thead>' +
            '<tbody>' +
              rows +
            '</tbody>' +
          '</table>' +
        '</div>' +
      '</div>'
    );
  }


  async function glpAppointmentDeskMarkDone(
    appointmentName,
    button
  ) {
    appointmentName =
      String(
        appointmentName ||
        ""
      ).trim();

    if (!appointmentName) {
      return;
    }

    var oldText =
      button
        ? button.textContent
        : "";

    try {
      if (button) {
        button.disabled =
          true;

        button.textContent =
          "Saving…";
      }

      await frappeCall(
        "frappe.client.set_value",
        {
          doctype:
            "Patient Appointment",
          name:
            appointmentName,
          fieldname:
            {
              status:
                "Closed"
            }
        },
        15000
      );

      (
        STATE.data.appointments ||
        []
      ).forEach(
        function (
          appointment
        ) {
          if (
            appointment &&
            appointment.name ===
              appointmentName
          ) {
            appointment.status =
              "Closed";
          }
        }
      );

      (
        STATE.glpAppointments ||
        []
      ).forEach(
        function (
          appointment
        ) {
          if (
            appointment &&
            appointment.name ===
              appointmentName
          ) {
            appointment.status =
              "Closed";
          }
        }
      );

      toast(
        "Appointment marked complete"
      );

      render();

    } catch (
      error
    ) {
      void 0;

      if (button) {
        button.disabled =
          false;

        button.textContent =
          oldText ||
          "Mark done";
      }

      glpSafeMessage(
        "Appointment not updated",
        glpRequestErrorMessage(
          error
        ),
        true
      );
    }
  }


  function renderPlans() {
    var list = (STATE.glpPlans || []).filter(function (p) {
      return qmatch([
        p.name,p.patient,p.patient_name,p.status,p.therapy_plan_template,
        p.category,p.custom_category,p.therapy_type,p.custom_therapy_type,p._branch
      ].join(" "));
    });

    var h = pageHead(
      "OPERATIONS · THERAPY PLAN",
      "Session Execution",
      "Only Therapy Plans containing a GLP-related Therapy Type are shown. Start Date and Branch filters are applied before classification.",
      '<button class="glp-btn" type="button" data-dose-review-help="1">Dose review first</button>' +
      '<button class="glp-btn primary" type="button" data-new-therapy-session="1">+ New therapy session</button>'
    );

    var glpPlanProgress = list.map(
      glpSessionProgressForPlan
    );

    h += '<div class="glp-grid glp-grid-4">' +
      tile("Plans",list.length,"selected branch","teal","") +
      tile("Active",list.filter(function (p) { return ["in progress","not started"].indexOf(norm(p.status)) >= 0; }).length,"active / not started","ok","") +
      tile("Sessions completed",glpPlanProgress.reduce(function (s,r) { return s + n(r.done); },0),"GLP sessions completed","blue","") +
      tile("Adherence",pct(
        glpPlanProgress.reduce(function (s,r) { return s + n(r.done); },0),
        glpPlanProgress.reduce(function (s,r) { return s + n(r.total); },0)
      ) + "%","GLP completed vs planned","gold","") +
    '</div>';

    h += viewSearchBox();
    h += planTable(list);

    return h;
  }

  function planTable(list) {
    var rows = list.map(function (p) {
      var glpProgress =
        glpSessionProgressForPlan(p);

      var done = glpProgress.done;
      var total = glpProgress.total;

      return '<tr class="click" data-open-doctype="Therapy Plan" data-open-name="' + esc(p.name) + '">' +
        '<td><span class="glp-name">' + esc(p.patient_name || p.patient || "—") + '</span><span class="glp-muted">' + esc(p.patient || "") + ' · ' + esc(p._branch || "—") + '</span></td>' +
        '<td><span class="glp-name">' + esc(therapyPlanDisplayTitle(p)) + '</span></td>' +
        '<td>' + fmtDate(p.start_date) + '</td>' +
        '<td><b>' + done + ' / ' + (total > 0 ? total : '—') + '</b>' + progress(done,total) + '</td>' +
        '<td>' + esc(
          (p._glp_therapy_types || []).join(", ") ||
          "GLP Therapy"
