  function followupTasks() {
    var real =
      (STATE.programmeRecords || [])
        .filter(function (r) {
          return (
            Number(r.followup_required || 0) === 1 ||
            !!r.followup_date ||
            !!r.followup_type
          );
        })
        .map(function (r) {
          var completed =
            norm(r.followup_status) ===
            "completed";

          return {
            due:
              r.followup_date ||
              r.posting_date ||
              todayISO(),
            client:
              r.client_name ||
              r.client ||
              r.lead ||
              "—",
            patient:
              r.client ||
              r.lead ||
              "",
            branch:
              r.branch || "",
            type:
              r.followup_type ||
              "Follow-up",
            remarks:
              r.followup_remarks ||
              r.remarks ||
              "",
            by:
              r.completed_by ||
              r.assigned_to ||
              "",
            status:
              completed
                ? "Closed"
                : "Pending",
            sourceDoctype:
              "GLP Programme Record",
            sourceName:
              r.name
          };
        });

    return real.filter(function (x) {
      return qmatch([
        x.client,x.patient,x.branch,
        x.type,x.remarks,x.by,x.status
      ].join(" "));
    });
