  function addDays(value,days) {
    var d = new Date(value + "T00:00:00");
    d.setDate(d.getDate()+days);
    return d.getFullYear() + "-" +
      String(d.getMonth()+1).padStart(2,"0") + "-" +
      String(d.getDate()).padStart(2,"0");
  }

  function renderFollowups() {
    var all = followupTasks();
    var today = todayISO();

    var overdue = all.filter(function (f) {
      return f.status === "Pending" && f.due < today;
    });

    var due = all.filter(function (f) {
      return f.status === "Pending" && f.due === today;
    });

    var upcoming = all.filter(function (f) {
      return f.status === "Pending" && f.due > today;
    });

    var closed = all.filter(function (f) {
      return f.status === "Closed";
    });

    var map = {
      over:overdue,
      due:due,
      up:upcoming,
      done:closed,
      all:all
    };

    var list = map[STATE.followTab] || due;

    var h = pageHead(
      "LIFE ERP · GLP-1 PROGRAMME",
      "Follow-up Desk",
      "Tolerance calls, appointment reminders, missed appointment recovery and therapy-plan review queue.",
      '<button class="glp-btn primary" type="button" data-new-doctype="Patient Appointment">+ New follow-up</button>'
    );

    h += '<div class="glp-grid glp-grid-4">' +
      tile("Overdue",overdue.length,"past due and still open","crit","") +
      tile("Due today",due.length,fmtDate(today),"warn","") +
      tile("Upcoming",upcoming.length,"future reminders","blue","") +
      tile("Closed",closed.length,"completed source appointments","ok","") +
    '</div>';

    h += '<div class="glp-view-filter">' +
      ["over","due","up","done","all"].map(function (k) {
        var label = {over:"Overdue",due:"Due today",up:"Upcoming",done:"Closed",all:"All"}[k];
        return '<button type="button" class="glp-btn ' + (STATE.followTab === k ? "primary" : "") + '" data-follow-tab="' + k + '">' + label + '</button>';
