  // ================================================================
  // V5.81 - HARD REMOVE OLD DASHBOARD READING LEGEND
  // ================================================================
  // Older cached/rendered builds could still leave this legend in the DOM:
  // READING · Good — on plan · Watch · Intervene · Stock and cold chain
  // · People and clients · Money and decisions.
  //
  // V5.80 no longer renders that markup, and this hard cleanup additionally
  // removes/hides any stale copy that survives browser/page caching.
  function removeGLPReadingLegendV581() {
    if (!ROOT) {
      return;
    }

    if (
      !document.getElementById(
        "life-glp-v581-hide-reading-legend"
      )
    ) {
      var style =
        document.createElement(
          "style"
        );

      style.id =
        "life-glp-v581-hide-reading-legend";

      style.textContent =
        "#life-glp-app .glp-legend{display:none!important;}";

      document.head.appendChild(
        style
      );
    }

    Array.from(
      ROOT.querySelectorAll(
        ".glp-legend, [data-glp-reading-legend]"
      )
    ).forEach(
      function (node) {
        var text =
          String(
            node.textContent ||
            ""
          ).toLowerCase();

        if (
          text.indexOf("good") >= 0 &&
          text.indexOf("watch") >= 0 &&
          text.indexOf("intervene") >= 0
        ) {
          if (node.parentNode) {
            node.parentNode.removeChild(
              node
            );
          }
        }
      }
    );

    /*
      Also catch a stale element where an old build lost its class but kept
      the exact text sequence.
    */
    Array.from(
      ROOT.querySelectorAll(
        "div,section,aside"
      )
    ).forEach(
      function (node) {
        var text =
          String(
            node.textContent ||
            ""
          )
            .replace(
              /\s+/g,
              " "
            )
            .trim()
            .toLowerCase();

        if (
          text.length < 250 &&
          text.indexOf("reading") >= 0 &&
          text.indexOf("good") >= 0 &&
          text.indexOf("watch") >= 0 &&
          text.indexOf("intervene") >= 0 &&
          text.indexOf("stock and cold chain") >= 0 &&
          text.indexOf("people and clients") >= 0 &&
          text.indexOf("money and decisions") >= 0
        ) {
          if (node.parentNode) {
            node.parentNode.removeChild(
              node
            );
          }
        }
      }
    );
  }


