  function render() {
    renderNav();

    if (
      STATE.view === "dashboard" &&
      STATE.branchDetail
    ) {
      CONTENT.innerHTML =
        renderBranchDetail();
    } else if (
      STATE.view === "dashboard"
    ) {
      CONTENT.innerHTML =
        renderDashboard();
    }
    else if (STATE.view === "leads") CONTENT.innerHTML = renderLeads();
    else if (STATE.view === "assessment") CONTENT.innerHTML = renderAssessment();
    else if (STATE.view === "patients") CONTENT.innerHTML = renderPatients();
    else if (STATE.view === "appointments") CONTENT.innerHTML = renderAppointments();
    else if (STATE.view === "plans") CONTENT.innerHTML = renderPlans();
    else if (STATE.view === "followups") CONTENT.innerHTML = renderFollowups();
    else if (STATE.view === "invoices") CONTENT.innerHTML = renderInvoices();
    else if (STATE.view === "stock") CONTENT.innerHTML = renderStock();
    else if (STATE.view === "usedstock") CONTENT.innerHTML = renderUsedStockV580();
    else if (STATE.view === "pens") CONTENT.innerHTML = renderPenRegister();
    else if (STATE.view === "adverse") CONTENT.innerHTML = renderAdverseEvents();
    else CONTENT.innerHTML = renderPlaceholder(STATE.view);

    bindDynamic();
    installGLPCompactTableStylesV576();
    installGLPEnquiryCompactStylesV582();
    installGLPReferenceTypographyV583();
    removeGLPReadingLegendV581();
  }

  function bindDynamic() {
    var usedStockRefresh =
      ROOT.querySelector(
        "[data-refresh-used-stock]"
      );

    if (usedStockRefresh) {
      usedStockRefresh.addEventListener(
        "click",
        async function () {
          var button =
            this;

          var oldText =
            button.textContent;

          button.disabled =
            true;

          button.textContent =
            "Refreshing...";

          try {
            await glpLoadUsedStockV580();
            render();
          } catch (e) {
            glpSafeMessage(
              "Used Stock could not refresh",
              glpRequestErrorMessage(
                e
              ),
              true
            );
          } finally {
            button.disabled =
              false;

            button.textContent =
              oldText ||
              "↻ Refresh";
          }
        }
      );
    }

    var s = $("glp-view-search");

    if (s) {
      var searchTimer = null;

      s.addEventListener(
        "input",
        function () {
          STATE.q = this.value;
          STATE.invoicePage = 1;

          if (
            STATE.view === "invoices"
          ) {
            clearTimeout(
              searchTimer
            );

            searchTimer =
              setTimeout(
                async function () {
                  await loadInvoicePageFast(1);
                  render();

                  var r =
                    $("glp-view-search");

                  if (r) {
                    r.focus();
                    r.setSelectionRange(
                      r.value.length,
                      r.value.length
                    );
                  }
                },
                300
              );

            return;
          }

          render();

          var r =
            $("glp-view-search");

          if (r) {
            r.focus();
            r.setSelectionRange(
              r.value.length,
              r.value.length
            );
          }
        }
      );
    }


    if (
      STATE.view ===
      "patients"
    ) {
      var patientStatusFilter =
        $(
          "glp-patient-status-filter"
        );

      if (
        patientStatusFilter
      ) {
        patientStatusFilter
          .addEventListener(
            "change",
            function () {
              STATE.status =
                this.value ||
                "ALL";

              render();
            }
          );
      }
    }

    if (
      STATE.view ===
      "appointments"
    ) {
      Array.from(
        ROOT.querySelectorAll(
          "[data-appointment-period]"
        )
      ).forEach(
        function (button) {
          button.addEventListener(
            "click",
            function () {
              STATE.appointmentDeskPeriod =
                this.getAttribute(
                  "data-appointment-period"
                ) ||
                "today";

              render();
            }
          );
        }
      );

      var appointmentTypeFilter =
        $(
          "glp-appt-type-filter"
        );

      if (appointmentTypeFilter) {
        appointmentTypeFilter.addEventListener(
          "change",
          function () {
            STATE.appointmentDeskType =
              this.value ||
              "ALL";

            render();
          }
        );
      }

      var appointmentBranchFilter =
        $(
          "glp-appt-branch-filter"
        );

      if (appointmentBranchFilter) {
        appointmentBranchFilter.addEventListener(
          "change",
          function () {
            STATE.appointmentDeskBranch =
              this.value ||
              "ALL";

            render();
          }
        );
      }

      var appointmentReset =
        ROOT.querySelector(
          "[data-appointment-desk-reset]"
        );

      if (appointmentReset) {
        appointmentReset.addEventListener(
          "click",
          function () {
            STATE.appointmentDeskPeriod =
              "today";

            STATE.appointmentDeskBranch =
              STATE.branch !==
                "ALL"
                ? STATE.branch
                : "ALL";

            STATE.appointmentDeskType =
              "ALL";

            STATE.q =
              "";

            render();
          }
        );
      }

      var appointmentExport =
        ROOT.querySelector(
          "[data-appointment-export]"
        );

      if (appointmentExport) {
        appointmentExport.addEventListener(
          "click",
          function () {
            exportAppointmentDeskCSV(
              glpAppointmentDeskFilterList(
                scoped(
                  STATE.data.appointments
                )
              )
            );
          }
        );
      }
    }


    var assessmentLeadSearch =
      $("glp-assessment-lead-search");

    if (assessmentLeadSearch) {
      var assessmentSearchTimer = null;
      var assessmentSearchToken = 0;

      assessmentLeadSearch.addEventListener(
        "input",
        function () {
          var input =
            this;

          var raw =
            String(
              input.value || ""
            ).trim();

          var select =
            $("glp-assessment-lead");

          var selectWrap =
            $("glp-assessment-select-wrap");

          var hint =
            $("glp-assessment-search-hint");

          var results =
            $("glp-assessment-search-results");

          if (
            !select ||
            !selectWrap ||
            !results
          ) {
            return;
          }

          clearTimeout(
            assessmentSearchTimer
          );

          assessmentSearchToken += 1;

          var token =
            assessmentSearchToken;

          if (raw.length < 3) {
            selectWrap.style.display =
              "none";

            results.style.display =
              "none";

            results.innerHTML = "";

            select.innerHTML =
              '<option value="">— select enquiry —</option>';

            if (hint) {
              hint.textContent =
                "Type 3 letters or digits to search only GLP-treatment clients in " + assessmentClientScopeLabel();
            }

            return;
          }

          selectWrap.style.display =
            "none";

          results.style.display =
            "block";

          results.innerHTML =
            '<div class="glp-assessment-result-loading">Searching ERPNext...</div>';

          select.innerHTML =
            '<option value="">Searching...</option>';

          if (hint) {
            hint.textContent =
              "Searching GLP clients in " +
              assessmentClientScopeLabel() +
              "...";
          }

          assessmentSearchTimer =
            setTimeout(
              async function () {
                try {
                  var matches =
                    await searchAssessmentEnquiriesFast(
                      raw
                    );

                  if (
                    token !==
                    assessmentSearchToken
                  ) {
                    return;
                  }

                  /*
                    Keep only the current search result set.
                    This prevents the Assessment page from slowly
                    accumulating hundreds of Lead rows.
                  */
                  var selected =
                    assessmentSelectedLead();

                  STATE.data.leads =
                    selected
                      ? [selected]
                      : [];

                  matches.forEach(
                    function (l) {
                      if (
                        !STATE.data.leads.some(
                          function (x) {
                            return (
                              x.name ===
                              l.name
                            );
                          }
                        )
                      ) {
                        STATE.data.leads.push(
                          l
                        );
                      }
                    }
                  );

                  var html =
                    '<option value="">— select enquiry —</option>';

                  matches.forEach(
                    function (l) {
                      var mobile =
                        maskClientMobile(
                          l.mobile_no ||
                          l.phone ||
                          ""
                        );

                      html +=
                        '<option value="' +
                          esc(l.name) +
                        '">' +
                          esc(
                            leadName(l) +
                            " · " +
                            mobile.masked +
                            " · " +
                            (
                              l._branch ||
                              l.branch ||
                              "—"
                            )
                          ) +
                        '</option>';
                    }
                  );

                  select.innerHTML =
                    html;

                  if (matches.length) {
                    results.style.display =
                      "block";

                    results.innerHTML =
                      matches.map(
                        function (l) {
                          var mobile =
                            maskClientMobile(
                              l.mobile_no ||
                              l.phone ||
                              ""
                            );

                          return (
                            '<button type="button" class="glp-assessment-result" ' +
                              'data-assessment-lead-choice="' +
                                esc(l.name) +
                              '">' +
                              '<span class="glp-assessment-result-main">' +
                                esc(leadName(l)) +
                              '</span>' +
                              '<span class="glp-assessment-result-meta">' +
                                esc(mobile.masked) +
                                ' · ' +
                                esc(
                                  l._branch ||
                                  l.branch ||
                                  "—"
                                ) +
                              '</span>' +
                            '</button>'
                          );
                        }
                      ).join("");

                    Array.from(
                      results.querySelectorAll(
                        "[data-assessment-lead-choice]"
                      )
                    ).forEach(
                      function (btn) {
                        btn.addEventListener(
                          "click",
                          async function () {
                            var value =
                              this.getAttribute(
                                "data-assessment-lead-choice"
                              ) || "";

                            if (!value) {
                              return;
                            }

                            select.value =
                              value;

                            STATE.assessmentLead =
                              value;

                            STATE.assessmentStep = 1;

                            STATE.assessmentLeadLoading =
                              true;

                            render();

                            await loadSelectedAssessmentLeadFull(
                              value
                            );

                            STATE.assessmentLeadLoading =
                              false;

                            render();
                          }
                        );
                      }
                    );

                  } else {
                    results.style.display =
                      "block";

                    results.innerHTML =
                      '<div class="glp-assessment-result-empty">No GLP-treatment clients found in this branch.</div>';
                  }

                  if (hint) {
                    hint.textContent =
                      matches.length
                        ? (
                            matches.length +
                            " matching enquir" +
                            (
                              matches.length === 1
                                ? "y"
                                : "ies"
                            ) +
                            " · select one below"
                          )
                        : "No GLP-treatment clients found in this branch";
                  }

                } catch (e) {
                  if (
                    token !==
                    assessmentSearchToken
                  ) {
                    return;
                  }

                  void 0;

                  select.innerHTML =
                    '<option value="">Search failed — try again</option>';

                  results.style.display =
                    "block";

                  results.innerHTML =
                    '<div class="glp-assessment-result-empty">Search failed — try again.</div>';

                  if (hint) {
                    hint.textContent =
                      "Could not search ERPNext. Try another 3-letter / 3-digit search.";
                  }
                }
              },
              280
            );
        }
      );

      assessmentLeadSearch.addEventListener(
        "keydown",
        function (e) {
          if (e.key !== "Enter") {
            return;
          }

          var raw =
            String(
              this.value || ""
            ).trim();

          if (raw.length < 3) {
            e.preventDefault();

            var hint =
              $("glp-assessment-search-hint");

            if (hint) {
              hint.textContent =
                "Type at least 3 letters or 3 digits first";
            }

            return;
          }

          var select =
            $("glp-assessment-lead");

          if (!select) {
            return;
          }

          var realOptions =
            Array.from(
              select.options
            ).filter(
              function (o) {
                return !!o.value;
              }
            );

          if (realOptions.length === 1) {
            e.preventDefault();

            select.value =
              realOptions[0].value;

            select.dispatchEvent(
              new Event(
                "change",
                {
                  bubbles:true
                }
              )
            );
          }
        }
      );
    }

    var assessmentLead =
      $("glp-assessment-lead");

    if (assessmentLead) {
      assessmentLead.addEventListener(
        "change",
        async function () {
          var value =
            this.value || "";

          STATE.assessmentLead =
            value;

          STATE.assessmentStep = 1;

          if (!value) {
            STATE.assessmentLeadLoading =
              false;

            render();
            return;
          }

          STATE.assessmentLeadLoading =
            true;

          render();

          await loadSelectedAssessmentLeadFull(
            value
          );

          STATE.assessmentLeadLoading =
            false;

          render();
        }
      );
    }

    if (STATE.view === "assessment") {
      bindAssessmentLiveInputs();
    }

    var enquiryClient =
      $("glp-enquiry-client-filter");

    var enquiryClientResults =
      $("glp-enquiry-client-results");

    if (
      enquiryClient &&
      enquiryClientResults
    ) {
      enquiryClient.addEventListener(
        "input",
        function () {
          var value =
            this.value || "";

          STATE.leadClientFilter =
            value;

          STATE.leadClientSelectedId =
            "";

          STATE.leadPage = 1;

          paintEnquiryClientSuggestions(
            this,
            enquiryClientResults
          );

          /*
            Clearing the field immediately restores all clients.
            For 1–2 characters we deliberately do not show/select/filter.
          */
          if (!value.trim()) {
            render();
          }
        }
      );

      enquiryClient.addEventListener(
        "focus",
        function () {
          paintEnquiryClientSuggestions(
            this,
            enquiryClientResults
          );
        }
      );

      enquiryClientResults.addEventListener(
        "click",
        function (event) {
          var option =
            event.target.closest(
              "[data-enquiry-client-name]"
            );

          if (!option) {
            return;
          }

          var name =
            option.getAttribute(
              "data-enquiry-client-name"
            );

          var lead =
            (STATE.data.leads || [])
              .find(function (l) {
                return l.name === name;
              });

          if (!lead) {
            return;
          }

          /*
            Show only the client name in the search field.
            Keep the exact Lead ID separately so the Enquiry Register
            still filters to the selected record only.
          */
          STATE.leadClientFilter =
            leadName(
              lead
            );

          STATE.leadClientSelectedId =
            lead.name;

          STATE.leadPage = 1;

          enquiryClientResults.style.display =
            "none";

          render();
        }
      );

      document.addEventListener(
        "click",
        function (event) {
          if (
            !enquiryClient.contains(
              event.target
            ) &&
            !enquiryClientResults.contains(
              event.target
            )
          ) {
            enquiryClientResults.style.display =
              "none";
          }
        },
        {
          once: true
        }
      );
    }


    var stage =
      $("glp-stage-filter");

    if (stage) {
      stage.addEventListener(
        "change",
        function () {
          STATE.stage =
            this.value;

          STATE.leadPage = 1;
          render();
        }
      );
    }

    var source =
      $("glp-source-filter");

    if (source) {
      source.addEventListener(
        "change",
        function () {
          STATE.source =
            this.value;

          STATE.leadPage = 1;
          render();
        }
      );
    }
  }

  async function gotoView(view) {
    STATE.view = view;
    STATE.branchDetail = "";
    STATE.branchDetailData = {
      leads: [],
      appointments: [],
      patients: []
    };
    STATE.q = "";
    STATE.stage = "ALL";
    STATE.source = "ALL";
    STATE.leadClientFilter = "";
    STATE.leadClientSelectedId = "";
    STATE.leadPage = 1;
    STATE.invoicePage = 1;

    if (
      view ===
      "appointments"
    ) {
      STATE.appointmentDeskPeriod =
        "today";

      STATE.appointmentDeskType =
        "ALL";

      STATE.appointmentDeskBranch =
        STATE.branch !==
          "ALL"
          ? STATE.branch
          : "ALL";
    }

    NAV.some(function (g) {
      var found =
        g.items.some(
          function (it) {
            return it[0] === view;
          }
        );

      if (found) {
        STATE.openGroup =
          g.group;
        return true;
      }

      return false;
    });

    SIDE.classList.remove("open");

    CONTENT.innerHTML =
      '<div class="glp-loading">' +
        '<span class="glp-spinner"></span>' +
        '<div><b>Loading ' +
        esc(view) +
        '...</b><span>Only this module is being fetched.</span></div>' +
      '</div>';

    if (
      view === "dashboard"
    ) {
      await loadDashboardPreview();
    } else {
      await loadFullViewFast(
        view
      );
    }

    render();

    window.scrollTo({
      top:0,
      behavior:"smooth"
    });
  }

