  function styleLeadEnquiryDialog(
    dialog
  ) {
    if (
      !dialog ||
      !dialog.$wrapper
    ) {
      return;
    }

    installLeadEnquiryDialogStyles();

    dialog.$wrapper.addClass(
      "glp-enquiry-dialog"
    );

    var header =
      dialog.$wrapper.find(
        ".modal-header"
      );

    if (
      header.length &&
      !header.find(
        ".glp-enquiry-dialog-subtitle"
      ).length
    ) {
      header.append(
        '<div class="glp-enquiry-dialog-subtitle">Creates a Lead in ERPNext and adds it to the enquiry register.</div>'
      );
    }

    var footer =
      dialog.$wrapper.find(
        ".modal-footer"
      );

    if (
      footer.length &&
      !footer.find(
        ".glp-enquiry-cancel"
      ).length
    ) {
      /*
        IMPORTANT:
        This GLP page already has its own $(id) helper, so using
        $("<button>") here incorrectly calls document.getElementById()
        instead of jQuery. That was the reason the Log enquiry button
        stopped working in V5.29.

        Create the Cancel button with the native DOM API instead.
      */
      var cancel =
        document.createElement(
          "button"
        );

      cancel.type =
        "button";

      cancel.className =
        "btn btn-default glp-enquiry-cancel";

      cancel.textContent =
        "Cancel";

      cancel.addEventListener(
        "click",
        function () {
          dialog.hide();
        }
      );

      if (
        footer[0]
      ) {
        footer[0].insertBefore(
          cancel,
          footer[0].firstChild
        );
      }
    }
  }


