              )
                .filter(Boolean)
                .filter(function (branchName) {
                  return !isExcludedBranch(
                    branchName
                  );
                });

            var filters = [
              [
                "Branch",
                "name",
                "not in",
                [
                  "Testing Branch",
                  "Head Office"
                ]
              ]
            ];

            if (
              allowed.length
            ) {
              filters.push([
                "Branch",
                "name",
                "in",
                allowed
              ]);
            }

            return {
              filters:
                filters
            };
          }
        },

        {
          fieldtype: "Column Break"
        },

        {
          fieldtype: "Link",
          fieldname: "source",
          label: "Source",
          options: "Lead Source",
          reqd: 1
        },

        {
          fieldtype: "Section Break"
        },

        {
          fieldtype: "Data",
          fieldname: "custom_bmi",
          label: "BMI stated"
        },

        {
          fieldtype: "Column Break"
        },

        {
          fieldtype: "Link",
          fieldname: "lead_owner",
          label: "Owner",
          options: "User",
          default: currentUser,
          get_query: function () {
