        }
      ],

      primary_action_label:
        "Save enquiry",

      primary_action:
        async function (values) {
          try {
            if (!values.first_name) {
              frappe.msgprint(
                "Name is required."
              );
              return;
            }

            if (!values.mobile_no) {
              frappe.msgprint(
                "Mobile is required."
              );
              return;
            }

            if (!values.branch) {
              frappe.msgprint(
                "Branch is required."
              );
              return;
            }

            if (!values.source) {
              frappe.msgprint(
                "Source is required."
              );
              return;
            }

            if (
              isExcludedBranch(
                values.branch
              )
            ) {
              frappe.msgprint(
                "Testing Branch and Head Office cannot be selected."
              );
              return;
            }

            d.disable_primary_action();

            var doc = {
              doctype: "Lead",

              /* Your Lead naming series */
              naming_series:
                "CRM-LEAD-.YYYY.-",

              /* Full Name is read-only in your Lead;
                 ERPNext derives it from first_name / last_name. */
              first_name:
                values.first_name,

              mobile_no:
                values.mobile_no,

              branch:
                values.branch,

              source:
                values.source,

              /* Your required Lead status field */
              status:
                "Lead",

              custom_posting_date:
                todayISO(),

              custom_status_updated_date:
                todayISO(),

              custom_cc_stage:
                "UNTOUCHED"
            };

            if (values.lead_owner) {
              doc.lead_owner =
                values.lead_owner;
            }

            if (
              values.custom_bmi !== "" &&
              values.custom_bmi != null
            ) {
              doc.custom_bmi =
                String(
                  values.custom_bmi
                ).trim();
            }

            if (
              values.custom_remarks
            ) {
              doc.custom_remarks =
                values.custom_remarks;
            }

            var inserted =
              await frappeCall(
                "frappe.client.insert",
                {
                  doc: doc
                }
              );

            d.hide();

            toast(
              "Enquiry saved: " +
              (
                inserted &&
                inserted.name
                  ? inserted.name
                  : values.first_name
              )
            );

            /* Refresh exact live lead values */
            await loadSummaryFast();

            if (
              STATE.view === "leads"
            ) {
              await loadFullViewFast(
                "leads"
              );
            } else {
              await loadDashboardPreview();
            }

            render();

          } catch (e) {
            void 0;

            d.enable_primary_action();

            var msg =
              "Could not save the enquiry.";

            try {
              if (
                e &&
                e._server_messages
              ) {
                var messages =
                  JSON.parse(
                    e._server_messages
                  );

                if (
                  messages &&
                  messages.length
                ) {
                  var parsed =
                    JSON.parse(
                      messages[0]
                    );

                  if (
                    parsed &&
                    parsed.message
                  ) {
                    msg =
                      parsed.message;
                  }
                }
              }
            } catch (ignore) {}

            frappe.msgprint({
              title:
                "Could not save enquiry",
              indicator:
                "red",
              message:
                msg
            });
          }
        }
    });

    d.show();

    styleLeadEnquiryDialog(
      d
    );
  }


  /* ============================================================
     V4.18 APPOINTMENT + THERAPY SESSION POPUPS
     No page navigation. Saves directly into ERPNext backend.
     ============================================================ */

  var GLP_POPUP_META_CACHE = {};

  async function glpPopupMeta(doctype) {
    if (GLP_POPUP_META_CACHE[doctype]) {
      return GLP_POPUP_META_CACHE[doctype];
    }

    try {
      var m =
        await getFullDoc(
          "DocType",
          doctype
        );

      GLP_POPUP_META_CACHE[doctype] =
        m || {
          fields: []
        };

    } catch (e) {
      void 0;

      GLP_POPUP_META_CACHE[doctype] = {
        fields: []
      };
    }

    return GLP_POPUP_META_CACHE[doctype];
  }

  function glpPopupFieldMap(meta) {
    var map = {};

    (
      meta &&
      Array.isArray(meta.fields)
        ? meta.fields
        : []
    ).forEach(
      function (f) {
        if (f.fieldname) {
          map[f.fieldname] = f;
        }
      }
    );

    return map;
  }

  function glpPopupExistingField(
    meta,
    candidates
  ) {
    var map =
      glpPopupFieldMap(meta);

    for (
      var i = 0;
      i < candidates.length;
      i++
    ) {
      if (map[candidates[i]]) {
        return candidates[i];
      }
    }

    return "";
  }

  function glpPopupFieldByLabel(
    meta,
    labels
  ) {
    var wanted =
      (labels || [])
        .map(
          function (label) {
            return norm(
              label
            );
          }
        )
        .filter(Boolean);

    if (!wanted.length) {
      return "";
    }

    var fields =
      (
        meta &&
        Array.isArray(
          meta.fields
        )
      )
        ? meta.fields
        : [];

    for (
      var i = 0;
      i < fields.length;
      i++
    ) {
      var field =
        fields[i];

      if (
        !field ||
        !field.fieldname
      ) {
        continue;
      }

      var label =
        norm(
          field.label ||
          ""
        );

      var fieldname =
        norm(
          field.fieldname ||
          ""
        );

      if (
        wanted.indexOf(
          label
        ) >= 0 ||
        wanted.indexOf(
          fieldname
        ) >= 0
      ) {
        return field.fieldname;
      }
    }

    return "";
  }


  function glpPopupPutSmart(
    doc,
    meta,
    candidates,
    labels,
    value
  ) {
    if (
      value === undefined ||
      value === null ||
      (
        typeof value === "string" &&
        value === ""
      )
    ) {
      return "";
    }

    var fieldname =
      glpPopupExistingField(
        meta,
        candidates || []
      );

    if (!fieldname) {
      fieldname =
        glpPopupFieldByLabel(
          meta,
          labels || []
        );
    }

    if (fieldname) {
      doc[fieldname] =
        value;
    }

    return fieldname;
  }


  function glpPopupPut(
    doc,
    meta,
    candidates,
    value,
    fallback
  ) {
    if (
      value === undefined ||
      value === null ||
      (
        typeof value === "string" &&
        value === ""
      )
    ) {
      return "";
    }

    var fieldname =
      glpPopupExistingField(
        meta,
        candidates
      );

    if (!fieldname && fallback) {
      fieldname = fallback;
    }

    if (fieldname) {
      doc[fieldname] = value;
    }

    return fieldname;
  }

  function glpPopupTime(value) {
    var s =
      String(value || "").trim();

    if (
      /^\d{2}:\d{2}$/.test(s)
    ) {
      return s + ":00";
    }

    return s;
  }

  function glpAppointmentTimeLabel(
    value
  ) {
    var parts =
      String(
        value ||
        ""
      ).split(":");

    var hour =
      Number(
        parts[0] ||
        0
      );

    var minute =
      Number(
        parts[1] ||
        0
      );

    var suffix =
      hour >= 12
        ? "PM"
        : "AM";

    var displayHour =
      hour % 12;

    if (!displayHour) {
      displayHour =
        12;
    }

    return (
      displayHour +
      ":" +
      String(
        minute
      ).padStart(
        2,
        "0"
      ) +
      " " +
      suffix
    );
  }


  function glpAppointmentDefaultTime() {
    var now =
      new Date();

    var minutes =
      (
        now.getHours() *
        60
      ) +
      now.getMinutes();

    /*
      Round UP to the next dashboard slot:
      7:00, 7:30, 8:00, 8:30 ... 7:00 PM.
    */
    minutes =
      Math.ceil(
        minutes /
        30
      ) *
      30;

    minutes =
      Math.max(
        7 * 60,
        Math.min(
          19 * 60,
          minutes
        )
      );

    return (
      String(
        Math.floor(
          minutes /
          60
        )
      ).padStart(
        2,
        "0"
      ) +
      ":" +
      String(
        minutes %
        60
      ).padStart(
        2,
        "0"
      )
    );
  }


  function glpAppointmentTimeOptions(
    selected
  ) {
    selected =
      selected ||
      glpAppointmentDefaultTime();

    var out =
      '<option value="">Select time...</option>';

    for (
      var minutes =
        7 * 60;
      minutes <=
        19 * 60;
      minutes +=
        30
    ) {
      var value =
        String(
          Math.floor(
            minutes /
            60
          )
        ).padStart(
          2,
          "0"
        ) +
        ":" +
        String(
          minutes %
          60
        ).padStart(
          2,
          "0"
        );

      out +=
        '<option value="' +
        value +
        '"' +
        (
          value ===
          selected
            ? ' selected'
            : ''
        ) +
