      ).padStart(2,"0")
    );
  }

  function glpPopupAddMinutes(
    time,
    minutes
  ) {
    var p =
      String(time || "00:00")
        .split(":");

    var total =
      (
        Number(p[0] || 0) *
        60
      ) +
      Number(p[1] || 0) +
      Number(minutes || 0);

    total =
      (
        total %
        1440 +
        1440
      ) %
      1440;

    return (
      String(
        Math.floor(total / 60)
      ).padStart(2,"0") +
      ":" +
      String(
        total % 60
      ).padStart(2,"0")
    );
  }

  function glpPopupPlan(name) {
    return (
      STATE.glpPlanMap &&
      STATE.glpPlanMap[name]
    ) || null;
