  function glpPopupPlanTypes(plan) {
    var types =
      plan &&
      Array.isArray(
        plan._glp_therapy_types
      )
        ? plan._glp_therapy_types
        : [];

    return types
      .filter(Boolean)
      .filter(
        function (v,i,a) {
          return a.indexOf(v) === i;
