  function glpPopupTherapyType(
    name
  ) {
    var n = norm(name);

    return (
      STATE.glpTherapyTypes ||
      []
    ).find(
      function (t) {
        return (
          norm(t.name) === n ||
          norm(t.therapy_type) === n
        );
      }
    ) || null;
  }

  function glpPopupBranchOptions() {
    var rows =
      (
        (
          STATE.allBranches &&
          STATE.allBranches.length
            ? STATE.allBranches
            : STATE.branches
        ) || []
      ).filter(
        function (b) {
          return (
            b &&
            !isExcludedBranch(b)
          );
        }
      );

    if (
      STATE.userBranchScope &&
      STATE.userBranchScope.length
    ) {
      var allowed =
        STATE.userBranchScope.map(norm);

      rows =
        rows.filter(function (b) {
          return allowed.indexOf(
            norm(b)
          ) >= 0;
        });
    }

    return rows;
  }

  function glpEffectiveAppointmentBranch(plan) {
    var candidates = [
      plan &&
        (
          plan._branch ||
          plan.branch
        ),
      STATE.branchDetail,
      (
        STATE.branch !== "ALL"
          ? STATE.branch
          : ""
      ),
      (
        STATE.userBranchLocked &&
        STATE.userBranchScope &&
        STATE.userBranchScope.length === 1
          ? STATE.userBranchScope[0]
          : ""
      )
    ];

    for (
      var i = 0;
      i < candidates.length;
      i++
    ) {
      var b =
        String(
          candidates[i] || ""
        ).trim();

      if (
        b &&
        !isExcludedBranch(b) &&
        glpBranchAllowedForCurrentUser(b)
      ) {
        return b;
      }
    }

    return "";
  }

  function glpPopupPlanQuery(
    dialog
