  function glpPopupUpdateTypeOptions(
    dialog,
    planName
  ) {
    var plan =
      glpPopupPlan(
        planName
      );

    var types =
      glpPopupPlanTypes(
        plan
      );

    if (!types.length) {
      types = (
        STATE.glpTherapyTypes ||
        []
      ).map(
        function (t) {
          return (
            t.therapy_type ||
            t.name
          );
        }
      ).filter(Boolean);
    }

    var control =
      dialog.get_field(
        "therapy_type"
      );

    if (
      control &&
      control.df
    ) {
      control.df.options =
        [""]
          .concat(types)
          .join("\n");

      control.refresh();
    }

    if (types.length) {
      dialog.set_value(
        "therapy_type",
        types[0]
      );
    }
  }

  function glpPopupApplyPlan(
    dialog,
    planName
  ) {
    var plan =
      glpPopupPlan(
        planName
