  function installGLPGlobalErrorPopupTopLayer() {
    if (
      window.__lifeGLPGlobalPopupTopLayerInstalled
    ) {
      return;
    }

    window.__lifeGLPGlobalPopupTopLayerInstalled =
      true;

    var style =
      document.createElement(
        "style"
      );

    style.id =
      "glp-global-popup-top-layer-style";

    /*
      #glp-native-modal = 99999.

      Frappe / Bootstrap error dialogs are forced above it so server-side
      validation messages (frappe.throw, MandatoryError, ValidationError,
      msgprint, request errors, etc.) are always visible.
    */
    style.textContent = `
      body > .modal-backdrop,
      body .modal-backdrop {
        z-index: 2147483400 !important;
      }

      body > .modal,
      body .modal.show,
      body .frappe-dialog,
      body .msgprint-dialog,
      body [data-modal="true"] {
        z-index: 2147483500 !important;
      }

      body .modal .modal-dialog,
      body .frappe-dialog .modal-dialog,
      body .msgprint-dialog .modal-dialog {
        position: relative !important;
        z-index: 2147483501 !important;
      }

      #glp-top-message-modal {
        z-index: 2147483600 !important;
      }
    `;

    document.head.appendChild(
      style
    );

    function raiseNode(
      node
    ) {
      if (
        !node ||
        node.nodeType !== 1
      ) {
        return;
      }

      var element =
        node;

      if (
        element.matches &&
        element.matches(
          ".modal-backdrop"
        )
      ) {
        element.style.setProperty(
          "z-index",
          "2147483400",
          "important"
        );
      }

      if (
        element.matches &&
        element.matches(
          ".modal, .frappe-dialog, .msgprint-dialog"
        )
      ) {
        element.style.setProperty(
          "z-index",
          "2147483500",
          "important"
        );
      }

      if (
        element.querySelectorAll
      ) {
        element
          .querySelectorAll(
            ".modal-backdrop"
          )
          .forEach(
            function (backdrop) {
              backdrop.style.setProperty(
                "z-index",
                "2147483400",
                "important"
              );
            }
          );

        element
          .querySelectorAll(
            ".modal, .frappe-dialog, .msgprint-dialog"
          )
          .forEach(
            function (dialog) {
              dialog.style.setProperty(
                "z-index",
                "2147483500",
                "important"
              );
            }
          );
      }
    }

    /*
      Frappe creates its error modal only after the request fails.
      Watch the DOM so even dynamically-created server error popups are
      lifted above the open Therapy Session modal immediately.
    */
    var observer =
      new MutationObserver(
        function (mutations) {
          mutations.forEach(
            function (mutation) {
              (
                mutation.addedNodes ||
                []
              ).forEach(
                raiseNode
              );
            }
          );
        }
      );

    observer.observe(
      document.body,
      {
        childList: true,
        subtree: true
      }
    );

    /*
      Also raise any dialog that was already present before this function
      was installed.
    */
    document
      .querySelectorAll(
        ".modal-backdrop, .modal, .frappe-dialog, .msgprint-dialog"
      )
      .forEach(
        raiseNode
      );
  }


  function glpSafeMessage(
    title,
    message,
    isError
  ) {
    /*
      Always show dashboard messages ABOVE the Therapy Session /
      Appointment modal.

      The custom GLP modal uses z-index 99999. Frappe msgprint can have
      a lower Bootstrap z-index, which makes validation messages appear
      behind the open dashboard modal. Use a dedicated top-layer dialog.
    */
    var old =
      document.getElementById(
        "glp-top-message-modal"
      );

    if (old) {
      old.remove();
    }

    var overlay =
      document.createElement(
        "div"
      );

    overlay.id =
      "glp-top-message-modal";

    overlay.style.cssText = [
      "position:fixed",
      "inset:0",
      "z-index:2147483600",
      "display:flex",
      "align-items:center",
      "justify-content:center",
