      "background:rgba(0,0,0,.28)"
    ].join(";");

    var dialog =
      document.createElement(
        "div"
      );

    dialog.style.cssText = [
      "position:relative",
      "width:min(620px,94vw)",
      "max-height:80vh",
      "overflow:auto",
      "background:#fffdf8",
      "border:1px solid #d8d4c7",
      "border-radius:16px",
      "box-shadow:0 28px 90px rgba(0,0,0,.34)",
      "font-family:Arial,sans-serif"
    ].join(";");

    var head =
      document.createElement(
        "div"
      );

    head.style.cssText = [
      "display:flex",
      "align-items:center",
      "justify-content:space-between",
      "gap:16px",
      "padding:16px 18px",
      "border-bottom:1px solid #e1ddd2",
      "background:#faf7ef"
    ].join(";");

    var heading =
      document.createElement(
        "h3"
      );

    heading.textContent =
      title ||
      "GLP Programme";

    heading.style.cssText = [
      "margin:0",
      "font:700 21px Georgia,serif",
      "color:" +
        (
          isError
            ? "#7d211a"
            : "#073f31"
        )
    ].join(";");

    var close =
      document.createElement(
        "button"
      );

    close.type =
      "button";

    close.setAttribute(
      "aria-label",
      "Close"
    );

    close.textContent =
      "×";

    close.style.cssText = [
      "border:0",
      "background:transparent",
      "font-size:30px",
      "line-height:1",
      "cursor:pointer",
      "color:#6b756f",
      "padding:0 2px"
    ].join(";");

    var body =
      document.createElement(
        "div"
      );

    body.style.cssText = [
      "padding:20px 18px 22px",
      "font-size:16px",
      "line-height:1.55",
      "color:#4a4f4c",
      "white-space:pre-wrap",
      "overflow-wrap:anywhere"
    ].join(";");

    /*
      Server errors sometimes contain <strong> / <br>. Convert those to
      readable plain text instead of injecting server HTML.
    */
    var temp =
      document.createElement(
        "div"
      );

    temp.innerHTML =
      String(
        message || ""
      )
        .replace(
          /<br\s*\/?>/gi,
          "\n"
        );

    body.textContent =
      temp.textContent ||
      temp.innerText ||
      String(
        message || ""
      );

    function closeTopMessage() {
      if (
        overlay &&
        overlay.parentNode
      ) {
        overlay.remove();
      }
    }

    close.addEventListener(
      "click",
      closeTopMessage
    );

    overlay.addEventListener(
      "click",
      function (event) {
        if (
          event.target ===
          overlay
        ) {
          closeTopMessage();
        }
      }
    );

    document.addEventListener(
      "keydown",
      function escHandler(event) {
        if (
          event.key === "Escape" &&
          document.getElementById(
            "glp-top-message-modal"
          )
        ) {
          closeTopMessage();

          document.removeEventListener(
            "keydown",
            escHandler
          );
        }
      }
    );

    head.appendChild(
      heading
    );

    head.appendChild(
      close
    );

    dialog.appendChild(
      head
    );

    dialog.appendChild(
      body
    );

    overlay.appendChild(
      dialog
    );

    document.body.appendChild(
      overlay
    );
  }


  function glpRequestErrorMessage(error) {
    if (!error) {
      return "ERPNext rejected the request.";
    }

    try {
      var raw =
        error._server_messages ||
        (
          error.responseJSON &&
          error.responseJSON._server_messages
        );

      if (raw) {
        var parsed =
          typeof raw === "string"
            ? JSON.parse(raw)
            : raw;

        if (Array.isArray(parsed)) {
          var messages =
            parsed.map(function (m) {
              try {
                var item =
                  typeof m === "string"
                    ? JSON.parse(m)
                    : m;

                return (
                  item.message ||
                  item.title ||
                  ""
                );
              } catch (e) {
                return String(m || "");
              }
            }).filter(Boolean);

          if (messages.length) {
            return messages.join("<br>");
          }
        }
      }
    } catch (e) {}

    return (
      error.message ||
      (
        error.responseJSON &&
        (
          error.responseJSON.message ||
          error.responseJSON.exception
        )
      ) ||
      "ERPNext rejected the request."
    );
  }


