  function glpNextAppointmentDateOptions(
    selected,
    daysAhead
  ) {
    selected =
      String(
        selected || ""
      ).trim();

    daysAhead =
      Number(
        daysAhead || 60
      );

    if (
      !Number.isFinite(
        daysAhead
      ) ||
      daysAhead < 1
    ) {
      daysAhead = 60;
    }

    var out =
      '<option value="">Select date...</option>';

    var values = [];

    /*
      Use tomorrow as the first normal option.
      A next appointment must be after the current session.
    */
    var base =
      new Date();

    base.setHours(
      12,
      0,
      0,
      0
    );

    for (
      var offset = 1;
      offset <= daysAhead;
      offset++
    ) {
      var date =
        new Date(
          base.getTime()
        );

      date.setDate(
        base.getDate() +
        offset
      );

      var yyyy =
        date.getFullYear();

      var mm =
        String(
          date.getMonth() + 1
        ).padStart(2,"0");

      var dd =
        String(
          date.getDate()
        ).padStart(2,"0");

      var value =
        yyyy +
        "-" +
        mm +
        "-" +
        dd;

      values.push(
        value
      );

      var label =
        dd +
        "/" +
        mm +
        "/" +
        yyyy;

      out +=
        '<option value="' +
        esc(value) +
        '"' +
        (
          value === selected
            ? ' selected'
            : ''
        ) +
        '>' +
        esc(label) +
        '</option>';
    }

    /*
      If an already-booked appointment is outside the normal
      60-day list, still show it as a valid selected option.
    */
    if (
      selected &&
      values.indexOf(
        selected
      ) < 0
    ) {
      var parts =
        selected.split("-");

      var selectedLabel =
        (
          parts.length === 3
            ? (
                parts[2] +
                "/" +
                parts[1] +
                "/" +
                parts[0]
              )
            : selected
        );

      out =
        '<option value="">Select date...</option>' +
        '<option value="' +
        esc(selected) +
        '" selected>' +
        esc(selectedLabel) +
        '</option>' +
        out.replace(
          '<option value="">Select date...</option>',
          ''
        );
    }

    return out;
  }


  function glpHalfHourTimeOptions(
    selected
  ) {
    var out =
      '<option value="">Select time...</option>';

    selected =
      String(
        selected || ""
      ).slice(0,5);

    /*
      Appointment slots:
      07:00 AM, 07:30 AM ... 06:30 PM, 07:00 PM.
    */
    var startMinutes =
      7 * 60;

    var endMinutes =
      19 * 60;

    for (
      var minutes = startMinutes;
      minutes <= endMinutes;
      minutes += 30
    ) {
      var hour24 =
        Math.floor(
          minutes / 60
        );

      var minute =
        minutes % 60;

      var value =
        String(
          hour24
        ).padStart(2,"0") +
        ":" +
        String(
          minute
        ).padStart(2,"0");

      var hour12 =
        hour24 % 12;

      if (!hour12) {
        hour12 = 12;
      }

      var label =
        hour12 +
        ":" +
        String(
          minute
        ).padStart(2,"0") +
        (
          hour24 < 12
            ? " AM"
            : " PM"
        );

      out +=
        '<option value="' +
        esc(value) +
        '"' +
        (
          value === selected
            ? ' selected'
            : ''
        ) +
        '>' +
        esc(label) +
        '</option>';
    }

    return out;
  }


