  function glpPopupMetaBranchField(meta) {
    var map =
      glpPopupFieldMap(meta);

    var direct = [
      "branch",
      "branch_name",
      "custom_branch",
      "custom_branch_name"
    ];

    for (
      var i = 0;
      i < direct.length;
      i++
    ) {
      if (map[direct[i]]) {
        return direct[i];
      }
    }

    var fields =
      (
        meta &&
        Array.isArray(meta.fields)
          ? meta.fields
          : []
      );

    for (
      var j = 0;
      j < fields.length;
      j++
    ) {
      var f = fields[j];

      if (
        f &&
        f.fieldname &&
        f.fieldtype === "Link" &&
        f.options === "Branch"
      ) {
        return f.fieldname;
      }
    }

    return "";
  }

  function glpMasterNameContainsBranch(
    value,
    branch
  ) {
    if (
      !value ||
      !branch
    ) {
      return false;
    }

    var clean = function (v) {
      return norm(v)
        .replace(
          /[^a-z0-9]+/g,
          ""
        );
    };

    var a = clean(value);
    var b = clean(branch);

    return (
      !!a &&
      !!b &&
      a.indexOf(b) >= 0
    );
  }

  function glpMasterRowMatchesBranch(
    row,
    branch,
    branchField
  ) {
    if (!branch) {
      return true;
    }

    if (!row) {
      return false;
    }

    if (
      Number(
        row.custom_available_all_branches ||
        row.available_all_branches ||
        0
      ) === 1
    ) {
      return true;
    }

    var listText =
      String(
        row.custom_branch_list_text ||
        row.branch_list_text ||
        ""
      );

    if (
      listText &&
      norm(listText).indexOf(
        norm(branch)
      ) >= 0
    ) {
      return true;
    }

    if (
      branchField &&
      row[branchField]
    ) {
      return (
        norm(
          row[branchField]
        ) ===
        norm(branch)
      );
    }

    /*
      Several Service Room records in this site include the branch
      in the record name, for example "Hair Room NO-1-Chandanagar".
      Use that only as a fallback when no explicit Branch link exists.
    */
    return glpMasterNameContainsBranch(
      row.name,
      branch
    );
  }

  async function glpLoadPopupMasterRows(
    doctype,
    baseFields,
    branch,
    orderBy
  ) {
    var meta =
      await glpPopupMeta(
        doctype
      );

    var map =
      glpPopupFieldMap(meta);

    var branchField =
      glpPopupMetaBranchField(
        meta
      );

    var fields =
      (baseFields || [])
        .filter(function (f) {
          return (
            f === "name" ||
            !!map[f]
          );
        });

    [
      branchField,
      "custom_available_all_branches",
      "available_all_branches",
      "custom_branch_list_text",
      "branch_list_text"
    ].forEach(function (f) {
      if (
        f &&
        map[f] &&
        fields.indexOf(f) < 0
      ) {
        fields.push(f);
      }
    });

    if (fields.indexOf("name") < 0) {
      fields.unshift("name");
    }

    var rows =
      await getListPage(
        doctype,
        fields,
        [],
        orderBy ||
        "name asc",
        0,
        1000
      ).catch(
        function () {
          return [];
        }
      );

    if (!branch) {
      return rows || [];
    }

    return (
      rows || []
    ).filter(function (r) {
      return glpMasterRowMatchesBranch(
        r,
        branch,
        branchField
      );
    });
  }

  function glpPopupFieldSpecByCandidatesOrLabel(
    meta,
    candidates,
    labels,
    excluded
  ) {
    var excludedSet =
      new Set(
        (excluded || [])
          .filter(Boolean)
      );

    var map =
      glpPopupFieldMap(
        meta
      );

    for (
      var i = 0;
      i < (candidates || []).length;
      i++
    ) {
      var candidate =
        candidates[i];

      if (
        map[candidate] &&
        !excludedSet.has(
          candidate
        )
      ) {
        return map[candidate];
      }
    }

    var wanted =
      (labels || [])
        .map(
          function (label) {
            return norm(
              label
            );
          }
        )
        .filter(Boolean);

    var fields =
      (
        meta &&
        Array.isArray(
          meta.fields
        )
      )
        ? meta.fields
        : [];

    for (
      var j = 0;
      j < fields.length;
      j++
    ) {
      var field =
        fields[j];

      if (
        !field ||
        !field.fieldname ||
        excludedSet.has(
          field.fieldname
        )
      ) {
        continue;
      }

      if (
        wanted.indexOf(
          norm(
            field.label ||
            ""
          )
        ) >= 0
      ) {
        return field;
      }
    }

    return null;
  }


