  async function glpLoadServiceRoomMasterRows(
    branch
  ) {
    var meta =
      await glpPopupMeta(
        "Service Room"
      );

    var fieldsMeta =
      (
        meta &&
        Array.isArray(
          meta.fields
        )
      )
        ? meta.fields
        : [];

    var map =
      glpPopupFieldMap(
        meta
      );

    var branchField =
      glpPopupMetaBranchField(
        meta
      );

    var fields = [
      "name"
    ];

    var branchLikeFields = [];
    var serviceUnitLinkFields = [];

    fieldsMeta.forEach(
      function (field) {
        if (
          !field ||
          !field.fieldname
        ) {
          return;
        }

        var key =
          norm(
            (
              field.fieldname ||
              ""
            ) +
            " " +
            (
              field.label ||
              ""
            )
          );

        if (
          key.indexOf("branch") >= 0 ||
          key.indexOf("location") >= 0 ||
          key.indexOf("centre") >= 0 ||
          key.indexOf("center") >= 0
        ) {
          branchLikeFields.push(
            field.fieldname
          );
        }

        if (
          field.fieldtype === "Link" &&
          (
            field.options === "Healthcare Service Unit" ||
            field.options === "Service Unit"
          )
        ) {
          serviceUnitLinkFields.push(
            field.fieldname
          );
        }
      }
    );

    [
      branchField,
      "disabled",
      "status",
      "custom_available_all_branches",
      "available_all_branches",
      "custom_branch_list_text",
      "branch_list_text"
    ]
      .concat(
        branchLikeFields
      )
      .concat(
        serviceUnitLinkFields
      )
      .forEach(
        function (fieldname) {
          if (
            fieldname &&
            map[fieldname] &&
            fields.indexOf(fieldname) < 0
          ) {
            fields.push(
              fieldname
            );
          }
        }
      );

    var rows =
      await getListPage(
        "Service Room",
        fields,
        [],
        "name asc",
        0,
        1000
      ).catch(
        function (error) {
          void 0;

          return [];
        }
      );

    rows =
      (rows || [])
        .filter(
          function (row) {
            if (
              Object.prototype.hasOwnProperty.call(
                row,
                "disabled"
              ) &&
              Number(row.disabled || 0) === 1
            ) {
              return false;
            }

            if (
              row.status &&
              [
                "disabled",
                "inactive"
              ].indexOf(
                norm(row.status)
              ) >= 0
            ) {
              return false;
            }

            return true;
          }
        );

    if (!branch) {
      return rows;
    }

    var allowedUnitNames =
      new Set();

    if (serviceUnitLinkFields.length) {
      try {
        var units =
          await glpLoadHealthcareServiceUnitsForBranch(
            branch
          );

        (units || [])
          .forEach(
            function (unit) {
              if (
                unit &&
                unit.name
              ) {
                allowedUnitNames.add(
                  unit.name
                );
              }
            }
          );
      } catch (e) {}
    }

    var matched =
      rows.filter(
        function (row) {
          if (
            glpMasterRowMatchesBranch(
              row,
              branch,
              branchField
            )
          ) {
            return true;
          }

          for (
            var i = 0;
            i < branchLikeFields.length;
            i++
          ) {
            if (
              glpLooseBranchValueMatch(
                row[
                  branchLikeFields[i]
                ],
                branch
              )
            ) {
              return true;
            }
          }

          for (
            var j = 0;
            j < serviceUnitLinkFields.length;
            j++
          ) {
            if (
              row[
                serviceUnitLinkFields[j]
              ] &&
              allowedUnitNames.has(
                row[
                  serviceUnitLinkFields[j]
                ]
              )
            ) {
              return true;
            }
          }

          return glpMasterNameContainsBranch(
            row.name,
            branch
          );
        }
      );

    if (!matched.length) {
      var allBranches =
        (
          STATE.allBranches ||
          STATE.branches ||
          []
        )
          .filter(
            function (branchName) {
              return (
                branchName &&
                !isExcludedBranch(
                  branchName
                )
              );
            }
          );

      var anyNameTagged =
        rows.some(
          function (row) {
            return allBranches.some(
              function (branchName) {
                return glpMasterNameContainsBranch(
                  row.name,
                  branchName
                );
              }
            );
          }
        );

      var hasBranchSignals =
        !!branchField ||
        branchLikeFields.length > 0 ||
        serviceUnitLinkFields.length > 0 ||
        anyNameTagged;

      if (!hasBranchSignals) {
        void 0;

        matched =
          rows.slice();
      }
    }

    void 0;

    return matched;
  }


  async function glpLoadAppointmentServiceRooms(
    branch
  ) {
    var spec =
      await glpPatientAppointmentServiceRoomSpec();

    var targetDoctype =
      spec.options ||
      "Service Room";

    var rows = [];

    if (
      targetDoctype === "Healthcare Service Unit"
    ) {
      rows =
        await glpLoadHealthcareServiceUnitsForBranch(
          branch
        );

    } else if (
      targetDoctype === "Service Room"
    ) {
      rows =
        await glpLoadServiceRoomMasterRows(
          branch
        );

    } else {
      rows =
        await glpLoadPopupMasterRows(
          targetDoctype,
          [
            "name"
          ],
          branch,
          "name asc"
        );
    }

    if (
      !rows.length &&
      !spec.options
    ) {
      rows =
        await glpLoadServiceRoomMasterRows(
          branch
        );
    }

    void 0;

    return {
      rows:
        rows ||
        [],
      spec:
        spec,
      doctype:
        targetDoctype
    };
  }


  async function glpLoadPractitionersForBranch(
