  async function glpLoadHealthcareServiceUnitsForBranch(
    branch
  ) {
    var meta =
      await glpPopupMeta(
        "Healthcare Service Unit"
      );

    var map =
      glpPopupFieldMap(meta);

    var branchField =
      glpPopupMetaBranchField(
        meta
      );

    var fields = [
      "name"
    ];

    /*
      LIFE installations can store branch/location information in custom
      fields rather than a standard Branch link. Load likely location fields
      when they exist.
    */
    (
      meta &&
      Array.isArray(meta.fields)
        ? meta.fields
        : []
    ).forEach(function (f) {
      if (
        !f ||
        !f.fieldname
      ) {
        return;
      }

      var key =
        norm(
          (
            f.fieldname ||
            ""
          ) +
          " " +
          (
            f.label ||
            ""
          )
        );

      if (
        (
          key.indexOf("branch") >= 0 ||
          key.indexOf("location") >= 0 ||
          key.indexOf("parent") >= 0
        ) &&
        fields.indexOf(
          f.fieldname
        ) < 0
      ) {
        fields.push(
          f.fieldname
        );
      }
    });

    [
      branchField,
      "parent_healthcare_service_unit",
      "is_group",
      "disabled",
      "custom_available_all_branches",
      "available_all_branches",
      "custom_branch_list_text",
      "branch_list_text"
    ].forEach(function (f) {
      if (
        f &&
        map[f] &&
        fields.indexOf(f) < 0
      ) {
        fields.push(f);
      }
    });

    var rows =
      await getListPage(
        "Healthcare Service Unit",
        fields,
        [],
        "name asc",
        0,
        1000
      ).catch(function () {
        return [];
      });

    rows =
      (rows || [])
        .filter(function (r) {
          return (
            !Object.prototype.hasOwnProperty.call(
              r,
              "disabled"
            ) ||
            Number(
              r.disabled || 0
            ) !== 1
          );
        });

    if (!branch) {
      return rows;
    }

    var rowMap = {};

    rows.forEach(function (r) {
      if (
        r &&
        r.name
      ) {
        rowMap[r.name] = r;
      }
    });

    function rowExplicitlyMatches(
      row
    ) {
      if (!row) {
        return false;
      }

      if (
        glpMasterRowMatchesBranch(
          row,
          branch,
          branchField
        )
      ) {
        return true;
      }

      /*
        Also inspect loaded custom branch/location fields.
      */
      for (
        var i = 0;
        i < fields.length;
        i++
      ) {
        var f = fields[i];

        if (
          !f ||
          f === "name" ||
          f === "parent_healthcare_service_unit"
        ) {
          continue;
        }

        if (
          glpLooseBranchValueMatch(
            row[f],
            branch
          )
        ) {
          return true;
        }
      }

      return false;
    }

    var matched = [];
    var seen = new Set();

    function add(row) {
      if (
        row &&
        row.name &&
        !seen.has(row.name)
      ) {
        seen.add(row.name);
        matched.push(row);
      }
    }

    /*
      1. Direct branch/name/custom-field matches.
    */
    rows.forEach(function (r) {
      if (
        rowExplicitlyMatches(r)
      ) {
        add(r);
      }
    });

    /*
      2. Child units can inherit their branch from a parent Healthcare
         Service Unit. Walk the parent chain.
    */
    rows.forEach(function (r) {
      if (
        seen.has(r.name)
      ) {
        return;
      }

      var parent =
        r.parent_healthcare_service_unit ||
        "";

      var guard = 0;

      while (
        parent &&
        rowMap[parent] &&
        guard < 12
      ) {
        if (
          rowExplicitlyMatches(
            rowMap[parent]
          )
        ) {
          add(r);
          break;
        }

        parent =
          rowMap[parent]
            .parent_healthcare_service_unit ||
          "";

        guard += 1;
      }
    });

    /*
      3. Some LIFE sites have a branch-specific Service Room master while
         Healthcare Service Unit uses a shorter generic name. Match those
         names only against Service Rooms already proven to belong to branch.
         Example:
           "Slimming Room No. 1"
           "Slimming Room No. 1-Madhapur"
    */
    if (!matched.length) {
      var rooms =
        await glpLoadPopupMasterRows(
          "Service Room",
          ["name"],
          branch,
          "name asc"
        );

      var roomNames =
        (rooms || [])
          .map(function (r) {
            return r.name || "";
          })
          .filter(Boolean);

      rows.forEach(function (unit) {
        var unitName =
          unit.name || "";

        var related =
          roomNames.some(function (roomName) {
            var u =
              norm(unitName)
                .replace(
                  /[^a-z0-9]+/g,
                  ""
                );

            var r =
              norm(roomName)
                .replace(
                  /[^a-z0-9]+/g,
                  ""
                );

            return (
              !!u &&
              !!r &&
              (
                u === r ||
                u.indexOf(r) >= 0 ||
                r.indexOf(u) >= 0
              )
            );
          });

        if (related) {
          add(unit);
        }
      });
    }

    void 0;

    return matched;
  }

