  function bindNativeSearchSelect(
    modal,
    searchId,
    selectId,
    options
  ) {
    var searchEl =
      modal.querySelector(
        "#" + searchId
      );

    var selectEl =
      modal.querySelector(
        "#" + selectId
      );

    if (
      !searchEl ||
      !selectEl
    ) {
      return null;
    }

    options =
      options || {};

    var combo =
      searchEl.closest(
        ".glp-native-combo"
      );

    var menu =
      combo &&
      combo.querySelector(
        ".glp-native-combo-menu"
      );

    var arrow =
      combo &&
      combo.querySelector(
        ".glp-native-combo-arrow"
      );

    if (
      !combo ||
      !menu
    ) {
      return null;
    }

    function optionText(
      option
    ) {
      return String(
        option.textContent ||
        option.innerText ||
        option.value ||
        ""
      ).trim();
    }

    function realOptions() {
      return Array.from(
        selectEl.options ||
        []
      ).filter(
        function (option) {
          return !!option.value;
        }
      );
    }

    function setOpen(
      open
    ) {
      combo.classList.toggle(
        "open",
        !!open
      );

      searchEl.setAttribute(
        "aria-expanded",
        open
          ? "true"
          : "false"
      );
    }

    function syncInputFromSelect() {
      var selected =
        selectEl.selectedOptions &&
        selectEl.selectedOptions[0];

      if (
        selected &&
        selected.value
      ) {
        searchEl.value =
          optionText(
            selected
          );
      }
    }

    function selectOption(
      option
    ) {
      if (
        !option ||
        !option.value
      ) {
        return;
      }

      selectEl.value =
        option.value;

      searchEl.value =
        optionText(
          option
        );

      setOpen(
        false
      );

      selectEl.dispatchEvent(
        new Event(
          "change",
          {
            bubbles:true
          }
        )
      );
    }

    function filteredOptions(
      query
    ) {
      query =
        norm(
          query ||
          ""
        );

      return realOptions()
        .filter(
          function (option) {
            if (!query) {
              return true;
            }

            var haystack =
              norm(
                optionText(option) +
                " " +
                String(
                  option.value ||
                  ""
                )
              );

            return (
              haystack.indexOf(
                query
              ) >= 0
            );
          }
        );
    }

    function renderMenu(
      query
    ) {
      var matches =
        filteredOptions(
          query
        );

      menu.innerHTML =
        "";

      if (!matches.length) {
        var empty =
          document.createElement(
            "div"
          );

        empty.className =
          "glp-native-combo-empty";

        empty.textContent =
          "No matching options";

        menu.appendChild(
          empty
        );

        setOpen(
          true
        );

        return matches;
      }

      matches.forEach(
        function (option) {
          var item =
            document.createElement(
              "button"
            );

          item.type =
            "button";

          item.className =
            "glp-native-combo-option";

          item.setAttribute(
            "role",
            "option"
          );

          item.dataset.value =
            option.value;

          item.textContent =
            optionText(
              option
            );

          if (
            selectEl.value ===
            option.value
          ) {
            item.classList.add(
              "selected"
            );
          }

          item.addEventListener(
            "mousedown",
            function (event) {
              /*
                mousedown prevents the input blur event from closing the
                dropdown before the option click can run.
              */
              event.preventDefault();
            }
          );

          item.addEventListener(
            "click",
            function () {
              selectOption(
                option
              );
            }
          );

          menu.appendChild(
            item
          );
        }
      );

      setOpen(
        true
      );

      return matches;
    }

    searchEl.addEventListener(
      "focus",
      function () {
        renderMenu(
          searchEl.value
        );
      }
    );

    searchEl.addEventListener(
      "click",
      function () {
        renderMenu(
          searchEl.value
        );
      }
    );

    searchEl.addEventListener(
      "input",
      function () {
        /*
          Once user edits the displayed label, clear the hidden selected
          value until a valid option is chosen again.
        */
        selectEl.value =
          "";

        renderMenu(
          searchEl.value
        );
      }
    );

    searchEl.addEventListener(
      "keydown",
      function (event) {
        if (
          event.key ===
          "Escape"
        ) {
          setOpen(
            false
          );

          return;
        }

        if (
          event.key !==
          "Enter"
        ) {
          return;
        }

        event.preventDefault();

        var matches =
          filteredOptions(
            searchEl.value
          );

        if (matches.length) {
          selectOption(
            matches[0]
          );
        }
      }
    );

    searchEl.addEventListener(
      "blur",
      function () {
        setTimeout(
          function () {
            setOpen(
              false
            );

            /*
              If user typed arbitrary text without selecting a valid row,
              restore the last valid selected label or leave blank.
            */
            if (
              !selectEl.value
            ) {
              searchEl.value =
                "";
            } else {
              syncInputFromSelect();
            }
          },
          120
        );
      }
    );

    if (arrow) {
      arrow.addEventListener(
        "mousedown",
        function (event) {
          event.preventDefault();
        }
      );

      arrow.addEventListener(
        "click",
        function () {
          if (
            combo.classList.contains(
              "open"
            )
          ) {
            setOpen(
              false
            );
          } else {
            searchEl.focus();

            renderMenu(
              ""
            );
          }
        }
      );
    }

    selectEl.addEventListener(
      "change",
      function () {
        syncInputFromSelect();
      }
    );

    /*
      Close this combo when user clicks elsewhere inside the modal.
    */
    modal.addEventListener(
      "mousedown",
      function (event) {
        if (
          !combo.contains(
            event.target
          )
        ) {
          setOpen(
            false
          );
        }
      }
    );

    syncInputFromSelect();

    return {
      search:
        searchEl,

      select:
        selectEl,

      refresh:
        function () {
          /*
            Hidden select options may have been replaced after branch
            changes. Rebuild from the latest option list.
          */
          renderMenu(
            searchEl.value
          );

          setOpen(
            false
          );

          syncInputFromSelect();
        },

      clear:
        function () {
          searchEl.value =
            "";

          selectEl.value =
            "";

          menu.innerHTML =
            "";

          setOpen(
            false
          );
        },

      sync:
        syncInputFromSelect
    };
  }


