            notes:
              modal.querySelector(
                "#glp-na-notes"
              ).value.trim()
          };

          var required = [
            ["therapy_plan","Therapy Plan"],
            ["patient","Client"],
            ["therapy_type","GLP Therapy Type"],
            ["branch","Branch"],
            ["service_room","Service Room"],
            ["practitioner","Practitioner"],
            ["appointment_date","Appointment Date"],
            ["appointment_time","Appointment Time"]
          ];

          var missing =
            required
              .filter(function (r) {
                return !values[r[0]];
              })
              .map(function (r) {
                return r[1];
              });

          if (missing.length) {
            throw new Error(
              "Complete: " +
              missing.join(", ")
            );
          }

          var plan =
            nativePlanInfo(
              values.therapy_plan
            );

          var requiredBranch =
            glpEffectiveAppointmentBranch(
              plan
            );

          if (
            requiredBranch &&
            norm(values.branch) !==
              norm(requiredBranch)
          ) {
            throw new Error(
              "This client belongs to " +
              requiredBranch +
              ". Appointment branch cannot be changed."
            );
          }

          if (
            !glpBranchAllowedForCurrentUser(
              values.branch
            )
          ) {
            throw new Error(
              "The appointment branch is outside the logged-in user's branch access."
            );
          }

          /*
            Give immediate click feedback. Previously the button appeared to do
            nothing while branch masters were fetched again.
          */
          btn.disabled = true;
          btn.textContent =
            "Booking...";

          void 0;

          /*
            Rooms and practitioners in these selects were already loaded using
            the branch-scoped master query. Re-fetching them here is unnecessary
            and could make the Book button appear frozen.
          */
          var allowedRooms =
            new Set(
              Array.from(
                roomEl.options || []
              )
                .map(function (o) {
                  return o.value;
                })
                .filter(Boolean)
            );

          var allowedPractitioners =
            new Set(
              Array.from(
                practitionerEl.options || []
              )
                .map(function (o) {
                  return o.value;
                })
                .filter(Boolean)
            );

          if (
            !allowedRooms.has(
              values.service_room
            )
          ) {
            throw new Error(
              "Select a Service Room belonging to " +
              values.branch +
              "."
            );
          }

          if (
            !allowedPractitioners.has(
              values.practitioner
            )
          ) {
            throw new Error(
              "Select a Practitioner belonging to " +
              values.branch +
              "."
            );
          }

          btn.textContent =
            "Saving...";

          var created =
            await saveNativeAppointment(
              values
            );

          void 0;

          /*
            The successful insert above is authoritative. The LIFE backend
            can emit a separate legacy "Client Appointment not allowed to
            be renamed" msgprint after creation; V5.15 suppresses only that
            exact non-fatal message and never suppresses insert failures.
          */
          glpCloseNonFatalAppointmentRenameModal();

          closeGLPNativeModal();

          glpSafeMessage(
            "Appointment created",
            (
              created &&
              created.name
            ) ||
            "Patient Appointment created successfully.",
            false
          );

          /*
            Refresh is non-critical. Never report "not created" just because
            the dashboard refresh failed after the ERPNext insert succeeded.
          */
          try {
            await glpPopupRefreshAppointments();
          } catch (refreshError) {
            void 0;
          }

        } catch (e) {
          void 0;

          btn.disabled = false;
          btn.textContent =
            "Book Appointment";

          glpSafeMessage(
            "Appointment not created",
            glpRequestErrorMessage(e),
            true
          );
        }
      }
    );
  }

