  async function glpTherapyPlanPaymentSummary(
    therapyPlan
  ) {
    if (!therapyPlan) {
      return {
        invoice_count: 0,
        billed: 0,
        collected: 0,
        outstanding: 0,
        invoices: [],
        link_fields: []
      };
    }

    await ensureSchemaFast(
      "Sales Invoice"
    );

    /*
      LIFE has used both fields historically:
        - therapy_plan_reference_id
        - custom_therapy_plan

      Check whichever fields actually exist instead of assuming only one.
    */
    var linkFields = [];

    if (
      fieldExists(
        "Sales Invoice",
        "therapy_plan_reference_id"
      )
    ) {
      linkFields.push(
        "therapy_plan_reference_id"
      );
    }

    if (
      fieldExists(
        "Sales Invoice",
        "custom_therapy_plan"
      )
    ) {
      linkFields.push(
        "custom_therapy_plan"
      );
    }

    if (!linkFields.length) {
      throw new Error(
        "Sales Invoice has no Therapy Plan link field configured."
      );
    }

    var fields = [
      "name",
      "posting_date",
      "grand_total",
      "rounded_total",
      "outstanding_amount",
      "paid_amount",
      "docstatus",
      "is_return"
    ];

    linkFields.forEach(
      function (fieldname) {
        if (
          fields.indexOf(
            fieldname
          ) < 0
        ) {
          fields.push(
            fieldname
          );
        }
      }
    );

    var queries =
      await Promise.all(
        linkFields.map(
          async function (fieldname) {
            try {
              return (
                await getListPage(
                  "Sales Invoice",
                  fields,
                  [
                    [
                      fieldname,
                      "=",
                      therapyPlan
                    ],
                    [
                      "docstatus",
                      "=",
                      1
                    ],
                    [
                      "is_return",
                      "=",
                      0
                    ]
                  ],
                  "posting_date desc",
                  0,
                  200
                )
              ) || [];
            } catch (e) {
              void 0;

              return [];
            }
          }
        )
      );

    var byName = {};

    queries.forEach(
      function (rows) {
        (rows || [])
          .forEach(
            function (row) {
              if (
                row &&
                row.name
              ) {
                byName[
                  row.name
                ] = row;
              }
            }
          );
      }
    );

    var rows =
      Object.keys(byName)
        .map(function (name) {
          return byName[name];
        });

    var billed = 0;
    var outstanding = 0;
    var collected = 0;

    rows.forEach(function (inv) {
      var total =
        n(
          inv.grand_total ||
          inv.rounded_total
        );

      var due =
        Math.max(
          0,
          n(inv.outstanding_amount)
        );

      var paid =
        n(inv.paid_amount);

      billed += total;
      outstanding += due;

      /*
        Prefer paid_amount where it is populated.
        Historical LIFE invoices may instead only reflect payment through
        outstanding_amount, so derive collected = total - outstanding.
      */
      if (paid > 0) {
        collected += paid;
      } else {
        collected += Math.max(
          0,
          total - due
        );
      }
    });

    return {
      invoice_count:
        rows.length,
      billed:
        billed,
      collected:
        collected,
      outstanding:
        outstanding,
      invoices:
        rows,
      link_fields:
        linkFields
    };
  }

