  function glpTimeComparable(
    value
  ) {
    var text =
      String(
        value || ""
      ).trim();

    if (!text) {
      return "00:00:00";
    }

    if (
      /^\d{1,2}:\d{2}$/.test(
        text
      )
    ) {
      text += ":00";
    }

    var parts =
      text.split(":");

    var hh =
      String(
        Math.max(
          0,
          Math.min(
            23,
            parseInt(
              parts[0] || "0",
              10
            ) || 0
          )
        )
      ).padStart(2,"0");

    var mm =
      String(
        Math.max(
          0,
          Math.min(
            59,
            parseInt(
              parts[1] || "0",
              10
            ) || 0
          )
        )
      ).padStart(2,"0");

    var ss =
      String(
        Math.max(
          0,
          Math.min(
            59,
            parseInt(
              parts[2] || "0",
              10
            ) || 0
          )
        )
      ).padStart(2,"0");

    return (
      hh + ":" +
      mm + ":" +
      ss
    );
  }


  function glpAppointmentIsAfterSession(
    appointmentDate,
    appointmentTime,
    sessionDate,
    sessionTime
  ) {
    appointmentDate =
      String(
        appointmentDate || ""
      ).trim();

    sessionDate =
      String(
        sessionDate || ""
      ).trim();

    if (
      !appointmentDate ||
      !sessionDate
    ) {
      return false;
    }

    if (
      appointmentDate >
      sessionDate
    ) {
      return true;
    }

    if (
      appointmentDate <
      sessionDate
    ) {
      return false;
    }

    return (
      glpTimeComparable(
        appointmentTime
      ) >
      glpTimeComparable(
        sessionTime
      )
    );
  }


