  async function glpEnsureNextAppointmentForSession(
    values
  ) {
    var nextDate =
      String(
        values.next_appointment_date ||
        ""
      ).trim();

    var nextTime =
      String(
        values.next_appointment_time ||
        ""
      ).trim();

    var nextRoom =
      String(
        values.next_appointment_room ||
        ""
      ).trim();

    var missing = [];

    if (!nextDate) {
      missing.push(
        "Next Appointment Date"
      );
    }

    if (!nextTime) {
      missing.push(
        "Next Appointment Time"
      );
    }

    if (!nextRoom) {
      missing.push(
        "Next Appointment Service Room"
      );
    }

    if (missing.length) {
      throw new Error(
        "A next appointment is mandatory before submitting a Therapy Session. Complete: " +
        missing.join(", ")
      );
    }

    if (
      isGLPDoseTherapyName(
        values.therapy_type
      ) &&
      !glpIsAllowedNextDoseDate(
        values.session_date,
        nextDate
      )
    ) {
      throw new Error(
        "Next GLP appointment must be exactly 6, 7 or 8 days after the current Therapy Session. Allowed dates: " +
        glpAllowedNextDoseDates(
          values.session_date
        )
          .map(function (dateValue) {
            return fmtDate(dateValue);
          })
          .join(", ")
      );
    }

    if (
      !glpAppointmentIsAfterSession(
        nextDate,
        nextTime,
        values.session_date,
        values.in_time
      )
    ) {
      throw new Error(
        "Next Appointment must be after the current Therapy Session date and time."
      );
    }

    var existing =
      await glpFindExistingNextAppointment(
        values.patient,
        values.session_date,
        values.in_time
      );

    if (existing) {
      var existingDate =
        String(
          existing.appointment_date ||
          ""
        ).trim();

      var existingTime =
        String(
          existing.appointment_time ||
          ""
        ).slice(0,5);

      var existingRoom =
        String(
          existing.service_room ||
          ""
        ).trim();

      var selectedTime =
        String(
          nextTime || ""
        ).slice(0,5);

      var sameSelection =
        (
          existingDate ===
            nextDate &&
          existingTime ===
            selectedTime &&
          existingRoom ===
            nextRoom
        );

      if (sameSelection) {
        return {
          appointment:
            existing,
          created:
            false,
          updated:
            false
        };
      }

      var updatedExisting =
        await glpUpdateExistingNextAppointment(
          existing,
          values
        );

      void 0;

      return {
        appointment:
          updatedExisting,
        created:
          false,
        updated:
          true
      };
    }

    var created =
      await saveNativeAppointment(
        {
          therapy_plan:
            values.therapy_plan,
          patient:
            values.patient,
          therapy_type:
            values.therapy_type,
          branch:
            values.branch,
          service_room:
            nextRoom,
          practitioner:
            values.practitioner,
          appointment_date:
            nextDate,
          appointment_time:
            nextTime,
          duration:
            Number(
              values.duration || 30
            ),
          service_unit:
            values.service_unit,
          notes:
            (
              values.remarks
                ? (
                    "Next GLP appointment booked from Therapy Session execution. " +
                    values.remarks
                  )
                : "Next GLP appointment booked from Therapy Session execution."
            )
        }
      );

    void 0;

    return {
      appointment:
        created,
      created:
        true,
      updated:
        false
    };
  }


