  async function glpSessionFindPrescriptionEvidence(
    plan,
    record,
    patient
  ) {
    var targets = [];

    if (
      record &&
      record.name
    ) {
      targets.push(
        {
          doctype:
            "GLP Programme Record",
          name:
            record.name
        }
      );
    }

    if (
      plan &&
      plan.name
    ) {
      targets.push(
        {
          doctype:
            "Therapy Plan",
          name:
            plan.name
        }
      );
    }

    if (patient) {
      targets.push(
        {
          doctype:
            "Patient",
          name:
            patient
        }
      );
    }

    var rows = [];

    for (
      var i = 0;
      i < targets.length;
      i++
    ) {
      var target =
        targets[i];

      try {
        var found =
          await getListPage(
            "File",
            [
              "name",
              "file_name",
              "file_url",
              "attached_to_doctype",
              "attached_to_name"
            ],
            [
              [
                "attached_to_doctype",
                "=",
                target.doctype
              ],
              [
                "attached_to_name",
                "=",
                target.name
              ]
            ],
            "creation desc",
            0,
            100
          );

        rows =
          rows.concat(
            found ||
            []
          );

      } catch (e) {
        /*
          File permission is not required to block session creation.
          If existing prescription evidence cannot be read, the user can
          upload the prescription again in this first-execution popup.
        */
      }
    }

    return (
      rows.find(
        function (file) {
          var text =
            String(
              (
                file.file_name ||
                ""
              ) +
              " " +
              (
                file.file_url ||
                ""
              )
            ).toLowerCase();

          return (
            /prescription/.test(
              text
            ) ||
            /doctor[\s_-]*rx/.test(
              text
            ) ||
            /dr[\s_-]*rx/.test(
              text
            ) ||
            /doctor[\s_-]*prescription/.test(
              text
            )
          );
        }
      ) ||
      null
    );
  }


