    }

    if (
      Number(
        file.size ||
        0
      ) >
      15 *
      1024 *
      1024
    ) {
      throw new Error(
        label +
        " must be 15 MB or smaller."
      );
    }

    var name =
      String(
        file.name ||
        ""
      ).toLowerCase();

    var image =
      (
        name.endsWith(
          ".jpg"
        ) ||
        name.endsWith(
          ".jpeg"
        ) ||
        name.endsWith(
          ".png"
        ) ||
        name.endsWith(
          ".webp"
        )
      );

    var pdf =
      name.endsWith(
        ".pdf"
      );

    if (
      imageOnly &&
      !image
    ) {
      throw new Error(
        label +
        " must be a JPG, JPEG, PNG or WEBP image."
      );
    }

    if (
      !imageOnly &&
      !image &&
      !pdf
    ) {
      throw new Error(
        label +
        " must be a PDF, JPG, JPEG, PNG or WEBP file."
      );
    }
  }


  async function glpUploadTherapySessionAttachment(
    file,
    sessionName,
    category
  ) {
    if (!file) {
      return null;
    }

    var form =
      new FormData();

    form.append(
      "file",
      file,
      file.name
    );

    form.append(
      "is_private",
      "1"
    );

    form.append(
      "folder",
      "Home/Attachments"
    );

    form.append(
      "doctype",
      "Therapy Session"
    );

    form.append(
      "docname",
      sessionName
    );

    var csrf =
      (
        window.frappe &&
        (
          frappe.csrf_token ||
          (
            frappe.boot &&
            frappe.boot.csrf_token
          )
        )
      ) ||
      "";

    var response =
      await fetch(
        "/api/method/upload_file",
        {
          method:
            "POST",
          credentials:
            "same-origin",
          headers:
            csrf
              ? {
                  "X-Frappe-CSRF-Token":
                    csrf,
                  "Accept":
                    "application/json"
                }
              : {
                  "Accept":
                    "application/json"
                },
          body:
            form
        }
      );

    var payload = {};

    try {
      payload =
        await response.json();
    } catch (e) {}

    if (
      !response.ok ||
      !payload ||
      !payload.message ||
      !payload.message.file_url
    ) {
      throw new Error(
        (
          payload &&
          (
            payload.exception ||
            payload._server_messages
          )
        ) ||
        (
          category +
          " upload failed (HTTP " +
          response.status +
          ")."
        )
      );
    }

    return {
      category:
        category,
      file_name:
        payload.message.file_name ||
        file.name,
      file_url:
        payload.message.file_url
    };
  }


