  /* ============================================================
     V5.72 - GLP DOSE APPROVAL 417 FIX
     ------------------------------------------------------------
     Older builds called a missing API method:
       /api/method/glp_dose_approval

     That caused:
       Failed to get method for command glp_dose_approval

     V5.72 keeps the existing Therapy Plan based approval flow but
     does NOT depend on that missing API.  It reads/writes the
     Therapy Plan directly through standard Frappe client methods.
     ============================================================ */

  var GLP_DOSE_PLAN_CACHE = {};

  function glpDoseText(value) {
    var raw = String(value == null ? "" : value).trim();
    if (!raw) return "";
    var m = raw.match(/(2\.5|5|7\.5|10)(?:\s*mg)?/i);
    return m ? (m[1] + " mg") : raw;
  }

  function glpDoseFindField(meta, exactCandidates, keywordGroups) {
    var fields = (meta && meta.fields) || [];
    var byName = {};
    fields.forEach(function (df) {
      byName[String(df.fieldname || "").toLowerCase()] = df;
    });

    for (var i = 0; i < exactCandidates.length; i++) {
      var name = String(exactCandidates[i] || "").toLowerCase();
      if (byName[name]) return byName[name].fieldname;
    }

    for (var g = 0; g < keywordGroups.length; g++) {
      var words = keywordGroups[g];
      for (var j = 0; j < fields.length; j++) {
        var df = fields[j] || {};
        var hay = (
          String(df.fieldname || "") + " " +
          String(df.label || "")
        ).toLowerCase();
        if (words.every(function (w) { return hay.indexOf(w) >= 0; })) {
          return df.fieldname;
        }
      }
    }
    return "";
  }

  async function glpDosePlanMetaAndDoc(planName, force) {
    planName = String(planName || "").trim();
    if (!planName) throw new Error("Therapy Plan is required for dose approval check.");

    if (!force && GLP_DOSE_PLAN_CACHE[planName]) {
      return GLP_DOSE_PLAN_CACHE[planName];
    }

    var meta = await glpPopupMeta("Therapy Plan");
    var response = await frappe.call({
      method: "frappe.client.get",
      args: {
        doctype: "Therapy Plan",
        name: planName
      }
    });
    var doc = response && response.message ? response.message : response;
    if (!doc || !doc.name) {
      throw new Error("Therapy Plan " + planName + " could not be loaded.");
    }

    var fields = {
      reference: glpDoseFindField(
        meta,
        [
          "custom_glp_current_dose",
          "custom_current_dose",
          "custom_glp_reference_dose",
          "custom_reference_dose",
          "custom_glp_starting_dose",
          "custom_glp_starting_dose_mg",
          "custom_starting_dose_mg",
          "starting_dose_mg"
        ],
        [
          ["current", "dose"],
          ["reference", "dose"],
          ["starting", "dose"]
        ]
      ),
      proposed: glpDoseFindField(
        meta,
        [
          "custom_glp_proposed_dose",
          "custom_proposed_dose",
          "custom_glp_requested_dose",
          "custom_requested_dose",
          "custom_glp_next_dose",
          "custom_next_dose"
        ],
        [
          ["proposed", "dose"],
          ["requested", "dose"],
          ["next", "dose"]
        ]
      ),
      status: glpDoseFindField(
        meta,
        [
          "custom_glp_dose_approval_status",
          "custom_dose_approval_status",
          "custom_glp_dose_change_status",
          "custom_dose_change_status"
        ],
        [
          ["dose", "approval", "status"],
          ["dose", "change", "status"]
        ]
      ),
      reason: glpDoseFindField(
        meta,
        [
          "custom_glp_dose_change_reason",
          "custom_dose_change_reason",
          "custom_glp_dose_reason",
          "custom_dose_reason"
        ],
        [
          ["dose", "change", "reason"],
          ["dose", "reason"]
        ]
      ),
      practitioner: glpDoseFindField(
        meta,
        [
          "custom_glp_dose_requested_by",
          "custom_dose_requested_by",
          "custom_glp_dose_practitioner",
          "custom_dose_practitioner"
        ],
        [
          ["dose", "requested", "by"],
          ["dose", "practitioner"]
        ]
      ),
      approvedBy: glpDoseFindField(
        meta,
        [
          "custom_glp_dose_approved_by",
          "custom_dose_approved_by",
          "custom_glp_approved_by",
          "custom_approved_by"
        ],
        [
          ["dose", "approved", "by"],
          ["approval", "by"]
        ]
      )
    };

    var out = { meta: meta, doc: doc, fields: fields };
    GLP_DOSE_PLAN_CACHE[planName] = out;
    return out;
  }

  function glpDoseApprovalPayload(info, requestedDose) {
    var doc = info.doc || {};
    var f = info.fields || {};
    var reference = glpDoseText(
      (f.reference && doc[f.reference]) ||
      doc.custom_glp_starting_dose_mg ||
      doc.custom_starting_dose_mg ||
      doc.starting_dose_mg ||
      ""
    );
    var proposed = glpDoseText((f.proposed && doc[f.proposed]) || "");
    var status = String((f.status && doc[f.status]) || "").trim();
    var reason = String((f.reason && doc[f.reason]) || "").trim();
    var approvedBy = String((f.approvedBy && doc[f.approvedBy]) || "").trim();
    var requested = glpDoseText(requestedDose || proposed || "");

    if (requested && reference && requested === reference) {
      status = "Not Required";
    }

    var approvalRequired = !!(requested && reference && requested !== reference);
    if (!reference && requested) approvalRequired = false;

    return {
      success: true,
      reference_dose: reference,
      billed_dose: reference,
      proposed_dose: proposed,
      requested_dose: requested,
      status: status || (approvalRequired ? "Not Requested" : "Not Required"),
      reason: reason,
      approved_by: approvedBy,
      approval_required: approvalRequired,
      source: reference ? "Therapy Plan" : "",
      sales_invoice: ""
    };
  }

  async function glpDoseApprovalCall(action, args) {
    args = Object.assign({}, args || {});
    action = String(action || "").trim().toLowerCase();

    var planName = String(args.therapy_plan || "").trim();
    if (!planName) {
      throw new Error("Therapy Plan is required for GLP dose approval.");
    }

    var info = await glpDosePlanMetaAndDoc(planName, action === "status");

    if (action === "context" || action === "status") {
      return glpDoseApprovalPayload(info, args.requested_dose || "");
    }

    if (action === "lookup") {
      var lookup = glpDoseApprovalPayload(info, args.requested_dose || "");
      var requested = glpDoseText(args.requested_dose || "");
      var storedProposed = glpDoseText(lookup.proposed_dose || "");

      if (lookup.approval_required && storedProposed && requested && storedProposed !== requested) {
        lookup.status = "Not Requested";
        lookup.reason = "";
        lookup.approved_by = "";
      }
      return lookup;
    }

    if (action === "request") {
      var f = info.fields || {};
      var currentDose = glpDoseText(args.current_dose || "");
      var requestedDose = glpDoseText(args.requested_dose || "");
      var reason = String(args.reason || "").trim();
      var practitioner = String(args.practitioner || "").trim();

      if (!currentDose || !requestedDose) {
        throw new Error("Current Dose and Proposed Next Dose are required.");
      }
      if (currentDose === requestedDose) {
        return {
          success:true,
          reference_dose:currentDose,
          proposed_dose:requestedDose,
          requested_dose:requestedDose,
          status:"Not Required",
          approval_required:false
        };
      }
      if (!reason) throw new Error("Doctor Request Reason is required.");

      if (!f.proposed || !f.status || !f.reason) {
        throw new Error(
          "Therapy Plan dose approval fields were not found. " +
          "Required fields are Proposed/Requested Dose, Dose Approval Status and Dose Change Reason."
        );
      }

      var values = {};
      values[f.proposed] = requestedDose;
      values[f.status] = "Pending";
      values[f.reason] = reason;
      if (f.reference && !info.doc[f.reference]) values[f.reference] = currentDose;
      if (f.practitioner && practitioner) values[f.practitioner] = practitioner;
      if (f.approvedBy) values[f.approvedBy] = "";

      await frappe.call({
        method: "frappe.client.set_value",
        args: {
          doctype: "Therapy Plan",
          name: planName,
          fieldname: values
        }
      });

      delete GLP_DOSE_PLAN_CACHE[planName];
      var fresh = await glpDosePlanMetaAndDoc(planName, true);
      var result = glpDoseApprovalPayload(fresh, requestedDose);
      result.status = String((fresh.fields.status && fresh.doc[fresh.fields.status]) || "Pending").trim() || "Pending";
      return result;
    }

    throw new Error("Unsupported GLP dose approval action: " + action);
  }


