    var proposedEl =
      modal.querySelector(
        "#glp-dose-review-proposed"
      );

    var practitionerEl =
      modal.querySelector(
        "#glp-dose-review-practitioner"
      );

    var reasonEl =
      modal.querySelector(
        "#glp-dose-review-reason"
      );

    var currentNoteEl =
      modal.querySelector(
        "#glp-dose-review-current-note"
      );

