    async function loadContext() {
      setStatus(
        "Reading the client's current/reference GLP dose…",
        ""
      );

      var context =
        await glpDoseApprovalCall(
          "context",
          {
            therapy_plan:
              plan.name
          }
        );

      state.reference_dose =
        context.reference_dose ||
        context.billed_dose ||
        "";

      state.source =
        context.source ||
        "";

      state.status =
        context.status ||
        "";

      state.approved_by =
        context.approved_by ||
        "";

      state.reason =
        context.reason ||
        "";

      state.proposed_dose =
        context.proposed_dose ||
        "";

      if (
        state.reference_dose
      ) {
        currentEl.value =
          state.reference_dose;

        currentEl.disabled =
          true;

        if (currentNoteEl) {
          currentNoteEl.textContent =
            "Current/reference dose: " +
            state.reference_dose +
            (
              state.source
                ? " · source: " +
                  state.source
                : ""
            );
        }
      } else {
        currentEl.disabled =
          false;

        if (currentNoteEl) {
          currentNoteEl.textContent =
            "No previous/current dose was found. Select the client's existing dose.";
        }
      }

      if (
        state.proposed_dose
      ) {
        proposedEl.value =
          state.proposed_dose;
      }

      if (
        state.reason
      ) {
        reasonEl.value =
          state.reason;
      }

      if (
        state.status ===
        "Approved"
      ) {
        setStatus(
          "Approved" +
          (
            state.approved_by
              ? " by " +
                state.approved_by
              : ""
          ) +
          ". Treatment may proceed with the approved proposed dose.",
          "ok"
        );
      } else if (
        state.status ===
        "Pending"
      ) {
        setStatus(
          "Approval is Pending. Do not administer the changed dose yet.",
          ""
        );
      } else if (
        state.status ===
        "Rejected"
      ) {
        setStatus(
          "The latest dose change was Rejected.",
          "bad"
        );
      } else {
        setStatus(
          "Select the proposed next dose. A changed dose requires management approval before treatment.",
          ""
        );
      }
    }

    async function lookupSelection() {
      var currentDose =
        String(
          currentEl.value ||
          state.reference_dose ||
          ""
        ).trim();

      var proposedDose =
        String(
          proposedEl.value ||
          ""
        ).trim();

      state.status = "";
      state.approved_by = "";

      if (
        !currentDose ||
        !proposedDose
      ) {
        setStatus(
          "Select Current Dose and Proposed Next Dose.",
          ""
        );
        return null;
      }

      if (
        currentDose ===
        proposedDose
      ) {
        state.status =
          "Not Required";

        setStatus(
          "No dose change: " +
          currentDose +
          " → " +
          proposedDose +
          ". Management approval is not required.",
          "ok"
        );

        return {
          approval_required:false,
          status:"Not Required"
        };
      }

      var lookup =
        await glpDoseApprovalCall(
          "lookup",
          {
            therapy_plan:
              plan.name,
            current_dose:
              currentDose,
            requested_dose:
              proposedDose
          }
        );

      state.status =
        lookup.status ||
        "Not Requested";

      state.approved_by =
        lookup.approved_by ||
        "";

      state.reason =
        lookup.reason ||
        state.reason ||
        "";

      if (
        state.status ===
        "Approved"
      ) {
        setStatus(
          "Approved" +
          (
            state.approved_by
              ? " by " +
                state.approved_by
              : ""
          ) +
          ". The changed dose may be administered.",
          "ok"
        );
      } else if (
        state.status ===
        "Pending"
      ) {
        setStatus(
          "Approval is Pending. Do not administer the changed dose until management approves it.",
          ""
        );
      } else if (
        state.status ===
        "Rejected"
      ) {
        setStatus(
          "The dose change was Rejected. Review the client before sending a new request.",
          "bad"
        );
      } else {
        setStatus(
          "Dose change detected: " +
          currentDose +
          " → " +
          proposedDose +
          ". Enter the reason and click Send for Approval.",
          ""
        );
      }

      return lookup;
    }

    proposedEl.addEventListener(
      "change",
      function () {
        lookupSelection()
          .catch(function (error) {
            setStatus(
              glpRequestErrorMessage(
                error
              ),
              "bad"
            );
          });
      }
    );

    currentEl.addEventListener(
      "change",
      function () {
        lookupSelection()
          .catch(function (error) {
            setStatus(
              glpRequestErrorMessage(
                error
              ),
              "bad"
            );
          });
      }
    );

    if (checkBtn) {
      checkBtn.addEventListener(
        "click",
        async function () {
          try {
            var status =
              await glpDoseApprovalCall(
                "status",
                {
                  therapy_plan:
                    plan.name
                }
              );

            state.status =
              status.status ||
              "";

            state.approved_by =
              status.approved_by ||
              "";

            state.reason =
              status.reason ||
              "";

            state.proposed_dose =
              status.proposed_dose ||
              "";

            if (
              state.status ===
              "Approved"
            ) {
              setStatus(
                "Approved" +
                (
                  state.approved_by
                    ? " by " +
                      state.approved_by
                    : ""
                ) +
                ". Treatment may proceed with " +
                (
                  state.proposed_dose ||
                  "the approved dose"
                ) +
                ".",
                "ok"
              );
            } else if (
              state.status ===
              "Rejected"
            ) {
              setStatus(
                "Dose change is Rejected. Do not administer the changed dose.",
                "bad"
              );
            } else if (
              state.status ===
              "Pending"
            ) {
              setStatus(
                "Approval is still Pending. Do not administer the changed dose yet.",
                ""
              );
            } else {
              setStatus(
                "There is no pending/approved dose-change request on this Therapy Plan.",
                ""
              );
            }

          } catch (error) {
            glpSafeMessage(
              "Approval check failed",
              glpRequestErrorMessage(
                error
              ),
              true
            );
          }
        }
      );
    }

    submitBtn.addEventListener(
      "click",
      async function () {
        var oldText =
          submitBtn.textContent;

        try {
          var currentDose =
            String(
              currentEl.value ||
              state.reference_dose ||
              ""
            ).trim();

          var proposedDose =
            String(
              proposedEl.value ||
              ""
            ).trim();

          var practitioner =
            String(
              practitionerEl.value ||
              ""
            ).trim();

          var reason =
            String(
              reasonEl.value ||
              ""
            ).trim();

          if (!currentDose) {
            throw new Error(
              "Select the client's Current Dose."
            );
          }

          if (!proposedDose) {
            throw new Error(
              "Select the Proposed Next Dose."
            );
          }

          if (!practitioner) {
            throw new Error(
              "Select the Doctor / Practitioner."
            );
          }

          if (
            currentDose ===
            proposedDose
          ) {
            glpSafeMessage(
              "No approval required",
              "Current Dose and Proposed Next Dose are both " +
                proposedDose +
                ". Continue the normal treatment plan.",
              false
            );

            closeGLPNativeModal();
            return;
          }

          if (!reason) {
            throw new Error(
              "Enter the Doctor Request Reason."
            );
          }

          submitBtn.disabled =
            true;

          submitBtn.textContent =
            "Sending for approval…";

          var result =
            await glpDoseApprovalCall(
              "request",
              {
                therapy_plan:
                  plan.name,
                current_dose:
                  currentDose,
                requested_dose:
                  proposedDose,
                reason:
                  reason,
                practitioner:
                  practitioner
              }
            );

          state.status =
            result.status ||
            "Pending";

          state.proposed_dose =
            proposedDose;

          if (
            state.status ===
            "Approved"
          ) {
            setStatus(
              "This Therapy Plan already has approval for " +
              proposedDose +
              ".",
              "ok"
            );
          } else {
            setStatus(
              "Request stored on the Therapy Plan and sent to management. Do not administer " +
              proposedDose +
              " until status becomes Approved.",
              ""
            );
          }

          glpSafeMessage(
            "Dose change sent for approval",
            "Therapy Plan " +
              plan.name +
              " · " +
              state.status +
              ".",
            false
          );

        } catch (error) {
          glpSafeMessage(
            "Dose request not sent",
            glpRequestErrorMessage(
              error
            ),
            true
          );

        } finally {
          submitBtn.disabled =
            false;

          submitBtn.textContent =
            oldText ||
            "Send for Approval";
        }
      }
    );

    await loadContext();

    return modal;
  }





  // ================================================================
  // V5.80 - GLP EXECUTION: MAIN STORE -> SUB STORE
  // ================================================================
  //
  // LIFE GLP stock rule:
  //   Branch Main Store = unused / available physical GLP stock
  //   Branch Sub Store  = used / executed GLP stock
  //
  // After one submitted GLP Therapy Session:
  //   Main Store -1
  //   Sub Store  +1
  //
  // This is a Material Transfer, NOT a Material Issue. The stock remains
  // traceable in ERPNext and the Sub Store balance becomes the Used Stock
  // count shown in the new GLP dashboard tab.
  //
  // The transfer is idempotent per Therapy Session.

  function glpSessionStockMarkerV580(sessionName) {
    return "GLP Therapy Session Used Stock Transfer: " +
      String(sessionName || "").trim();
  }


  function glpIsMainStoreWarehouseV580(name) {
    var value =
      norm(
        name
      );

    return (
      value.indexOf(
        "main store"
      ) >= 0 &&
      value.indexOf(
        "sub store"
      ) < 0 &&
      value.indexOf(
        "substore"
      ) < 0
    );
  }


  function glpIsSubStoreWarehouseV580(name) {
    var value =
      norm(
        name
      );

    return (
      value.indexOf(
        "sub store"
      ) >= 0 ||
      value.indexOf(
        "substore"
      ) >= 0
    );
  }


  async function glpFindExistingSessionStockTransferV580(
    sessionName
  ) {
    var marker =
      glpSessionStockMarkerV580(
        sessionName
      );

    try {
      var rows =
        await getListPage(
          "Stock Entry",
          [
            "name",
            "docstatus",
            "purpose",
            "stock_entry_type",
            "remarks",
            "from_warehouse",
            "to_warehouse",
            "posting_date",
            "posting_time"
          ],
          [
            [
              "docstatus",
              "=",
              1
            ],
            [
              "remarks",
              "like",
              "%" + marker + "%"
            ]
          ],
          "creation desc",
          0,
          5
        );

      return (
        rows &&
        rows.length
          ? rows[0]
          : null
      );
    } catch (e) {
      void 0;
      return null;
    }
  }


  async function glpSessionTherapyTypeMasterV580(
    therapyType
  ) {
    var key =
      norm(
        therapyType
      );

    var cached =
      (
        STATE.glpTherapyTypes ||
        []
      ).find(
        function (row) {
          return [
            row && row.name,
            row && row.therapy_type
          ].some(
            function (value) {
              return (
                value &&
                norm(value) === key
              );
            }
          );
        }
      );

    if (cached) {
      return cached;
    }

    try {
      var rows =
        await getListPage(
          "Therapy Type",
          [
            "name",
            "therapy_type",
            "item",
            "item_code",
            "item_name",
            "disabled"
          ],
          [
            [
              "name",
              "=",
              therapyType
            ]
          ],
          "modified desc",
          0,
          1
        );

      return (
        rows &&
        rows.length
          ? rows[0]
          : null
      );
    } catch (e) {
      return null;
    }
  }


  async function glpSessionPlanInvoiceStockItemsV580(
    planName
  ) {
    var result = [];

    if (
      !planName ||
      !fieldExists(
        "Sales Invoice",
        "therapy_plan_reference_id"
      )
    ) {
      return result;
    }

    try {
      var invoices =
        await getListPage(
          "Sales Invoice",
          [
            "name",
            "therapy_plan_reference_id",
            "docstatus",
            "posting_date"
          ],
          [
            [
              "therapy_plan_reference_id",
              "=",
              planName
            ],
            [
              "docstatus",
              "in",
              [
                0,
                1
              ]
            ]
          ],
          "posting_date desc, modified desc",
          0,
          20
        );

      var invoiceNames =
        (invoices || [])
          .map(
            function (row) {
              return row.name;
            }
          )
          .filter(Boolean);

      if (!invoiceNames.length) {
        return result;
      }

      var rows =
        await getChildListPage(
          "Sales Invoice",
          "Sales Invoice Item",
          [
            "parent",
            "item_code",
            "item_name",
            "description"
          ],
          [
            [
              "parent",
              "in",
              invoiceNames
            ]
          ],
          "parent asc, idx asc",
          0,
          1000
        );

      result =
        (rows || [])
          .filter(
            function (row) {
              return (
                row &&
                row.item_code &&
                glpInvoiceItemMatches(
                  row
                )
              );
            }
          );
    } catch (e) {
      void 0;
    }

    return result;
  }


  async function glpResolveSessionStockItemsV580(
    values
  ) {
    var candidateCodes = [];
    var labels = {};

    var therapy =
      await glpSessionTherapyTypeMasterV580(
        values.therapy_type
      );

    var directCode =
      therapy &&
      (
        therapy.item_code ||
        therapy.item ||
        ""
      );

    if (directCode) {
      candidateCodes.push(
        directCode
      );

      labels[
        directCode
      ] =
        therapy.item_name ||
        directCode;
    }

    var invoiceItems =
      await glpSessionPlanInvoiceStockItemsV580(
        values.therapy_plan
      );

    invoiceItems.forEach(
      function (row) {
        if (
          row.item_code &&
          candidateCodes.indexOf(
            row.item_code
          ) < 0
        ) {
          candidateCodes.push(
            row.item_code
          );
        }

        if (row.item_code) {
          labels[
            row.item_code
          ] =
            row.item_name ||
            row.item_code;
        }
      }
    );

    if (!candidateCodes.length) {
      return [];
    }

    var masters =
      await glpLoadAppointmentItemMasters(
        candidateCodes
      );

    var stockItems =
      candidateCodes
        .filter(
          function (code) {
            var item =
              masters[
                code
              ];

            return (
              item &&
              Number(
                item.is_stock_item ||
                0
              ) === 1 &&
              Number(
                item.disabled ||
                0
              ) !== 1
            );
          }
        )
        .map(
          function (code) {
            var item =
              masters[
                code
              ];

            return {
              item_code:
                item.item_code ||
                item.name ||
                code,
              item_name:
                item.item_name ||
                labels[
                  code
                ] ||
                code,
              stock_uom:
                item.stock_uom ||
                "Nos"
            };
          }
        );

    var doseTokens =
      glpAppointmentStrengthTokens(
        String(
          values.injection_dose ||
          values.billed_dose ||
          ""
        ) +
        " mg"
      );

    if (
      doseTokens.length &&
      stockItems.length > 1
    ) {
      var matches =
        stockItems.filter(
          function (item) {
            var itemText =
              norm(
                (
                  item.item_code ||
                  ""
                ) +
                " " +
                (
                  item.item_name ||
                  ""
                )
              )
                .replace(
                  /\s+/g,
                  ""
                );

            return doseTokens.some(
              function (token) {
                return (
                  itemText.indexOf(
                    token
                  ) >= 0
                );
              }
            );
          }
        );

      if (matches.length) {
        stockItems =
          matches;
      }
    }

    return stockItems;
  }


  async function glpResolveMainAndSubWarehouseV580(
    branch
  ) {
    branch =
      String(
        branch ||
        ""
      ).trim();

    if (!branch) {
      throw new Error(
        "Therapy Session branch is required for stock transfer."
      );
    }

    var map =
      await glpLoadAppointmentWarehouseMap(
        [
          branch
        ]
      );

    var warehouses =
      (
        map[
          branch
        ] ||
        []
      )
        .filter(
          function (row) {
            return (
              row &&
              row.name
            );
          }
        );

    var main =
      warehouses.find(
        function (row) {
          return glpIsMainStoreWarehouseV580(
            row.name
          );
        }
      );

    var sub =
      warehouses.find(
        function (row) {
          return glpIsSubStoreWarehouseV580(
            row.name
          );
        }
      );

    if (!main) {
      throw new Error(
        branch +
        " Main Store warehouse could not be identified. Stock was not moved."
      );
    }

    if (!sub) {
      throw new Error(
        branch +
        " Sub Store warehouse could not be identified. Stock was not moved."
      );
    }

    if (
      main.name ===
      sub.name
    ) {
      throw new Error(
        "Main Store and Sub Store resolved to the same Warehouse."
      );
    }

    return {
      main:
        main.name,
      sub:
        sub.name
    };
  }


  async function glpResolveSessionMainStockV580(
    values
  ) {
    var branch =
      String(
        values.branch ||
        ""
      ).trim();

    var pair =
      await glpResolveMainAndSubWarehouseV580(
        branch
      );

    var stockItems =
      await glpResolveSessionStockItemsV580(
        values
      );

    if (!stockItems.length) {
      throw new Error(
        "No physical GLP Item could be resolved from the Therapy Type / linked invoice."
      );
    }

    var itemCodes =
      stockItems.map(
        function (row) {
          return row.item_code;
        }
      );

    var bins =
      await getListPage(
        "Bin",
        [
          "name",
          "warehouse",
          "item_code",
          "actual_qty",
          "reserved_qty",
          "projected_qty"
        ],
        [
          [
            "warehouse",
            "=",
            pair.main
          ],
          [
            "item_code",
            "in",
            itemCodes
          ]
        ],
        "item_code asc",
        0,
        500
      );

    var available =
      stockItems
        .map(
          function (item) {
            var bin =
              (bins || [])
                .find(
                  function (row) {
                    return (
                      row.item_code ===
                      item.item_code
                    );
                  }
                );

            return {
              main_warehouse:
                pair.main,
              sub_warehouse:
                pair.sub,
              item_code:
                item.item_code,
              item_name:
                item.item_name,
              stock_uom:
                item.stock_uom ||
                "Nos",
              actual_qty:
                Number(
                  bin &&
                  bin.actual_qty ||
                  0
                )
            };
          }
        )
        .filter(
          function (row) {
            return (
              row.actual_qty >= 1
            );
          }
        );

    if (!available.length) {
      throw new Error(
        "No available GLP stock was found in " +
        pair.main +
        " for this execution."
      );
    }

    if (available.length === 1) {
      return available[0];
    }

    var doseTokens =
      glpAppointmentStrengthTokens(
        String(
          values.injection_dose ||
          values.billed_dose ||
          ""
        ) +
        " mg"
      );

    var exact =
      available.filter(
        function (row) {
          var itemText =
            norm(
              row.item_code +
              " " +
              row.item_name
            )
              .replace(
                /\s+/g,
                ""
              );

          return doseTokens.some(
            function (token) {
              return (
                itemText.indexOf(
                  token
                ) >= 0
              );
            }
          );
        }
      );

    if (exact.length === 1) {
      return exact[0];
    }

    throw new Error(
      "More than one GLP stock Item is available in the branch Main Store. The executed dose could not uniquely identify which Item to move."
    );
  }


  async function glpAttachStockTransferToSessionV580(
    sessionName,
    stockEntryName
  ) {
    if (
      !sessionName ||
      !stockEntryName
    ) {
      return;
    }

    try {
      var meta =
        await glpPopupMeta(
          "Therapy Session"
        );

      var fieldname =
        glpPopupExistingField(
          meta,
          [
            "custom_stock_entry_reference",
            "custom_glp_stock_entry",
            "custom_stock_entry",
            "stock_entry_reference"
          ]
        ) ||
        glpPopupFieldByLabel(
          meta,
          [
            "Stock Entry Reference",
            "GLP Stock Entry",
            "Stock Entry"
          ]
        );

      if (fieldname) {
        await frappeCall(
          "frappe.client.set_value",
          {
            doctype:
              "Therapy Session",
            name:
              sessionName,
            fieldname:
              fieldname,
            value:
              stockEntryName
          },
          15000
        );
      }
    } catch (e) {
      void 0;
    }
  }


  async function glpMoveExecutedStockToSubStoreV580(
    savedSession,
    values
  ) {
    var sessionName =
      savedSession &&
      savedSession.name
        ? savedSession.name
        : "";

    if (!sessionName) {
      throw new Error(
        "Therapy Session ID is missing; stock transfer was not attempted."
      );
    }

    var existing =
      await glpFindExistingSessionStockTransferV580(
        sessionName
      );

    if (existing) {
      await glpAttachStockTransferToSessionV580(
        sessionName,
        existing.name
      );

      return {
        created:
          false,
        existing:
          true,
        stock_entry:
          existing.name,
        from_warehouse:
          existing.from_warehouse ||
          "",
        to_warehouse:
          existing.to_warehouse ||
          ""
      };
    }

    var stock =
      await glpResolveSessionMainStockV580(
        values
      );

    var stockUom =
      stock.stock_uom ||
      "Nos";

    var marker =
      glpSessionStockMarkerV580(
        sessionName
      );

    var stockEntryDoc = {
      doctype:
        "Stock Entry",
      docstatus:
        0,
      naming_series:
        "MAT-STE-.YYYY.-",
      stock_entry_type:
        "Material Transfer",
      purpose:
        "Material Transfer",
      company:
        "Life Slimming And Cosmetic Pvt Ltd",
      from_warehouse:
        stock.main_warehouse,
      to_warehouse:
        stock.sub_warehouse,
      remarks:
        marker +
        "\nClient: " +
        String(
          values.patient ||
          ""
        ) +
        "\nTherapy Plan: " +
        String(
          values.therapy_plan ||
          ""
        ) +
        "\nTherapy Type: " +
        String(
          values.therapy_type ||
          ""
        ) +
        "\nDose: " +
        String(
          values.injection_dose ||
          values.billed_dose ||
          ""
        ) +
        " mg",
      items: [
        {
          item_code:
            stock.item_code,
          qty:
            1,
          uom:
            stockUom,
          stock_uom:
            stockUom,
          conversion_factor:
            1,
          s_warehouse:
            stock.main_warehouse,
          t_warehouse:
            stock.sub_warehouse
        }
      ]
    };

    /*
      Recheck before submit so a retry never moves the same execution twice.
    */
    existing =
      await glpFindExistingSessionStockTransferV580(
        sessionName
      );

    if (existing) {
      await glpAttachStockTransferToSessionV580(
        sessionName,
        existing.name
      );

      return {
        created:
          false,
        existing:
          true,
        stock_entry:
          existing.name,
        from_warehouse:
          existing.from_warehouse ||
          stock.main_warehouse,
        to_warehouse:
          existing.to_warehouse ||
          stock.sub_warehouse
      };
    }

    var submitted =
      await frappeCall(
        "frappe.client.submit",
        {
          doc:
            stockEntryDoc
        },
        45000
      );

    if (
      !submitted ||
      !submitted.name ||
      Number(
        submitted.docstatus ||
        0
      ) !== 1
    ) {
      throw new Error(
        "ERPNext did not return a submitted Material Transfer Stock Entry."
      );
    }

    await glpAttachStockTransferToSessionV580(
      sessionName,
      submitted.name
    );

    /*
      Used Stock view is live from Bin. Clear its cache immediately.
    */
    STATE.usedStockLoadedAt =
      0;

    STATE.usedStockRows =
      [];

    void 0;

    return {
      created:
        true,
      existing:
        false,
      stock_entry:
        submitted.name,
      from_warehouse:
        stock.main_warehouse,
      to_warehouse:
        stock.sub_warehouse,
      item_code:
        stock.item_code,
      item_name:
        stock.item_name,
      qty:
        1,
      uom:
        stockUom
    };
  }


