  async function glpLoadUsedStockV580() {
    await loadTherapyTypesFast();

    var branches =
      (
        STATE.userBranchLocked &&
        STATE.userBranchScope &&
        STATE.userBranchScope.length
          ? STATE.userBranchScope.slice()
          : (
              STATE.glpBranches &&
              STATE.glpBranches.length
                ? STATE.glpBranches.slice()
                : (
                    STATE.allBranches ||
                    STATE.branches ||
                    []
                  ).slice()
            )
      )
        .map(
          function (branch) {
            return typeof branch === "string"
              ? branch
              : (
                  branch.name ||
                  branch.branch ||
                  ""
                );
          }
        )
        .filter(Boolean)
        .filter(
          function (branch) {
            return !isExcludedBranch(
              branch
            );
          }
        );

    branches =
      Array.from(
        new Set(
          branches
        )
      );

    if (
      STATE.branch !==
      "ALL"
    ) {
      branches =
        branches.filter(
          function (branch) {
            return (
              norm(branch) ===
              norm(
                STATE.branch
              )
            );
          }
        );
    }

    if (!branches.length) {
      STATE.usedStockRows = [];
      STATE.usedStockWarehouses = [];
      STATE.usedStockLoadedAt = Date.now();
      return;
    }

    var warehouseMap =
      await glpLoadAppointmentWarehouseMap(
        branches
      );

    var subWarehouses = [];

    branches.forEach(
      function (branch) {
        (
          warehouseMap[
            branch
          ] ||
          []
        ).forEach(
          function (warehouse) {
            if (
              warehouse &&
              warehouse.name &&
              glpIsSubStoreWarehouseV580(
                warehouse.name
              )
            ) {
              subWarehouses.push(
                {
                  branch:
                    branch,
                  warehouse:
                    warehouse.name
                }
              );
            }
          }
        );
      }
    );

    var uniqueWarehouseNames =
      Array.from(
        new Set(
          subWarehouses.map(
            function (row) {
              return row.warehouse;
            }
          )
        )
      );

    STATE.usedStockWarehouses =
      subWarehouses;

    if (!uniqueWarehouseNames.length) {
      STATE.usedStockRows = [];
      STATE.usedStockLoadedAt = Date.now();
      return;
    }

    /*
      Pull live positive balances from Sub Stores. Since LIFE treats Sub Store
      as executed/used GLP stock, Bin.actual_qty is the Used Stock count.
    */
    var binRows =
      await mapChunksLimited(
        chunkArray(
          uniqueWarehouseNames,
          80
        ),
        2,
        async function (warehouseChunk) {
          try {
            return await getListPage(
              "Bin",
              [
                "name",
                "warehouse",
                "item_code",
                "actual_qty",
                "reserved_qty",
                "projected_qty"
              ],
              [
                [
                  "warehouse",
                  "in",
                  warehouseChunk
                ],
                [
                  "actual_qty",
                  ">",
                  0
                ]
              ],
              "warehouse asc, item_code asc",
              0,
              2000
            );
          } catch (e) {
            void 0;
            return [];
          }
        }
      );

    binRows =
      []
        .concat.apply(
          [],
          binRows || []
        );

    var itemCodes =
      Array.from(
        new Set(
          (binRows || [])
            .map(
              function (row) {
                return row.item_code;
              }
            )
            .filter(Boolean)
        )
      );

    var itemMasters =
      await glpLoadAppointmentItemMasters(
        itemCodes
      );

    var glpAliasCodes = {};

    (
      STATE.glpTherapyTypes ||
      []
    ).forEach(
      function (therapy) {
        [
          therapy.item_code,
          therapy.item
        ].forEach(
          function (code) {
            if (code) {
              glpAliasCodes[
                norm(
                  code
                )
              ] =
                true;
            }
          }
        );
      }
    );

    var warehouseBranchMap = {};

    subWarehouses.forEach(
      function (row) {
        warehouseBranchMap[
          row.warehouse
        ] =
          row.branch;
      }
    );

    STATE.usedStockRows =
      (binRows || [])
        .map(
          function (bin) {
            var item =
              itemMasters[
                bin.item_code
              ] ||
              {};

            var itemText =
              [
                bin.item_code,
                item.item_name
              ]
                .filter(Boolean)
                .join(
                  " "
                );

            /*
              Show only GLP stock. Direct Therapy Type item link is preferred;
              text GLP recognition remains a compatibility fallback.
            */
            var isGLP =
              !!glpAliasCodes[
                norm(
                  bin.item_code
                )
              ] ||
              textHasGLP(
                itemText
              );

            if (!isGLP) {
              return null;
            }

            return {
              branch:
                warehouseBranchMap[
                  bin.warehouse
                ] ||
                "",
              warehouse:
                bin.warehouse,
              item_code:
                bin.item_code,
              item_name:
                item.item_name ||
                bin.item_code,
              stock_uom:
                item.stock_uom ||
                "Nos",
              used_qty:
                Number(
                  bin.actual_qty ||
                  0
                ),
              reserved_qty:
                Number(
                  bin.reserved_qty ||
                  0
                ),
              projected_qty:
                Number(
                  bin.projected_qty ||
                  0
                )
            };
          }
        )
        .filter(Boolean)
        .sort(
          function (a,b) {
            var branchCompare =
              String(
                a.branch ||
                ""
              ).localeCompare(
                String(
                  b.branch ||
                  ""
                )
              );

            if (branchCompare) {
              return branchCompare;
            }

            return String(
              a.item_name ||
              ""
            ).localeCompare(
              String(
                b.item_name ||
                ""
              )
            );
          }
        );

    STATE.usedStockLoadedAt =
      Date.now();
  }


