  async function saveNativeTherapySession(
    values
  ) {
    var meta =
      await glpPopupMeta(
        "Therapy Session"
      );

    var plan =
      nativePlanInfo(
        values.therapy_plan
      );

    if (!plan) {
      throw new Error(
        "Select a valid GLP Therapy Plan."
      );
    }

    var requiredBranch =
      glpEffectiveAppointmentBranch(
        plan
      );

    if (
      requiredBranch &&
      norm(values.branch) !==
        norm(requiredBranch)
    ) {
      throw new Error(
        "This client belongs to " +
        requiredBranch +
        ". Therapy Session branch cannot be changed."
      );
    }

    if (
      values.branch &&
      !glpBranchAllowedForCurrentUser(
        values.branch
      )
    ) {
      throw new Error(
        "The Therapy Session branch is outside the logged-in user's branch access."
      );
    }

    if (
      isGLPDoseTherapyName(
        values.therapy_type
      )
    ) {
      /* One click/save = one physical injection execution. */
      values.sessions_quantity = 1;
    }

    var doc = null;

    try {
      doc =
        await frappeCall(
          "healthcare.healthcare.doctype.therapy_plan.therapy_plan.make_therapy_session",
          {
            patient:
              values.patient,
            therapy_type:
              values.therapy_type,
            company:
              plan.company ||
              "Life Slimming And Cosmetic Pvt Ltd",
            therapy_plan:
              values.therapy_plan,
            practitioner:
              values.practitioner
          }
        );
    } catch (e) {
      doc = null;
    }

    if (
      !doc ||
      typeof doc !== "object" ||
      Array.isArray(doc)
    ) {
      doc = {
        doctype:
          "Therapy Session"
      };
    }

    doc.doctype =
      "Therapy Session";

    delete doc.appointment;
    delete doc.department;

    glpPopupPut(
      doc,
      meta,
      ["patient"],
      values.patient,
      "patient"
    );

    glpPopupPut(
      doc,
      meta,
      ["therapy_plan"],
      values.therapy_plan,
      "therapy_plan"
    );

    glpPopupPut(
      doc,
      meta,
      ["therapy_type"],
      values.therapy_type,
      "therapy_type"
    );

    glpPopupPut(
      doc,
      meta,
      ["branch"],
      values.branch
    );

    glpPopupPut(
      doc,
      meta,
      [
        "practitioner",
        "healthcare_practitioner"
      ],
      values.practitioner,
      "practitioner"
    );

    glpPopupPut(
      doc,
      meta,
      [
        "service_unit",
        "healthcare_service_unit"
      ],
      values.service_unit
    );

    glpPopupPut(
      doc,
      meta,
      ["duration"],
      Number(
        values.duration || 30
      ),
      "duration"
    );

    glpPopupPut(
      doc,
      meta,
      ["company"],
      plan.company ||
      "Life Slimming And Cosmetic Pvt Ltd",
      "company"
    );

    glpPopupPut(
      doc,
      meta,
      [
        "custom_actual_session_date",
        "session_date",
        "start_date"
      ],
      values.session_date,
