  function glpForceNativeCalendarInput(
    element,
    id
  ) {
    if (!element) {
      return null;
    }

    /*
      V4.83 hard guarantee:
      Even if an older cached markup path renders this field as a <select>,
      replace it immediately with a real <input type="date">.
    */
    if (
      String(
        element.tagName || ""
      ).toUpperCase() !== "INPUT" ||
      String(
        element.type || ""
      ).toLowerCase() !== "date"
    ) {
      var replacement =
        document.createElement(
          "input"
        );

      replacement.id =
        id || element.id || "";

      replacement.type =
        "date";

      replacement.className =
        element.className || "";

      replacement.value =
        element.value || "";

      if (
        element.required
      ) {
        replacement.required =
          true;
      }

      element.replaceWith(
        replacement
      );

      element =
        replacement;
    }

    element.setAttribute(
      "type",
      "date"
    );

    element.setAttribute(
      "min",
      todayISO()
    );

    element.removeAttribute(
      "disabled"
    );

    element.addEventListener(
      "click",
      function () {
        try {
          if (
            typeof element.showPicker ===
            "function"
          ) {
            element.showPicker();
          }
        } catch (e) {}
      }
    );

    return element;
  }



  // ================================================================
  // V5.77 - SESSION EXECUTION: ALL GLP CLIENTS, NO PAGE DATE FILTER
  // ================================================================
  // The page From / To dates are reporting filters. They must NOT limit
  // the Client / Therapy Plan choices inside New Therapy Session Execution.
  //
  // This loader deliberately fetches GLP Therapy Plans without STATE.from
  // or STATE.to. Branch/user permission scope is still respected.
  async function loadAllGLPSessionPlansIgnoreDateV577(
    branchScope
  ) {
    await loadTherapyTypesFast();

    var therapyNames =
      glpTherapyTypeNames();

    if (!therapyNames.length) {
      return [];
    }

    var detailRows = [];

    try {
      /*
        Start from Therapy Plan Detail so we fetch only plans that actually
        contain a GLP Therapy Type. No date filter is applied here.
      */
      detailRows =
        await getChildListPage(
          "Therapy Plan",
          "Therapy Plan Detail",
          [
            "parent",
            "therapy_type"
          ],
          [
            [
              "therapy_type",
              "in",
              therapyNames
            ]
          ],
          "modified desc",
          0,
          5000
        );
    } catch (e) {
      void 0;
      detailRows = [];
    }

    var typeMap = {};
    var planIds = [];

    (detailRows || []).forEach(function (row) {
      if (!row || !row.parent) {
        return;
      }

      if (!typeMap[row.parent]) {
        typeMap[row.parent] = [];
        planIds.push(row.parent);
      }

      var therapy =
        row.therapy_type ||
        "GLP Therapy";

      if (
        typeMap[row.parent].indexOf(
          therapy
        ) < 0
      ) {
        typeMap[row.parent].push(
          therapy
        );
      }
    });

    if (!planIds.length) {
      return [];
    }

    var planRows = [];

    try {
      var chunks =
        chunkArray(
          planIds,
          120
        );

      planRows =
        await mapChunksLimited(
          chunks,
          3,
          async function (ids) {
            try {
              return (
                await getAllRows(
                  "Therapy Plan",
                  SCHEMA["Therapy Plan"].fields,
                  [
                    [
                      "name",
                      "in",
                      ids
                    ]
                  ],
                  "start_date desc",
                  500
                )
              ) || [];
            } catch (error) {
              void 0;
              return [];
            }
          }
        );
    } catch (e) {
      void 0;
      planRows = [];
    }

    var rows =
      uniqueRowsByName(
        planRows || []
      )
        .filter(function (plan) {
          return (
            plan &&
            typeMap[plan.name]
          );
        });

    rows.forEach(function (plan) {
      plan._branch =
        directDetectedBranch(
          plan,
          "Therapy Plan"
        ) ||
        plan._branch ||
        plan.branch ||
        "";

      plan._glp_therapy_types =
        typeMap[plan.name] ||
        ["GLP Therapy"];
    });

    /*
      Respect the branch selected on the page when one is selected.
      Only the From / To date filter is intentionally ignored.
    */
    var requestedBranch =
      branchScope ||
      STATE.branchDetail ||
      (
        STATE.branch !== "ALL"
          ? STATE.branch
          : ""
      ) ||
      (
        STATE.userBranchLocked &&
        STATE.userBranchScope &&
        STATE.userBranchScope.length === 1
          ? STATE.userBranchScope[0]
          : ""
      );

    if (requestedBranch) {
      var requestedKey =
        norm(
          requestedBranch
        );

      rows =
        rows.filter(function (plan) {
          return (
            norm(
              plan._branch ||
              plan.branch ||
              ""
            ) ===
            requestedKey
          );
        });
    }

    /*
      Always enforce the logged-in user's permitted branch scope.
    */
    if (
      STATE.userBranchScope &&
      STATE.userBranchScope.length
    ) {
      var allowed =
        STATE.userBranchScope.map(
          norm
        );

      rows =
        rows.filter(function (plan) {
          var planBranch =
            plan._branch ||
            plan.branch ||
            "";

          return (
            !planBranch ||
            allowed.indexOf(
              norm(
                planBranch
              )
            ) >= 0
          );
        });
    }

    rows.sort(function (a,b) {
      return String(
        b.start_date ||
        b.modified ||
        b.creation ||
        ""
      ).localeCompare(
        String(
          a.start_date ||
          a.modified ||
          a.creation ||
          ""
        )
      );
    });

    void 0;

    return rows;
  }

  async function openGLPTherapySessionNativeModal() {
    ensureGLPSessionClinicalStyles();

    /*
      Therapy Session follows the same branch rule as Appointment:
      the selected GLP Therapy Plan/client decides the branch.
      Practitioner and Service Unit are then loaded only for that branch.
    */
    var initialBranch =
      glpEffectiveAppointmentBranch(
        null
      );

    var plans =
      nativeCurrentPlans(
        initialBranch
      );

    /*
      V5.35 FIX
      ---------
      Keep the complete Therapy Session plan set inside THIS modal scope.
      V5.34 referenced allSessionPlans later in the Therapy Session client
      search / Therapy Plan filtering flow, but the variable had only been
      declared inside the Appointment modal. That caused:

        ReferenceError: allSessionPlans is not defined

      The session modal now owns its own copy.
    */
    var allSessionPlans =
      plans.slice();

    if (!plans.length) {
      glpSafeMessage(
        "No GLP Therapy Plans",
        (
          initialBranch
            ? (
                "No GLP Therapy Plans are available for " +
                initialBranch +
                "."
              )
            : "No GLP Therapy Plans are available in the logged-in user's branch scope."
