    function enforceSessionWeightLimit(
      weightEl
    ) {
      if (!weightEl) {
        return;
      }

      weightEl.setAttribute(
        "min",
        "0"
      );

      weightEl.setAttribute(
        "max",
        "250"
      );

      weightEl.setAttribute(
        "step",
        "0.1"
      );

      weightEl.setAttribute(
        "inputmode",
        "decimal"
      );

      weightEl.setAttribute(
        "autocomplete",
        "off"
      );

      /*
        HTML max alone does not stop the user from typing a larger
        number. Enforce the limit while typing as well.
      */
      weightEl.addEventListener(
        "keydown",
        function (event) {
          if (
            event.key === "e" ||
            event.key === "E" ||
            event.key === "+" ||
            event.key === "-"
          ) {
            event.preventDefault();
          }
        }
      );

      weightEl.addEventListener(
        "input",
        function () {
          var raw =
            String(
              weightEl.value || ""
            ).trim();

          if (!raw) {
            return;
          }

          var value =
            Number(
              raw
            );

          if (
            !Number.isFinite(
              value
            )
          ) {
            weightEl.value = "";
            return;
          }

          if (value < 0) {
            weightEl.value = "0";
            return;
          }

          if (value > 250) {
            weightEl.value = "250";

            weightEl.setCustomValidity(
              "Maximum allowed weight is 250 kg."
            );

            setTimeout(
              function () {
                weightEl.setCustomValidity(
                  ""
                );
              },
              1200
            );

            return;
          }

          weightEl.setCustomValidity(
            ""
          );
        }
      );

      weightEl.addEventListener(
        "blur",
        function () {
          var raw =
            String(
              weightEl.value || ""
            ).trim();

          if (!raw) {
            return;
          }

          var value =
            Number(
              raw
            );

          if (
            !Number.isFinite(
              value
            )
          ) {
            weightEl.value = "";
            return;
          }

          value =
            Math.max(
              0,
              Math.min(
                250,
                value
              )
            );

          /*
            Keep at most one decimal place because the field uses 0.1 kg.
          */
          weightEl.value =
            String(
              Math.round(
                value * 10
              ) / 10
            );
        }
      );
    }

