    async function syncSessionNextAppointmentRequirement() {
      currentNextAppointment =
        null;

      var sessionDateForNext =
        String(
          (
            sessionDateEl &&
            sessionDateEl.value
          ) ||
          todayISO()
        ).slice(0,10);

      var allowedNextDates =
        glpAllowedNextDoseDates(
