        nextDateEl.innerHTML =
          glpNextDoseDateOptions(
            sessionDateForNext,
            existingDate
          );

        nextDateEl.value =
          existingDate;

        var existingTime =
          existing.appointment_time
            ? String(
                existing.appointment_time
              ).slice(0,5)
            : "";

        if (
          existingTime &&
          Array.from(
            nextTimeEl.options || []
