          row.middle_name,
          row.last_name
        ]
          .filter(Boolean)
          .join(" ") ||
        row.name ||
        "";

      var id =
        row.name || "";

      return (
        name +
        (
          id &&
          id !== name
            ? " · " + id
            : ""
        )
      );
    }


    function sessionPatientResultMeta(
      row
    ) {
      var mobile =
        patientMobileValue(
          row
        );

      /*
        V5.36
        Therapy Session client search should show the mobile number normally.
        Do not display the masked 123••••789 pattern inside this search list.
      */
      var phone =
        normalizedPhone(
          mobile
        );

      var mobileDisplay =
        phone
          ? phone.digits
          : "";

      var branch =
        row._branch ||
        sessionPatientPlanBranch(
          row.name
        ) ||
        "—";

      return [
        mobileDisplay,
        branch
      ]
        .filter(Boolean)
        .join(" · ");
    }


    function populateSessionPlansForPatient(
      patientId
    ) {
      var clientPlans =
        sessionPlansForPatient(
          patientId
        );

      planEl.innerHTML =
        '<option value="">Select Therapy Plan...</option>' +
        clientPlans
          .map(function (plan) {
            var label =
              plan.name;

            var displayTitle =
              therapyPlanDisplayTitle(
                plan
              );

            if (
              displayTitle &&
              displayTitle !==
                plan.name
            ) {
              label +=
                " · " +
                displayTitle;
            }

            if (plan.start_date) {
              label +=
                " · " +
                fmtDate(
                  plan.start_date
                );
            }

            return (
              '<option value="' +
                esc(
                  plan.name
                ) +
              '">' +
                esc(
                  label
                ) +
              '</option>'
            );
          })
          .join("");

      planEl.value =
        "";

      planEl.disabled =
        !clientPlans.length;

      typeEl.value =
        "";

      if (!clientPlans.length) {
        planEl.innerHTML =
          '<option value="">No GLP Therapy Plans found</option>';
      }

      return clientPlans;
    }


    async function loadSessionPatientRows() {
      if (
        Array.isArray(
          sessionPatientRowsCache
        )
      ) {
        return sessionPatientRowsCache;
      }

      var patientIds =
        Array.from(
          new Set(
            (
              allSessionPlans ||
              []
            )
              .map(function (plan) {
                return (
                  plan &&
                  plan.patient
                );
              })
              .filter(Boolean)
          )
        );

      if (!patientIds.length) {
        sessionPatientRowsCache = [];
        return [];
      }

      var patientSet = {};

      patientIds.forEach(
        function (patientId) {
          patientSet[patientId] = true;
        }
      );

      var rowMap = {};

      /*
        Start with Patient rows that are already loaded by the dashboard.
        This makes name / Patient ID search available immediately and does
        not depend on a new ERPNext request.
      */
      (STATE.data.patients || [])
        .forEach(function (row) {
          if (
            row &&
            row.name &&
            patientSet[row.name]
          ) {
            rowMap[row.name] =
              Object.assign(
                {},
                row
              );
          }
        });

      /*
        V5.36 IMPORTANT
        ----------------
        Do not depend on the cached SCHEMA["Patient"].fields here.
        A stale browser schema cache can contain an old/non-existent mobile
        field and make frappe.client.get_list fail. That was producing:

          "Could not search clients."

        Read one real Patient document first and derive the actual fields
        available in this ERPNext site.
      */
      var requestedFields = [
        "name",
        "patient_name",
        "first_name",
        "middle_name",
        "last_name"
      ];

      try {
        var samplePatient =
          await getFullDoc(
            "Patient",
            patientIds[0]
          );

        if (samplePatient) {
          var sampleKeys =
            Object.keys(
              samplePatient
            );

          requestedFields =
            requestedFields
              .filter(function (fieldname) {
                return (
                  fieldname === "name" ||
                  sampleKeys.indexOf(
                    fieldname
                  ) >= 0
                );
              });

          var mobileFields =
            sampleKeys
              .filter(function (fieldname) {
                return (
                  /(mobile|phone|telephone|contact.*(no|number))/i.test(
                    fieldname
                  )
                );
              });

          BRANCH_CANDIDATES.forEach(
            function (fieldname) {
              if (
                sampleKeys.indexOf(
                  fieldname
                ) >= 0
              ) {
                requestedFields.push(
                  fieldname
                );
              }
            }
          );

          requestedFields =
            requestedFields
              .concat(
                mobileFields
              )
              .filter(function (
                fieldname,
                index,
                all
              ) {
                return (
                  all.indexOf(
                    fieldname
                  ) === index
                );
              });

          sessionPatientMobileFieldsCache =
            mobileFields.slice();
        }
      } catch (sampleError) {
        void 0;
      }

      var listRows = [];

      try {
        var chunks =
          chunkArray(
            patientIds,
            150
          );

        listRows =
          await mapChunksLimited(
            chunks,
            2,
            async function (ids) {
              try {
                return await getAllRows(
                  "Patient",
                  requestedFields,
                  [
                    [
                      "name",
                      "in",
                      ids
                    ]
                  ],
                  "modified desc",
                  500
                );
              } catch (error) {
                void 0;

                return [];
              }
            }
          );
      } catch (listError) {
        void 0;
      }

      (listRows || [])
        .forEach(function (row) {
          if (row && row.name) {
            rowMap[row.name] =
              Object.assign(
                {},
                rowMap[row.name] || {},
                row
              );
          }
        });

      /*
        If list permission / a custom Patient field still blocks get_list,
        fetch the linked GLP Patients directly. This is slower, so it is only
        a fallback, but it keeps mobile-number search functional.
      */
      var rowsWithMobile =
        Object.keys(rowMap)
          .filter(function (name) {
            return !!patientMobileValue(
              rowMap[name]
            );
          });

      if (
        rowsWithMobile.length <
        Math.min(
          patientIds.length,
          10
        )
      ) {
        try {
          var directChunks =
            chunkArray(
              patientIds,
              20
            );

          var directRows =
            await mapChunksLimited(
              directChunks,
              3,
              async function (ids) {
                var fetched =
                  await Promise.all(
                    ids.map(
                      function (patientId) {
                        return getFullDoc(
                          "Patient",
                          patientId
                        )
                          .catch(function () {
                            return null;
                          });
                      }
                    )
                  );

                return fetched.filter(Boolean);
              }
            );

          (directRows || [])
            .forEach(function (row) {
              if (row && row.name) {
                rowMap[row.name] =
                  Object.assign(
                    {},
                    rowMap[row.name] || {},
                    row
                  );
              }
            });
        } catch (directError) {
          void 0;
        }
      }

      /*
        Always keep a fallback entry from Therapy Plan itself, even when the
        logged-in user cannot list/read the Patient document.
      */
      patientIds.forEach(
        function (patientId) {
          if (!rowMap[patientId]) {
            var plan =
              sessionPlansForPatient(
                patientId
              )[0];

            rowMap[patientId] = {
              name:
                patientId,
              patient_name:
                (
                  plan &&
                  plan.patient_name
                ) ||
                patientId
            };
          }
        }
      );

      sessionPatientRowsCache =
        Object.keys(
          rowMap
        )
          .map(function (key) {
            var row =
              rowMap[key];

            row._branch =
              row._branch ||
              sessionPatientPlanBranch(
                row.name
              );

            return row;
          })
          .filter(function (row) {
            var branch =
              row._branch ||
              "";

            return (
              !branch ||
              glpBranchAllowedForCurrentUser(
                branch
              )
            );
          });

      return sessionPatientRowsCache;
    }


    async function searchSessionPatients(
      query
    ) {
      query =
        String(
          query || ""
        ).trim();

      if (query.length < 3) {
        return [];
      }

      var rows = [];

      try {
        rows =
          await loadSessionPatientRows();
      } catch (loadError) {
        void 0;

        rows = [];
      }

      var textKey =
        norm(
          query
        );

      var digitKey =
        query.replace(
          /\D/g,
          ""
        );

      var useDigitSearch =
        digitKey.length >= 3;

      var matches =
        (rows || [])
          .filter(function (row) {
            var mobile =
              patientMobileValue(
                row
              );

            var phone =
              normalizedPhone(
                mobile
              );

            if (
              useDigitSearch &&
              phone &&
              phone.digits.indexOf(
                digitKey
              ) >= 0
            ) {
              return true;
            }

            var haystack =
              norm(
                [
                  row.name,
                  row.patient_name,
                  row.first_name,
                  row.middle_name,
                  row.last_name,
                  mobile,
                  row._branch
                ].join(" ")
              );

            return (
              haystack.indexOf(
                textKey
              ) >= 0
            );
          });

      /*
        Numeric query fallback:
        Search real Patient mobile fields directly, then keep only Patients
        that belong to the GLP Therapy Plans available in this modal.
      */
      if (
        useDigitSearch &&
        !matches.length
      ) {
        try {
          var allowedPatientIds =
            Array.from(
              new Set(
                (
                  allSessionPlans ||
                  []
                )
                  .map(function (plan) {
                    return (
                      plan &&
                      plan.patient
                    );
                  })
                  .filter(Boolean)
              )
            );

          var allowedSet = {};

          allowedPatientIds.forEach(
            function (patientId) {
              allowedSet[patientId] = true;
            }
          );

          var mobileFields =
            sessionPatientMobileFieldsCache ||
            [];

          if (
            !mobileFields.length &&
            allowedPatientIds.length
          ) {
            var sample =
              await getFullDoc(
                "Patient",
                allowedPatientIds[0]
              );

            mobileFields =
              Object.keys(
                sample || {}
              )
                .filter(function (fieldname) {
                  return (
                    /(mobile|phone|telephone|contact.*(no|number))/i.test(
                      fieldname
                    )
                  );
                });

            sessionPatientMobileFieldsCache =
              mobileFields.slice();
          }

          if (mobileFields.length) {
            var directFields = [
              "name",
              "patient_name",
              "first_name",
              "middle_name",
              "last_name"
            ];

            mobileFields.forEach(
              function (fieldname) {
                if (
                  directFields.indexOf(
                    fieldname
                  ) < 0
                ) {
                  directFields.push(
                    fieldname
                  );
                }
              }
            );

            var directMatches =
              await frappeCall(
                "frappe.client.get_list",
                {
                  doctype:
                    "Patient",
                  fields:
                    directFields,
                  filters:
                    [],
                  or_filters:
                    mobileFields.map(
                      function (fieldname) {
                        return [
                          "Patient",
                          fieldname,
                          "like",
                          "%" +
                            digitKey +
                          "%"
                        ];
                      }
                    ),
                  order_by:
                    "modified desc",
                  limit_start:
                    0,
                  limit_page_length:
                    50
                },
                12000
              );

            (directMatches || [])
              .forEach(function (row) {
                if (
                  row &&
                  row.name &&
                  allowedSet[row.name]
                ) {
                  row._branch =
                    sessionPatientPlanBranch(
                      row.name
                    );

                  if (
                    !row._branch ||
                    glpBranchAllowedForCurrentUser(
                      row._branch
                    )
                  ) {
                    matches.push(
                      row
                    );
                  }
                }
              });
          }
        } catch (mobileSearchError) {
          void 0;
        }
      }

      return uniqueRowsByName(
        matches || []
      ).slice(
        0,
        20
      );
    }


    function closeSessionPatientResults() {
      if (!patientResultsEl) {
        return;
      }

      patientResultsEl.style.display =
        "none";

      patientResultsEl.innerHTML =
        "";
    }


    async function clearSessionClientSelection(
      keepSearchText
    ) {
      if (patientIdEl) {
        patientIdEl.value =
          "";
      }

      if (
        patientEl &&
        !keepSearchText
      ) {
        patientEl.value =
          "";
      }

      if (patientEl) {
        patientEl.dataset.selectedLabel =
          "";
      }

      planEl.innerHTML =
        '<option value="">Select client first...</option>';

      planEl.value =
        "";

      planEl.disabled =
        true;

      typeEl.value =
        "";

      branchEl.value =
        "";

      resetDoseApprovalState();

      await refreshSessionBranchMasters(
