    async function selectSessionClient(
      row
    ) {
      if (
        !row ||
        !row.name
      ) {
        return;
      }

      var label =
        sessionPatientDisplayLabel(
          row
        );

      patientIdEl.value =
        row.name;

      patientEl.value =
        label;

      patientEl.dataset.selectedLabel =
        label;

      closeSessionPatientResults();

      var clientPlans =
        populateSessionPlansForPatient(
          row.name
        );

      if (patientHintEl) {
        patientHintEl.textContent =
          clientPlans.length +
          (
            clientPlans.length === 1
              ? " GLP Therapy Plan available."
              : " GLP Therapy Plans available."
          );
      }

      branchEl.value =
        "";

      typeEl.value =
        "";

      resetDoseApprovalState();

      await refreshSessionBranchMasters(
        ""
      );

      await syncSessionNextAppointmentRequirement();

      if (planEl) {
        try {
          planEl.focus();
        } catch (ignore) {}
      }
    }


    function renderSessionPatientResults(
      matches
    ) {
      if (!patientResultsEl) {
        return;
      }

      if (!matches.length) {
        patientResultsEl.innerHTML =
          '<div class="glp-session-client-result-empty">' +
            'No GLP client found for this search.' +
          '</div>';

        patientResultsEl.style.display =
          "block";

        return;
      }

      patientResultsEl.innerHTML =
        matches
          .map(function (row) {
            return (
              '<button type="button" class="glp-session-client-result" ' +
                'data-glp-session-patient="' +
                  esc(
                    row.name
                  ) +
                '">' +
                '<b>' +
                  esc(
                    row.patient_name ||
                    row.name
                  ) +
                '</b>' +
                '<span>' +
                  esc(
                    [
                      row.name,
                      sessionPatientResultMeta(
                        row
                      )
                    ]
                      .filter(Boolean)
                      .join(" · ")
                  ) +
                '</span>' +
              '</button>'
            );
          })
          .join("");

      patientResultsEl.style.display =
        "block";

      Array.from(
        patientResultsEl.querySelectorAll(
          "[data-glp-session-patient]"
        )
      ).forEach(
        function (button) {
          button.addEventListener(
            "click",
            async function () {
              var patientId =
                this.getAttribute(
                  "data-glp-session-patient"
                ) ||
                "";

              var rows =
                await loadSessionPatientRows();

              var row =
                rows.find(
                  function (candidate) {
                    return (
                      candidate.name ===
                        patientId
                    );
                  }
                );

              if (row) {
                await selectSessionClient(
                  row
                );
              }
            }
          );
        }
      );
    }


    if (patientEl) {
      patientEl.addEventListener(
        "input",
        function () {
          var input =
            this;

          var raw =
            String(
              input.value || ""
            ).trim();

          var selectedLabel =
            String(
              input.dataset.selectedLabel ||
              ""
            );

          clearTimeout(
            sessionPatientSearchTimer
          );

          sessionPatientSearchToken +=
            1;

          var token =
            sessionPatientSearchToken;

          if (
            selectedSessionPatientId() &&
            raw !== selectedLabel
          ) {
            clearSessionClientSelection(
              true
            ).catch(function () {});
          }

          if (raw.length < 3) {
            closeSessionPatientResults();

            if (patientHintEl) {
              patientHintEl.textContent =
                "Enter at least 3 letters or digits to search GLP clients.";
            }

            return;
          }

          if (patientHintEl) {
            patientHintEl.textContent =
              "Searching GLP clients...";
          }

          if (patientResultsEl) {
            patientResultsEl.innerHTML =
              '<div class="glp-session-client-result-empty">Searching ERPNext...</div>';

            patientResultsEl.style.display =
              "block";
          }

          sessionPatientSearchTimer =
            setTimeout(
              async function () {
                try {
                  var matches =
                    await searchSessionPatients(
                      raw
                    );

                  if (
                    token !==
                    sessionPatientSearchToken
                  ) {
                    return;
                  }

                  renderSessionPatientResults(
                    matches
                  );

                  if (patientHintEl) {
                    patientHintEl.textContent =
                      matches.length
                        ? (
                            matches.length +
                            (
                              matches.length === 1
                                ? " matching GLP client."
                                : " matching GLP clients."
                            )
                          )
                        : "No matching GLP client.";
                  }

                } catch (error) {
                  void 0;

                  if (patientResultsEl) {
                    patientResultsEl.innerHTML =
                      '<div class="glp-session-client-result-empty">Could not search clients.</div>';

                    patientResultsEl.style.display =
                      "block";
                  }

                  if (patientHintEl) {
                    patientHintEl.textContent =
                      "Client search failed.";
                  }
                }
              },
              250
            );
        }
      );

      patientEl.addEventListener(
        "focus",
        function () {
          var raw =
            String(
              this.value || ""
            ).trim();

          if (
            raw.length >= 3 &&
            !selectedSessionPatientId()
          ) {
            this.dispatchEvent(
              new Event(
                "input",
                {
                  bubbles:true
                }
              )
            );
          }
        }
      );
    }


    modal.addEventListener(
      "click",
      function (event) {
        if (
          patientResultsEl &&
          patientEl &&
          !patientResultsEl.contains(
            event.target
          ) &&
          event.target !==
            patientEl
        ) {
