    function refreshDoseSubmitGate() {
      /*
        Therapy Session is entered AFTER treatment.
        Keep the button clickable; validation returns a clear message if
        the pre-treatment Therapy Plan approval is missing.
      */
      if (sessionSubmitButton) {
        sessionSubmitButton.disabled =
          false;
      }
    }


    function resetDoseApprovalState() {
      doseApprovalState = {
        billed_dose:"",
        reference_dose:"",
        sales_invoice:"",
        source:"",
        status:"",
        reason:"",
        approved_by:"",
        proposed_dose:""
      };

      if (injectionDoseEl) {
        injectionDoseEl.value = "";
      }

      if (doseRequestIdEl) {
        doseRequestIdEl.textContent = "";
      }

      setDoseApprovalStatus(
        "Select Dose (mg). A changed dose will be verified against the pre-treatment approval stored on the Therapy Plan.",
        ""
      );

      refreshDoseSubmitGate();
    }


    async function refreshDoseApprovalForSelection() {
      var plan =
        nativePlanInfo(
          planEl.value
        );

      if (
        !plan ||
        !isGLPDoseTherapyName(
          typeEl.value
        )
      ) {
        if (doseBlockEl) {
          doseBlockEl.style.display =
            "none";
        }

        refreshDoseSubmitGate();
        return;
      }

      if (doseBlockEl) {
        doseBlockEl.style.display =
          "grid";
      }

      var selected =
        String(
          (
            injectionDoseEl &&
            injectionDoseEl.value
          ) ||
          ""
        ).trim();

      if (!selected) {
        doseApprovalState.status = "";

        if (doseRequestIdEl) {
          doseRequestIdEl.textContent = "";
        }

        setDoseApprovalStatus(
          "Select Dose (mg). Approval requests are raised from Therapy Plan → Dose Review before treatment.",
          ""
        );

        refreshDoseSubmitGate();
        return;
      }

      var lookup =
        await glpDoseApprovalCall(
          "lookup",
          {
            therapy_plan:
              planEl.value,
            requested_dose:
              selected
          }
        );

      doseApprovalState.billed_dose =
        lookup.reference_dose ||
        lookup.billed_dose ||
        doseApprovalState.billed_dose ||
        "";

      doseApprovalState.reference_dose =
        doseApprovalState.billed_dose;

      doseApprovalState.status =
        lookup.status ||
        "";

      doseApprovalState.approved_by =
        lookup.approved_by ||
        "";

      doseApprovalState.reason =
        lookup.reason ||
        "";

      doseApprovalState.proposed_dose =
        lookup.proposed_dose ||
        selected;

      if (doseRequestIdEl) {
        doseRequestIdEl.textContent =
          doseApprovalState.status
            ? (
                "Therapy Plan approval · " +
                doseApprovalState.status
              )
            : "";
      }

      if (
        lookup.approval_required === false ||
        doseApprovalState.status ===
          "Not Required"
      ) {
        setDoseApprovalStatus(
          doseApprovalState.billed_dose
            ? (
                "Dose matches the current/reference dose (" +
                doseApprovalState.billed_dose +
                "). No management change approval is required."
              )
            : "No previous/reference dose is recorded. This will become the first recorded GLP dose.",
          "ok"
        );

      } else if (
        doseApprovalState.status ===
        "Approved"
      ) {
        setDoseApprovalStatus(
          "Pre-treatment Therapy Plan dose approval is Approved" +
          (
            doseApprovalState.approved_by
              ? " by " +
                doseApprovalState.approved_by
              : ""
          ) +
          ". This post-treatment execution may be submitted.",
          "ok"
        );

      } else if (
        doseApprovalState.status ===
        "Pending"
      ) {
        setDoseApprovalStatus(
          "Therapy Plan dose change approval is still Pending. This changed-dose execution cannot be submitted as approved.",
          ""
        );

      } else if (
        doseApprovalState.status ===
        "Rejected"
      ) {
        setDoseApprovalStatus(
          "Therapy Plan dose change approval was Rejected. This changed-dose execution cannot be submitted.",
          "bad"
        );

      } else {
        setDoseApprovalStatus(
          "No approved Therapy Plan dose change was found for this changed dose. Use Therapy Plan → Dose Review before treatment.",
          "bad"
        );
      }

      refreshDoseSubmitGate();
    }


    async function syncDoseContextForPlan() {
      doseApprovalState.status = "";
      doseApprovalState.reason = "";
      doseApprovalState.approved_by = "";
      doseApprovalState.proposed_dose = "";

      if (
        !planEl.value
      ) {
        doseApprovalState.billed_dose = "";
        doseApprovalState.reference_dose = "";
        doseApprovalState.source = "";
        doseApprovalState.sales_invoice = "";
        await refreshDoseApprovalForSelection();
        return;
      }

      try {
        var context =
          await glpDoseApprovalCall(
            "context",
            {
              therapy_plan:
                planEl.value
            }
          );

        doseApprovalState.billed_dose =
          context.reference_dose ||
          context.billed_dose ||
          "";

        doseApprovalState.reference_dose =
          doseApprovalState.billed_dose;

        doseApprovalState.sales_invoice =
          context.sales_invoice ||
          "";

        doseApprovalState.source =
          context.source ||
          "";

        doseApprovalState.status =
          context.status ||
          "";

        doseApprovalState.reason =
          context.reason ||
          "";

        doseApprovalState.approved_by =
          context.approved_by ||
          "";

        doseApprovalState.proposed_dose =
          context.proposed_dose ||
          "";

        void 0;

      } catch (error) {
        doseApprovalState.billed_dose = "";
        doseApprovalState.reference_dose = "";
        doseApprovalState.sales_invoice = "";
        doseApprovalState.source = "";
        doseApprovalState.status = "";

        void 0;
      }

      await refreshDoseApprovalForSelection();
    }


    if (injectionDoseEl) {
      injectionDoseEl.addEventListener(
        "change",
        function () {
          doseApprovalState.status = "";
          doseApprovalState.reason = "";

          refreshDoseApprovalForSelection()
            .catch(function (error) {
              setDoseApprovalStatus(
                glpRequestErrorMessage(
                  error
                ),
                "bad"
              );
            });
        }
      );
    }


    async function ensureDoseApprovalBeforeSession(
      values
    ) {
      if (
        !isGLPDoseTherapyName(
          values.therapy_type
        )
      ) {
        return;
      }

      var selected =
        String(
          values.injection_dose ||
          ""
        ).trim();

      if (!selected) {
        throw new Error(
          "Select Dose (mg) for this Therapy Session."
        );
      }

      values.vial_strength =
        selected;

      values.injection_dose =
        selected;

      var lookup =
        await glpDoseApprovalCall(
          "lookup",
          {
            therapy_plan:
              values.therapy_plan,
            requested_dose:
              selected
          }
        );

      var referenceDose =
        String(
          lookup.reference_dose ||
          lookup.billed_dose ||
          doseApprovalState.reference_dose ||
          ""
        ).trim();

      values.billed_dose =
        referenceDose ||
        selected;

      if (
        lookup.approval_required === false ||
        lookup.status ===
          "Not Required"
      ) {
        values.dose_change_reason = "";
        values.dose_approval_status =
          "Not Required";

        doseApprovalState.status =
          "Not Required";

        return;
      }

      if (
        lookup.status !==
        "Approved"
      ) {
        throw new Error(
          "Dose " +
          selected +
          " is a change from current/reference dose " +
          (
            referenceDose ||
            "not recorded"
          ) +
          ". Therapy Plan management approval is " +
          (
            lookup.status ||
            "Not Requested"
          ) +
          ". Approval must be completed before the changed-dose treatment."
        );
      }

      values.dose_change_reason =
        lookup.reason ||
        "";

      values.dose_approval_status =
        "Approved";

      doseApprovalState.status =
        "Approved";

      doseApprovalState.reason =
        lookup.reason ||
        "";

      doseApprovalState.approved_by =
        lookup.approved_by ||
        "";
    }


    async function syncPlan() {
      var p =
        nativePlanInfo(
          planEl.value
        );

      if (p) {
        var selectedPatient =
          selectedSessionPatientId();

        if (
          selectedPatient &&
          p.patient !==
            selectedPatient
        ) {
          glpSafeMessage(
            "Therapy Plan mismatch",
            "Select a Therapy Plan belonging to the selected client.",
            true
          );

          planEl.value =
            "";

          typeEl.value =
            "";

          return;
        }

        if (
          !selectedPatient &&
          p.patient
        ) {
          patientIdEl.value =
            p.patient;
        }
      }

      if (
        p &&
        p.patient &&
        selectedSessionPatientId() ===
          p.patient
      ) {
        loadSessionPatientRows()
          .then(function (rows) {
            var row =
              rows.find(function (candidate) {
                return (
                  candidate.name ===
                    p.patient
                );
              });

            if (row) {
              var label =
                sessionPatientDisplayLabel(
                  row
                );

              patientEl.value =
                label;

              patientEl.dataset.selectedLabel =
                label;
            }
          })
          .catch(function () {});
      }

      typeEl.value =
        p
          ? nativePlanTherapy(p)
          : "";

      if (!p) {
        branchEl.value = "";

        await refreshSessionBranchMasters(
          ""
        );

        return;
      }

      var planBranch =
        glpEffectiveAppointmentBranch(
          p
        );

      if (!planBranch) {
        glpSafeMessage(
          "Branch missing",
          "The selected GLP Therapy Plan does not have a valid branch.",
          true
        );

        planEl.value = "";
        typeEl.value = "";
        branchEl.value = "";

        await refreshSessionBranchMasters(
          ""
        );

        return;
      }

      if (
        !glpBranchAllowedForCurrentUser(
          planBranch
        )
      ) {
        glpSafeMessage(
          "Branch not allowed",
          "This client belongs to " +
            planBranch +
            ", which is outside the logged-in user's branch access.",
          true
        );

        planEl.value = "";
        typeEl.value = "";
        branchEl.value = "";

        await refreshSessionBranchMasters(
          ""
        );

        return;
      }

      branchEl.value =
        planBranch;

      await refreshSessionBranchMasters(
        planBranch
      );

      await syncSessionServiceUnitFromTherapyType();

      syncSessionBMIFromPlan();

      await syncFirstExecutionRequirements();

      await syncSessionNextAppointmentRequirement();

      await syncDoseContextForPlan();
    }

    planEl.addEventListener(
      "change",
      function () {
        syncPlan().catch(
          function (e) {
            void 0;

            glpSafeMessage(
              "Branch details not loaded",
              glpRequestErrorMessage(e),
              true
            );
          }
        );
      }
    );

    modal.querySelector(
      "#glp-ns-time"
    ).addEventListener(
      "change",
      function () {
        if (
          planEl.value
        ) {
          syncSessionNextAppointmentRequirement()
            .catch(
              function (e) {
                void 0;
              }
            );
        }
      }
    );

    /*
      If the page itself already identifies one branch, pre-load its
      practitioner/service-unit lists. The actual client branch is still
      re-confirmed when a Therapy Plan is selected.
    */
    if (defaultBranch) {
      branchEl.value =
        defaultBranch;

      if (
        masters.practitioners.length === 1
      ) {
        practitionerEl.value =
          masters.practitioners[0].name;
      }

      unitEl.innerHTML =
        '<option value="">Select Therapy Plan first...</option>';

      unitEl.disabled =
        true;

      nextRoomEl.innerHTML =
        sessionRoomOptions(
          masters.rooms
        );

      nextDateEl.disabled =
        true;

      nextTimeEl.disabled =
        true;

      nextRoomEl.disabled =
        true;
    } else {
      practitionerEl.disabled =
        true;

      unitEl.disabled =
        true;

      nextDateEl.disabled =
        true;

      nextTimeEl.disabled =
        true;

      nextRoomEl.disabled =
        true;

      practitionerEl.innerHTML =
        '<option value="">Select Therapy Plan first...</option>';

      unitEl.innerHTML =
        '<option value="">Select Therapy Plan first...</option>';

      nextRoomEl.innerHTML =
        '<option value="">Select Therapy Plan first...</option>';
    }

    /*
      V5.33:
      Initialise the dose approval UI only inside Therapy Session.
    */
    resetDoseApprovalState();

    if (doseBlockEl) {
      doseBlockEl.style.display =
        "none";
    }

    refreshDoseSubmitGate();

    modal.querySelector(
      "#glp-native-submit"
    ).addEventListener(
      "click",
      async function () {
        var btn = this;

        try {
          btn.disabled = true;
          btn.textContent = "Checking...";

          var values = {
            therapy_plan:
              planEl.value,
            patient:
              selectedSessionPatientId(),
            therapy_type:
              typeEl.value.trim(),
            branch:
              branchEl.value,
            practitioner:
              practitionerEl.value,
            service_unit:
              unitEl.value,
            session_date:
              todayISO(),
            in_time:
              modal.querySelector(
                "#glp-ns-time"
              ).value,
            duration:
              modal.querySelector(
                "#glp-ns-duration"
              ).value,
            sessions_quantity:
              modal.querySelector(
                "#glp-ns-qty"
              ).value,
            billed_dose:
              doseApprovalState.billed_dose ||
              "",
            vial_strength:
              injectionDoseEl
                ? injectionDoseEl.value
                : "",
            injection_dose:
              injectionDoseEl
                ? injectionDoseEl.value
                : "",
            dose_change_reason:
              doseApprovalState.reason ||
              "",
            dose_approval_status:
              doseApprovalState.status ||
              "",
            before_weight:
              beforeWeightEl.value,
            after_weight:
              afterWeightEl.value,
            bmi:
              bmiEl
                ? bmiEl.value
                : "",
            measurements:
              measurementsEl
                ? measurementsEl.value.trim()
                : "",
            bca_file:
              (
                bcaFileEl &&
                bcaFileEl.files &&
                bcaFileEl.files[0]
              ) ||
              null,
            before_photo:
              (
                beforePhotoEl &&
                beforePhotoEl.files &&
                beforePhotoEl.files[0]
              ) ||
              null,
            first_blood_file:
              (
                firstBloodEl &&
                firstBloodEl.files &&
                firstBloodEl.files[0]
              ) ||
              null,
            first_consent_file:
              (
                firstConsentEl &&
                firstConsentEl.files &&
                firstConsentEl.files[0]
              ) ||
              null,
            first_prescription_file:
              (
                firstPrescriptionEl &&
                firstPrescriptionEl.files &&
                firstPrescriptionEl.files[0]
              ) ||
              null,
            execution_number:
              sessionExecutionNumber,
            is_first_execution:
              sessionExecutionNumber ===
                1,
            first_existing_blood:
              !!(
                sessionFirstEvidence &&
                sessionFirstEvidence.blood_report &&
                sessionFirstEvidence.blood_report.available
              ),
            first_existing_consent:
              !!(
                sessionFirstEvidence &&
                sessionFirstEvidence.consent &&
                sessionFirstEvidence.consent.available
              ),
            first_existing_prescription:
              !!(
                sessionFirstEvidence &&
                sessionFirstEvidence.prescription &&
                sessionFirstEvidence.prescription.available
              ),
            blood_pressure:
              modal.querySelector(
                "#glp-ns-bp"
              ).value.trim(),
            blood_sugar:
              modal.querySelector(
                "#glp-ns-sugar"
              ).value.trim(),
            pulse:
              modal.querySelector(
                "#glp-ns-pulse"
              ).value.trim(),
            next_appointment_date:
              nextDateEl.value,
            next_appointment_time:
              nextTimeEl.value,
            next_appointment_room:
              nextRoomEl.value,
            remarks:
              modal.querySelector(
                "#glp-ns-remarks"
              ).value.trim()
          };

          var required = [
            ["therapy_plan","Therapy Plan"],
            ["patient","Client"],
            ["therapy_type","GLP Therapy Type"],
            ["branch","Branch"],
            ["practitioner","Practitioner"],
            ["session_date","Session Date"],
            ["in_time","In Time"],
            ["duration","Duration"],
            ["sessions_quantity","Sessions Qty"]
          ];

          required.push(
            ["service_unit","Service Unit"],
            ["bmi","BMI"],
            ["measurements","Measurements"]
          );

          if (
            isGLPDoseTherapyName(
              values.therapy_type
            )
          ) {
            required.push(
              ["injection_dose","Dose (mg)"]
            );
          }

          var missing =
            required
              .filter(function (r) {
                return !values[r[0]];
              })
              .map(function (r) {
                return r[1];
              });

          if (missing.length) {
            throw new Error(
              "Complete: " +
              missing.join(", ")
            );
          }

          var bmiValue =
            Number(
              values.bmi
            );

          if (
            !Number.isFinite(
              bmiValue
            ) ||
            bmiValue <= 0 ||
            bmiValue > 100
          ) {
            throw new Error(
              "BMI is mandatory and must be a valid value between 1 and 100."
            );
          }

          if (!values.bca_file) {
            throw new Error(
              "BCA Report / Body Composition Analysis is mandatory for GLP Therapy Session execution."
            );
          }

          if (!values.before_photo) {
            throw new Error(
              "Before Photo is mandatory for GLP Therapy Session execution."
            );
          }

          glpValidateSessionEvidenceFile(
            values.bca_file,
            "BCA Report",
            false
          );

          glpValidateSessionEvidenceFile(
            values.before_photo,
            "Before Photo",
            true
          );

          /*
            Re-check execution count live immediately before save. This is
            the authoritative first-execution decision even if another tab
            created a Therapy Session after the popup was opened.
          */
          var liveExecutionNumber =
            await glpSessionLiveExecutionNumber(
              nativePlanInfo(
                values.therapy_plan
              ),
              values.therapy_type
            );

          values.execution_number =
            liveExecutionNumber;

          values.is_first_execution =
            liveExecutionNumber ===
              1;

          if (
            values.is_first_execution
          ) {
            sessionFirstEvidence =
              await glpSessionFirstExecutionEvidence(
                nativePlanInfo(
                  values.therapy_plan
                ),
                values.patient
              );

            values.first_existing_blood =
              !!(
                sessionFirstEvidence.blood_report &&
                sessionFirstEvidence.blood_report.available
              );

            values.first_existing_consent =
              !!(
                sessionFirstEvidence.consent &&
                sessionFirstEvidence.consent.available
              );

            values.first_existing_prescription =
              !!(
                sessionFirstEvidence.prescription &&
                sessionFirstEvidence.prescription.available
              );

            if (
              !values.first_existing_blood &&
              !values.first_blood_file
            ) {
              throw new Error(
                "First GLP execution requires the client's Blood Report."
              );
            }

            if (
              !values.first_existing_consent &&
              !values.first_consent_file
            ) {
              throw new Error(
                "First GLP execution requires a signed GLP Consent Form."
              );
            }

            if (
              !values.first_existing_prescription &&
              !values.first_prescription_file
            ) {
              throw new Error(
                "First GLP execution requires the Doctor Prescription."
              );
            }

            glpValidateSessionEvidenceFile(
              values.first_blood_file,
              "Blood Report",
              false
            );

            glpValidateSessionEvidenceFile(
              values.first_consent_file,
              "GLP Consent Form",
              false
            );

            glpValidateSessionEvidenceFile(
              values.first_prescription_file,
              "Doctor Prescription",
              false
            );
          }

          [
            [
              "before_weight",
              "Before Weight"
            ],
            [
              "after_weight",
              "After Weight"
            ]
          ].forEach(
            function (item) {
              var raw =
                values[
                  item[0]
                ];

              if (
                raw === "" ||
                raw === null ||
                raw === undefined
              ) {
                return;
              }

              var weight =
                Number(
                  raw
                );

              if (
                !Number.isFinite(
                  weight
                ) ||
                weight < 0 ||
                weight > 250
              ) {
                throw new Error(
                  item[1] +
                  " must be between 0 and 250 kg."
                );
              }
            }
          );

          if (
            values.next_appointment_date &&
            values.next_appointment_date <
              todayISO()
          ) {
            throw new Error(
              "Next Appointment Date cannot be a past date."
            );
          }

          if (
            values.next_appointment_time
          ) {
            var selectedNextTime =
              glpTimeComparable(
                values.next_appointment_time
              );

            if (
              selectedNextTime <
                "07:00:00" ||
              selectedNextTime >
                "19:00:00"
            ) {
              throw new Error(
                "Next Appointment Time must be between 7:00 AM and 7:00 PM."
              );
            }
          }

          var plan =
            nativePlanInfo(
              values.therapy_plan
            );

          var requiredBranch =
            glpEffectiveAppointmentBranch(
              plan
            );

          if (
            requiredBranch &&
            norm(values.branch) !==
              norm(requiredBranch)
          ) {
            throw new Error(
              "This client belongs to " +
              requiredBranch +
              ". Therapy Session branch cannot be changed."
            );
          }

          if (
            !glpBranchAllowedForCurrentUser(
              values.branch
            )
          ) {
            throw new Error(
              "The Therapy Session branch is outside the logged-in user's branch access."
            );
          }

          /*
            Validate against the already branch-scoped dropdowns.
          */
          var allowedPractitioners =
            new Set(
              Array.from(
                practitionerEl.options || []
              )
                .map(function (o) {
                  return o.value;
                })
                .filter(Boolean)
            );

          if (
            !allowedPractitioners.has(
              values.practitioner
            )
          ) {
            throw new Error(
              "Select a Practitioner belonging to " +
              values.branch +
              "."
            );
          }

          var configuredServiceUnit =
            await glpValidateTherapyTypeServiceUnit(
              values.therapy_type
            );

          if (
            !values.service_unit ||
            values.service_unit !==
              configuredServiceUnit
          ) {
            values.service_unit =
              configuredServiceUnit;

            unitEl.innerHTML =
              '<option value="' +
                esc(configuredServiceUnit) +
              '">' +
                esc(configuredServiceUnit) +
              '</option>';

            unitEl.value =
              configuredServiceUnit;
          }

          btn.textContent =
            "Checking dose...";

          await ensureDoseApprovalBeforeSession(
            values
          );

          /*
            V5.42 PAYMENT CHECK FIX
            -----------------------
            Do not call a Web Page API method here. The installed ERPNext /
            LIFE backend remains authoritative when Therapy Session is saved.
            If payment is not sufficient, the backend save will reject the
            session and the existing catch block will show that real error.
          */

          btn.textContent =
            "Checking next appointment...";

          var nextAppointmentResult =
            await glpEnsureNextAppointmentForSession(
              values
            );

          void 0;

          btn.textContent =
            values.is_first_execution
              ? "Saving first execution + documents..."
              : "Saving session + clinical evidence...";

          void 0;

          var saved =
            await saveNativeTherapySession(
              values
            );

          btn.textContent =
            "Moving stock to Sub Store...";

          var stockIssueResult = null;
          var stockIssueError = null;

          try {
            stockIssueResult =
              await glpMoveExecutedStockToSubStoreV580(
                saved,
                values
              );
          } catch (stockError) {
            stockIssueError =
              glpRequestErrorMessage(
                stockError
              );

            void 0;
          }

          closeGLPNativeModal();

          if (stockIssueError) {
            glpSafeMessage(
              "Therapy Session created — stock needs attention",
              (
                (
                  saved &&
                  saved.name
                ) ||
                "Therapy Session"
              ) +
              " was submitted successfully, but stock could not be moved from Main Store to Sub Store automatically.<br><br>" +
              stockIssueError,
              true
            );
          } else {
            glpSafeMessage(
              "Therapy Session created",
              (
                (
                  saved &&
                  saved.name
                ) ||
                "Therapy Session created successfully."
              ) +
              (
                stockIssueResult &&
                stockIssueResult.stock_entry
                  ? (
                      "<br><br>Stock moved: <b>" +
                      esc(
                        stockIssueResult.from_warehouse ||
                        values.branch
                      ) +
                      "</b> → <b>" +
                      esc(
                        stockIssueResult.to_warehouse ||
                        "Sub Store"
                      ) +
                      "</b>.<br>Used Stock +1.<br>Stock Entry: <b>" +
                      esc(
                        stockIssueResult.stock_entry
                      ) +
                      "</b>"
                    )
                  : ""
              ),
              false
            );
          }

          try {
            await glpPopupRefreshPlan(
              values.therapy_plan
            );
          } catch (refreshError) {
            void 0;
          }

        } catch (e) {
          void 0;

          btn.disabled =
            false;

          btn.textContent =
            "Submit Therapy Session";

          var sessionError =
            glpRequestErrorMessage(e);

          if (
            /please take next appointment of client/i.test(
              String(
                sessionError ||
                ""
              )
            )
          ) {
            sessionError =
              "ERPNext requires the client's next appointment before the Therapy Session can be submitted. " +
              "V4.71 checks this before submit and creates the selected next appointment first. " +
              "If this message still appears, refresh the page and verify the newly booked Patient Appointment is active and scheduled after the current session.";
          }

          if (
            /not enough payment for next therapy session/i.test(
              String(
                sessionError ||
                ""
              )
            )
          ) {
            sessionError =
              "Dashboard payment check passed, but the installed LIFE app hook " +
              "restrict_therapy_session_without_payment still blocked the Therapy Session. " +
              "This cannot be bypassed from Web Page JavaScript or an API Server Script; " +
              "the installed events.py rule must allow GLP sessions.";
          }

          if (
            /mandatoryerror/i.test(
              String(
                sessionError ||
                ""
              )
            ) &&
            /service_unit/i.test(
              String(
                sessionError ||
                ""
              )
            )
          ) {
            sessionError =
              "Service Unit is mandatory. The page now takes it automatically from Therapy Type → Healthcare Service Unit. Refresh the page and try again.";
          }

          glpSafeMessage(
            "Therapy Session not created",
            sessionError,
            true
          );
        }
      }
    );
  }

  async function openGLPAppointmentDialog() {
    /*
      The Therapy Plan may have been created moments ago in the Billing tab.
      Refresh live from ERPNext before opening the appointment modal instead
      of depending on the dashboard's old in-memory STATE.glpPlans.
    */
    await refreshGLPAppointmentPlansLive();

    /*
      Website pages in this ERPNext build expose frappe.ui.Dialog but
      do not expose frappe.ui.form.make_control, which makes the Desk
      dialog crash. Use the website-safe native modal directly.
    */
    return openGLPAppointmentNativeModal();
  }

  async function openGLPTherapySessionDialog() {
    /*
      ERPNext Website pages here expose frappe.ui.Dialog but not
      frappe.ui.form.make_control. The Desk dialog therefore crashes.
      Open the working website-safe Therapy Session modal directly.
    */
    return openGLPTherapySessionNativeModal();
  }


  function newDoc(doctype) {
    if (window.frappe && frappe.new_doc) {
      try {
        frappe.new_doc(doctype);
        return;
      } catch (e) {}
    }

    var route = norm(doctype).replace(/\s+/g,"-");
    window.open("/app/" + route,"_blank","noopener");
  }


