  function ensureSidebarSpacer() {
    if (
      !SIDE ||
      !SIDE.parentNode
    ) {
      return null;
    }

    var spacer =
      document.getElementById(
        "glp-sidebar-spacer"
      );

    if (!spacer) {
      spacer =
        document.createElement(
          "div"
        );

      spacer.id =
        "glp-sidebar-spacer";

      spacer.className =
        "glp-sidebar-spacer";

      SIDE.parentNode.insertBefore(
        spacer,
        SIDE
      );
    }

    return spacer;
  }


  function enforceReferenceSidebar() {
    if (
      !SIDE ||
      window.innerWidth <= 1000
    ) {
      return;
    }

    ensureSidebarSpacer();

    /*
      Inline !important beats the older Web Page CSS that still contains
      the previous sticky sidebar / large toggle rules.
    */
    SIDE.style.setProperty(
      "position",
      "fixed",
      "important"
    );

    SIDE.style.setProperty(
      "left",
      "0px",
      "important"
    );

    SIDE.style.setProperty(
      "top",
      "48px",
      "important"
    );

    SIDE.style.setProperty(
      "bottom",
      "0px",
      "important"
    );

    SIDE.style.setProperty(
      "height",
      "calc(100vh - 48px)",
      "important"
    );

    SIDE.style.setProperty(
      "max-height",
      "calc(100vh - 48px)",
      "important"
    );

    SIDE.style.setProperty(
      "overflow",
      "hidden",
      "important"
    );

    var nav =
      SIDE.querySelector(
        ".glp-nav"
      );

    if (nav) {
      nav.style.setProperty(
        "overflow-y",
        "auto",
        "important"
      );

      nav.style.setProperty(
        "overflow-x",
        "hidden",
        "important"
      );

      nav.style.setProperty(
        "min-height",
        "0",
        "important"
      );

      nav.style.setProperty(
        "flex",
        "1 1 auto",
        "important"
      );
    }
  }


  function positionReferenceToggle() {
    var btn =
      document.getElementById(
        "glp-sidebar-toggle"
      );

    if (
      !btn ||
      window.innerWidth <= 1000
    ) {
      return;
    }

    var collapsed =
      ROOT.classList.contains(
        "glp-sidebar-collapsed"
      );

    btn.style.setProperty(
      "position",
      "fixed",
      "important"
    );

    btn.style.setProperty(
      "top",
      "50vh",
      "important"
    );

    btn.style.setProperty(
      "left",
      collapsed
        ? "49px"
        : "205px",
      "important"
    );

    btn.style.setProperty(
      "right",
      "auto",
      "important"
    );

    btn.style.setProperty(
      "transform",
      "translateY(-50%)",
      "important"
    );
  }


  function setSidebarCollapsed(collapsed) {
    ROOT.classList.toggle(
      "glp-sidebar-collapsed",
      !!collapsed
    );

    var toggle =
      document.getElementById(
        "glp-sidebar-toggle"
      );

    if (toggle) {
      toggle.innerHTML =
        collapsed
          ? "▶"
          : "◀";

      toggle.title =
        collapsed
          ? "Expand sidebar"
          : "Collapse sidebar";

      toggle.setAttribute(
        "aria-label",
        collapsed
          ? "Expand sidebar"
          : "Collapse sidebar"
      );
    }

    try {
      localStorage.setItem(
        "life_glp_sidebar_collapsed",
        collapsed
          ? "1"
          : "0"
      );
    } catch (e) {}

    requestAnimationFrame(
      function () {
        enforceReferenceSidebar();
        positionReferenceToggle();
      }
    );
  }


  function setupSidebarCollapse() {
    if (!SIDE) {
      return;
    }

    injectSidebarCollapseStyles();

    ensureSidebarSpacer();

    var oldClose =
      document.getElementById(
        "glp-sidebar-close-btn"
      );

    if (
      oldClose &&
      oldClose.parentNode
    ) {
      oldClose.parentNode.removeChild(
        oldClose
      );
    }

    var btn =
      document.getElementById(
        "glp-sidebar-toggle"
      );

    if (!btn) {
      btn =
        document.createElement(
          "button"
        );

      btn.type =
        "button";

      btn.id =
        "glp-sidebar-toggle";

      btn.className =
        "glp-sidebar-toggle";

      btn.innerHTML =
        "◀";

      btn.title =
        "Collapse sidebar";

      btn.setAttribute(
        "aria-label",
        "Collapse sidebar"
      );

      /*
        Button stays outside the sidebar's own scrollable navigation.
      */
      ROOT.appendChild(
        btn
      );

      btn.addEventListener(
        "click",
        function () {
          setSidebarCollapsed(
            !ROOT.classList.contains(
              "glp-sidebar-collapsed"
            )
          );
        }
      );
    }

    var saved =
      "0";

    try {
      saved =
        localStorage.getItem(
          "life_glp_sidebar_collapsed"
        ) ||
        "0";
    } catch (e) {}

    setSidebarCollapsed(
      saved === "1"
    );

    enforceReferenceSidebar();
    positionReferenceToggle();

    setTimeout(
      function () {
        enforceReferenceSidebar();
        positionReferenceToggle();
      },
      50
    );

    setTimeout(
      function () {
        enforceReferenceSidebar();
        positionReferenceToggle();
      },
      300
    );

    if (
      !window.__lifeGLPReferenceSidebarResizeBound
    ) {
      window.__lifeGLPReferenceSidebarResizeBound =
        true;

      window.addEventListener(
        "resize",
        function () {
          enforceReferenceSidebar();
          positionReferenceToggle();
        }
      );
    }
  }


  function attachEvents() {
    /*
      Mobile privacy:
      Keep the number masked normally.
      Reveal the full number only while the mouse is directly over
      that mobile number, then restore masking on mouse-out.
    */
    ROOT.addEventListener("mouseover",function (e) {
      var mobile =
        e.target.closest(
          "[data-mobile-full][data-mobile-masked]"
        );

      if (
        !mobile ||
        !ROOT.contains(mobile)
      ) {
        return;
      }

      mobile.textContent =
        mobile.getAttribute(
          "data-mobile-full"
        ) || "";
    });

    ROOT.addEventListener("mouseout",function (e) {
      var mobile =
        e.target.closest(
          "[data-mobile-full][data-mobile-masked]"
        );

      if (
        !mobile ||
        !ROOT.contains(mobile)
      ) {
        return;
      }

      mobile.textContent =
        mobile.getAttribute(
          "data-mobile-masked"
        ) || "";
    });

    ROOT.addEventListener("click",function (e) {
      /*
        Appointment and Therapy Session actions are handled FIRST.
        This prevents generic data-view / table-row handlers from
        swallowing these buttons.
      */
      var priorityDoseReview =
        e.target.closest(
          "[data-dose-review-plan]"
        );

      if (priorityDoseReview) {
        e.preventDefault();
        e.stopPropagation();

        var doseReviewPlan =
          priorityDoseReview.getAttribute(
            "data-dose-review-plan"
          );

        Promise.resolve(
          openGLPDoseReviewNativeModal(
            doseReviewPlan
          )
        ).catch(
          function (err) {
            void 0;

            glpSafeMessage(
              "Dose Review could not open",
              glpRequestErrorMessage(
                err
              ),
              true
            );
          }
        );

        return;
      }

      var doseReviewHelp =
        e.target.closest(
          "[data-dose-review-help]"
        );

      if (doseReviewHelp) {
        e.preventDefault();
        e.stopPropagation();

        glpSafeMessage(
          "Dose Review",
          "Use the Dose Review button on the client's Therapy Plan row before treatment. If the proposed dose changes, send it for management approval. Enter Therapy Session Execution only after treatment.",
          false
        );

        return;
      }

      var prioritySession =
        e.target.closest(
          "[data-new-therapy-session]"
        );

      if (prioritySession) {
        e.preventDefault();
        e.stopPropagation();

        Promise.resolve(
          openGLPTherapySessionDialog()
        ).catch(
          function (err) {
            void 0;

            return openGLPTherapySessionNativeModal();
          }
        );

        return;
      }

      var priorityNew =
        e.target.closest(
          '[data-new-doctype="Patient Appointment"]'
        );

      if (priorityNew) {
        e.preventDefault();
        e.stopPropagation();

        void 0;

        priorityNew.disabled =
          true;

        var oldAppointmentText =
          priorityNew.textContent;

        priorityNew.textContent =
          "Loading GLP plans...";

        Promise.resolve(
          openGLPAppointmentDialog()
        )
          .catch(
            function (err) {
              void 0;

              glpSafeMessage(
                "New Appointment could not open",
                glpRequestErrorMessage(
                  err
                ),
                true
              );
            }
          )
          .finally(
            function () {
              priorityNew.disabled =
                false;

              priorityNew.textContent =
                oldAppointmentText ||
                "+ New appointment";
            }
          );

        return;
      }

      var dateTrigger = e.target.closest("[data-open-date]");

      if (dateTrigger) {
        e.preventDefault();
        e.stopPropagation();

        openNativeDatePicker(
          dateTrigger.getAttribute("data-open-date")
        );

        return;
      }

      var backExecutive =
        e.target.closest(
          "[data-back-executive]"
        );

      if (backExecutive) {
        STATE.branchDetail = "";
        STATE.branchDetailData = {
          leads: [],
          appointments: [],
          patients: []
        };

        render();

        window.scrollTo({
          top:0,
          behavior:"smooth"
        });

        return;
      }

      var branchRow =
        e.target.closest(
          "[data-open-branch]"
        );

      if (branchRow) {
        openBranchDetail(
          branchRow.getAttribute(
            "data-open-branch"
          )
        );

        return;
      }

      /*
        V5.67 - Branch Command: Create Client
        -------------------------------------
        The Branch Command primary action creates/assesses a GLP client,
        not a Patient Appointment.

        It opens the existing 6-step New Assessment flow and carries the
        branch that the user was viewing into Step 1.
      */
      var createGlpClient =
        e.target.closest(
          "[data-new-glp-client]"
        );

      if (createGlpClient) {
        var launchBranch =
          String(
            createGlpClient.getAttribute(
              "data-branch"
            ) || ""
          ).trim();

        STATE.assessmentLaunchBranch =
          launchBranch;

        STATE.assessmentLead =
          "";

        STATE.assessmentLeadLoading =
          false;

        STATE.assessmentStep =
          1;

        STATE.glpAssessmentRecord =
          null;

        gotoView(
          "assessment"
        );

        return;
      }

      var v = e.target.closest("[data-view]");
      if (v) {
        var targetView =
          v.getAttribute(
            "data-view"
          );

        /*
          Sidebar / generic New Assessment must use the normal branch scope.
          Only the dedicated Branch Command "Create client" button carries
          assessmentLaunchBranch.
        */
        if (
          targetView ===
          "assessment"
        ) {
          STATE.assessmentLaunchBranch =
            "";
        }

        gotoView(
          targetView
        );

        return;
      }

      var g = e.target.closest("[data-group]");
      if (g) {
        var group =
          g.getAttribute(
            "data-group"
          );

        if (
          ROOT.classList.contains(
            "glp-sidebar-collapsed"
          ) &&
          window.innerWidth > 1000
        ) {
          STATE.openGroup = group;
          setSidebarCollapsed(false);
          renderNav();
          return;
        }

        STATE.openGroup =
          STATE.openGroup === group
            ? ""
            : group;

        renderNav();
        return;
      }

      var reset = e.target.closest("[data-reset-view]");
      if (reset) {
        STATE.q = "";
        STATE.stage = "ALL";
        STATE.source = "ALL";
        STATE.status = "ALL";
        STATE.leadClientFilter = "";
        STATE.leadPage = 1;
        STATE.invoicePage = 1;
        $("glp-global-search").value = "";

        if (
          STATE.view === "invoices"
        ) {
          loadInvoicePageFast(1)
            .then(function () {
              render();
            });
        } else {
          render();
        }

        return;
      }

      var contraBtn = e.target.closest("[data-assessment-contra]");
      if (contraBtn) {
        contraBtn.classList.toggle("active");

        var values = Array.from(
          ROOT.querySelectorAll("[data-assessment-contra].active")
        ).map(function (btn) {
          return btn.getAttribute("data-assessment-contra") || "";
        }).filter(Boolean);

        var contraHidden = $("ass-contraindications");
        if (contraHidden) contraHidden.value = values.join("; ");
        updateAssessmentLivePanel();
        return;
      }

      var labsUploaded = e.target.closest("[data-assessment-labs-uploaded]");
      if (labsUploaded) {
        labsUploaded.classList.toggle("active");

        var isDone =
          labsUploaded.classList.contains("active");

        var labsStatus = $("ass-labs-status");
        if (labsStatus) {
          labsStatus.value =
            isDone
              ? "Completed"
              : "Pending";
        }

        Array.from(
          ROOT.querySelectorAll(
            ".glp-v564-lab-status"
          )
        ).forEach(
          function (select) {
            if (
              isDone &&
              norm(select.value) ===
                "pending"
            ) {
              select.value =
                "Uploaded";
            } else if (
              !isDone &&
              norm(select.value) ===
                "uploaded"
            ) {
              select.value =
                "Pending";
            }
          }
        );

        labsUploaded.textContent =
          isDone
            ? "✓ Lab reports uploaded"
            : "Mark lab reports uploaded";

        updateAssessmentLivePanel();
        return;
      }

      var bcaDone = e.target.closest("[data-assessment-bca-done]");
      if (bcaDone) {
        bcaDone.classList.toggle("active");

        var bcaHidden = $("ass-bca-done");
        if (bcaHidden) {
          bcaHidden.checked =
            bcaDone.classList.contains("active");
        }

        bcaDone.textContent =
          bcaDone.classList.contains("active")
            ? "✓ BCA done"
            : "Mark BCA done";

        return;
      }

      var consentSigned = e.target.closest("[data-assessment-consent-signed]");
      if (consentSigned) {
        consentSigned.classList.toggle("active");

        var signed =
          consentSigned.classList.contains("active");

        var consentInput = $("ass-consent-status");
        if (consentInput) {
          consentInput.value =
            signed
              ? "Signed"
              : "Pending";
        }

        var consentCheckbox =
          $("ass-consent-signed");

        if (consentCheckbox) {
          consentCheckbox.checked =
            signed;
        }

        consentSigned.textContent =
          signed
            ? "✓ Consent signed and scanned"
            : "Mark consent signed";

        updateAssessmentLivePanel();
        return;
      }

      var photoId = e.target.closest("[data-assessment-photo-id]");
      if (photoId) {
        photoId.classList.toggle("active");

        var collected =
          photoId.classList.contains("active");

        var photoCheck =
          $("ass-photo-id-collected");

        if (photoCheck) {
          photoCheck.checked =
            collected;
        }

        photoId.textContent =
          collected
            ? "✓ Photo ID on file"
            : "Mark photo ID collected";

        return;
      }

      var printConsent = e.target.closest("[data-assessment-print-consent]");
      if (printConsent) {
        window.print();
        return;
      }

      var assStep =
        e.target.closest(
          "[data-assessment-step]"
        );

      if (assStep) {
        var targetStep = Number(assStep.getAttribute("data-assessment-step")) || 1;
        var maxStep = glpAssessmentSavedMaxStepV564();
        if (targetStep > maxStep) {
          toast("Save the current step before moving forward.", true);
          return;
        }
        showAssessmentStep(targetStep);
        return;
      }

      var assNext =
        e.target.closest(
          "[data-assessment-next]"
        );

      if (assNext) {
        var currentStep = Number(assNext.getAttribute("data-assessment-next")) || STATE.assessmentStep || 1;
        glpAssessmentContinueV564(currentStep, assNext);
        return;
      }

      var assPrev =
        e.target.closest(
          "[data-assessment-prev]"
        );

      if (assPrev) {
        var fromStep =
          Number(
            assPrev.getAttribute(
              "data-assessment-prev"
            )
          ) ||
          STATE.assessmentStep ||
          1;

        showAssessmentStep(
          Math.max(
            1,
            fromStep - 1
          )
        );
        return;
      }

      var assSave =
        e.target.closest(
          "[data-assessment-save]"
        );

      if (assSave) {
        saveAssessmentLead();
        return;
      }

      var assReset =
        e.target.closest(
          "[data-assessment-reset]"
        );

      if (assReset) {
        STATE.assessmentLead = "";
        STATE.assessmentLeadLoading = false;
        STATE.assessmentStep = 1;
        STATE.glpAssessmentRecord = null;
        STATE.glpAssessmentResumeBusy = false;
        render();
        return;
      }

      var follow = e.target.closest("[data-follow-tab]");
      if (follow) {
        STATE.followTab = follow.getAttribute("data-follow-tab");
        render();
        return;
      }

      var appointmentMarkDone =
        e.target.closest(
          "[data-appointment-mark-done]"
        );

      if (
        appointmentMarkDone
      ) {
        e.preventDefault();
        e.stopPropagation();

        glpAppointmentDeskMarkDone(
          appointmentMarkDone.getAttribute(
            "data-appointment-mark-done"
          ),
          appointmentMarkDone
        );

        return;
      }

      var appointmentDetail =
        e.target.closest(
          "[data-appointment-details]"
        );

      if (appointmentDetail) {
        e.preventDefault();
        e.stopPropagation();

        var appointmentName =
          appointmentDetail.getAttribute(
            "data-appointment-details"
          );

        Promise.resolve(
          openGLPAppointmentDetails(
            appointmentName
          )
        ).catch(
          function (err) {
            void 0;

            glpSafeMessage(
              "Appointment details could not open",
              glpRequestErrorMessage(
                err
              ),
              true
            );
          }
        );

        return;
      }

      var row = e.target.closest("[data-open-doctype][data-open-name]");
      if (row) {
        openBackend(
          row.getAttribute("data-open-doctype"),
          row.getAttribute("data-open-name")
        );
        return;
      }

      var enquiryPageBtn =
        e.target.closest(
          "[data-enquiry-page]"
        );

      if (
        enquiryPageBtn &&
        !enquiryPageBtn.disabled
      ) {
        STATE.leadPage =
          Number(
            enquiryPageBtn.getAttribute(
              "data-enquiry-page"
            )
          ) || 1;

        render();

        var register =
          CONTENT.querySelector(
            ".glp-view-filter"
          );

        if (register) {
          register.scrollIntoView({
            behavior:
              "smooth",
            block:
              "start"
          });
        }

        return;
      }

      var invoicePageBtn = e.target.closest("[data-invoice-page]");
      if (invoicePageBtn && !invoicePageBtn.disabled) {
        var nextPage = Number(
          invoicePageBtn.getAttribute("data-invoice-page")
        ) || 1;

        CONTENT.innerHTML =
          '<div class="glp-loading">' +
            '<span class="glp-spinner"></span>' +
            '<div><b>Loading invoices...</b><span>Fetching 15 records.</span></div>' +
          '</div>';

        loadInvoicePageFast(nextPage)
          .then(function () {
            render();
            window.scrollTo({
              top:0,
              behavior:"smooth"
            });
          });

        return;
      }

      var nw = e.target.closest("[data-new-doctype]");
      if (nw) {
        var newDoctype =
          nw.getAttribute(
            "data-new-doctype"
          );

        if (
          newDoctype === "Lead"
        ) {
          Promise.resolve(
            openLeadEnquiryDialog()
          ).catch(
            function (error) {
              void 0;

              toast(
                "Could not open Log enquiry.",
                true
              );
            }
          );

        } else if (
          newDoctype ===
          "Patient Appointment"
        ) {
          return;

        } else {
          newDoc(
            newDoctype
          );
        }

        return;
      }
    });

    $("glp-menu-btn").addEventListener("click",function () {
      if (
        window.innerWidth <= 1000
      ) {
        SIDE.classList.toggle(
          "open"
        );
        return;
      }

      setSidebarCollapsed(
        !ROOT.classList.contains(
          "glp-sidebar-collapsed"
        )
      );
    });

    $("glp-branch-select").addEventListener("change",function () {
      STATE.branch =
        this.value || "ALL";
      STATE.branchDetail = "";
      STATE.branchDetailData = {
        leads: [],
        appointments: []
      };
      STATE.invoicePage = 1;
      STATE.leadPage = 1;
      STATE.assessmentLead = "";
      STATE.loadedViews = {};
      loadData();
    });

    $("glp-global-search").addEventListener("input",function () {
      STATE.q = this.value;

      if (
        STATE.view ===
        "leads"
      ) {
        STATE.leadPage = 1;
      }

      if (STATE.view !== "dashboard") render();
    });

    $("glp-from-date").addEventListener("change",function () {
      var d = $("glp-from-date-display");
      if (d) {
        d.value = displayDateDMY(this.value);
      }
    });

    $("glp-to-date").addEventListener("change",function () {
      var d = $("glp-to-date-display");
      if (d) {
        d.value = displayDateDMY(this.value);
      }
    });

    $("glp-apply-date").addEventListener("click",function () {
      var f = $("glp-from-date").value;
      var t = $("glp-to-date").value;

      if (!f || !t) {
        toast("Select both dates",true);
        return;
      }

      if (f > t) {
        toast("From date cannot be after To date",true);
        return;
      }

      STATE.from = f;
      STATE.to = t;
      STATE.branchDetail = "";
      STATE.branchDetailData = {
        leads: [],
        appointments: []
      };
      STATE.assessmentLead = "";
      STATE.leadPage = 1;
      syncDateChrome();
      loadData();
    });

    $("glp-reset-date").addEventListener("click",function () {
      var period = businessMonthRange(
        todayISO()
      );

      STATE.from = period.from;
      STATE.to = period.to;
      STATE.branchDetail = "";
      STATE.branchDetailData = {
        leads: [],
        appointments: []
      };
      STATE.assessmentLead = "";

      syncDateChrome();
      loadData();
    });

    $("glp-refresh-btn").addEventListener("click",loadData);
    $("glp-print-btn").addEventListener("click",function () {
      window.print();
    });
  }

  function syncDateChrome() {
    $("glp-from-date").value = STATE.from;
    $("glp-to-date").value = STATE.to;

    var fromDisplay =
      $("glp-from-date-display");

    var toDisplay =
      $("glp-to-date-display");

    if (fromDisplay) {
      fromDisplay.value =
        displayDateDMY(
          STATE.from
        );
    }

    if (toDisplay) {
      toDisplay.value =
        displayDateDMY(
          STATE.to
        );
    }

    var a = new Date(
      STATE.from + "T00:00:00"
    );

    var b = new Date(
      STATE.to + "T00:00:00"
    );

    var days = Math.max(
      1,
      Math.round((b-a)/86400000)+1
    );

    $("glp-horizon").textContent =
      days + " days";
  }

  function init() {
    installGLPGlobalErrorPopupTopLayer();

    var period = businessMonthRange(
      todayISO()
    );

    STATE.from = period.from;
    STATE.to = period.to;

    syncDateChrome();
    renderNav();
    setupSidebarCollapse();
    attachEvents();
    loadData();
  }

  init();

})();
